  import math.{abs, max, min}
  import mutable.ArrayBuffer
  import scala.reflect.ClassTag

  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val H, W, N = ni()
    val sr, sc = ni() - 1
    val S, T = ns(N) map {
      case 'L' => 0
      case 'R' => 1
      case 'U' => 2
      case 'D' => 3
    }

    debug(S)
    debug(T)

    // [0, dst)の範囲で動ける
    // 高橋くんはdstを目指す
    // [L, R, U, D]
    def reach(P: Array[Int], s: Int, dst: Int): Boolean = {
      debug(s"s:$s dst:$dst")
      var p = s
      REP(N) { i =>
        p = max(p, p + P(S(i))) // できるだけ大きくする
        debug(s"takahashi i:$i p:$p")
        if (p == dst) return true // 超えるのは高橋くんの番のみ

        p = max(0, min(p, p + P(T(i)))) // できるだけ小さくする。でも0は超えれない
        debug(s"aoki i:$i p:$p")
      }
      false
    }

    val r = reach(Array(-1, 1, 0, 0), sc, W)
    val l = reach(Array(1, -1, 0, 0), W - 1 - sc, W)
    val d = reach(Array(0, 0, -1, 1), sr, H)
    val u = reach(Array(0, 0, 1, -1), H - 1 - sr, H)

    val ok = !(r || l || u || d)
    if (ok) out.println("YES")
    else out.println("NO")
  }

