            case 'D': safetyU = max(safetyU-1, 0); break;
        }

        // Takahashi's turn
        switch (S[i]) {
            case 'L': ++safetyL; break;
            case 'R': --safetyR; break;
            case 'U': ++safetyU; break;
            case 'D': --safetyD; break;
        }

        if (safetyL >= W or safetyR < 0 or safetyU >= H or safetyD < 0) {
