                FOR(i, turn + 1, N) {
                    if (S[i] == 'D') {
                        future_D++;
                    }
                }
                if (future_D > H - r) {
                    //cerr << "Takahashi D" << endl;
                    r++;
                } else {
                    //cerr << "Takahashi do nothing" << endl;
                }
            }
        }

        if (r == 0 || r == H + 1 || c == 0 || c == W + 1) {
            remain = false;
            break;
        }

        // Aoki
        char aok_command = T[turn];
        if (aok_command == 'L') {
            if (c > W - c + 1) {
                //cerr << "Aoki L" << endl;
                c--;
            } else if (c < W - c + 1) {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            } else {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            }
        } else if (aok_command == 'R') {
            if (c < W - c + 1) {
                //cerr << "Aoki R" << endl;
                c++;
            } else if (c > W - c + 1) {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            } else {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            }
        } else if (aok_command == 'U') {
            if (r > H - r + 1) {
                //cerr << "Aoki U" << endl;
                r--;
            } else if (r < H - r + 1) {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            } else {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            }
        } else if (aok_command == 'D') {
            if (r < H - r + 1) {
                //cerr << "Aoki D" << endl;
                r++;
            } else if (r > H - r + 1) {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            } else {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            }
        }
    }

    if (remain) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

