        && (N & (1 << 2)) > 0 && ((N & (1 << 4)) == 0)) {
        cout << "NO" << endl;
        return 0;
    }
    sr--;
    sc--;
    if (solve(C, sc, 'L', 'R') || solve(R, sr, 'U', 'D')) {
        cout << "NO" << endl;
    }
    else {
        cout << "YES" << endl;
    }
    return 0;
}

