		rep(j, 4)
			dp[i][j] = dp[i + 1][j];
		if (s[1][i] == 'U')
			dp[i][1] = min(h - 1, dp[i][1] + 1);
		else if (s[1][i] == 'D')
			dp[i][0] = max(0, dp[i][0] - 1);
		else if (s[1][i] == 'L')
			dp[i][3] = min(w - 1, dp[i][3] + 1);
		else
			dp[i][2] = max(0, dp[i][2] - 1);
		if (s[0][i] == 'U')
			dp[i][0]++;
		else if (s[0][i] == 'D')
			dp[i][1]--;
		else if (s[0][i] == 'L')
			dp[i][2]++;
		else
			dp[i][3]--;
		if (dp[i][0] > dp[i][1] || dp[i][2] > dp[i][3]) {
			cout << "NO";
			return 0;
		}
	}
	x--; y--;
	if (dp[0][0] <= x && x <= dp[0][1] && dp[0][2] <= y && y <= dp[0][3])
		cout << "YES";
	else
		cout << "NO";
}

