int solve(int sx, string &S, string &T, int W, int dir) {

    int p = sx;
    int N = S.size();

    int l = sx, r = sx;
    for (int i = 0; i < N; i++) {
        if (dir == 0) {
            if (S[i] == 'L') l--;
            else if (S[i] == 'R') r++;
            if (l > r) swap(l, r);
            if (l < 0 || r >= W) return 0;
            if (r - 1 >= l && T[i] == 'L') r--;
            else if (l + 1 <= r && T[i] == 'R') l++;

        } else {
            if (S[i] == 'D') l--;
            else if (S[i] == 'U') r++;
            if (l > r) swap(l, r);
            if (l < 0 || r >= W) return 0;

            if (r - 1 >= l && T[i] == 'D') r--;
            else if (l + 1 <= r && T[i] == 'U') l++;
        }
    }


    return 1;
}

