typedef long long ll;

const ll MOD = 1e9 + 7;

bool solve(int H, int W, int N, int Sr, int Sc, string& S, string& T) {
    bool answer = true;

    // i回目(0..N-1)の直大の行動終了時点でleftest <= rightest の位置に駒があれば後手が勝てる
    vector<int> leftest(N+1), rightest(N+1);
    leftest[N] = 1;
    rightest[N] = W;

    RREP(i,0,N) {
        int dLeft = (S[i] == 'L' ? 1 : 0) + (i > 0 && T[i-1] == 'R' && leftest[i+1] != W ? -1 : 0);
        leftest[i] = dLeft + leftest[i+1];

        int dRight = (S[i] == 'R' ? -1 : 0) + (i > 0 && T[i-1] == 'L' && rightest[i+1] != 1 ? 1 : 0);
        rightest[i] = dRight + rightest[i+1];
        if (leftest[i] > rightest[i]) return false;
    }
    if (leftest[0] > Sc || rightest[0] < Sc) return false;

    // i回目(0..N-1)でlowest <= highest の位置に駒があれば後手が勝てる
    vector<int> lowest(N+1), highest(N+1);
    lowest[N] = 1;
    highest[N] = H;

    RREP(i,0,N) {
        int dLow = (S[i] == 'D' ? 1 : 0) + (i > 0 && T[i-1] == 'U' && lowest[i+1] != H ? -1 : 0);
        lowest[i] = max(dLow + lowest[i+1], 1);

        int dHigh = (S[i] == 'U' ? -1 : 0) + (i > 0 && T[i-1] == 'D' && highest[i+1] != 1 ? 1 : 0);
        highest[i] = min(dHigh + highest[i+1], H);
        if (lowest[i] > highest[i]) return false;
    }
    if (lowest[0] > Sc || highest[0] < Sc) return false;

    return true;
}

signed main() {
    int H, W, N, Sr, Sc;
    cin >> H >> W >> N >> Sr >> Sc;
    string S, T;
    cin >> S >> T;

    cout << (solve(H, W, N, Sr, Sc, S, T) ? "YES" : "NO") << '\n';

    return 0;
}

