};

static std::string const YES = "YES";
static std::string const NO = "NO";

static std::vector<direction_t> sCandidates;
static std::vector<direction_t> tCandidates;

static std::vector<int> lefts;
static std::vector<int> rights;
static std::vector<int> ups;
static std::vector<int> downs;

static int h;
static int w;
static int n;

static int minimax(position_t position, bool turn, int moves) {
  if (n * 2 - moves <= 0) {
    return -1;
  }

  int const maximumMovableLength = n - moves / 2;
  if (position.y - maximumMovableLength >= 0 &&
      position.y + maximumMovableLength < h &&
      position.x - maximumMovableLength >= 0 &&
      position.x + maximumMovableLength < w) {
    return -1;
  }

  direction_t candidate =
      turn ? sCandidates[moves / 2] : tCandidates[moves / 2];
  if (candidate == nothing) {
    return minimax(position, !turn, moves + 1);
  }
  position_t const newPosition =
      position_t(position.y + candidate.y, position.x + candidate.x);
  if (newPosition.y < 0 || h <= newPosition.y || newPosition.x < 0 ||
      w <= newPosition.x) {
    if (turn) {
      return 1;
    } else {
      return minimax(position, !turn, moves + 1);
    }
  }

  int const distance = abs(position.y - h / 2) + abs(position.x - w / 2);
  int const newDistance =
      abs(newPosition.y - h / 2) + abs(newPosition.x - w / 2);
  if (newDistance < distance) {
    if (turn) {
      if (minimax(newPosition, !turn, moves + 1) > 0) {
        return 1;
      }
      return minimax(position, !turn, moves + 1);
    } else {
      if (minimax(position, !turn, moves + 1) < 0) {
        return -1;
      }
      return minimax(newPosition, !turn, moves + 1);
    }
  } else {
    if (turn) {
      if (minimax(position, !turn, moves + 1) > 0) {
        return 1;
      }
      return minimax(newPosition, !turn, moves + 1);
    } else {
      if (minimax(newPosition, !turn, moves + 1) < 0) {
        return -1;
      }
      return minimax(position, !turn, moves + 1);
    }
  }
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> h;
  std::cin >> w;
  std::cin >> n;
  int s_r;
  std::cin >> s_r;
  int s_c;
  std::cin >> s_c;
  std::string s;
  std::cin >> s;
  sCandidates.reserve(n);
  lefts.reserve(n + 1);
  rights.reserve(n + 1);
  ups.reserve(n + 1);
  downs.reserve(n + 1);
  lefts.emplace_back(0);
  rights.emplace_back(0);
  ups.emplace_back(0);
  downs.emplace_back(0);
  for (auto const ch : s) {
    lefts.push_back(lefts.back());
    rights.push_back(lefts.back());
    ups.push_back(lefts.back());
    downs.push_back(lefts.back());
    switch (ch) {
      case 'L':
        lefts.back()++;
        break;
      case 'R':
        rights.back()++;
        break;
      case 'U':
        ups.back()++;
        break;
      case 'D':
        downs.back()++;
        break;
    }
  }
  bool const leftEnabled = s_c - lefts.back() < 0;
  bool const rightEnabled = s_c + rights.back() >= w;
  bool const upEnabled = s_r - ups.back() < 0;
  bool const downEnabled = s_r + downs.back() >= h;
  for (auto const ch : s) {
    switch (ch) {
      case 'L':
        sCandidates.push_back(leftEnabled ? left : nothing);
        break;
      case 'R':
        sCandidates.push_back(rightEnabled ? right : nothing);
        rights.back()++;
        break;
      case 'U':
        sCandidates.push_back(upEnabled ? up : nothing);
        ups.back()++;
        break;
      case 'D':
        sCandidates.push_back(downEnabled ? down : nothing);
        downs.back()++;
        break;
    }
  }
  std::string t;
  std::cin >> t;
  tCandidates.reserve(n);
  for (auto const ch : t) {
    switch (ch) {
      case 'L':
        tCandidates.push_back(rightEnabled ? left : nothing);
        break;
      case 'R':
        tCandidates.push_back(leftEnabled ? right : nothing);
        break;
      case 'U':
        tCandidates.push_back(downEnabled ? up : nothing);
        break;
      case 'D':
        tCandidates.push_back(upEnabled ? down : nothing);
        break;
    }
  }
  auto const res = minimax(position_t(s_r - 1, s_c - 1), true, 0);
  std::cout << ((res > 0) ? NO : YES) << std::endl;
  return 0;
}

