// Returns 0 (Player 0 wins) or 1 (Player 1 wins)
int FindWinner(int W, int N, int sc, string S, string T, char L, char R)
{
  // player 1 wins if x in [left, right]
  int left = 1;
  int right = W;
  int pleft;
  int pright;

  for (int i = N - 1; i >= 0; --i) {
    // Player 1
    if (T[i] == L) {
      pleft = left;
      if (right != W) pright = right + 1;
      else pright = right;
    } else if (T[i] == R) {
      if (left != 1) pleft = left - 1;
      else pleft = left;
      pright = right;
    }
    else {
      pleft = left;
      pright = right;
    }
    swap(left, pleft);
    swap(right, pright);

    // Player 0
    if (S[i] == L) {
      pleft = left + 1;
      pright = right;
    } else if (S[i] == R) {
      pleft = left;
      pright = right - 1;
    }
    else {
      pleft = left;
      pright = right;
    }
    swap(left, pleft);
    swap(right, pright);
    if (left > right) return 0;
  }

  if (left <= sc and sc <= right) return 1;
  else return 0;
}

int main()
{
  int H, W, N;
  cin >> H >> W >> N;
  int sr, sc;
  cin >> sr >> sc;  // 1-origin coordinate
  string S, T;
  cin >> S;
  cin >> T;

  if (FindWinner(W, N, sc, S, T, 'L', 'R') == 0 or
      FindWinner(H, N, sr, S, T, 'U', 'D') == 0) {
    cout << "NO" << endl;
  } else {
    cout << "YES" << endl;
  }

  return 0;
}

