bool remain(int n, char up, char down, int st) {
	int top = 0, bot = n + 1;
	for(int i = k; i >= 1; --i) {
		if(t[i] == up) bot = min(n + 1, bot + 1);
		if(t[i] == down) top = max(0, top - 1);
		if(s[i] == up) top++;
		if(s[i] == down) bot--;
		if(top + 1 == bot) return false;
	}
	return top < st && st < bot;
}

