int main() {
    int h, w, n;
    cin >> h >> w >> n;
    int sx, sy;
    cin >> sx >> sy;
    string s, t;
    cin >> s >> t;
    vector<vector<int>> op1(n + 1, vector<int>(4));
    vector<vector<int>> op2(n + 1, vector<int>(4));
    for (int i = n - 1; i >= 0; i--) {
        int c;
        if (s[i] == 'L') c = 0;
        else if (s[i] == 'R') c = 1;
        else if (s[i] == 'U') c = 2;
        else if (s[i] == 'D') c = 3;
        op1[i][c] = op1[i + 1][c] + 1;
        for (int j = 0; j < 4; j++) {
            if (j != c) {
                op1[i][j] = op1[i + 1][j];
            }
        }
        if (t[i] == 'L') c = 0;
        else if (t[i] == 'R') c = 1;
        else if (t[i] == 'U') c = 2;
        else if (t[i] == 'D') c = 3;
        op2[i][c] = op2[i + 1][c] + 1;
        for (int j = 0; j < 4; j++) {
            if (j != c) {
                op2[i][j] = op2[i + 1][j];
            }
        }
    }

    int l = sy, r = w + 1 - sy, u = sx, d = h + 1 - sx;
    bool can = true;
    for (int i = 0; i < n; i++) {
        if ((l == 1 and s[i] == 'L')
            or (r == 1 and s[i] == 'R')
            or (u == 1 and s[i] == 'U')
            or (d == 1 and s[i] == 'D')) {

            can = false;
            break;
        }
        if (s[i] == 'L' and op1[i][0] - op2[i][1] >= l) {
            l--;
            r++;
        } else if (s[i] == 'R' and op1[i][1] - op1[i][0] >= r) {
            r--;
            l++;
        } else if (s[i] == 'U' and op1[i][2] - op2[i][3] >= u) {
            u--;
            d++;
        } else if (s[i] == 'D' and op1[i][3] - op2[i][2] >= d) {
            d--;
            u++;
        }

        // 動かすかどうか
        if (t[i] == 'L' and op1[i + 1][1] - op2[i][0] >= r and l != 1) {
            l--;
            r++;
        } else if (t[i] == 'R' and op1[i + 1][0] - op1[i][1] >= l and r != 1) {
            r--;
            l++;
        } else if (t[i] == 'U' and op1[i + 1][3] - op2[i][2] >= d and u != 1) {
            u--;
            d++;
        } else if (t[i] == 'D' and op1[i + 1][2] - op2[i][3] >= u and d != 1) {
            d--;
            u++;
        }
    }

    if (can) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

