		if (b[i]==-1) c[i]--;
		c[i]=max(c[i],max(0,a[i]));
		d[i]=d[i+1];
		if (a[i]==-1) d[i]--;
		if (b[i]==1) d[i]++;
		d[i]=min(d[i],min(0,a[i]));
	}
	int y=x;
	for (int i=1;i<=n;i++)
	{
