    if (isLR(T[i])) {
      if (T[i] == 'L') {
        table0 = table0 | table0 << 1;
      } else {
        table0 = table0 | table0 >> 1;
        table0[W] = false;
      }
    }
    if (isLR(S[i])) {
      if (S[i] == 'L') {
        table0 = table0 & table0 << 1;
      } else {
        table0 = table0 & table0 >> 1;
      }
    }
  }
  REPR(i, N - 1) {
    if (isUD(T[i])) {
      if (T[i] == 'U') {
        table1 = table1 | table1 << 1;
      } else {
        table1 = table1 | table1 >> 1;
        table1[H] = false;
      }
    }
    if (isUD(S[i])) {
      if (S[i] == 'U') {
        table1 = table1 & table1 << 1;
      } else {
        table1 = table1 & table1 >> 1;
      }
    }
  }
  if (table0[p[0]] && table1[p[1]]) {
    print("YES");
  } else {
    print("NO");
  }
  DUMP(bitset<MAXN>(table0));
  DUMP(bitset<MAXN>(table1));
}

