const int N=2e5+10;
int min(int a,int b){return a>b?b:a;}
int max(int a,int b){return a>b?a:b;}
bool judge(int pos,int lim,int s,int a[],int b[]){
//printf("::pos=%d lim=%d s=%d\n",pos,lim,s);
//printf("a::");for(int i=0;i<s;i++)printf(" %d",a[i]);printf("\n");
//printf("b::");for(int i=0;i<s;i++)printf(" %d",b[i]);printf("\n");
  int ml=pos,mr=pos;
  for(int i=0;i<s;i++){
    if(a[i]==1)mr--;
    else if(a[i]==-1)ml++;
    if(ml<1||mr>lim)return true;
  	if(b[i]==1)ml--;
    else if(b[i]==-1)mr++;
    mr=min(mr,lim);
    ml=max(ml,1);
  }
  return false;
}
int main(){
  int n,m,x,y,s,ta[N],tb[N];
  string a,b;
  cin>>n>>m>>s>>x>>y>>a>>b;
  for(int i=0;i<s;i++)if(a[i]=='L')ta[i]=-1;
  else if(a[i]=='R')ta[i]=1;
  else ta[i]=0;
  for(int i=0;i<s;i++)if(b[i]=='L')tb[i]=-1;
  else if(b[i]=='R')tb[i]=1;
  else tb[i]=0;
  if(judge(y,m,s,ta,tb))printf("NO\n");
  else {
    for(int i=0;i<s;i++)if(a[i]=='U')ta[i]=1;
    else if(a[i]=='D')ta[i]=-1;
    else ta[i]=0;
    for(int i=0;i<s;i++)if(b[i]=='U')tb[i]=1;
    else if(b[i]=='D')tb[i]=-1;
    else tb[i]=0;
    if(judge(x,n,s,ta,tb))printf("NO\n");
    else printf("YES\n");
  }
}

