void solve() {
    int H, W, N; cin >> H >> W >> N;
    int sr, sc; cin >> sr >> sc;
    string S, T; cin >> S >> T;
    int l = 0, r = W + 1, d = 0, u = H + 1;
    per(i, N) {
        if(i != N - 1) {
            if(T[i] == 'L') {
                if(r != W + 1)  r += 1;
            } else if(T[i] == 'R') {
                if(l != 0) l -= 1;
            } else if(T[i] == 'U') {
                if(d != 0) d -= 1;
            } else {
                if(u != H + 1) u += 1;
            }
        }

        if(l + 1 >= r || d + 1 >= u) {
            cout << "NO" << endl;
            return;
        }

        if(S[i] == 'L') {
            l += 1;
        } else if(S[i] == 'R') {
            r -= 1;
        } else if(S[i] == 'U') {
            u -= 1;
        } else {
            d += 1;
        }

        if(l + 1 >= r || d + 1 >= u) {
            cout << "NO" << endl;
            return;
        }
    }
    if(sr >= u || sr <= d || sc >= r || sc <= l) {
        cout << "NO" << endl;
        return;
    }
    cout << "YES" << endl;
    return;
}

