bool solve(char c1, char c2, int lim1, int ss) {
  int left = 1, right = lim1;
  if (s[N-1] == c1) left++;
  if (s[N-1] == c2) right--;
  // dbg2(left, right)
  // line()
  for (int i = N-2; i >= 0; i--) {
    if (t[i] == c1) {
      right = min(right+1, lim1);
    } else if (t[i] == c2) {
      left = max(1ll, left-1);
    }
    // dbg2(left, right)
    if (s[i] == c1) {
      left++;
    } else if (s[i] == c2) {
      right--;
    }
    // dbg2(left, right)
    // line()
    if (right < left) return false;
  }
  // line()
  // line()

  return ss >= left and right <= ss;
}

