typedef vector<ll> VLL;
typedef vector<VLL> VVLL;
//typedef boost::multiprecision::cpp_int bigint;

ll H, W, N, sx, sy;
string S, T;

pll calc(VLL& vec1, VLL& vec2, ll M) {
	ll x = 0, xx = M + 1;
	for (ll n = N - 1; n >= 0; n--) {
		if (vec1[n] == vec2[n]) {
			x = max((ll)0, x - vec1[n]);
			xx = min(M + 1, xx - vec2[n]);
		}
		else if (vec1[n] + vec2[n] == 0)continue;
		else if (vec1[n] == 1) {
			if (x < xx) {
				xx--;
			}
		}
		else if (vec1[n] == -1) {
			if (x < xx) {
				x++;
			}
		}
		else if (vec2[n] == 1) {
			x = max((ll)0, x - 1);
		}
		else {
			xx = min(M + 1, xx + 1);
		}
		if (x == 0 && vec1[n] == -1)x = 1;
		else if (xx == M + 1 && vec1[n] == 1)xx = M;
		if (x == xx - 1)return pll(x, xx);
	}
	return pll(x, xx);
}

int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0);
	cin >> H >> W >> N >> sy >> sx;
	cin >> S >> T;
	VLL SX(N, 0), SY(N, 0), TX(N, 0), TY(N, 0);
	for (ll n = 0; n < N; n++) {
		if (S[n] == 'L')SX[n] = -1;
		else if (S[n] == 'R')SX[n] = 1;
		else if (S[n] == 'U')SY[n] = -1;
		else SY[n] = 1;
		if (T[n] == 'L')TX[n] = -1;
		else if (T[n] == 'R')TX[n] = 1;
		else if (T[n] == 'U')TY[n] = -1;
		else TY[n] = 1;
	}
	pll resx = calc(SX, TX, W);
	pll resy = calc(SY, TY, H);
	bool flagx = (sx <= resx.first) || (resx.second <= sx);
	bool flagy = (sy <= resy.first) || (resy.second <= sy);
	if (flagx || flagy)cout << "NO\n";
	else cout << "YES\n";
	return 0;
}

