            gap = (Rgap - takahashi) + min(aoki, Lgap);
            if(0 <= gap && gap - min(aoki, Lgap) < 0){
                tmp = Lgap;
                Lgap -= min(aoki, tmp) - 1;
                Rgap += min(aoki, tmp) - 1;
            }
        }
        if(s[i] == 'L'){
            takahashi = T[n][3] - T[i][3];
            aoki = A[i+1][1];
            gap = (Lgap - takahashi) + min(aoki, Rgap);
            if(0 <= gap && gap - min(aoki, Rgap) < 0){
                tmp = Rgap;
                Rgap -= min(aoki, tmp) - 1;
                Lgap += min(aoki, tmp) - 1;
            }
        }
        if(s[i] == 'U'){
            takahashi = T[n][0] - T[i][0];
            aoki = A[i+1][2];
            gap = (Ugap - takahashi) + min(aoki, Dgap);
            if(0 <= gap && gap - min(aoki, Dgap) < 0){
                tmp = Dgap;
                Dgap -= min(aoki, tmp) - 1;
                Ugap += min(aoki, tmp) - 1;
            }
        }
        if(s[i] == 'D'){
            takahashi = T[n][2] - T[i][2];
            aoki = A[i+1][0];
            gap = (Dgap - takahashi) + min(aoki, Ugap);
            if(0 <= gap && gap - min(aoki, Ugap) < 0){
                tmp = Ugap;
                Ugap -= min(aoki, tmp) - 1;
                Dgap += min(aoki, tmp) - 1;
            }
        }

        //cout << Ugap << " " << Rgap << " " << Dgap << " " << Lgap << endl;

        if(gap < 0){
            valid = false;
            //cout << i << endl;
        }
    }

    if(valid) cout << "YES" << endl;
    else cout << "NO" << endl;
}

