void solve(long long H, long long W, long long N, long long s_r, long long s_c, std::string S, std::string T){
    LL l = -1, r = W, u = -1, d = H;

    RREP(i, N-1) {
        if(i != N - 1) {
            if(T[i] == 'U') d = min(H, d+1);
            if(T[i] == 'D') u = max(-1LL, u-1);
            if(T[i] == 'L') r = min(W, r+1);
            if(T[i] == 'R') l = max(-1LL, l-1);
        }

        if(S[i] == 'U') u++;
        if(S[i] == 'D') d--;
        if(S[i] == 'L') l++;
        if(S[i] == 'R') r--;

