using namespace std;

bool judge(
  int64_t H, int64_t W, int64_t N, 
  int64_t sr, int64_t sc, 
  const string &S, const string &T,
  int64_t dy, int64_t dx, char s, char t
)
{
  int64_t y = sr - 1, x = sc - 1;
  for (int64_t n = 0; n < N; ++n) {
    if (S[n] == s) { y += dy; x += dx; }
    if (!((0 <= y && y < H) && (0 <= x && x < W))) { return false; }
    if (T[n] == t) { y -= dy; x -= dx; }
    if (!((0 <= y && y < H) && (0 <= x && x < W))) { y += dy; x += dx; }
  }
  return (0 <= y && y < H) && (0 <= x && x < W);
}

