  bool flag = true;
  flag &= judge(H, W, N, sr, sc, S, T,  0, +1, 'R', 'L');
  flag &= judge(H, W, N, sr, sc, S, T,  0, -1, 'L', 'R');
  flag &= judge(H, W, N, sr, sc, S, T, +1,  0, 'D', 'U');
  flag &= judge(H, W, N, sr, sc, S, T, -1,  0, 'U', 'D');
  cout << (flag ? "YES" : "NO") << endl;

  return 0;
}

