bool can_remove() {
    int x, y;

    // Takahashi Left Up
    PRINT("Takahashi Left Up principle");
    x = sr;
    y = sc;
    REP(i, N) {
        if (S[i] == 'L') {
            PRINT("Takahashi L");
            y--;
        } else if (S[i] == 'U') {
            PRINT("Takahashi U");
            x--;
        } else {
            PRINT("Takahashi pass");
        }
        pri(x, y);
        if (out_range(x, y)) {
            PRINT("remove from Left Up");
            return true;
        }
        if (T[i] == 'R' && y + 1 < W) {
            PRINT("Aoki R");
            y++;
        } else if (T[i] == 'D' && x + 1 < H) {
            PRINT("Aoki D");
            x++;
        } else {
            PRINT("Aoki pass");
        }
    }

    // Takahashi Right Down
    PRINT("Takahashi Right Down principle");
    x = sr;
    y = sc;
    REP(i, N) {
        if (S[i] == 'R') {
            y++;
            PRINT("Takahashi R");
        } else if (S[i] == 'D') {
            x++;
            PRINT("Takahashi D");
        } else {
            PRINT("Takahashi pass");
        }
        pri(x, y);
        if (out_range(x, y)) {
            PRINT("remove from Right Down");
            return true;
        }
        if (T[i] == 'L' && y - 1 >= 0) {
            PRINT("Aoki L");
            y--;
        } else if (T[i] == 'U' && x - 1 >= 0) {
            PRINT("Aoki U");
            x--;
        } else {
            PRINT("Aoki pass");
        }
        pri(x, y);
    }

    // Takahashi Left Down
    x = sr;
    y = sc;
    REP(i, N) {
        if (S[i] == 'L') {
            y--;
        } else if (S[i] == 'D') {
            x++;
        }
        if (out_range(x, y)) {
            PRINT("remove from Left Down");
            return true;
        }
        if (T[i] == 'R' && y + 1 < W) {
            y++;
        } else if (T[i] == 'U' && x - 1 >= 0) {
            x--;
        }
    }

    // Takahashi Right Up
    x = sr;
    y = sc;
    REP(i, N) {
        if (S[i] == 'R') {
            y++;
        } else if (S[i] == 'U') {
            x--;
        }
        if (out_range(x, y)) {
            PRINT("remove from Right Up");
            return true;
        }
        if (T[i] == 'L' && y - 1 >= 0) {
            y--;
        } else if (T[i] == 'D' && x + 1 < H) {
            x++;
        }
    }

    return false;
}

