int H,W;
int sh,sw;
int N;
string S, T;

class BLRUDGame {
public:
void solve(std::istream& cin, std::ostream& cout) {
    cin >> H >> W >> N >> sh >> sw >> S >> T;
    int l1=0,r1=0,u1=0,d1=0,l2=0,r2=0,u2=0,d2=0;
    _for(i,N){
        char c = S[i];
        if(c == 'L')l1 ++;
        else if(c == 'R')r1 ++;
        else if(c == 'U')u1 ++;
        else d1++;
        c = T[i];
        if(l1 - r2 >= sw || r1 - l2 >= W - sw + 1 || u1 - d2 >= sh || d1 - u2 >= H - sh +1){
            cout << "NO\n";return;
        }
        if(c == 'L')l2 ++;
        else if(c == 'R')r2 ++;
        else if(c == 'U')u2 ++;
        else d2++;
        l2 = min(l2, sw -  1 + r1);
        r2 = min(r2, W - sw + l1);
        u2 = min(u2, sh -1 + d1);
        d2 = min(d2, H - sh + u1);

    }
    cout << "YES\n";

}
};

int main() {
	BLRUDGame solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

