            --c_h;
            if(c_h==0){
                ans=false;
                goto end;
            }
        }
        if(s[i]=='L'){
            --c_w;
            if(c_w==0){
                ans=false;
                goto end;
            }
        }
        if(t[i]=='D'){
            if(c_h<h) ++c_h;
        }
        if(t[i]=='R'){
            if(c_w<w) ++c_w;
        }
    }

    c_h=sr, c_w=sc;
    for(int i=0; i<n; ++i){
        if(s[i]=='D'){
            ++c_h;
            if(c_h==h+1){
                ans=false;
                goto end;
            }
        }
        if(s[i]=='R'){
            ++c_w;
            if(c_w==w+1){
                ans=false;
                goto end;
            }
        }
        if(t[i]=='U'){
            if(c_h>1) --c_h;
        }
        if(t[i]=='L'){
            if(c_w>1) --c_w;
        }
    }

end:
