int SR, SC, R, C;
string S, T;

bool check(char l, char r)
{
  int need_plus, need_minus, plus, minus;
  if (l == 'L')
  {
    need_plus = C + 1 - SC;
    need_minus = SC;
  }
  else
  {
    need_plus = R + 1 - SR;
    need_minus = SR;
  }

  for (int i = 0; i < S.size(); i++)
  {
    if (S[i] == r and T[i] == r)
      plus++, minus--;
    else if (S[i] == l and T[i] == l)
      minus++, plus--;
  }

  return plus >= need_plus or minus >= need_minus;
}

int main()
{
  int i, n, m, j, len;
  ios_base::sync_with_stdio(0);

  cin >> R >> C >> len;

  cin >> SR >> SC;

  cin >> S >> T;

  bool ans = check('L', 'R') || check('U', 'D');

  cout << (ans ? "NO" : "YES");
  return 0;
}

