bool hoge(int dir) {

  int a1 = 0, a2 = 0, a3 = 0;
  int t1 = 0, t2 = 0, t3 = 0;

  REP(i,n) {
    if (i&1) {

      if (s[i] == d[dir] && t[i] == d[dir]) {
        a1++;
      } else if (s[i] == d[(dir+2)%4] || t[i] == d[(dir+2)%4]) {
        a3++;
      }

    } else {

      if (s[i] == d[dir] || t[i] == d[dir]) {
        t1++;
      } else if ((mp[s[i]] + 1) * (dir + 1) & 1 || (mp[t[i]] + 1) * (dir + 1) & 1) {
        t2++;
      } else {
        t3++;
      }

    }

    int pos;

    if (dir == 0) {
      pos = sh;
      //cout << pos << " " << t1 << " " << t3 << " " << a1 << " " << a3 << endl;
      pos -= t1;
      pos += t3;
      pos -= a1;
      pos += a3;
      //cout << pos << endl;
      if (pos <= 0) return 0;
    } else if (dir == 1) {
      pos = sw;
      pos -= t1;
      pos += t3;
      pos -= a1;
      pos += a3;

      if (pos <= 0) return 0;

    } else if (dir == 2) {
      pos = sh;
      pos += t1;
      pos -= t3;
      pos -= a1;
      pos += a3;

      if (pos > w) return 0;
    } else if (dir == 3) {
      pos = sw;
      pos += t1;
      pos -= t3;
      pos -= a1;
      pos += a3;

      if (pos > w) return 0;
    }

  }
  return 1;
}

