pair<vector<int>, vector<int>> convert(const string& moves) {
	vector<int> vert, hor;

	for(auto& chr: moves) {
		if(chr == 'R') {
			vert.push_back(0);
			hor.push_back(1);
		} else if(chr == 'L') {
			vert.push_back(0);
			hor.push_back(-1);
		} else if(chr == 'U') {
			vert.push_back(-1);
			hor.push_back(0);
		} else {
			vert.push_back(1);
			hor.push_back(0);
		}
	}

	return make_pair(vert, hor);
}

int H, W, N;
int sx, sy;

int solve_1D(const vector<int>& a, const vector<int>& b, int pos, int sz) {
	int n = len(a);

	for(auto& dir: {-1, 1}) {
		int cur = pos;

		for(int i = 0; i < n; ++i) {
			if(a[i] == dir) {
				cur += a[i];
			}

			if(cur < 0 || cur >= sz) {
				return 0;
			}

			if(b[i] == -dir) {
				int cur2 = cur + b[i];

				if(cur2 >= 0 && cur2 < sz) {
					cur = cur2;
				}
			}
		}
	}

	return 1;
}

