bool check(int &left, int &right, const int len, int &pmax, int &nmax)
{
    if(right > len) { // 大きい方に抜ける
      int d = right - len;
      if(nmax >= d) {
	nmax -= d;
	right = len;
      } else {
	//	cout << "Out to RIGHT" << endl;
	return false;
      }

    }
    if(left <= 0) {
      int d = -left + 1;
      if(pmax >= d) {
	pmax -= d;
	left = 1;
      } else {
	//	cout << "Out to LEFT" << endl;
	return false;
      }
    }
    if(left - nmax <= 0) {
      nmax = left - 1;
    }
    if(right + pmax > len) {
      pmax = len - right;
    }
    if(pmax < 0) {
      //cout << "Out to LEFT 2" << endl;
       return false;
    }
    if(nmax < 0) {
      //cout << "out to RIGHT 2" << endl;
       return false;
    }
return true;
}

