bool check(char l, char r, int X, int lim)
{
  int n = S.size();
  int lo = 0, hi = lim - 1;

  for (int i = n - 1; i >= 0; i--)
  {
    if (T[i] == r)
      lo = max(lo - 1, 0);
    else
      hi = min(hi + 1, lim - 1);
    if (S[i] == r)
      hi--;
    else
      lo++;
  }
  return lo <= X and X <= hi;
}

