signed main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);

    int H, W, N;
    in(H); in(W); in(N);
    int sr, sc;
    in(sr); in(sc);
    string S, T;
    in(S); in(T);

    vector<int> up(N, 0), down(N, 0), left(N, 0), right(N, 0);
    vector<int> up2(N, 0), down2(N, 0), left2(N, 0), right2(N, 0);
    rep(i, N) {
        if (S[i] == 'U') up[i]++;
        if (S[i] == 'D') down[i]++;
        if (S[i] == 'L') left[i]++;
        if (S[i] == 'R') right[i]++;
        if (T[i] == 'U') up2[i]++;
        if (T[i] == 'D') down2[i]++;
        if (T[i] == 'L') left2[i]++;
        if (T[i] == 'R') right2[i]++;
    }
    bool taka_win = true;
    vector<int> dp(N);
    // if up is last move set to 1
    dp[N-1] = (up[N-1]) ? 1 : 0;
    for (int i=N-2; i>=0; i--) {
        if (up[i]) {
            if (down2[i]) dp[i] = dp[i+1];
            else dp[i] = dp[i+1] + 1;
        }
        if (dp[i] > H-1)
            taka_win = false;
    }
    // if down is last move set to N-2;
    dp[N-1] = (down[N-1]) ? N-2 : N-1;
    for (int i=N-2; i>=0; i--) {
        if (down[i]) {
            if (up2[i]) dp[i] = dp[i+1];
            else dp[i] = dp[i+1] - 1;
        }
        if (dp[i] < 0)
            taka_win = false;
    }

    // if left is last move set to 1
    dp[N-1] = (left[N-1]) ? 1 : 0;
    for (int i=N-2; i>=0; i--) {
        if (left[i]) {
            if (right2[i]) dp[i] = dp[i+1];
            else dp[i] = dp[i+1] + 1;
        }
        if (dp[i] > W-1)
            taka_win = false;
    }
    // if down is last move set to N-2;
    dp[N-1] = (right[N-1]) ? N-2 : N-1;
    for (int i=N-2; i>=0; i--) {
        if (right[i]) {
            if (left2[i]) dp[i] = dp[i+1];
            else dp[i] = dp[i+1] - 1;
        }
        if (dp[i] < 0)
            taka_win = false;
    }

    cout << (taka_win ? "YES" : "NO") << endl;


    return 0;
}

