void tr_vc(vector<int> &tsx, vector<int> &tsy, string s, int n){
	rep(i, n){
		if(s[i] == 'L'){
			tsx.at(i) = -1;
			tsy.at(i) = 0;
		}else if(s[i] == 'R'){
			tsx.at(i) = 1;
			tsy.at(i) = 0;
		}else if(s[i] == 'U'){
			tsx.at(i) = 0;
			tsy.at(i) = -1;
		}else{
			tsx.at(i) = 0;
			tsy.at(i) = 1;
		}
	}
}

bool fc(vector<int> &s, vector<int> &t, int p, int li, int n){
	int li0 = 1, limx = li;
	rrep(i, n){
		// cerr << t.at(i) << " " << s.at(i) << " ";
		if(t.at(i) == -1){
			limx = min(li, limx+1);
		}else if(t.at(i) == 1){
			li0 = max(1, li0-1);
		}

		if(s.at(i) == -1){
			li0++;
		}else if(s.at(i) == 1){
			limx--;
		}
		if(limx < li0) return true;
		// cerr << li0 << " " << limx << " " << p << endl;
	}
	if(p < li0 || limx < p) return true;
	return false;
}

