bool solve(int n, int s, int len, string foo, string bar, char add, char sub) {
  int l = 1, r = n;
  for (int i = len - 1; ~i; --i) {
    if (bar[i] == add) {
      --l;
    } else if (bar[i] == sub) {
      ++r;
    }
    l = max(l, 1);
    r = min(r, n);
    if (foo[i] == add) {
      --r;
    } else if (foo[i] == sub) {
      ++l;
    }
    if (l > r) {
      return false;
    }
  }
  return l <= s && s <= r;
}

