  std::vector<int> tU(N+1, 0);
  std::vector<int> tD(N+1, 0);
  std::vector<int> aR(N+1, 0);
  std::vector<int> aL(N+1, 0);
  std::vector<int> aU(N+1, 0);
  std::vector<int> aD(N+1, 0);
  std::vector<int> saR(N+1, 0);
  std::vector<int> saL(N+1, 0);
  std::vector<int> saU(N+1, 0);
  std::vector<int> saD(N+1, 0);
  switch(T[0]){
    case 'R': aR[1]++;
    break;
    case 'L': aL[1]++;
    break;
    case 'U': aU[1]++;
    break;
    case 'D': aD[1]++;
    break;
  }
  switch(S[0]){
    case 'R': tR[1]++;
    break;
    case 'L': tL[1]++;
    break;
    case 'U': tU[1]++;
    break;
    case 'D': tD[1]++;
    break;
  }
  for(int i = 1;i<N+1;i++){
    tR[i] = tR[i-1];
    tL[i] = tL[i-1];
    tU[i] = tU[i-1];
    tD[i] = tD[i-1];
    switch(S[i-1]){
      case 'R': tR[i]++;
      break;
      case 'L': tL[i]++;
      break;
      case 'U': tU[i]++;
      break;
      case 'D': tD[i]++;
      break;
    }
    aR[i] = aR[i-1];
    aL[i] = aL[i-1];
    aU[i] = aU[i-1];
    aD[i] = aD[i-1];
    switch(T[i-1]){
      case 'R': aR[i]++;
      break;
      case 'L': aL[i]++;
      break;
      case 'U': aU[i]++;
      break;
      case 'D': aD[i]++;
      break;
    }
  }
  saR[N]=max(0, tR[N]-aL[N]);
  saL[N]=max(0, tL[N]-aR[N]);
  saU[N]=max(0, tU[N]-aD[N]);
  saD[N]=max(0, tD[N]-aU[N]);
  for(int i=N-1;i>0;i--){
    saR[i]=max(saR[i+1], tR[i]-aL[i]);
    saL[i]=max(saL[i+1], tL[i]-aR[i]);
    saU[i]=max(saU[i+1], tU[i]-aD[i]);
    saD[i]=max(saD[i+1], tD[i]-aU[i]);
  }
  int rama, lama, uama, dama;
  ranges(i, 1, N+1){
    rama=max(0,saR[i]-aL[i-1]);
    lama=max(0,saL[i]-aR[i-1]);
    uama=max(0,saU[i]-aD[i-1]);
    dama=max(0,saD[i]-aU[i-1]);
    int Lmax=sc-max(1,lama);
    int Rmax=W-sc-max(0,rama);
    int Umax=sr-max(1, uama);
    int Dmax=H-sr-max(0, dama);
    int right = tR[i]-min(max(0, Lmax),aL[i-1]),left=min(max(0, Rmax),aR[i-1])-tL[i],up=min(max(0, Umax),aD[i-1])-tU[i],down=tD[i]-min(max(0, Dmax),aU[i-1]);
    if(sc+right>W||sc+left<= 0||sr+down>H||sr+up<=0){
      std::cout << "NO" << '\n';
      break;
    }else if(i==N){
      std::cout << "YES" << '\n';
    }
    //std::cout << Lmax << Rmax << Umax << Dmax << '\n';
  }
  return 0;
}

