bool dfs(int idx, int yy, int xx) {
  if (check(yy, xx)) {
    // dbg3(idx, yy, xx)
    return true;
  }
  if (idx >= 2*N) {
    return false;
  }

  if (dp[idx][yy][xx] != -1) {
    return dp[idx][yy][xx];
  }

  if (idx % 2 == 0) { // 先手.trueにしたい
    bool ret = false;
    // no
    ret |= dfs(idx+1, yy, xx);
    // yes
    int ny = yy + mp[g[idx]].first;
    int nx = xx + mp[g[idx]].second;
    ret |= dfs(idx+1, ny, nx);

    return dp[idx][yy][xx] = ret;
  } else { // 後手.falseにしたい
    bool ret = true;
    // no
    ret &= dfs(idx+1, yy, xx);
    // yes
    int ny = yy + mp[g[idx]].first;
    int nx = xx + mp[g[idx]].second;
    ret &= dfs(idx+1, ny, nx);

    return dp[idx][yy][xx] = ret;
  }
}

