int aa[maxn], bb[maxn];

int trans(char c)
{
    switch(c)
    {
        case 'L' : return 0;
        case 'R' : return 1;
        case 'U' : return 2;
        case 'D' : return 3;
    }
    return -1;
}

void yes()
{
    cout << "YES\n";
    exit(0);
}
void no()
{
    cout << "NO\n";
    exit(0);
}

int M, m;
int a[maxn], b[maxn];
int l[maxn], r[maxn];
void solve()
{
    //cerr << "A" << endl;
    dec(i, n, 1)
    {
        l[i] = l[i + 1];
        if(a[i] == -1)
            l[i] ++;
        if(b[i] == 1)
            l[i] --;
        if(a[i] == -1)
            chkmax(l[i], 1);
        else
            chkmax(l[i], 0);

        r[i] = r[i + 1];
        if(a[i] == 1)
            r[i] ++;
        if(b[i] == -1)
            r[i] --;
        if(a[i] == 1)
            chkmax(r[i], 1);
        else
            chkmax(r[i], -1);
    }

    if(m - l[1] < 1 || m + r[1] > M)
        no();

    /*cerr << "B" << endl;
    enum(i, 1, n)
        cerr << l[i] << ' ' << r[i] << endl;*/
    enum(i, 1, n)
        if(l[i] + r[i] >= M)
            no();
}

int main()
{
    cin >> H >> W >> n >> pos.fi >> pos.se;
    string foo;
    cin >> foo;
    enum(i, 1, n)
        aa[i] = trans(foo[i - 1]);
    cin >> foo;
    enum(i, 1, n)
        bb[i] = trans(foo[i - 1]);

    M = W;
    m = pos.se;
    enum(i, 1, n)
    {
        a[i] = aa[i] < 2 ? (aa[i] == 0 ? -1 : 1) : 0;
        b[i] = bb[i] < 2 ? (bb[i] == 0 ? -1 : 1) : 0;
    }
    solve();

    M = H;
    m = pos.fi;
    enum(i, 1, n)
    {
        a[i] = aa[i] >= 2 ? (aa[i] == 2 ? -1 : 1) : 0;
        b[i] = bb[i] >= 2 ? (bb[i] == 2 ? -1 : 1) : 0;
    }
    solve();

    yes();
    return 0;
}

