bool check(int L, int s, char a, char b, string S, string T){
    int N = S.length();
    int left = 1;
    int right = L;
    bool ok = 1;
    for(int i = N-1; i>=0; i--){
        if(i != N-1){ //青木くんのターン
            if(T[i] == a){
                right = min(L,right+1);
            }
            else if(T[i] == b){
                left = max(1,left-1);
            }
        }

        //高橋くんのターン
        if(S[i] == a){
            left = left + 1;
        }
        else if(S[i] == b){
            right = right - 1;
        }

        if(left > right) ok = 0;

    }

    if(s < left || right < s) ok = 0;

    return ok;
}

