ll border( ll r, ll c )
{
  return std::min( { r+1, H-r, c+1, W-c } );
}

bool safe( ll r, ll c )
{ return r >= 0 && r < H && c >= 0 && c < W; }

int main()
{
  std::cin >> H >> W >> N >> sr >> sc >> S >> T;

  --sr, --sc;

  ll r = sr, c = sc;

  rep( i, N )
  {
    ll d = LRUD.find( S[i] );
    ll nr = r+di[d], nc = c+dj[d];

    if( border( nr, nc ) < border( r, c ) )
      r = nr, c = nc;

    if( !safe( r, c ) )
    {
      puts("NO");

      return 0;
    }

    d = LRUD.find( T[i] );
    nr = r+di[d], nc = c+dj[d];

    if( border( nr, nc ) > border( r, c ) )
      r = nr, c = nc;

    if( !safe( r, c ) )
    {
      puts("NO");

      return 0;
    }
  }

  puts("YES");

  return 0;
}

