using namespace std;

bool simulate(
	char chT, char chA, int dxT, int dyT, 
	int H, int W, int N, int sx, int sy, 
	const string &T, const string &A)
{
	int dxA = -dxT;
	int dyA = -dyT;

	for (int i = 0; i < N; ++i) {
		if (T[i] == chT) {
			sx += dxT;
			sy += dyT;
			if (sx < 1 || W < sx || sy < 1 || H < sy) {
				return true;
			}
		}
		if (A[i] == chA) {
			sx = max(1, min(W, sx + dxA));
			sy = max(1, min(H, sy + dyA));
		}
	}
	return false;
}

string solve(int H, int W, int N, int sr, int sc, const string &S, const string &T)
{
	if (simulate('L', 'R', -1, 0, H, W, N, sc, sr, S, T)) {
		return "NO";
	}
	if (simulate('R', 'L', +1, 0, H, W, N, sc, sr, S, T)) {
		return "NO";
	}
	if (simulate('U', 'D', 0, -1, H, W, N, sc, sr, S, T)) {
		return "NO";
	}
	if (simulate('D', 'U', 0, +1, H, W, N, sc, sr, S, T)) {
		return "NO";
	}
	return "YES";
}

