    int sr, sc; cin >> sr >> sc;
    string S, T; cin >> S >> T;
    reverse(ALL(S)); reverse(ALL(T));

    // solve
    pair<int, int> f = make_pair(1, W);
    rep(i, S.size()){
        if(T[i] == 'R') f.first = max(1, f.first - 1);
        if(T[i] == 'L') f.second = min(W, f.second + 1);
        if(S[i] == 'R') f.second--;
        if(S[i] == 'L') f.first++;
        if(f.first > f.second){
