int main() {
#ifdef DEBUG
	ifstream ifs("in.txt");
	cin.rdbuf(ifs.rdbuf());
#endif
	ll H, W, N;
	cin >> H >> W >> N;
	ll sr, sc;
	cin >> sr >> sc;
	sr -= 1; sc -= 1;
	string S, T;
	cin >> S >> T;

	// 高橋君、Sは落としたい, 先手

	///////////////////////////////////////////////
/////////      ヨコ方向        ///////////////
///////////////////////////////////////////////
	int left = -1;
	int right = W;
	FORREV(i, N, N) {
		auto c_s = S[i];
		auto c_t = T[i];
		if (i == N - 1) {
			if (c_s == 'L') left += 1;
			else if (c_s == 'R') right -= 1;
			continue;
		}
		if (c_s == 'L' and (c_t != 'R'))
			left += 1;
		else if (c_s == 'R' and (c_t != 'L')) {
			right -= 1;
		}
	}

	if (sc <= left or right <= sc) {
		cout << "NO" << endl;
		exit(0);
	}


	///////////////////////////////////////////////
/////////      タテ方向        ///////////////
///////////////////////////////////////////////
	int up = -1;
	int down = H;
	FORREV(i, N, N) {
		auto c_s = S[i];
		auto c_t = T[i];
		if (i == N - 1) {
			if (c_s == 'U') up += 1;
			else if (c_s == 'D') down -= 1;
			continue;
		}
		if (c_s == 'D' and (c_t != 'U')) {
			down -= 1;
		}
		else if (c_s == 'U' and (c_t != 'D')) {
			up += 1;
		}
	}

	if (sr <= up or down <= sr) {
		cout << "NO" << endl;
		exit(0);
	}
	cout << "YES" << endl;
	return 0;
}

