  int h, w, n, s_x, s_y; cin >> h >> w >> n >> s_x >> s_y; s_x--; s_y--;
  std::string S, T; cin >> S >> T;
  Vint atLeast(4, 0);
  Wint P(n, Vint(4, 0)), Q(n, Vint(4, 0));
  P[n-1][asserting(S[n-1])]++;
  bool flag = true;
  rREP(i, n-1){
    int p = asserting(S[i]), q = asserting(T[i]);
    int diffL = P[i+1][0] - (Q[i+1][1] - atLeast[0]);
