      else{
        flag = false; break;
      }
    }
    int diffR = P[i+1][1] - (Q[i+1][0] - atLeast[1]);
    if(s_x + diffR == w - 1 and p == 1){
      if(q == 0) atLeast[0]++;
      else{
        flag = false; break;
      }
    }
    int diffU = P[i+1][2] - (Q[i+1][3] - atLeast[2]);
