      if(q == 3) atLeast[3]++;
      else{
        flag = false; break;
      }
    }
    int diffD = P[i+1][3] - (Q[i+1][2] - atLeast[3]);
    if(s_y + diffD == h-1 and p == 3){
      if(q == 2) atLeast[2]++;
      else{
        flag = false; break;
      }
    }
    P[i][p] = P[i+1][p] +1;
    Q[i][q] = Q[i+1][q] + 1;
  }
  if(flag) puts("YES");
  else puts("NO");
  return 0;
}

