bool checkMoveRight() {
	int x = Sx;
	repeat(i, N) {
		if (x == W && S[i] == 'R') return false;
		x += (S[i] == 'R') - (T[i] == 'L');
		if (x < 1) x = 1;
	}
	return true;
}


bool checkMoveLeft() {
	int x = Sx;
	repeat(i, N) {
		if (x == 1 && S[i] == 'L') return false;
		x += -(S[i] == 'L') + (T[i] == 'R');
		if (x > W) x = W;
	}
	return true;
}


bool checkMoveDown() {
	int y = Sy;
	repeat(i, N) {
		if (y == H && S[i] == 'D') return false;
		y += (S[i] == 'D') - (T[i] == 'U');
		if (y < 1) y = 1;
	}
	return true;
}


bool checkMoveUp() {
	int y = Sy;
	repeat(i, N) {
		if (y == 1 && S[i] == 'U') return false;
		y += -(S[i] == 'U') - (T[i] == 'D');
		if (y > H) y = H;
	}
	return true;
}

bool solve() {
	return checkMoveRight() && checkMoveLeft() && checkMoveDown() && checkMoveUp();
}


