      if (S[i] == 'D') {
        if (!(H % 2 == 1 && s == (H + 1) / 2)) {
          s--;
        }
      }
    }
    if (i != N - 1 && H % 2 == 1 && s == (H + 1) / 2) {
      if (SD[i + 1] < SU[i + 1]) {
        s++;
      }
      else {
        s--;
      }
    }
    else if (s >= H / 2) {
      if (T[i] == 'D') {
        s--;
      }
    }
    else if (s < H / 2) {
      if (T[i] == 'U') {
        s++;
      }
    }
    if (s < 1 || s > H) {
      return false;
    }
  }
  return true;
}

