  if (S[0] == 'L') {
    SL[0]++;
  }
  else if (S[0] == 'R') {
    SR[0]++;
  }
  else if (S[0] == 'U') {
    SU[0]++;
  }
  else {
    SD[0]++;
  }
  for (int i = 1; i < N; i++) {
    if (S[i] == 'L') {
      SL[i] = SL[i - 1] + 1;
      SR[i] = SR[i - 1];
      SU[i] = SU[i - 1];
      SD[i] = SD[i - 1];
    }
    else if (S[i] == 'R') {
      SL[i] = SL[i - 1];
      SR[i] = SR[i - 1] + 1;
      SU[i] = SU[i - 1];
      SD[i] = SD[i - 1];
    }
