void solve(long long H, long long W, long long N, long long s_r, long long s_c, std::string S, std::string T) {
	bool ans = true;
	map<int, int> char_to_index;
	char_to_index['L'] = 0;
	char_to_index['R'] = 1;
	char_to_index['U'] = 2;
	char_to_index['D'] = 3;
	LL pos[4] = { s_c - 1, W - s_c, s_r - 1, H - s_r };
	LL max_pos[4] = { W - 1, W - 1, H - 1, H - 1 };
	for (LL i = 0; i < N; ++i) {
