#define bit(x,v) ((ll)x << v)

class BIT {

	static const int MAX_N = 100010;
public:
	BIT() { memset(bit, 0, sizeof(bit)); }
	int bit[MAX_N + 1], n;
	int sum(int i) {
		int s = 0;
		while (i > 0)
		{
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, int x) {
		while (i <= n)
		{
			bit[i] += x;
			i += i & -i;
		}
	}
	void clear() {
		memset(bit, 0, sizeof(bit));
	}
	int a[MAX_N];
	void bable_swap_count() {
		ll ans = 0;
		for (size_t j = 0; j < n; j++)
		{
			ans += j - sum(a[j]);
			add(a[j], 1);
		}
		printf("%lld\n", ans);
	}

	int search(int s, int x) {

		ll half = (s + x) / 2;
		ll sh = sum(x);

		ll sl = sum(half);

		ll st = sum(s);
		if (sh - sl == 0) {
			return x;
		}
		if (sh - sl < x - half) {
			return search(half, x);
		}

		if (sl - st == 0) {
			return half;
		}

		if (sl - st < half - s) {
			return search(s, half);
		}
		return -1;
	}
};
vector<int> es[100010];
ll memo[2][100010];
ll rec(int x, int color, int frm) {

	if (~memo[color][x]) return memo[color][x];
	ll res = 1;
	for (auto v : es[x])
	{
		if (v == frm) continue;
		if (color == 1) {
			res *= rec(v, 0, x);
		}
		else {

			res *= rec(v, 0, x) + rec(v, 1, x);
		}
		res %= INF;
	}

	return memo[color][x] = res;

}
