double cal(double r, double h) {
	return ((r * r * M_PI) * h) / 3.0;
}
double cal2(double x,double r,double h,double b) {
	double first = cal(r, h);
	if (x + h > b) {
		double ph = h - (x + h - b);
		double pr = ((x + h - b) / h) * r;
		first = M_PI * ph * (r * r ) ;
	}
	return first;
}
ll rec2(int x) {

	if (es[x].size() == 0) return 0;
	vector<int> r;
	for (auto v : es[x]) {
		r.push_back(rec2(v));
	}
	sort(r.begin(), r.end());
	reverse(r.begin(), r.end());
	int res = 0;
	for (int i = 1; i <= es[x].size(); i++)
	{
		res = max(res,i + r[i - 1]);
	}
	return res;
}

bool che(string s,string t,int w,char l,char r,int pos) {
	int lm = 0;
	int lp[200010];
	memset(lp, 0, sizeof(lp));
	// Lについて
	for (int i = n - 1; i >= 0; i--)
	{
		if (s[i] == l && t[i] == r) {
			if (lm == 0) {
				lm++;
			}
		}
		else if (s[i] == l) {
			lm++;
			if (lm == w) {
				return false;
			}
		}
		else if (t[i] == r) {
			lm--;
			lm = max(0, lm);
		}
		lp[i] = lm;
	}
	// Rについて
	int rm = w + 1;
	int rp[200010];
	memset(rp, 0, sizeof(rp));
	for (int i = n - 1; i >= 0; i--)
	{
		if (s[i] == r && t[i] ==l) {
			if (rm == w + 1) {
				rm--;
			}
		}
		else if (s[i] == r) {
			rm--;
			if (rm == 1) {
				return false;
			}
		}
		else if (t[i] == l) {
			rm++;
			rm = min(rm, w + 1);
		}
		rp[i] = rm;
	}

	if (lp[0] >= pos || rp[0] <= pos) return false;

	for (size_t i = 0; i < n; i++)
	{
		if (lp[i] >= rp[i]) {
			return false;
		}
	}

	return true;
}
