ll dirX(char c) {
  if (c == 'L')  return -1;
  if (c == 'R')  return 1;
  return 0;
}

ll dirY(char c) {
  if (c == 'D')  return 1;
  if (c == 'U')  return -1;
  return 0;
}

bool myout(ll y, ll x)  {
  return y > H || y < 1 || x > W || x < 1;
}

bool game(char cT, char cA) {
  ll y = sr;
  ll x = sc;
  ll mvTy = dirY(cT);
  ll mvTx = dirX(cT);
  ll mvAy = dirY(cA);
  ll mvAx = dirX(cA);
  for (ll i = 0; i < N; i++) {
    if (S.at(i) == cT) {
      y += mvTy;
      x += mvTx;
      if (myout(y, x))  return true;
    }
    if (T.at(i) == cA)  {
      ll y1 = y + mvAy;
      ll x1 = x + mvAx;
      if (!myout(y1, x1)) {
	y = y1;
	x = x1;
      }
    }
  }
  return false;
}

