        if(t[i]=='R'){
            if(r!=l){
                l++;
            }
            else{
                if(r+rbuf+1<w) rbuf++;
            }
        }
        if(t[i]=='U'){
            if(u!=b){
                b--;
            }
            else{
                if(u-ubuf-1>=0) ubuf++;
            }
        }
        if(t[i]=='D'){
            if(u!=b){
                u++;
            }
            else{
                if(b+bbuf+1<h) bbuf++;
            }
        }
    }
    cout<<"YES"<<endl;
    return 0;
}

