    vector<int> w_dir, w_who, h_dir, h_who;
    for (int i = 0; i < n; i++) {
        switch (S[i]) {
            case 'U':
                h_dir.push_back(-1);
                h_who.push_back(1);
                break;
            case 'D':
                h_dir.push_back(1);
                h_who.push_back(1);
                break;
            case 'L':
                w_dir.push_back(-1);
                w_who.push_back(1);
                break;
            case 'R':
                w_dir.push_back(1);
                w_who.push_back(1);
                break;
            default:;
        }

        switch (T[i]) {
            case 'U':
                h_dir.push_back(-1);
                h_who.push_back(0);
                break;
            case 'D':
                h_dir.push_back(1);
                h_who.push_back(0);
                break;
            case 'L':
                w_dir.push_back(-1);
                w_who.push_back(0);
                break;
            case 'R':
                w_dir.push_back(1);
                w_who.push_back(0);
                break;
            default:;
        }
    }

    if (judge(w_dir, w_who, w, s_c) && judge(h_dir, h_who, h, s_r)) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

