		for(auto i = 0; i < n; ++i){
			if((lr && s[i] == 'R') || (!lr && s[i] == 'D')){
				++sf;
			}
			if((lr && s[i] == 'L') || (!lr && s[i] == 'U')){
				++sb;
			}
			if(sf + sb + 1 > edge || p + sf - tb > edge || p - sb + tf < 1){
				return false;
			}
			if((lr && t[i] == 'R') || (!lr && t[i] == 'D')){
				if(sb > 0){
					--sb;
				}else{
					tf = min(edge - p, tf + 1);
				}
			}
			if((lr && t[i] == 'L') || (!lr && t[i] == 'U')){
				if(sf > 0){
					--sf;
				}else{
					tb = min(p - 1, tb + 1);
				}
			}
		}
		return true;
	};
	cout << (test(true, sc, w) && test(false, sr, h) ? "YES" : "NO") << endl;
	return 0;
}

