void solve() {
  ll H, W, N, sr, sc;
  string S, T;
  cin >> H >> W >> N >> sr >> sc >> S >> T;

  // 1 次元の問題に帰着
  // コマが残れば return される
  auto solve_one_dim = [](ll start, ll limit, VL ss, VL ts) {
    // [l, r] にコマがあれば ok
    ll l = 1;
    ll r = limit;

    repr(i, ts.size()) {
      ll t = ts[i];
      if (t == 1) l = max(l - 1, 1ll);
      if (t == -1) r = min(r + 1, limit);

      ll s = ss[i];
      if (s == 1) r -= 1;
      if (s == -1) l += 1;

      if (r < l) drop("NO");
    }

    if (!(l <= start && start <= r)) drop("NO");
  };

  VL ss_w(N), ts_w(N), ss_h(N), ts_h(N);

  auto fill = [N](VL& w, VL& h, string& str) {
    rep(i, N) {
      char ch = str[i];
      if (ch == 'R') w[i] = 1, h[i] = 0;
      if (ch == 'L') w[i] = -1, h[i] = 0;
      if (ch == 'U') w[i] = 0, h[i] = -1;
      if (ch == 'D') w[i] = 0, h[i] = 1;
    }
  };

  fill(ss_w, ss_h, S);
  fill(ts_w, ts_h, T);

  solve_one_dim(sr, H, ss_h, ts_h);
  solve_one_dim(sc, W, ss_w, ts_w);

  cout << "YES" << endl;
}

