bool solve(int n, int a, string sa, string sb, char ca, char cb, int s) {
	int l=0, r=s+1;
	for(int i=n-1; ~i; --i) {
		if(sb[i]==ca)
			r = min(r+1, s+1);
		if(sb[i]==cb)
			l = max(l-1, 0);
		if(sa[i]==ca)
			++l;
		if(sa[i]==cb)
			--r;
		if(l>=a||a>=r)
			return 0;
	}
	return l<a&&a<r;
}

