void no()
{
  std::cout << "NO" << std::endl;

  exit(0);
}


bool solve(int W, int x, const std::string& S, const std::string& T)
{
  std::string s;

  for (int i = 0, size = S.size(); i < size; i ++) {
    if (S[i] == 'L' || S[i] == 'R')
      s.push_back(S[i]);

    if (T[i] == 'L' || T[i] == 'R')
      s.push_back(tolower(T[i]));
  }

  int N = s.size(), l = 1, r = W;

  for (int i = N - 1; i >= 0; i --) {
    char c = s[i];

    if (c == 'L') {
      l ++;
    }
    else if (c == 'R') {
      r --;
    }
    else if (c == 'l') {
      r = std::max(r + 1, W);
    }
    else {
      assert(c == 'r');

      l = std::max(l - 1, 1);
    }

    if (l > r)
      return false;
  }

  return l <= x && x <= W;
}


