  int H, W, N, sr, sc, xm, xp, ym, yp;

  std::string S, T;

  std::cin >> H >> W >> N >> sr >> sc >> S >> T;

  std::cerr << "H=" << H << " W=" << W << " sr=" << sr << " sc=" << sc << std::endl;

  std::string s(S), t(T);

  if (! solve(W, sc, s, t))
    no();

  for (int i = 0; i < N; i ++) {
    if (s[i] == 'R') {
      s[i] = 'U';
    }
    else if (s[i] == 'L') {
      s[i] = 'D';
    }
    else if (s[i] == 'U') {
      s[i] = 'R';
    }
    else {
      s[i] = 'L';
    }

    if (t[i] == 'R') {
      t[i] = 'U';
    }
    else if (t[i] == 'L') {
      t[i] = 'D';
    }
    else if (t[i] == 'U') {
      t[i] = 'R';
    }
    else {
      t[i] = 'L';
    }
  }

  if (! solve(H, sr, s, t))
    no();

  std::cout << "YES" << std::endl;

  return 0;
}

