struct direction_t {
  constexpr direction_t(int y_, int x_) : y(y_), x(x_) {}
  int y;
  int x;
};
bool operator==(const direction_t& lhs, const direction_t& rhs) {
  return lhs.y == rhs.y && lhs.x == rhs.x;
}

static constexpr direction_t nothing = direction_t(0, 0);
static constexpr direction_t left = direction_t(0, -1);
static constexpr direction_t right = direction_t(0, 1);
static constexpr direction_t up = direction_t(-1, 0);
static constexpr direction_t down = direction_t(1, 0);

struct position_t {
  constexpr position_t(int y_, int x_) : y(y_), x(x_) {}

  int y;
  int x;
};

static std::string const YES = "YES";
static std::string const NO = "NO";

static std::vector<direction_t> sCandidates;
static std::vector<direction_t> tCandidates;

static std::vector<int> lefts;
static std::vector<int> rights;
static std::vector<int> ups;
static std::vector<int> downs;

static int h;
static int w;
static int n;

static int minimax(position_t position, bool turn, int moves) {
  if (n * 2 - moves <= 0) {
    return -1;
  }

  int const movableIdx = n - (moves + 1) / 2;
  if (position.y - ups[movableIdx] >= 0 && position.y + downs[movableIdx] < h &&
      position.x - lefts[movableIdx] >= 0 &&
      position.x + rights[movableIdx] < w) {
    return -1;
  }

  direction_t candidate =
      turn ? sCandidates[moves / 2] : tCandidates[moves / 2];
  if (candidate == nothing) {
    return minimax(position, !turn, moves + 1);
  }
  position_t const newPosition =
      position_t(position.y + candidate.y, position.x + candidate.x);
  if (newPosition.y < 0 || h <= newPosition.y || newPosition.x < 0 ||
      w <= newPosition.x) {
    if (turn) {
      return 1;
    } else {
      return minimax(position, !turn, moves + 1);
    }
  }

  int const distance = abs(position.y - h / 2) + abs(position.x - w / 2);
  int const newDistance =
      abs(newPosition.y - h / 2) + abs(newPosition.x - w / 2);
  if (newDistance < distance) {
    if (turn) {
      if (minimax(newPosition, !turn, moves + 1) > 0) {
        return 1;
      }
      return minimax(position, !turn, moves + 1);
    } else {
      if (minimax(position, !turn, moves + 1) < 0) {
        return -1;
      }
      return minimax(newPosition, !turn, moves + 1);
    }
  } else {
    if (turn) {
      if (minimax(position, !turn, moves + 1) > 0) {
        return 1;
      }
      return minimax(newPosition, !turn, moves + 1);
    } else {
      if (minimax(newPosition, !turn, moves + 1) < 0) {
        return -1;
      }
      return minimax(position, !turn, moves + 1);
    }
  }
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> h;
