bool f(int n, int pos , int lim)
{
    int left = 1 , right = lim ;

    for(int i=n ; i>=1 ; i--)
    {
        if( b[i]== 1 ) left-- ;
        if( b[i]==-1 ) right++ ;

        left = max(left,1) ;
        right = min(right,lim) ;

        if(a[i]==1) right-- ;
        if(a[i]==-1) left++ ;

        if( right<left ) return 0 ;
    }
    if( left <= pos && pos <= right ) return true ;
    return false ;
}

