bool _common(int W, int N, int x0, vi& u, vi& v) {
    int llim = 0, rlim = W;

    for (int i=N-1; i>=0; --i) {
        if (i < N-1) {
            if (v[i] == -1 && rlim < W) ++rlim;
            else if (v[i] == 1 && llim > 0) --llim;
        }

        if (u[i] == 1 && rlim > 0) --rlim;
        else if (u[i] == -1 && llim < W) ++llim;

        if (llim >= rlim) return false;
    }

    return IN(x0, llim, rlim-1);
}

bool _horiz(int W, int N, int sc, string& s,string& t) {
    vi u(N,0), v(N,0);
    rep(i,N){
        if (s[i]=='R') u[i]=1;
        else if (s[i]=='L') u[i]=-1;

        if (t[i]=='R') v[i]=1;
        else if (t[i]=='L') v[i]=-1;
    }
    return _common(W, N, sc-1, u, v);
}

bool _vert(int H, int N, int sr, string& s,string& t) {
    vi u(N,0), v(N,0);
    rep(i,N){
        if (s[i]=='D') u[i]=1;
        else if (s[i]=='U') u[i]=-1;

        if (t[i]=='D') v[i]=1;
        else if (t[i]=='U') v[i]=-1;
    }
    return _common(H, N, sr-1, u, v);
}

bool solve(int H,int W,int N, int sr,int sc, string& s,string& t) {
    return _horiz(W,N, sc, s,t) && _vert(H,N, sr, s,t);
}

