      if(x==1) {
        l = max(1,l-1);
      } else {
        r = min(N,r+1);
      }
    } else {
      if(x==1) {
        r--;
      } else {
        l++;
      }
    }
    if(l>r) {
      return false;
    }
  }
  return l<=p&&p<=r;
}

