#include <bits/stdc++.h>
using namespace std;

bool is_valid(int lower_bound, int upper_bound, string S, string T, const char plus, const char minus, int start, int n)
{
    int minimum = 1;
    int maximum = upper_bound;
    if (S.back() == plus)
    {
        upper_bound--;
    }
    if (S.back() == minus)
    {
        lower_bound++;
    }

    int idx = n - 2;
    while (idx >= 0)
    {
        if (lower_bound > upper_bound)
        {
            return false;
        }
        if (T[idx] == plus)
        {
            lower_bound--;
        }
        if (T[idx] == minus)
        {
            upper_bound++;
        }
        upper_bound = min(upper_bound, maximum);
        lower_bound = max(lower_bound, minimum);

        if (S[idx] == plus)
        {
            upper_bound--;
        }
        if (S[idx] == minus)
        {
            lower_bound++;
        }
        upper_bound = min(upper_bound, maximum);
        lower_bound = max(lower_bound, minimum);

        idx--;
    }
    if (lower_bound > start || start > upper_bound)
    {
        return false;
    }
    if (lower_bound > upper_bound)
    {
        return false;
    }
    return true;
}

int main()
{
    int H, W, N, sr, sc;
    cin >> H >> W >> N >> sr >> sc;

    string S, T;
    cin >> S >> T;

    if (!is_valid(1, H, S, T, 'U', 'D', sr, N))
    {
        cout << "NO" << endl;
        return 0;
    }

    if (!is_valid(1, W, S, T, 'R', 'L', sc, N))
    {
        cout << "NO" << endl;
        return 0;
    }

    cout << "YES" << endl;
}

#include <iostream>
using namespace std;
int main(void){
    int H, W, N; cin >> H >> W >> N;
    int sh, sw; cin >> sh >> sw;
    string S; cin >> S;
    string T; cin >> T;
    string SS;
    for (int i = 0; i < N; i++) {
        SS.push_back(S[i]);
        SS.push_back('#');
    }
    for (int i = 0; i < N; i++) {
        SS[2*i+1] = T[i];
    }

    int lh = 1;
    int uh = H;
    int lw = 1;
    int uw = W;

    int ans = 1;
    for (int i = 2*N-1; 0 <= i; i--) {
        if (i%2) {
            if (SS[i] == 'U') {
                uh++;
                uh = min(H, uh);
            }
            if (SS[i] == 'D') {
                lh--;
                lh = max(1, lh);
            }
            if (SS[i] == 'L') {
                uw++;
                uw = min(W, uw);
            }
            if (SS[i] == 'R') {
                lw--;
                lw = max(1, lw);
            }
        } else {
            if (SS[i] == 'U') {
                lh++;
            }
            if (SS[i] == 'D') {
                uh--;
            }
            if (SS[i] == 'L') {
                lw++;
            }
            if (SS[i] == 'R') {
                uw--;
            }
        }
        if (uh - lh < 0 || uw - lw < 0) ans = 0;
    }
    if (!(lw <= sw && sw <= uw && lh <= sh && sh <= uh)) ans = 0;

    if (ans) cout << "YES" << endl;
    else cout << "NO" << endl;
}

