bool solve(int t, int mx, int sx){
    //Nターン後は、
    //[0, N-1]の区間に入っていられるかどうか
    char plus = 'D';
    char minu = 'U';
    if(t == 1){
        plus = 'R';
        minu = 'L';
    }
    // [l, r)の区間
    int l = 0, r = mx;
    //cerr<<endl;
    for(int i = N-1;i >= 0;i--){
        //cerr << "start: " <<l << " " << r <<endl;
        if(l == r)return false;
        if(T[i] == minu){
            r++;
            chmin(r, mx);
        }
        else if(T[i] == plus){
            l--;
            chmax(l, 0);
        }
        //cerr << l << " " << r << endl;
        if(S[i] == plus){
            r--;
        }
        else if(S[i] == minu){
            l++;
        }
        //cerr << l << " " << r << endl;
    }
    //cerr << "finished" << endl;
    //cerr << sx << endl;
    if(sx < l || r <= sx){
        return false;
    }
    return true;
}
