bool judge(int cur0, int lm, char ps, char ng) {
  int cur = cur0;
  for (int i = 0; i < n; i++) {
    if (s[i] == ng) cur--;
    if (cur < 0) {
      return false;
    }
    if (t[i] == ps && cur < lm - 1) cur++;
  }
  cur = cur0;
  for (int i = 0; i < n; i++) {
    if (s[i] == ps) cur++;
    if (cur >= lm) {
      return false;
    }
    if (t[i] == ng && cur > 0) cur--;
  }
  return true;
}

