}

#ifdef LOCAL
#define debug(...) cerr << "[" << #__VA_ARGS__ << "]:", debug_out(__VA_ARGS__)
#else
#define debug(...) 42
#endif

bool Stays(int len, int pos, vector<int> mv, vector<int> who) {
  debug(len, pos, mv, who);
  int L = 1;
  int R = len;
  for (int it = (int) mv.size() - 1; it >= 0; it--) {
    int m = mv[it];
    int w = who[it];
    if (w == 1) {
      if (m == -1) R = min(R + 1, len);
      else L = max(L - 1, 1);
    } else {
      if (m == -1) L++;
      else R--;
    }
    debug(it, L, R);
    if (L > R) return false;
  }
  return (L <= pos && pos <= R);
}

