using namespace std;

bool solve(int n, int a, string sa, string sb, char ca, char cb, int s) {
	int l = 0, r = s+1;
	for(int i = n-1; i >= 0; i--) {
		if(sb[i] == ca) {
			r = min(r+1, s+1);
		}
		if(sb[i] == cb) {
			l = max(l-1, 0);
		}
		if(sa[i] == ca) {
			l = l+1;
		}
		if(sa[i] == cb) {
			r = r-1;
		}
		if(l >= r) {
			return 0;
		}
	}
	return a > l && a < r;
}

