bool can_drop(int sx, int sy, int lx, int rx, int uy, int dy) {
    //std::cout << sx << " " << sy << " " << lx << " "<< rx << " "<< uy << " " << dy << " " <<std::endl;
    if (lx >= sx || rx <= 1 || rx <= lx) return true;
    if (uy >= sy || dy <= 1 || dy <= uy) return true;
    return false;
}

int main(int argc, char** argv) {
    int h, w, n;
    cin >> h >> w >> n;
    int sx, sy;
    cin >> sy >> sx;
    std::string c1, c2;
    cin >> c1 >> c2;

    int lx{0}, rx{w+1}, uy{0}, dy{h+1};
    auto it_1 = c1.rbegin(), it_2 = c2.rbegin();
    switch(*it_1) {
    case 'L':
        ++lx;
        break;
    case 'R':
        --rx;
        break;
    case 'U':
        ++uy;
        break;
    case 'D':
        --dy;
        break;
    }
    ++it_1; ++it_2;
    if (can_drop(sx, sy, lx, rx, uy, dy)) {
        cout << "NO" << endl;
        return 0;
    }

    for (;
         it_1 != c1.rend() && it_2 != c2.rend();
         ++it_1, ++it_2) {
        switch(*it_2) {
        case 'L':
            ++rx;
            break;
        case 'R':
            --lx;
            break;
        case 'U':
            ++dy;
            break;
        case 'D':
            --uy;
            break;
        }

        switch(*it_1) {
        case 'L':
            ++lx;
            break;
        case 'R':
            --rx;
            break;
        case 'U':
            ++uy;
            break;
        case 'D':
            --dy;
            break;
        }
        if (can_drop(sx, sy, lx, rx, uy, dy)) {
            cout << "NO" << endl;
            return 0;
        }
    }

    cout << ((sx <= lx || rx <= sx || sy <= uy || dy <= sy) ? "NO": "YES") << endl;

    return 0;
}

