struct Graph {
	int n;
	std::vector<std::vector<std::pair<int, s64> > > hen;

	// result of Warshall–Floyd
	std::vector<std::vector<s64> > WF;
	bool wf_completed = false;

	// result of dijkstra and Bellman-Ford/SPFA
	std::vector<std::vector<s64> > SSSP;
	std::set<int> sssp_completed;

	// result of dfs(reachable check)
	std::vector<std::vector<bool> > DFS;
	std::set<int> dfs_completed;

	Graph(int n) { // O(N)
		hen.resize(n, std::vector<std::pair<int, s64> >());
		SSSP.resize(n, std::vector<s64>());
		DFS.resize(n, std::vector<bool>());
		this->n = n;
	}

	// return the position of negative cycle(-1 if none)
	int bf(int k) {
		sssp_completed.insert(k);
		SSSP[k].resize(n,LINF);
		SSSP[k][k] = 0;
		FOR(i,n-1) {
			bool updated = false;
			FOR(j,n) {
				for (auto l : hen[j]) {
					if (SSSP[k][j] != LINF && SSSP[k][l.fi] > SSSP[k][j] + l.se)
						SSSP[k][l.fi] = SSSP[k][j] + l.se, updated = true;
				}
			}
			if (!updated) break;
		}

		FOR(j,n) {
			for (auto l : hen[j]) {
				if (SSSP[k][j] != LINF && SSSP[k][l.fi] > SSSP[k][j] + l.se) {
					return j; // negative loop
				}
			}
		}
		return -1;
	}

	int spfa(int k) {
		std::vector<bool> inque(n,false);
		std::vector<int> updated(n,0);

		sssp_completed.insert(k);
		SSSP[k].resize(n,LINF);
		SSSP[k][k] = 0;

		std::queue<int> que; inque[k] = true;que.push(k);
		while (que.size()) {
			int i = que.front(); que.pop();
			for (auto j : hen[i]) {
				if (SSSP[k][j.fi] > SSSP[k][i] + j.se) {
					SSSP[k][j.fi] = SSSP[k][i] + j.se;
					updated[j.fi]++;
					if (updated[j.fi] > n) return j.fi;
					if (!inque[j.fi]) {
						inque[j.fi] = true;
						que.push(j.fi);
					}
				}
			}
			inque[i] = false;
		}
		return -1;
	}

	void dij(int k) { // O(n+mlogm)
		SSSP[k].resize(n);
		fill(all(SSSP[k]), LINF);
		SSSP[k][k] = 0;
		using T = std::pair<s64, int>;
		std::priority_queue<T, std::vector<T>, std::greater<T> > que;
		que.push({0,k});
		while(que.size()) {
			auto i = que.top(); que.pop();
			for (auto j : hen[i.se]) {
				if (SSSP[k][j.fi] > i.fi + j.se) {
					SSSP[k][j.fi] = i.fi + j.se;
					que.push({SSSP[k][j.fi], j.fi});
				}
			}
		}
		sssp_completed.insert(k);
	}

	void wf() { // O(n^3)
		WF.resize(n);
		fill(all(WF), std::vector<s64>(n,LINF));
		FOR(i,n) {
			WF[i][i] = 0;
			for (auto j : hen[i]) {
				WF[i][j.fi] = j.se;
			}
		}
		FOR(k,n) {
			FOR(i,n) {
				FOR(j,n) {
					if (WF[i][k] != LINF && WF[k][j] != LINF) {
						WF[i][j] = std::min(WF[i][j], WF[i][k] + WF[k][j]);
					}
				}
			}
		}
		wf_completed = true;
	}

	void dfs(int from) { // O(N+M)
		DFS[from].resize(n, false);
		DFS[from][from] = true;
		std::queue<int> que; que.push(from);
		while(que.size()) {
			auto i = que.front(); que.pop();
			for (auto j : hen[i]) {
				if (!DFS[from][j.fi]) {
					DFS[from][j.fi] = true;
					que.push(j.fi);
				}
			}
		}
		dfs_completed.insert(from);
	}

	bool reachable(int from, int to) {
		assert(dfs_completed.count(from));
		return DFS[from][to];
	}

	std::pair<bool,s64> shortest(int from, int to) {
		assert(wf_completed || sssp_completed.count(from));
		if (wf_completed)
			return {WF[from][to] != LINF, WF[from][to]};
		else if (sssp_completed.count(from))
			return {SSSP[from][to] != LINF, SSSP[from][to]};
		else return {false, 0}; // should not reached
	}

	void add_hen(int from, int to, s64 cost, bool muki) {
		hen[from].push_back({to, cost});
		if (!muki) hen[to].push_back({from, cost});
	}
};
// Graph.dfs : O(N)
// Graph.dij : O(N+MlogM)
// Graph.bf  : O(NM)
// Graph.spfa: O(NM) faster
// Graph.wf  : O(N^3)
