bool stay(int len, int start, vector<int> mv, vector<int> wh) {
  int mn = 0, mx = len - 1;
  RREP(i, mv.size()) {
    if (wh[i]) {  // 青木君のターン
      if (mv[i] == -1)
        mx = min(len - 1, mx + 1);
      else
        mn = max(0, mn - 1);
    } else {  // 高橋君のターン
      if (mv[i] == -1)
        mn++;
      else
        mx--;
    }
    if (mn > mx) return false;
  }
  return mn <= start && start <= mx;
}

