	// Aoki's operation
	int uc = 0, dc = 0, lc = 0, rc = 0;
	bool win = 1;
	for (int i = 0; i < n; i++)
	{
		if (s[i] == 'L')
		{
			l = max(l-1, 1);
		}
		if (s[i] == 'R')
		{
			r = min(r+1, w);
		}
		if (s[i] == 'U')
		{
			u = max(u-1, 1);
		}
		if (s[i] == 'D')
		{
			d = min(d+1, h);
		}
		if (t[i] == 'L')
		{
			lc++;
		}
		if (t[i] == 'R')
		{
			rc++;
		}
		if (t[i] == 'U')
		{
			uc++;
		}
		if (t[i] == 'D')
		{
			dc++;
		}
		win &= r >= lc &&l >= rc && u >= dc && d >= uc;
	}
	cout << (win ? "YES" : "NO") << endl;
}

