	at   = st;
	high = st;
	rep(i, n) {
		if (s[i] == 'D') {
			at.F++;
			chmax(high.F, at.F);
		} else if (s[i] == 'R') {
			at.S++;
			chmax(high.S, at.S);
		}

		if (t[i] == 'U' and at.F - 1 > 0) {
			at.F--;
		} else if (t[i] == 'L' and at.S - 1 > 0) {
			at.S--;
		}
	//	clog << at << endl;
	}
	if (high.F > h or high.S > w) {
		ans = false;
	}
	clog << high << endl << endl;

	cout << solve(ans) << endl;
}

