namespace n91 {
bool solve() {
  usize h, w, n;
  std::cin >> h >> w >> n;
  usize x, y;
  std::cin >> x >> y;
  --x;
  --y;
  std::string s, t;
  std::cin >> s >> t;

  usize u = 0, d = h;
  for (const auto i : revrep(0, n)) {
    if (t[i] == 'U') {
      if (d != h) {
        ++d;
      }
    }
    if (t[i] == 'D') {
      if (u != 0) {
        --u;
      }
    }
    if (s[i] == 'U') {
      if (u != h) {
        ++u;
      }
    }
    if (s[i] == 'D') {
      if (d != 0) {
        --d;
      }
    }
    if (d <= u) {
      return false;
    }
  }
  if (x < u || d <= x) {
    return false;
  }

  usize l = 0, r = w;
  for (const auto i : revrep(0, n)) {
    if (t[i] == 'L') {
      if (r != w) {
        ++r;
      }
    }
    if (t[i] == 'R') {
      if (l != 0) {
        --l;
      }
    }
    if (s[i] == 'L') {
      if (l != w) {
        ++l;
      }
    }
    if (s[i] == 'R') {
      if (r != 0) {
        --r;
      }
    }
    if (r <= l) {
      return false;
    }
  }
  if (y < l || r <= y) {
    return false;
  }

  return true;
}

void main_() { std::cout << (solve() ? "YES" : "NO") << std::endl; }

