        vector<int> up(n + 1, h), down(n + 1, -1);
        for(int i = n - 1; i >= 0; --i){
            // dec(R)
            if(s[i] == p){
                chmax(down[i], 0);
                if(t[i] != q)
                    chmax(down[i], down[i + 1] + 1);
            }
