                chmin(up[i], h - 1);
                if(t[i] != p)
                    chmin(up[i], up[i + 1] - 1);
            }
            // t(L), s(!=R)
            if(t[i] == p && s[i] != q){
                chmax(down[i], down[i + 1] - 1);
            }
            if(t[i] == q && s[i] != p){
                chmin(up[i], up[i + 1] + 1);
            }
