bool stays(string &S, string &T, char back, char fwd, int H, int pos){
  int L=1; int R=H;
  int N=S.size();
  for(int i=N-1;i>=0;--i){
    char a = T[i];
    if(a==back){
      R = min(R+1,H);
    } else if (a==fwd){
      L = max(L-1,1);
