const int N = 200'009;

int n;
int a[N];
int b[N];
int sum[N];
int mx[N];

void work(int len, int x) {
  for (int i = 0; i < n; ++i) {
    sum[i] = i == 0 ? x : sum[i - 1];
    if (a[i] == b[i]) {
      sum[i] += a[i];
      mx[i] = sum[i];
    } else
    if (a[i] != 0 && b[i] != 0) {
      mx[i] = sum[i] + (a[i] == 1);
    } else
    if (a[i] != 0) {
      if (a[i] == 1) {
        ++sum[i];
      }
      mx[i] = sum[i];
    } else {
      // b[i] != 0
      if (b[i] == -1) {
        --sum[i];
      }
      mx[i] = sum[i];
    }
  }
  for (int i = n - 2; i >= 0; --i) {
    mx[i] = max(mx[i], mx[i + 1]);
  }
  int add = 0;
  int sum_pos = x, sum_neg = x;
  for (int i = 0; i < n; ++i) {
    if (a[i] == b[i]) {
      sum_pos += a[i];
      sum_neg += a[i];
      if (sum_pos > len || sum_neg < 1) {
        no();
      }
    } else
    if (a[i] != 0 && b[i] != 0) {
      if (a[i] == 1) {
        if (sum_pos + 1 > len) {
          no();
        }
      } else {
        // -1
        if (sum_neg - 1 < 1) {
          no();
        }
      }
    } else
    if (a[i] != 0) {
      if (a[i] == 1) {
        ++sum_pos;
      } else {
        --sum_neg;
      }
      if (sum_pos > len || sum_neg < 1) {
        no();
      }
    } else {
      // b[i] != 0
      if (b[i] == -1) {
        if (i + 1 < n) {
          if (mx[i] + add + 1 <= len) {
            ++add;
          } else {
            --sum_pos;
            --sum_neg;
            if (sum_pos > len || sum_neg < 1) {
              no();
            }
          }
        }
      }
    }
  }
}

