bool solve(int len, int pos, vector<int> v, vector<bool> f)
{
    int L = 1, R = len;
    for (int i = v.size() - 1; i >= 0; i--)
    {
        if (f[i])
        {
            if (v[i] == 1)
                R--;
            else
                L++;
        }
        else
        {
            if (v[i] == 1)
                L = max(L - 1, 1LL);
            else
                R = min(R + 1, len);
        }
        if (L > R)
            return false;
    }
    return (L <= pos && pos <= R);
}

