bool solve(int x, int r, vi a, vi b) {
	int n = a.size();
	int l = -1;
	Loopr(i, n) {
		if (b[i] == 1) {
			if (l >= 0) l--;
		}
		else if (b[i] == -1) {
			if (r <= n - 1) r++;
		}
		if (a[i] == 1) {
			r--;
		}
		else if (a[i] == -1) {
			l++;
		}
		if (r - l <= 1) return true;
	}
	if (l >= x || r <= x) return true;
	return false;
}

