using namespace std;

int max_subsequence(vector<int> xs) {
    int hi = 0;
    int current_lo = 0;
    int current_sum = 0;
    for (auto x : xs) {
        current_sum += x;
        current_lo = min(current_lo, current_sum);
        hi = max(hi, current_sum - current_lo);
    }
    return hi;
}


