#define MAX_N (200000)
#define SIZE_BUF (30)

using namespace std;

enum Dir { L, R, U, D };

Dir char_to_dir(char c) {
  switch (c) {
    case 'L':
      return L;
    case 'R':
      return R;
    case 'U':
      return U;
    case 'D':
      return D;
    default:
      printf("Something is wrong...\n");
      return L;
  }
}

int main(int argc, char *argv[]) {
  // read inputs
  int H, W, N, sr, sc;
  char S[MAX_N + 1], T[MAX_N + 1], buf[SIZE_BUF];
  scanf("%d %d %d %d %d", &H, &W, &N, &sr, &sc);
  scanf("%s", S);
  scanf("%s", T);
  sr--;  // NOTE : modified input
  sc--;  // NOTE : modified input
  // printf("%s\n", S);
  // printf("%s\n", T);

  // maximum steps in each direction
  int max_steps[4];
  max_steps[L] = sc;
  max_steps[R] = W - sc - 1;
  max_steps[U] = sr;
  max_steps[D] = H - sr - 1;
  // printf("max_steps:");
  // for (int dir = 0; dir < 4; dir++) {
  //   printf(" %d", max_steps[dir]);
  // }
  // printf("\n");

  // solve dp
  int ans = 1;
  int dpss[MAX_N + 1][4];
  // initialize
  for (int dir = 0; dir < 4; dir++) {
    dpss[0][dir] = 0;
  }
  // update
  for (int i = 0; i < N; i++) {
    const Dir dt = char_to_dir(S[i]), da = char_to_dir(T[i]);
    // printf("i = %d, dt = %d, da = %d\n", i, dt, da);
    // left
    dpss[i + 1][L] = dpss[i][L] + (dt == L ? 1 : 0);
    if (dpss[i + 1][L] > max_steps[L]) {
      ans = 0;
      break;
    }
    dpss[i + 1][L] += (da == R ? -1 : 0);
    dpss[i + 1][L] = max(dpss[i + 1][L], -max_steps[R]);
    // right
    dpss[i + 1][R] = dpss[i][R] + (dt == R ? 1 : 0);
    if (dpss[i + 1][R] > max_steps[R]) {
      ans = 0;
      break;
    }
    dpss[i + 1][R] += (da == L ? -1 : 0);
    dpss[i + 1][R] = max(dpss[i + 1][R], -max_steps[L]);
    // up
    dpss[i + 1][U] = dpss[i][U] + (dt == U ? 1 : 0);
    if (dpss[i + 1][U] > max_steps[U]) {
      ans = 0;
      break;
    }
    dpss[i + 1][U] += (da == D ? -1 : 0);
    dpss[i + 1][U] = max(dpss[i + 1][U], -max_steps[D]);
    // down
    dpss[i + 1][D] = dpss[i][D] + (dt == D ? 1 : 0);
    if (dpss[i + 1][D] > max_steps[D]) {
      ans = 0;
      break;
    }
    dpss[i + 1][D] = (da == U ? -1 : 0);
    dpss[i + 1][D] = max(dpss[i + 1][D], -max_steps[U]);
    // print
    // printf("i + 1 = %d:", i + 1);
    // for (int dir = 0; dir < 4; dir++) {
    //   printf(" %d", dpss[i + 1][dir]);
    // }
    // printf("\n");
  }

