bool win(vvi v, int n, int x) {
  int r = n + 1, l = 0;
  for (int i = (int)v[0].size() - 1; i >= 0; --i) {
    int nr = n + 1, nl = 0;
    if (v[0][i] == 1) {
      nr = n;
    }
    if (v[0][i] == -1) {
      nl = 1;
    }
    nr = min(nr, r - max(0, v[0][i]) - min(0, v[1][i]));
    nl = max(nl, l - min(0, v[0][i]) - max(0, v[1][i]));
    l = nl, r = nr;
//    cerr << i << ' ' << l << ' ' << r << ' ' << x << endl;
    if (l >= r - 1) break;
  }
  return x <= l || x >= r;
}

