using namespace std;
typedef long long ll;
#define int ll

#define REP(i,n) for(int i=0;i<n;++i)
#define SORT(name) sort(name.begin(), name.end())
#define ZERO(p) memset(p, 0, sizeof(p))
#define MINUS(p) memset(p, -1, sizeof(p))

const ll LLINF = (1LL<<60);
const int INF = (1LL<<30);
const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_N 200010

enum Direction { Up = 0, Down, Left, Right };

ll H, W, N;
ll Sr, Sc;
string S, T;

pair<ll, ll> dp_w[2][MAX_N];
pair<ll, ll> dp_h[2][MAX_N];

// S か T が st で、 S[i]/T[i] をチェックしているときの、
// はみ出ることがない範囲
pair<ll, ll> dfs_w(ll st = 0, ll i = 0) {
    if(i >= N) {
        return make_pair(0, W-1);
    }

    pair<ll, ll>& ret = dp_w[st][i];
    if(ret.first != LLINF && ret.second != LLINF) { return ret; }


    ll next_st = (st == 0) ? 1 : 0;
    ll next_i = (st == 0) ? i : (i + 1);
    ret = dfs_w(next_st, next_i);

    if(st == 0) {   // S を見る
        if(S[i] == 'R') {
            // 右側の OK 範囲が -1
            ret.second--;
        }
        else if(S[i] == 'L') {
            // 左側の OK 範囲が +1
            ret.first++;
        }
    }
    else {  // T を見る
        if(T[i] == 'R') {
            // 左側の OK 範囲が -1
            if(ret.first > 0) { ret.first--; }
        }
        else if(T[i] == 'L') {
            // 右側の OK 範囲が +1
            if(ret.second < W-1) { ret.second++; }
        }
    }

    return ret;
}
pair<ll, ll> dfs_h(ll st = 0, ll i = 0) {
    if(i >= N) { return make_pair(0, H-1); }

    pair<ll, ll>& ret = dp_h[st][i];
    if(ret.first != LLINF && ret.second != LLINF) { return ret; }

    ll next_st = (st == 0) ? 1 : 0;
    ll next_i = (st == 0) ? i : (i + 1);
    ret = dfs_h(next_st, next_i);

    if(st == 0) {
        if(S[i] == 'D') { ret.second--; }
        else if(S[i] == 'U') { ret.first++; }
    }
    else {
        if(T[i] == 'D') { if(ret.first > 0) { ret.first--; } }
        else if(T[i] == 'U') { if(ret.second < H-1) { ret.second++; } }
    }
    return ret;
}

signed main()
{
    cin >> H >> W >> N >> Sr >> Sc >> S >> T;
    Sr--; Sc--;

    REP(i, 2) {
        REP(j, N) {
            dp_w[i][j] = make_pair(LLINF, LLINF);
            dp_h[i][j] = make_pair(LLINF, LLINF);
        }
    }

    dfs_w();
    dfs_h();

    // dfs の結果範囲がなくなっている or i = 0時点での範囲が Sr/Sc の外なら、
    // 高橋君の勝ち
    if( !(dp_w[0][0].first <= Sc && Sc <= dp_w[0][0].second &&
          dp_h[0][0].first <= Sr && Sr <= dp_h[0][0].second) )
    {
        printf("NO\n");
        return 0;
    }
    REP(i, 2) {
        REP(j, N) {
            if(dp_w[i][j].first > dp_w[i][j].second || dp_h[i][j].first > dp_h[i][j].second)
            {
                printf("NO\n");
                return 0;
            }
        }
    }

    printf("YES\n");
    return 0;
}

