  vll ub(N), lb(N);
  if (S[N - 1] == u) {
    ub[N - 1] = x - 1;
    lb[N - 1] = 1;
  } else if (S[N - 1] == l) {
    ub[N - 1] = x;
    lb[N - 1] = 2;
  } else {
    ub[N - 1] = x;
    lb[N - 1] = 1;
