        ub[i] = ub[i + 1] - 1;
      }
      ub[i] = min(ub[i], x - 1);
      lb[i] = lb[i + 1];
    } else if (S[i] == l) {
      if (T[i] == u) {
        lb[i] = lb[i + 1];
      } else {
        lb[i] = lb[i + 1] + 1;
      }
      lb[i] = max(lb[i], 2LL);
      ub[i] = ub[i + 1];
