	cin >> Sx >> Sy;
	cin >> S >> T;
	bool ans = 1;
	int u1 = 0, u2 = 0, d1 = 0, d2 = 0, r1 = 0, r2 = 0, l1 = 0, l2 = 0;
	for (int i = 0; i < N; i++) {
		if (S[i] == 'U') u1++;
		else if (S[i] == 'R') r1++;
		else if (S[i] == 'D') d1++;
		else l1++;

		if (Sx + u1 - min(d2, Sx - 1) > H) ans = 0;
		if (Sx - d1 + min(u2, H - Sx) < 1) ans = 0;
		if (Sy + r1 - min(l2, Sy - 1) > W) ans = 0;
		if (Sx - l1 + min(r2, W - Sy) < 1) ans = 0;

		if (T[i] == 'U') u2++;
		else if (T[i] == 'R') r2++;
		else if (T[i] == 'D') d2++;
		else l2++;

		if (Sx + u1 - min(d2, Sx - 1) > H) ans = 0;
		if (Sx - d1 + min(u2, H - Sx) < 1) ans = 0;
		if (Sy + r1 - min(l2, Sy - 1) > W) ans = 0;
		if (Sx - l1 + min(r2, W - Sy) < 1) ans = 0;
	}
	if (ans) printf("YES\n");
	else printf("NO\n");
}

