bool check(int opt,int x,int y)
{
	int siz=0;
	for(int i=1;i<=n;i++)
	{
		int op=trs(s[i]),tx,ty;
		if(op==opt)tx=x+dx[op],ty=y+dy[op];else tx=x,ty=y;
		if((tx<=0||tx>h)||(ty<=0||ty>w))
		{
			if(siz)siz--;
			else return 0;
		}else x=tx,y=ty;
		if((trs(t[i])^opt)==2)
			if(opt==0)siz=min(siz+1,x-1);
			else if(opt==1)siz=min(siz+1,y-1);
			else if(opt==2)siz=min(siz+1,h-x);
			else siz=min(siz+1,w-y);
	}
	return 1;
}
