string g;
map<char, pii> mp = {
  {'R', {0, 1}},
  {'L', {0, -1}},
  {'U', {-1, 0}},
  {'D', {1, 0}},
};

bool check(int y, int x) {
  return y < 0 or y > H or x < 0 or x > W;
}

int dfs(int idx, int yy, int xx) {
  if (check(yy, xx)) {
  dbg3(idx, yy, xx)
  // dbg3(idx, yy, xx)
    // dbg2(yy, H)
    // dbg2(xx, W)
    return 1;
  }
  if (idx >= 2*N) {
    return 0;
  }

  int ret = 0;

  if (idx % 2 == 0) { // 先手
    // no
    ret |= dfs(idx+1, yy, xx);
    // yes
    int ny = yy + mp[g[idx]].first;
    int nx = xx + mp[g[idx]].second;
    ret |= dfs(idx+1, ny, nx);
  } else { // 後手
    // no
    ret |= dfs(idx+1, yy, xx);
    // yes
    int ny = yy + mp[g[idx]].first;
    int nx = xx + mp[g[idx]].second;
    if (ny < 0) ny = 0;
    if (ny > H) ny = H;
    if (nx < 0) nx = 0;
    if (ny > W) nx = W;
    ret |= dfs(idx+1, ny, nx);
  }

  // dbg(ret)
  return ret;
}

