int check(int len,int ini,string S,string T,string c) {
	int curmi = 1;
	int curma = len;
	for (int i = N - 1; i >= 0; i--) {
		if (T[i] == c[0]) {
			curma = min(len, curma + 1);
		}
		else if (T[i] == c[1]) {
			curmi = max(1, curmi - 1);
		}
		if (S[i] == c[0]) {
			curmi = curmi + 1;
		}
		else if (S[i] == c[1]) {
			curma = curma - 1;
		}
		if (curmi > curma)return 0;
		if (curmi > len)return 0;
		if (curma < 1)return 0;
	}
	if (curmi <= ini && ini <= curma)return 1;
	else return 0;
}

