	if ((T[idx] == 'L' && x == 1) ||
		(T[idx] == 'R' && x == W) ||
		(T[idx] == 'U' && y == 1) ||
		(T[idx] == 'D' && y == H)) return guchoku_1(y, x, idx + 1); // 動かすとtakahashiが勝つので動かさないのが最善

	return guchoku_1(y, x, idx + 1) || guchoku_1(y + c2vy(T[idx]), x + c2vx(T[idx]), idx + 1);
}


// takahashi
bool guchoku_1(int y, int x, int idx) {
	if ((S[idx] == 'L' && x == 1) ||
		(S[idx] == 'R' && x == W) ||
		(S[idx] == 'U' && y == 1) ||
		(S[idx] == 'D' && y == H)) return false; // takahashiが勝つ

	return guchoku_2(y, x, idx) && guchoku_2(y + c2vy(S[idx]), x + c2vx(S[idx]), idx);
}


bool guchoku(int y, int x, int idx) {
	// takahashiで決まる
	if ((S[idx] == 'L' && x == 1) ||
		(S[idx] == 'R' && x == W) ||
		(S[idx] == 'U' && y == 1) ||
		(S[idx] == 'D' && y == H)) return false; // takahashiが勝つ
	// aokiで決まる
	if (idx == N - 1) return true; // 最後は動かさなければいいので、Aokiが勝つ。

	bool res1, res2;
	// takahashi動かさない
	if ((T[idx] == 'L' && x == 1) ||
		(T[idx] == 'R' && x == W) ||
		(T[idx] == 'U' && y == 1) ||
		(T[idx] == 'D' && y == H)) res1 = guchoku(y, x, idx + 1);
	else res1 = guchoku(y, x, idx + 1) || guchoku(y + c2vy(T[idx]), x + c2vx(T[idx]), idx + 1);
	// takahashi動かす
	y += c2vy(S[idx]), x += c2vx(S[idx]);
	if ((T[idx] == 'L' && x == 1) ||
		(T[idx] == 'R' && x == W) ||
		(T[idx] == 'U' && y == 1) ||
		(T[idx] == 'D' && y == H)) res2 = guchoku(y, x, idx + 1);
	else res2 = guchoku(y, x, idx + 1) || guchoku(y + c2vy(T[idx]), x + c2vx(T[idx]), idx + 1);

	return res1 && res2;
}


//


bool checkMoveRight() {
	int x = Sx;
	repeat(i, N) {
		if (x == W && S[i] == 'R') return false;
		x += (S[i] == 'R') - (T[i] == 'L');
		if (x < 1) x = 1;
	}
	return true;
}


bool checkMoveLeft() {
	int x = Sx;
	repeat(i, N) {
		if (x == 1 && S[i] == 'L') return false;
		x += -(S[i] == 'L') + (T[i] == 'R');
		if (x > W) x = W;
	}
	return true;
}


bool checkMoveDown() {
	int y = Sy;
	repeat(i, N) {
		if (y == H && S[i] == 'D') return false;
		y += (S[i] == 'D') - (T[i] == 'U');
		if (y < 1) y = 1;
	}
	return true;
}


bool checkMoveUp() {
	int y = Sy;
	repeat(i, N) {
		if (y == 1 && S[i] == 'U') return false;
		y += -(S[i] == 'U') + (T[i] == 'D');
		if (y > H) y = H;
	}
	return true;
}

bool solve() {
	return checkMoveRight() && checkMoveLeft() && checkMoveDown() && checkMoveUp();
}


