bool solve(int L, int x, char l, char r) {
    int a = x, b = x;
    REP(i, n) {
        int da = A[i] == l ? -1 : (A[i] == r ? 1 : 0);
        int db = B[i] == l ? -1 : (B[i] == r ? 1 : 0);
        a = min(a, a + da);
        b = max(b, b + da);
        if (a < 0 || b > L)
            return true;
        a = max(a, a + db);
        b = min(b, b + db);
    }
    return false;
}

