bool solve(char pos, char neg, lin mx, lin cr)
{
    bool bt = true;
    lin pc = 0;
    lin nc = 0;

    lin lmn = 0;
    lin lmx = mx - 1;

    for (int i = n - 1; i >= 0; i--)
    {
        if(!bt && (t[i] == pos || t[i] == neg))
        {
            lmx -= pc;
            lmn += nc;

            if(lmn > lmx)
                return false;

            pc = 0;
            nc = 0;
            bt = true;
        }

        if(bt && (t[i] == pos || t[i] == neg))
        {
            if(t[i] == pos)
                pc++;
            else if(t[i] == neg)
                nc++;
        }

        if(bt && (s[i] == pos || s[i] == neg))
        {
            lmx += nc;
            lmn -= pc;
            lmx = min(lmx, mx - 1);
            lmn = max(lmn, (lin)0);

            pc = 0;
            nc = 0;
            bt = false;
        }

        if(!bt && (s[i] == pos || s[i] == neg))
        {
            if(s[i] == pos)
                pc++;
            else if(s[i] == neg)
                nc++;
        }
    }

    if(!bt)
    {
        lmx -= pc;
        lmn += nc;

        if(lmn > lmx)
            return false;
    }
    else
    {
        lmx += nc;
        lmn -= pc;
        lmx = min(lmx, mx - 1);
        lmn = max(lmn, (lin)0);
    }

    return lmn <= cr && cr <= lmx;
}

bool solve()
{
    return
        solve('D', 'U', h, y) &&
        solve('R', 'L', w, x);
}

