const bool IsMoreLikelyToFall(const int H, const int W, const int sr, const int sc, const char ch){
    switch(ch){
        case 'U':
            if(sr <= (H + 1) / 2) return true;
            else return false;
            break;
        case 'D':
            if(sr >= (H + 1) / 2) return true;
            else return false;
            break;
        case 'L':
            if(sc <= (W + 1) / 2) return true;
            else return false;
            break;
        case 'R':
            if(sc >= (W + 1) / 2) return true;
            else return false;
            break;
    }
}

void Move(const char ch, int &sr, int &sc){
    switch (ch)
    {
    case 'U':
        --sr;
        break;
    case 'D':
        ++sr;
        break;
    case 'L':
        --sc;
        break;
    case 'R':
        ++sc;
        break;
    }
}

bool HasFallen(const int H, const int W, const int sr, const int sc){
    return sr < 1 || sc < 1 || sr > H || sc > W;
}

int main()
{
    int H, W, N;
    cin >> H >> W >> N;
    int sr, sc;
    cin >> sr >> sc;
    string S, T;
    cin >> S >> T;

    for(int i = 0; i < N; ++i){
//        cout << S[i] << ' ' << sr << ' ' << sc << endl;
        if(IsMoreLikelyToFall(H, W, sr, sc, S[i]) == true){
            Move(S[i], sr, sc);
//        cout << "Moved : " << sr << ' ' << sc << endl;
            if(HasFallen(H, W, sr, sc)){
                cout << "No";
                return 0;
            }
        }
//        cout << S[i] << ' ' << sr << ' ' << sc << endl;
//        cout << T[i] << ' ' << sr << ' ' << sc << endl;
        if(IsMoreLikelyToFall(H, W, sr, sc, T[i]) == false){
            Move(T[i], sr, sc);
//        cout << "Moved : " << sr << ' ' << sc << endl;
        }
 //       cout << T[i] << ' ' << sr << ' ' << sc << endl;
    }

    cout << "Yes";
    return 0;
}

