	auto move = [&](char c) -> pair<int, int> {
		if(c == 'L')
			return {-1, 0};
		else if(c == 'U')
			return {0, -1};
		else if(c == 'R')
			return {1, 0};
		else if(c == 'D')
			return {0, 1};
		return {inf, inf};
	};

