bool solve(int H, int W, int N, int Sr, int Sc, string& S, string& T) {
    bool answer = true;

    // i回目(0..N-1)の直大の行動終了時点でleftest <= rightest の位置に駒があれば後手が勝てる
    vector<int> leftest(N+1), rightest(N+1);
    leftest[N] = 1;
    rightest[N] = W;

    RREP(i,0,N) {
        leftest[i] = S[i] == 'L' && (i == 0 || T[i-1] != 'R') ? leftest[i+1] + 1 : leftest[i+1];
        rightest[i] = S[i] == 'R' && (i == 0 || T[i-1] != 'L') ? rightest[i+1] - 1 : rightest[i+1];
        if (leftest[i] > rightest[i]) return false;
    }
    if (leftest[0] > Sc || rightest[0] < Sc) return false;

    // i回目(0..N-1)でlowest <= highest の位置に駒があれば後手が勝てる
    vector<int> lowest(N+1), highest(N+1);
    lowest[N] = 1;
    highest[N] = H;

    RREP(i,0,N) {
        lowest[i] = S[i] == 'D' && (i == 0 || T[i-1] != 'U') ? lowest[i+1] + 1 : lowest[i+1];
        highest[i] = S[i] == 'U' && (i == 0 || T[i-1] != 'D') ? highest[i+1] - 1 : highest[i+1];
        if (lowest[i] > highest[i]) return false;
    }
    if (lowest[0] > Sr || highest[0] < Sr) return false;

    return true;
}

