int T[200010][5];
int A[200010][5];

int main(){
    int h, w, n; cin>>h>>w>>n;
    int sy, sx; cin>>sy>>sx;
    string s, t; cin>>s>>t;

    for(int i=0; i<n; i++){
        T[i+1][0] += T[i][0] + (s[i] == 'U');
        T[i+1][1] += T[i][1] + (s[i] == 'R');
        T[i+1][2] += T[i][2] + (s[i] == 'D');
        T[i+1][3] += T[i][3] + (s[i] == 'L');

        A[i+1][0] += A[i][0] + (t[i] == 'U');
        A[i+1][1] += A[i][1] + (t[i] == 'R');
        A[i+1][2] += A[i][2] + (t[i] == 'D');
        A[i+1][3] += A[i][3] + (t[i] == 'L');
    }

    int Ugap = sy - 1;
    int Rgap = w - sx;
    int Dgap = h - sy;
    int Lgap = sx - 1;

    bool valid = true;
    for(int i=0; i<n; i++){

        //cout << Ugap << " " << Rgap << " " << Dgap << " " << Lgap << endl;

        int gap;
        int takahashi;
        int aoki;
        int tmp;
        if(s[i] == 'R'){
            takahashi = T[n][1] - T[i][1];
            aoki = A[i+1][3];
            gap = (Rgap - takahashi) + min(aoki, Lgap);
            if(0 <= gap && gap - min(aoki, Lgap) < 0){
                tmp = Lgap;
                Lgap -= min(aoki, tmp) - 1;
                Rgap += min(aoki, tmp);
            }
        }
        if(s[i] == 'L'){
            takahashi = T[n][3] - T[i][3];
            aoki = A[i+1][1];
            gap = (Lgap - takahashi) + min(aoki, Rgap);
            if(0 <= gap && gap - min(aoki, Rgap) < 0){
                tmp = Rgap;
                Rgap -= min(aoki, tmp) - 1;
                Lgap += min(aoki, tmp);
            }
        }
        if(s[i] == 'U'){
            takahashi = T[n][0] - T[i][0];
            aoki = A[i+1][2];
            gap = (Ugap - takahashi) + min(aoki, Dgap);
            if(0 <= gap && gap - min(aoki, Dgap) < 0){
                tmp = Dgap;
                Dgap -= min(aoki, tmp) - 1;
                Ugap += min(aoki, tmp);
            }
        }
        if(s[i] == 'D'){
            takahashi = T[n][2] - T[i][2];
            aoki = A[i+1][0];
            gap = (Dgap - takahashi) + min(aoki, Ugap);
            if(0 <= gap && gap - min(aoki, Ugap) < 0){
                tmp = Ugap;
                Ugap -= min(aoki, tmp) - 1;
                Dgap += min(aoki, tmp);
            }
        }

        //cout << Ugap << " " << Rgap << " " << Dgap << " " << Lgap << endl;

        if(gap < 0){
            valid = false;
            //cout << i << endl;
        }
    }

    if(valid) cout << "YES" << endl;
    else cout << "NO" << endl;
}

