int main() {
	ll H, W, N;
	cin >> H >> W >> N;
	ll sx, sy;
	cin >> sy >> sx;
	sx--;
	sy--;
	string S, T;
	cin >> S >> T;
	struct I {
		ll l;
		ll r;
		ll u;
		ll d;
	};
	I is_no;
	T.pop_back();
	ll n = S.size()+T.size();
	rep(i,0,n) {
		if (i % 2 == 0) {
			char c = S.back();
			S.pop_back();
			if (c == 'L') {
				is_no.l++;
			} else if (c == 'R') {
				is_no.r++;
			} else if (c == 'U') {
				is_no.u++;
			} else {
				is_no.d++;
			}
		} else {
			char c = T.back();
			T.pop_back();
			if (c == 'L') {
				is_no.r--;
			} else if (c == 'R') {
				is_no.l--;
			} else if (c == 'U') {
				is_no.d--;
			} else {
				is_no.u--;
			}
		}
		is_no.l = max((ll)0, min(W, is_no.l));
		is_no.r = max((ll)0, min(W, is_no.r));
		is_no.u = max((ll)0, min(H, is_no.u));
		is_no.d = max((ll)0, min(H, is_no.d));
		if (is_no.l + is_no.r >= W || is_no.u + is_no.d >= H) {
			cout << "NO" << endl;
			return 0;
		}
		// cout << i << ": " << is_no.l << " " << is_no.r << " " << is_no.u << " " << is_no.d << endl;
	}
	if (sx < is_no.l || sy < is_no.u || W-sx-1 < is_no.r || H-sy-1 < is_no.d) {
		cout << "NO" << endl;
	} else {
		cout << "YES" << endl;
	}
}

