#define N_MAX 200000
#define MOD 1000000007

int N;
bool func(int width, int pos, char *S, char *T)
{
	int left = 1, right = width;

	for (int i = N - 1; i >= 1; i--){
		if ('L' == S[i]){
			left++;
			if (left > right){
				return false;
			}
		}
		else if ('R' == S[i]){
			right--;
			if (left > right){
				return false;
			}
		}

		if ('L' == T[i - 1]){
			right = min(width, right + 1);
		}
		else if ('R' == T[i - 1]){
			left = max(1, left - 1);
		}
	}
	if ('L' == S[0]){
		left++;
		if (left > right){
			return false;
		}
	}
	else if ('R' == S[0]){
		right--;
		if (left > right){
			return false;
		}
	}
	if (left <= pos && pos <= right){
		return true;
	}
	return false;
}

void change(char *S)
{
	for (int i = 0; i < N; i++){
		if ('L' == S[i]){
			S[i] = 'U';
		}
		else if ('R' == S[i]){
			S[i] = 'D';
		}
		else if ('U' == S[i]){
			S[i] = 'L';
		}
		else if ('D' == S[i]){
			S[i] = 'R';
		}
	}

	return;
}

