				}
				if(c == 'D' && x1 < h){
					cout << "NO" << endl;
					return 0;
				}
			}
			if(t[j] == c1){
				if(c1 == 'L' && y1 > 1) y1--;
				if(c1 == 'R' && y1 < w) y1++;
				if(c1 == 'U' && x1 > 1) x1--;
				if(c1 == 'D' && x1 < h) x1++;
			}
		}
	}
