        if (T[i] == d) ub[i][0] = min(ub[i][0] + 1, width);
        // cerr << i << "t" << lb << " " << ub << endl;

        lb[i][1] = lb[i][0];
        ub[i][1] = ub[i][0];
        if (S[i] == u) ub[i][1]--;
        if (S[i] == d) lb[i][1]++;
        // if (lb >= ub) return true;
        // cerr << i << "s" << lb << " " << ub << endl;
    }
    int ll = pos, rr = pos + 1;
    for (int i : range(N)) {
        if (T[i] == u) rr++;
        if (T[i] == d) ll--;
        chmin(rr, ub[i][0]);
        chmax(ll, lb[i][0]);
        if (ll >= rr) {
            return true;
        }
        // cerr << i << " " << ll << " " << rr << endl;
    }
    return false;
    // return !(lb <= pos || pos < ub);
}
