	int l = 0, r = N - 1;
	rof(i, n) {
		if (b[i] == -1) {
			r++;
		} else if (b[i] == 1) {
			l--;
		} 
		l = max(0, l);
		r = min(r, N - 1);
		if (a[i] == -1) {
			l++;
		} else if (a[i] == 1) {
			r--;
		}
		if (l > r) return false;
	}
	return l <= start && start <= r;
}

