int dp(int n, int k) {
	int flag = 1;
	l[len + 1] = 1; r[len + 1] = n;
	for (int i = len; i >= 1; i --) {
		//cout << a[i] << ' ' << b[i] << endl;
		if (a[i] != -1 && b[i] == 1)
		  l[i] = max(l[i + 1] - 1, 1);
		else if (a[i] == -1 && (b[i] != 1 || l[i + 1] == 1))
			l[i] = l[i + 1] + 1;
		else
      l[i] = l[i + 1];

    if (a[i] != 1 && b[i] == -1) 
    	r[i] = min(r[i + 1] + 1, n);
    else if (a[i] == 1 && (b[i] != -1 || r[i + 1] == n))
    	r[i] = r[i + 1] - 1;
    else
    	r[i] = r[i + 1];

    if (l[i] > n || r[i] < 1 || l[i] > r[i]) {
    	flag = 0;
    	//cout << endl;
    	break;
    }
    //cout << "# " << l[i] << ' ' << r[i] << endl;
  }
  //cout << endl;
  if (!flag) return 0;
  if (k >= l[1] && k <= r[1]) return 1;
  return 0;
}



