        r--;
      }
      if(r-l<=1){
        cout << "NO" << endl;
        return 0;
      }
      if(ct=='D'){
        r=min(r+1,n+1);
      }
      else if(ct=='U'){
        l=max(0LL,l-1);
      }
    }
  }
