pii safe_range(int s[], int t[], int m, int l) {
    pii ret = {0, m - 1};

    RREP(i, l) {
        if (t[i] > 0 && ret.first > 0) ret = {ret.first - 1, ret.second};
        else if (t[i] < 0 && ret.second < m - 1) ret = {ret.first, ret.second + 1};

        if (s[i] > 0) ret = {ret.first, ret.second - 1};
        else if (s[i] < 0) ret = {ret.first + 1, ret.second};
        if (ret.second < ret.first) return {-1, -1};
    }
    return ret;
}

