		else D[i + 1] = D[i];
		chmax(U[i + 1], U_min[i] + 1);
		chmin(D[i + 1], D_max[i] - 1);
	}

	for (int i = 0; i < N; i++) {
		if (U[i] >= D_max[i + 1] || D[i + 1] <= U_min[i]) {
			cout << "NO" << "\n";
			return 0;
		}
	}

	cout << "YES" << "\n";

	return 0;
}

