			x+=dx[d];y+=dy[d];
			if(!x||x>h||!y||y>w)return 1;
		}
		if(t[i]==(d^1)){
			tx=x+dx[d^1];ty=y+dy[d^1];
			if(tx&&tx<=h&&ty&&ty<=w){x=tx;y=ty;}
		}
	}
	return 0;
}
