		if(chB[i] == 'L') {
			r = min(r + 1, W + 1);
		} else if(chB[i] == 'R') {
			l = max(l - 1, 0);
		}
		if(chA[i] == 'L') {
			if(++l == r - 1) break;
		} else if(chA[i] == 'R') {
			if(--r == l + 1) break;
		}
	}
	ans &= !(b <= l || b >= r);
	if(ans == 1) puts("YES"); else puts("NO");
	return 0;
}

