const int MX = 200000;

bool solve(int w, int n, int x, int* ds, int* dt) {
	int L = 1, R = w;
	for (int i = n - 1; i >= 0; i--) {
		if (dt[i] == 1) L = max(L - 1, 1);
		if (dt[i] == -1) R = min(R + 1, w);

		if (ds[i] == 1) R--;
		if (ds[i] == -1) L++;

		if (L > R) return false;
	}

	return L <= x && x <= R;
}

char s[MX + 1], t[MX + 1];
int ds[MX], dt[MX];

int main() {
	int h, w, n, x, y;
	ignore = scanf("%d %d %d %d %d %s %s", &h, &w, &n, &x, &y, s, t);

	bool ans = true;

	auto getX = [](char c) {
		if (c == 'U') return -1;
		if (c == 'D') return 1;
		return 0;
	};

	for (int i = 0; i < n; i++) {
		ds[i] = getX(s[i]);
		dt[i] = getX(t[i]);
	}

	ans = ans && solve(h, n, x, ds, dt);

	auto getY = [](char c) {
		if (c == 'L') return -1;
		if (c == 'R') return 1;
		return 0;
	};

	for (int i = 0; i < n; i++) {
		ds[i] = getY(s[i]);
		dt[i] = getY(t[i]);
	}

	ans = ans && solve(w, n, y, ds, dt);

	printf("%s\n", ans ? "YES" : "NO");

	return 0;
}

