    int x = r, y = c;
    for (int i = 0; i < n; ++i) {
        if (s[i] == d) {
            x += dx[d];
            y += dy[d];
            if (x < 0 || x >= h || y < 0 || y >= w)
                return false;
        }

        if (t[i] == (d + 2) % 4) {
            if (x + dx[(d + 2) % 4] >= 0 &&
                x + dx[(d + 2) % 4] < h  &&
                y + dy[(d + 2) % 4] >= 0 &&
                y + dy[(d + 2) % 4] < w) {
                x += dx[(d + 2) % 4];
                y += dy[(d + 2) % 4];
            }
        }
    }
    return true;
}

