using namespace std;

void solve(void)
{
	int h, w, n, sr, sc;
	cin >> h >> w >> n >> sr >> sc;
	string s, t;
	cin >> s >> t;
	vector<int> ls(n+1), rs(n+1), us(n+1), ds(n+1);
	ls[0] = rs[0] = sc;
	us[0] = ds[0] = sr;
	for (int i = 0; i < n; i++)
	{
		ls[i + 1] = max(ls[i] - (t[i] == 'L'), 1);
		rs[i + 1] = min(rs[i] + (t[i] == 'R'), w);
		ds[i + 1] = min(ds[i] + (t[i] == 'D'), h);
		us[i + 1] = max(us[i] - (t[i] == 'U'), 1);
	}
	reverse(s.begin(), s.end());
	reverse(t.begin(), t.end());
	//kill zone
	int l = 0, r = w + 1, u = 0, d = h + 1;
	bool fall = 0;
	for (int i = 0; i < n; i++)
	{
		fall |= l+1 == r || u+1 == d;
		fall |= us[n-i] >= d || u >= ds[n-i] || ls[n-i] >= r || l >= rs[n-i];
		if (t[i] == 'L') r = min(r+1, w+1);
		if (t[i] == 'R') l = max(l-1, 0);
		if (t[i] == 'U') d = min(d+1, h+1);
		if (t[i] == 'D') u = max(u-1, 0);
		if (s[i] == 'L') l = min(l+1, w+1);
		if (s[i] == 'R') r = max(r-1, 0);
		if (s[i] == 'U') u = min(u+1, h+1);
		if (s[i] == 'D') d = max(d-1, 0);
		/*
		cout << l << ' ' << ls[n - i] << endl
			 << r << ' ' << rs[n - i] << endl
			 << u << ' ' << us[n - i] << endl
			 << d << ' ' << ds[n - i] << endl;
		*/
		if (fall)
		{
			break;
		}
	}
	fall |= l + 1 == r || u + 1 == d;
	fall |= us[0] >= d || u >= ds[0] || ls[0] >= r || l >= rs[0];

	cout << (!fall ? "YES" : "NO") << endl;
}

