#include <bits/stdc++.h>
using namespace std;

const int N = 200005;

int h, w, n;
int r, c;
char s[N], t[N];

int find_optimal(int st, int en, char l, char r) {
  int ll = st, rr = en-1, ans = -1;
  while (ll <= rr) {
    int mid = ll + rr >> 1;

    bool can = true;
    int cur = st;

    for (int i=0; i<n; i++) {
      if (s[i] == l) --cur;
      if (cur < 0) {
        can = false;
        break;
      }

      if (t[i] == r) cur = min(cur+1, mid);
    }

    if (can) {
      ans = mid;
      rr = mid - 1;
    } else ll = mid + 1;
  }

  return ans;
}

