    else v.push_back(0);
  }
}
*/

int solve(int st, int en, char l, char r) {
  int tmp1 = find_optimal(st, en, l, r);
  if (tmp1 == -1) return 0;

  int tmp2 = find_optimal(en - st - 1, en, r, l);
  if (tmp2 == -1) return 0;
  tmp2 = en - tmp2 - 1;

  if (tmp1 > tmp2) return 0;

  return 1;
}



