void solve() {
	cin >> h >> w >> n;
	int x, y; cin >> x >> y;
	string s, t; cin >> s >> t;
	SegT up(2 * n + 1); up.update(0, 0);
	rep(i, n) {
		ru[2 * i + 1] = ru[2 * i];
		if (s[i] == 'U') {
			ru[2 * i + 1]++;
		}
		ru[2 * i + 2] = ru[2 * i + 1];
		if (t[i] == 'D') {
			ru[2 * i + 2]--;
		}
		up.update(2 * i + 1, ru[2 * i + 1]);
		up.update(2 * i + 2, ru[2 * i + 2]);
	}
	int z = up.query(0, 2 * n + 1);
	if (z >= x) {
		cout << "NO" << endl; return;
	}
	rep(i, n) {
		if (s[i] == 'D')x++;
		if (x > h) {
			cout << "NO" << endl; return;
		}
		int ma = up.query(2 * i + 2, 2 * n + 1);
		int cur = ru[2 * i + 2];
		ma -= cur;
		if (ma >= x) {
			if (ma == x && t[i] == 'D') {
				x++;
				if (x > h) {
					cout << "NO" << endl; return;
				}
			}
			else {
				cout << "NO" << endl; return;
			}
		}
		else if (ma < x - 1 && t[i] == 'U')x--;
	}
	SegT le(2 * n + 1); le.update(0, 0);
	rep(i, n) {
		rl[2 * i + 1] = rl[2 * i];
		if (s[i] == 'L') {
			rl[2 * i + 1]++;
		}
		rl[2 * i + 2] = rl[2 * i + 1];
		if (t[i] == 'R') {
			rl[2 * i + 2]--;
		}
		le.update(2 * i + 1, rl[2 * i + 1]);
		le.update(2 * i + 2, rl[2 * i + 2]);
	}
	z = le.query(0, 2 * n + 1);
	if (z >= y) {
		cout << "NO" << endl; return;
	}
	rep(i, n) {
		if (s[i] == 'R')y++;
		if (y > w) {
			cout << "NO" << endl; return;
		}
		int ma = le.query(2 * i + 2, 2 * n + 1);
		int cur = rl[2 * i + 2];
		ma -= cur;
		if (ma >= y) {
			if (ma == y && t[i] == 'R') {
				y++;
				if (y > w) {
					cout << "NO" << endl; return;
				}
			}
			else {
				cout << "NO" << endl; return;
			}
		}
		else if (ma < y - 1 && t[i] == 'L') {
			y--;
		}
	}
	cout << "YES" << endl;
}
