		if(c == 'L')
			return {-1, 0};
		else if(c == 'U')
			return {0, -1};
		else if(c == 'R')
			return {1, 0};
		else if(c == 'D')
			return {0, 1};
		return {inf, inf};
	};

	auto valid = [&](int x, int y) {
		return 1 <= x && x <= w && 1 <= y && y <= h;
	};

	int cpx = sx, cpy = sy;
	vector<int> dx = {0}, dy = {0};
	if(w % 2 == 0)
		dx.emplace_back(1);
	if(h % 2 == 0)
		dy.emplace_back(1);

	vector<bool> answs;
	for(int dxx : dx)
		for(int dyy : dy) {
