bool solve(int H, int W, int N, int Sr, int Sc, string& S, string& T) {
    bool answer = true;

    // i回目(0..N-1)の直大の行動終了時点でleftest <= rightest の位置に駒があれば後手が勝てる
    vector<int> leftest(N+1), rightest(N+1);
    leftest[N] = 1;
    rightest[N] = W;

    RREP(i,0,N) {
        leftest[i] = leftest[i+1];
        rightest[i] = rightest[i+1];

        // 先手は範囲を縮めようとする
        leftest[i] += S[i] == 'L' ? 1 : 0;
        rightest[i] += S[i] == 'R' ? -1 : 0;

        if (leftest[i] > rightest[i]) return false;

        // 後手は範囲を広げようとする
        leftest[i] += i > 0 && T[i-1] == 'R' ? -1 : 0;
        rightest[i] += i > 0 && T[i-1] == 'L' ? 1 : 0;
        leftest[i] = max(1, leftest[i]);
        rightest[i] = min(W, rightest[i]);

        if (leftest[i] > rightest[i]) return false;
    }
    if (leftest[0] > Sc || rightest[0] < Sc) return false;

    // i回目(0..N-1)でlowest <= highest の位置に駒があれば後手が勝てる
    vector<int> lowest(N+1), highest(N+1);
    lowest[N] = 1;
    highest[N] = H;

    RREP(i,0,N) {
        lowest[i] = lowest[i+1];
        highest[i] = highest[i+1];

        // 先手は範囲を縮めようとする
        lowest[i] += S[i] == 'D' ? 1 : 0;
        highest[i] += S[i] == 'U' ? -1 : 0;

        if (lowest[i] > highest[i]) return false;

        // 後手は範囲を広げようとする
        lowest[i] += i > 0 && T[i-1] == 'U' ? -1 : 0;
        highest[i] += i > 0 && T[i-1] == 'D' ? 1 : 0;
        lowest[i] = max(1, lowest[i]);
        highest[i] = min(H, highest[i]);

        if (lowest[i] > highest[i]) return false;
    }
    if (lowest[0] > Sc || highest[0] < Sc) return false;

    return true;
}

signed main() {
    int H, W, N, Sr, Sc;
    cin >> H >> W >> N >> Sr >> Sc;
    string S, T;
    cin >> S >> T;

    cout << (solve(H, W, N, Sr, Sc, S, T) ? "YES" : "NO") << '\n';

    return 0;
}

