bool solve() {
    // LR
    int left = 0;
    int right = W + 1;
    REV(i, N - 1, 0) {
        if (T[i] == 'L') {
            right = min(right + 1, W + 1);
        } else if (T[i] == 'R') {
            left = max(left - 1, 0LL);
        }
        if (S[i] == 'L') {
            left = min(left + 1, W + 1);
        } else if (S[i] == 'R') {
            right = max(right - 1, 0LL);
        }

        if (right - left <= 1) return false;
    }
    if (sy <= left || right <= sy) return false;

    left = 0;
    right = H + 1;
    REV(i, N - 1, 0) {
        if (T[i] == 'U') {
            right = min(right + 1, H + 1);
        } else if (S[i] == 'D') {
            left = max(left - 1, 0LL);
        }
        if (S[i] == 'U') {
            left = min(left + 1, H + 1);
        } else if (S[i] == 'D') {
            right = max(right - 1, 0LL);
        }

        if (right - left <= 1) return false;
    }
    if (sx <= left || right <= sx) return false;

    return true;
}

