    ll y0,x0,y1,x1;

    cin>>H>>W>>N;
    cin>>sy>>sx;
    sy--;sx--;

    string s,t;cin>>s>>t;

    auto check = [&](){
      if(y1<y0) no();
      if(x1<x0) no();
    };

    auto tak = [&](char c){
      // 領域を狭める
      if(c=='R'){
        x1--;
      }
      else if(c=='L'){
        x0++;
      }
      else if(c=='U'){
        y0++;
      }
      else if(c=='D'){
        y1--;
      }
      check();
    };

    auto aok = [&](char c){
      // 領域を広げる
      if(c=='R'){
        x0--; if(x0<0) x0=0;
      }
      else if(c=='L'){
        x1++; if(x1>W-1) x1=W-1;
      }
      else if(c=='U'){
        y1++; if(y1>H-1) y1=H-1;
      }
      else if(c=='D'){
        y0--; if(y0<0) y0=0;
      }
      check();  
    };

    // safe zone
    y0=0;
    x0=0;
    y1=H-1;
    x1=W-1;

    // takahashi's N-1
    tak(s[N-1]);

    for(int i=N-2; i>=0; i--){
      aok(t[i]);
      tak(s[i]);
    }

    if(sy<y0) no();
    if(sy>y1) no();
