// Naive Solution
// O(N * max(H, W)^2) -> should be AC or TLE

// Returns 0 (Player 0 wins) or 1 (Player 1 wins)
int FindWinner(int W, int N, int sc, string S, string T, char L, char R)
{
  // 0: Player0 wins, 1: Player1 wins
  vector<int> states(W + 2);
  states[0] = 0;
  for (int j = 1; j <= W; ++j) {
    states[j] = 1;
  }
  states[W + 1] = 0;
  vector<int> pstates(W + 2);

  for (int i = N - 1; i >= 0; --i) {
    // Player1
    pstates[0] = states[0];
    for (int j = 1; j <= W; ++j) {
      int dj;
      if (T[i] == L) dj = -1;
      else if (T[i] == R) dj = +1;
      else dj = 0;
      pstates[j] = max(states[j], states[j + dj]);
    }
    pstates[W + 1] = states[W + 1];
    swap(pstates, states);

    // Player0
    pstates[0] = states[0];
    for (int j = 1; j <= W; ++j) {
      int dj;
      if (S[i] == L) dj = -1;
      else if (S[i] == R) dj = +1;
      else dj = 0;
      pstates[j] = min(states[j], states[j + dj]);
    }
    pstates[W + 1] = states[W + 1];
    swap(pstates, states);
  }

  return states[sc];
}

int main()
{
  int H, W, N;
  cin >> H >> W >> N;
  int sr, sc;
  cin >> sr >> sc;  // 1-origin coordinate
  string S, T;
  cin >> S;
  cin >> T;

  if (FindWinner(W, N, sc, S, T, 'L', 'R') == 0 or
      FindWinner(H, N, sr, S, T, 'U', 'D') == 0) {
    cout << "NO" << endl;
  } else {
    cout << "YES" << endl;
  }

  return 0;
}

