bool solve(int lim, int init, const vi &a, const vi &b) {
	int n=a.size();
	int lo=1,hi=lim;
	for (int i=n-1;i>=0;i--) {
		if (b[i]==-1) {++hi; chkmin(hi,lim);}
		if (b[i]==1) {--lo; chkmax(lo,1);}
		if (a[i]==-1) {++lo;}
		if (a[i]==1) {--hi;}
		if (lo>hi) return false;
		if (!(1<=lo&&lo<=lim)) return false;
		if (!(1<=hi&&hi<=lim)) return false;
	}
	return lo<=init&&init<=hi;
}
void fail() {
	printf("NO\n"); exit(0);
}
void solve(long long H, long long W, long long N, long long s_r, long long s_c, string S, string T){
	string s[2]; s[0]=S;s[1]=T;
	int n=S.length();
	{
		vi a[2];
		for (int k=0;k<2;k++) {
			a[k].resize(n);
			for (int i=0;i<n;i++) {
				char c=s[k][i];
				if (c=='U') a[k][i]=-1;
				else if (c=='D') a[k][i]=1;
				else a[k][i]=0;
			}
		}
		if (!solve(H,s_r,a[0],a[1])) fail();
	}
	{
		vi a[2];
		for (int k=0;k<2;k++) {
			a[k].resize(n);
			for (int i=0;i<n;i++) {
				char c=s[k][i];
				if (c=='R') a[k][i]=1;
				else if (c=='L') a[k][i]=-1;
				else a[k][i]=0;
			}
		}
		if (!solve(W,s_c,a[0],a[1])) fail();
	}
	printf("YES\n"); exit(0);

}

