bool action(int i, int j, char a){
    if(a == 'L') return j <= (W + 1) / 2;
    else if(a == 'R') return W + 1 - j <= (W + 1) / 2;
    else if(a == 'U') return i <= (H + 1) / 2;
    else if(a == 'D') return H + 1 - i <= (H + 1) / 2;
}

