        if(act){
                if(a == 'L') sc--;
                else if(a == 'R') sc++;
                else if(a == 'U') sr--;
                else if(a == 'D') sr++;
        }
        if(sr < 1 || H < sr || sc < 1 || W < sc){
            PRINT("NO");
            return 0;
        }
    }
    PRINT("YES");
    return 0;
}

