struct Pos {
    int x, y;
    constexpr Pos() : Pos(0, 0) {}
    explicit constexpr Pos(int x, int y) : x(x), y(y) {}
};
constexpr bool operator==(const Pos& a, const Pos& b) { return a.x == b.x && a.y == b.y; }
constexpr bool operator!=(const Pos& a, const Pos& b) { return !(a == b); }
constexpr Pos operator+(const Pos & a, const Pos & b) { return Pos(a.x + b.x, a.y + b.y); }



int main() {

    int H, W, N;
    std::cin >> H >> W >> N;

    int sr, sc;
    std::cin >> sr >> sc;

    Pos piece(sc - 1, sr - 1);

    auto dir = [](char c) {
        switch (c) {
        case'U': return Pos(0, -1); break;
        case'D': return Pos(0, 1); break;
        case'L': return Pos(-1, 0); break;
        case'R': return Pos(1, 0); break;
        }
        return Pos();
    };

    auto dis = [&](const Pos & p) { return std::min(W - p.x, p.x + 1) + std::min(H - p.y, p.y + 1); };
    auto out_of_board = [&](const Pos & p) {return p.x < 0 || W <= p.x || p.y < 0 || H <= p.y; };
    //auto show = [](const Pos & p) {std::cout << "(" << p.x << "," << p.y << ")" << std::endl; };

    std::string S, T;
    std::cin >> S >> T;

    bool n_ans = false;

    for (int i = 0; i < N; ++i) {
        Pos takahashi = piece + dir(S[i]);
        if (n_ans = out_of_board(takahashi))break;
        if (dis(takahashi) < dis(piece))piece = takahashi;
        //show(piece);
        Pos aoki = piece + dir(T[i]);
        if (dis(aoki) > dis(piece))piece = aoki;
        //show(piece);
    }

    std::cout << (!n_ans ? "YES" : "NO") << std::endl;

}

