struct point{
    int h;
    int l;
    int step;
    int who;
};

int h,l;
string ss,tt;
int n;

void bfs(int start_h,int start_l){
    queue<point> que;
    while(!que.empty()) que.pop();
    point tmp;
    tmp.h=start_h;
    tmp.l=start_l;
    tmp.step=0;
    tmp.who=1;
    que.push(tmp);
    while(!que.empty()){
        tmp=que.front();
        //cout<<tmp.h<<" "<<tmp.l<<endl;
        que.pop();
        if(tmp.step>=n) continue;
        point t;
        t.h=tmp.h;
        t.l=tmp.l;
        t.step=tmp.step+1;
        if(tmp.who==1){
            t.who=0;
            que.push(t);
            if(ss[tmp.step]=='D'){
                t.h++;
                if(t.h>h){
                    cout<<"NO"<<endl;
                    return ;
                }
                que.push(t);
            }
            if(ss[tmp.step]=='U'){
                t.h--;
                if(t.h<1){
                    cout<<"NO"<<endl;
                    return ;
                }
                que.push(t);
            }
            if(ss[tmp.step]=='R'){
                t.l++;
                if(t.l>l){
                    cout<<"NO"<<endl;
                    return ;
                }
                que.push(t);
            }
            if(ss[tmp.step]=='L'){
                t.l--;
                if(t.l<1){
                    cout<<"NO"<<endl;
                    return ;
                }
                que.push(t);
            }
        }
        if(tmp.who==0){
            t.who=1;
            que.push(t);
            if(tt[tmp.step]=='D'&&t.h+1<=h){
                t.h++;
                que.push(t);
            }
            if(tt[tmp.step]=='U'&&t.h-1>=1){
                t.h--;
                que.push(t);
            }
            if(tt[tmp.step]=='R'&&t.l+1<=l){
                t.l++;
                que.push(t);
            }
            if(tt[tmp.step]=='L'&&t.l-1>=1){
                t.l--;
                que.push(t);
            }
        }
    }
    cout<<"YES"<<endl;
    return ;
}

int main(){
