        //cout << sr << " " << sc << endl;
        if(sc <= 0 || W < sc || sr <= 0 || H < sr){
            cout << "NO" << endl;
            return 0;
        }

        if(t[i] == 'L' && W-sc < sc-1) sc--; 
        else if(t[i] == 'R' && sc-1 < W-sc) sc++;
        else if(t[i] == 'U' && H-sr < sr-1) sr--;
        else if(t[i] == 'D'&& sr-1 < H-sr) sr++;
    }

    cout << "YES" << endl;

    return 0;
}

