struct direction_t {
  constexpr direction_t(int y_, int x_) : y(y_), x(x_) {}
  int y;
  int x;
};

static constexpr direction_t left = direction_t(0, -1);
static constexpr direction_t right = direction_t(0, 1);
static constexpr direction_t up = direction_t(-1, 0);
static constexpr direction_t down = direction_t(1, 0);

static std::array<direction_t, 4> directions = {
    left,
    right,
    up,
    down,
};

struct position_t {
  constexpr position_t(int y_, int x_) : y(y_), x(x_) {}

  int y;
  int x;
};

static std::string const YES = "YES";
static std::string const NO = "NO";

static std::vector<direction_t> sCandidates;
static std::vector<direction_t> tCandidates;

static int h;
static int w;
static int n;

static int minimax(position_t position, bool turn, int moves) {
  if (n * 2 - moves <= 0) {
    return -1;
  }

  int const maximumMovableLength = n - moves / 2;
  if (position.y - maximumMovableLength >= 0 &&
      position.y + maximumMovableLength < h &&
      position.x - maximumMovableLength >= 0 &&
      position.x + maximumMovableLength < w) {
    return -1;
  }

  direction_t candidate =
      turn ? sCandidates[moves / 2] : tCandidates[moves / 2];
  position_t const newPosition =
      position_t(position.y + candidate.y, position.x + candidate.x);
  if (newPosition.y < 0 || h <= newPosition.y || newPosition.x < 0 ||
      w <= newPosition.x) {
    if (turn) {
      return 1;
    } else {
      return minimax(position, !turn, moves + 1);
    }
  }

  int const distance = abs(position.y - h / 2) + abs(position.x - w / 2);
  int const newDistance =
      abs(newPosition.y - h / 2) + abs(newPosition.x - w / 2);
  if (newDistance < distance) {
    if (turn) {
      if (minimax(newPosition, !turn, moves + 1) > 0) {
        return 1;
      }
      return minimax(position, !turn, moves + 1);
    } else {
      if (minimax(position, !turn, moves + 1) < 0) {
        return 1;
      }
      return minimax(newPosition, !turn, moves + 1);
    }
  } else {
    if (turn) {
      if (minimax(position, !turn, moves + 1) > 0) {
        return 1;
      }
      return minimax(newPosition, !turn, moves + 1);
    } else {
      if (minimax(newPosition, !turn, moves + 1) < 0) {
        return 1;
      }
      return minimax(position, !turn, moves + 1);
    }
  }
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> h;
  std::cin >> w;
  std::cin >> n;
  int s_r;
  std::cin >> s_r;
  int s_c;
  std::cin >> s_c;
  std::string s;
  std::cin >> s;
  sCandidates.reserve(n);
  for (auto const ch : s) {
    switch (ch) {
      case 'L':
        sCandidates.push_back(left);
        break;
      case 'R':
        sCandidates.push_back(right);
        break;
      case 'U':
        sCandidates.push_back(up);
        break;
      case 'D':
        sCandidates.push_back(down);
        break;
    }
  }
  std::string t;
  std::cin >> t;
  tCandidates.reserve(n);
  for (auto const ch : t) {
    switch (ch) {
      case 'L':
        tCandidates.push_back(left);
        break;
      case 'R':
        tCandidates.push_back(right);
        break;
      case 'U':
        tCandidates.push_back(up);
        break;
      case 'D':
        tCandidates.push_back(down);
        break;
    }
  }
  auto const res = minimax(position_t(s_r - 1, s_c - 1), true, 0);
  std::cout << ((res > 0) ? NO : YES) << std::endl;
  return 0;
}

