    if(x2 == +1 && Lx >= 0) Lx--;

    if(x1 == -1) Lx++;
    if(x1 == +1) Rx--;
    if(Lx + 1 == Rx) NO();

    if(y2 == -1 && Ry < h) Ry++;
    if(y2 == +1 && Ly >= 0) Ly--;

    if(y1 == -1) Ly++;
    if(y1 == +1) Ry--;
