            cx--;
            chmax(cx, 0);
        }
    }

    // go left
    cy = sy, cx = sx;
    for(int i=0; i<n; i++){
        if(s[i] == 'L') cx--;
        if(cx < 0){
            valid = false;
            break;
        }
        if(t[i] == 'R'){
            cx++;
            chmin(cx, w - 1);
        }
    }

    if(valid) cout << "YES" << endl;
    else cout << "NO" << endl;
}

