vector<int> cand(int L, int R) {
  vector<int> S;
  for (int dx = -3; dx <= 3; dx++) S.push_back(L + dx);
  for (int dx = -3; dx <= 3; dx++) S.push_back(R + dx);
  return S;
}

bool solve(int W, int sx, const vector<int>& A, const vector<int>& B) {
  int N = A.size();
  int L = 1, R = W;
  for (int i = N - 1; i >= 0; i--) {
    int nL = W + 1, nR = 0;
    for (int x : cand(L, R)) {
      if (x < 1 || W < x) continue;
      bool ok = true;
      for (int a = 0; a < 2; a++) {
        int nx = x + A[i] * a;
        if (nx < 1 || W < nx) {
          ok = false;
          break;
        }
        bool found = false;
        for (int b = 0; b < 2; b++) {
          int nx = x + A[i] * a + B[i] * b;
          if (L <= nx && nx <= R) {
            found = true;
            break;
          }
        }
        ok &= found;
      }
      if (ok) {
        chmin(nL, x);
        chmax(nR, x);
      }
    }
    L = nL, R = nR;
  }
  return (L <= sx && sx <= R);
}

