bool solve(int X, int s, vector<event> V)
{
#if DEBUG == 1
  cerr << "X = " << X << ", s = " << s << endl;
#endif
  int maxi = s, mini = s;
  for (auto x : V)
  {
    int player = get<0>(x);
    int move = get<1>(x);
    if (player == 0 && move == 0)
    {
      mini--;
    }
    else if (player == 0 && move == 1)
    {
      maxi++;
    }
    else if (player == 1 && move == 0)
    {
      if (maxi > mini)
      {
        maxi--;
      }
    }
    else
    {
      if (maxi > mini)
      {
        mini++;
      }
    }
#if DEBUG == 1
    cerr << "(" << player << ", " << move << ") : ";
    cerr << "maxi = " << maxi << ", mini = " << mini << endl;
#endif
    if (mini < 0 || maxi >= X)
    {
      return true;
    }
  }
  return false;
}

