bool fall(int x, int e, int sl, int sr, int tl, int tr) {
  if (x - sl + tr < 0) return true;
  if (x + sr - tl >= e) return true;

  return false;
}

int solve(int st, int en, char l, char r) {
  int sl = 0, sr = 0, tl = 0, tr = 0;

  for (int i=0; i<n; i++) {
    if (s[i] == l) ++sl;
    else if (s[i] == r) ++sr;
    if (fall(st, en, sl, sr, tl, tr)) return 1;

    if (t[i] == l) ++tl;
    else if (t[i] == r) ++tr;
    if (fall(st, en, sl, sr, tl, tr)) return 1;
  }

  return 0;
}



