  scanf("%d %d", &r, &c);
  scanf("%s", s);
  scanf("%s", t);

  --r, --c;

  if (solve(r, h, 'L', 'R') || solve(c, w, 'U', 'D')) {
    printf("YES\n");
  } else printf("NO\n");

  return 0;
}

