inline void solve(pair <int, int> *dp, int h, char ch1, char ch2) {
    for(int i = 2 * n; i >= 1; i--) {
        int cur = 0;
        if(ch1 == str[i]) cur--;
        if(ch2 == str[i]) cur++;
        int l, r;
        if(i % 2 == 1) {
            l = 0, r = h + 1;
            inter(l, r, dp[i + 1].first, dp[i + 1].second);
            inter(l, r, dp[i + 1].first - cur, dp[i + 1].second - cur);
        }
        else {
            l = h + 1, r = 0;
            l = min(l, min(dp[i + 1].first, dp[i + 1].first - cur));
            r = max(r, max(dp[i + 1].second, dp[i + 1].second - cur));
        }
        inter(l, r, 1, h);
        dp[i] = {l, r};

    }
}

