#include <bits/stdc++.h>
using namespace std;
using ll = long long;

ll H, W, N, sr, sc;
string S, T;
vector<ll> SL, SR, SU, SD;

bool isLR() {
  ll s = sc;
  for (int i = 0; i < N; i++) {
    if (W % 2 == 1 && s == (W + 1) / 2 && i != N - 1) {
      if (SL[i + 1] < SR[i + 1]) {
        if (S[i] == 'R') {
          s++;
        }
      } else {
        if (S[i] == 'L') {
          s--;
        }
      }
    } else if (s <= W / 2) {
      if (S[i] == 'L') {
        s--;
      }
    } else if (s > W / 2) {
      if (S[i] == 'R') {
        s++;
      }
    }

    if (s < 1 || s > W) {
      return false;
    }

    if (W % 2 == 1 && s == (W + 1) / 2) {
      continue;
    } else if (s >= W / 2) {
      if (T[i] == 'L') {
        s--;
      }
    } else if (s < W / 2) {
      if (T[i] == 'R') {
        s++;
      }
    }
  }
  return true;
}

bool isUD() {
  ll s = sr;
  for (int i = 0; i < N; i++) {
    if (H % 2 == 1 && s == (H + 1) / 2 && i != N - 1) {
      if (SU[i + 1] < SD[i + 1]) {
        if (S[i] == 'D') {
          s--;
        }
      } else {
        if (S[i] == 'U') {
          s++;
        }
      }
    } else if (s <= H / 2) {
      if (S[i] == 'D') {
        s--;
      }
    } else if (s > H / 2) {
      if (S[i] == 'U') {
        s++;
      }
    }

    if (s < 1 || s > H) {
      return false;
    }

    if (H % 2 == 1 && s == (H + 1) / 2) {
      continue;
    } else if (s >= H / 2) {
      if (T[i] == 'D') {
        s--;
      }
    } else if (s < H / 2) {
      if (T[i] == 'U') {
        s++;
      }
    }
  }
  return true;
}

void solve() {
  if (T[0] == 'L') {
    SL[0]++;
  } else if (T[0] == 'R') {
    SR[0]++;
  } else if (T[0] == 'U') {
    SU[0]++;
  } else {
    SD[0]++;
  }
  for (int i = 1; i < N; i++) {
    if (T[i] == 'L') {
      SL[i] = SL[i - 1] + 1;
      SR[i] = SR[i - 1];
      SU[i] = SU[i - 1];
      SD[i] = SD[i - 1];
    } else if (T[i] == 'R') {
      SL[i] = SL[i - 1];
      SR[i] = SR[i - 1] + 1;
      SU[i] = SU[i - 1];
      SD[i] = SD[i - 1];
    } else if (T[i] == 'U') {
      SL[i] = SL[i - 1];
      SR[i] = SR[i - 1];
      SU[i] = SU[i - 1] + 1;
      SD[i] = SD[i - 1];
    } else {
      SL[i] = SL[i - 1];
      SR[i] = SR[i - 1];
      SU[i] = SU[i - 1];
      SD[i] = SD[i - 1] + 1;
    }
  }

  if (isLR() && isUD()) {
    cout << "YES\n";
  } else {
    cout << "NO\n";
  }

  return;
}

int main() {
  cin >> H >> W >> N;
  cin >> sr >> sc;
  cin >> S >> T;
  SL.resize(N, 0);
  SR.resize(N, 0);
  SU.resize(N, 0);
  SD.resize(N, 0);
  solve();
  return 0;
}

