bool Solve(int init, int M, char dec, char inc) {
  int p = init;
  for (int i = 0; i < N; ++i) {
    if (S[i] == inc) ++p;
    if (p > M) return true;
    if (T[i] == dec && p > 1) --p;
  }
  p = init;
  for (int i = 0; i < N; ++i) {
    if (S[i] == dec) --p;
    if (p <= 0) return true;
    if (T[i] == inc && p < M) ++p;
  }
  return false;
}

