  while(cin >> H >> W >> N) {
    cin >> sr >> sc;
    cin >> S >> T;
    bool ans = Solve(sr, H, 'U', 'D') || Solve(sc, W, 'L', 'R');
    cout << (ans ? "NO" : "YES") << endl;
  }
}

