#define FOR(i, m, n) for (int i = (m); i < (n); i++)
#define REP(i, n) FOR(i, 0, n)
#define RREP(i, n) for (int i = (n) - 1; i >= 0; i--)
using namespace std;

int main(void)
{
    int H, W, N;
    cin >> H >> W >> N;

    int r, c;
    cin >> r >> c;

    string S, T;
    cin >> S;
    cin >> T;

    bool remain = true;

    REP(turn, N) {
        // Takahashi
        char tak_command = S[turn];
        if (tak_command == 'L') {
            if (c < W - c + 1) {
                //cerr << "Takahashi L" << endl;
                c--;
            } else {
                // lookahead
                int future_L = 0;
                FOR(i, turn + 1, N) {
                    if (S[i] == 'L') {
                        future_L++;
                    }
                    if (future_L >= c - 1) {
                        //cerr << "Takahashi L" << endl;
                        c--;
                        goto aoki_turn;
                    }
                }
                //cerr << "Takahashi do nothing" << endl;
            }
        } else if (tak_command == 'R') {
            if (c > W - c + 1) {
                //cerr << "Takahashi R" << endl;
                c++;
            } else {
                // lookahead
                int future_R = 0;
                FOR(i, turn + 1, N) {
                    if (S[i] == 'R') {
                        future_R++;
                    }
                    if (future_R >= W - c) {
                        //cerr << "Takahashi R" << endl;
                        c++;
                        goto aoki_turn;
                    }
                }
                //cerr << "Takahashi do nothing" << endl;
            }
        } else if (tak_command == 'U') {
            if (r < H - r + 1) {
                //cerr << "Takahashi U" << endl;
                r--;
            } else {
                // lookahead
                int future_U = 0;
                FOR(i, turn + 1, N) {
                    if (S[i] == 'U') {
                        future_U++;
                    }
                    if (future_U >= r - 1) {
                        //cerr << "Takahashi U" << endl;
                        r--;
                        goto aoki_turn;
                    }
                }
                //cerr << "Takahashi do nothing" << endl;
            }
        } else if (tak_command == 'D') {
            if (r > H - r + 1) {
                //cerr << "Takahashi D" << endl;
                r++;
            } else {
                // lookahead
                int future_D = 0;
                FOR(i, turn + 1, N) {
                    if (S[i] == 'D') {
                        future_D++;
                    }
                    if (future_D >= H - r) {
                        //cerr << "Takahashi D" << endl;
                        r++;
                        goto aoki_turn;
                    }
                }
                //cerr << "Takahashi do nothing" << endl;
            }
        }

        aoki_turn:

        if (r == 0 || r == H + 1 || c == 0 || c == W + 1) {
            remain = false;
            break;
        }

        // Aoki
        char aok_command = T[turn];
        if (aok_command == 'L') {
            if (c > W - c + 1) {
                //cerr << "Aoki L" << endl;
                c--;
            } else if (c < W - c + 1) {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            } else {
                // lookahead Takahashi's
                FOR(i, turn + 1, N) {
                    if (S[i] == 'R') {
                        //cerr << "Aoki L" << endl;
                        c--;
                        break;
                    }
                }
            }
        } else if (aok_command == 'R') {
            if (c < W - c + 1) {
                //cerr << "Aoki R" << endl;
                c++;
            } else if (c > W - c + 1) {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            } else {
                // lookahead Takahashi's
                FOR(i, turn + 1, N) {
                    if (S[i] == 'L') {
                        //cerr << "Aoki R" << endl;
                        c++;
                        break;
                    }
                }
            }
        } else if (aok_command == 'U') {
            if (r > H - r + 1) {
                //cerr << "Aoki U" << endl;
                r--;
            } else if (r < H - r + 1) {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            } else {
                // lookahead Takahashi's
                FOR(i, turn + 1, N) {
                    if (S[i] == 'D') {
                        //cerr << "Aoki U" << endl;
                        r--;
                        break;
                    }
                }
            }
        } else if (aok_command == 'D') {
            if (r < H - r + 1) {
                //cerr << "Aoki D" << endl;
                r++;
            } else if (r > H - r + 1) {
                // do nothing
                //cerr << "Aoki do nothing" << endl;
            } else {
                // lookahead Takahashi's
                FOR(i, turn + 1, N) {
                    if (S[i] == 'U') {
                        //cerr << "Aoki U" << endl;
                        r++;
                        break;
                    }
                }
            }
        }
    }

    if (remain) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

