int dx[] = {0, 0, -1, 1};
int dy[] = {-1, 1, 0, 0};

int main() {
  int h, w, n, sx, sy;
  scanf("%d%d%d%d%d", &h, &w, &n, &sx, &sy);
  string s, t;
  cin >> s >> t;
  for (auto i = 0; i < n; i++) {
    // takahashi
    int nx, ny;
    switch (s[i]) {
      case 'L':
        nx = sx + dx[0];
        ny = sy + dy[0];
        break;
      case 'R':
        nx = sx + dx[1];
        ny = sy + dy[1];
        break;
      case 'U':
        nx = sx + dx[2];
        ny = sy + dy[2];
        break;
      case 'D':
        nx = sx + dx[3];
        ny = sy + dy[3];
        break;
    }
    if (nx < 1 || nx > h || ny < 1 || ny > w) {
      printf("%d %d %d %d\n", nx, ny, w, h);
      puts("NO");
      return 0;
    }
    if (min(h - nx + 1, nx) < min(h - sx + 1, sx)) sx = nx;
    if (min(w - ny + 1, ny) < min(w - sy + 1, sy)) sy = ny;
    // aoki
    switch (t[i]) {
      case 'L':
        nx = sx + dx[0];
        ny = sy + dy[0];
        break;
      case 'R':
        nx = sx + dx[1];
        ny = sy + dy[1];
        break;
      case 'U':
        nx = sx + dx[2];
        ny = sy + dy[2];
        break;
      case 'D':
        nx = sx + dx[3];
        ny = sy + dy[3];
        break;
    }
    if (nx < 1 || nx > h || ny < 1 || ny > w) continue;
    if (min(h - nx + 1, nx) > min(h - sx + 1, sx)) sx = nx;
    if (min(w - ny + 1, ny) > min(w - sy + 1, sy)) sy = ny;
  }
  puts("YES");
}

