	if (T[N - 1] == 'L') {
		l++;
	}
	if (T[N - 1] == 'R') {
		r--;
	}
	for (int i = N - 2; i >= 0; i--) {
		if (T[i] == 'L') {
			l++;
		}
		if (S[i] == 'R')l = max(0, l - 1);
		if (T[i] == 'R') {
			r--;
		}
		if (S[i] == 'L')r = min(W, r + 1);
	}
	if (r <= l || !(l <= x && x < r)) {
		cout << "NO" << endl;
		return 0;
	}

	int d = 0, u = H;//[d, u)の区間で存在したらセーフ
	if (T[N - 1] == 'D'){
		d++;
	}
	if (T[N - 1] == 'U') {
		u--;
	}
	for (int i = N - 2; i >= 0; i--) {
		if (T[i] == 'D') {
			d++;
		}
		if (S[i] == 'U')d = min(H, d + 1);
		if (T[i] == 'U') {
			u--;
		}
		if (S[i] == 'D')u = max(0, u - 1);
	}
	if (u <= d || !(d <= y && y < u)) {
		cout << "NO" << endl;
		return 0;
	}
	cout << "YES" << endl;
	return 0;
}

