            right = min(W, right+1);
        }

        // 先手は範囲を縮めようとする
        if (S[i] == 'L') {
            left++;
        } else if (S[i] == 'R') {
            right--;
        }

        if (left > right) return false;
    }
    if (left > Sc || right < Sc) return false;

    // i回目(0..N-1)でbottom <= top の位置に駒があれば後手が勝てる
    int bottom = 1, top = H;

    RREP(i,0,N) {
        // 後手は範囲を広げようとする
        if (T[i] == 'U') {
            bottom = max(1, bottom-1);
        } else if (T[i] == 'D') {
            top = min(W, top+1);
        }

        // 先手は範囲を縮めようとする
        if (S[i] == 'D') {
            bottom++;
        } else if (S[i] == 'U') {
            top--;
        }

        if (bottom > top) return false;
    }
    if (bottom > Sc || top < Sc) return false;

    return true;
}

