int best ( char c )
{
    if ( c == 'L' && SC <= w / 2 + 1 )
    {
        SC -- ; return 1 ;
    }
    else if ( c == 'R' && SC >= w - w / 2 )
    {
        SC ++ ; return 1 ;
    }
    else if ( c == 'U' && SR <= h / 2 + 1 )
    {
        SR -- ; return 1 ;
    }
    else if ( c == 'D' && SR >= h - h / 2 )
    {
        SR ++ ; return 1 ;
    }
    else return 0 ;
}

void besT ( char c )
{
    if ( c == 'R' && SC < w - w / 2 )
    {
        SC ++ ;
    }
    else if ( c == 'L' && SC > w / 2 + 1 )
    {
        SC -- ;
    }
    else if ( c == 'D' && SR < h - h / 2 )
    {
        SR ++ ;
    }
    else if ( c == 'U' && SR > h / 2 + 1 )
    {
        SR -- ;
    }
    return ;
}

bool check ()
{
    return ( SR == 0 || SR > h || SC == 0 || SC > w ) ;
}

