typedef long long LL;

struct Point {
  int r;
  int c;
};

struct Life {
  int L = 0;
  int R = 0;
  int U = 0;
  int D = 0;

  int H = 0;
  int W = 0;
  explicit Life(int h, int w) : H(h), W(w) {}
  void Display() {
    std::cout << "(" << L << " " << R << " " << U << " " << D << ")" << std::endl;
  }
};

int main() {
  int H, W, N; std::cin >> H >> W >> N;
  Point s; std::cin >> s.r >> s.c;
  std::string S, T; std::cin >> S >> T;

  Life life(H, W);
  life.U = s.r - 1;
  life.D = H - s.r;
  life.L = s.c - 1;
  life.R = W - s.r;
#if DEBUG
  life.Display();
#endif

  for (int i = 0; i < N; ++i) {
    // Takashi action.
    int v = 0;
    switch (S[i]) {
      case 'L':
        v = --life.L;
        break;
      case 'R':
        v = --life.R;
        break;
      case 'U':
        v = --life.U;
        break;
      case 'D':
        v = --life.D;
        break;
      default:
        break;
    }

    if (v < 0) {
      std::cout << "NO" << std::endl;
      return 0;
    }

#if DEBUG
    std::cout << "T: ";
    life.Display();
#endif

    // Aoki action.
    switch (T[i]) {
      case 'L':
        life.R = std::min(W - 1, life.R + 1);
        break;
      case 'R':
        life.L = std::min(W - 1, life.L + 1);
        break;
      case 'U':
        life.D = std::min(H - 1, life.D + 1);
        break;
      case 'D':
        life.U = std::min(H - 1, life.U + 1);
        break;
      default:
        break;
    }

#if DEBUG
    std::cout << "A: ";
    life.Display();
#endif
  }
}

