bool safe(char d1, char d2, int s, int bsize, int N)
{
    int lb = 1, rb = bsize;
    if (S[N-1] == d1)
        lb++;
    if (S[N-1] == d2)
        rb--;
    for (int i = N-2 ; i >= 0 ; i--) {
        if (S[i] == d1 && T[i] == d2)
            continue;
        if (S[i] == d2 && T[i] == d1)
            continue;
        if (S[i] == d1) {
            lb++;
        }
        else if (S[i] == d2) {
            rb--;
        }
        else {
            if (T[i] == d1)
                rb++;
            else if (T[i] == d2)
                lb--;
        }
        if (lb > rb)
            return false;
    }
    return lb <= s && s <= rb;
}

