bool _common(int W, int N, int x0, vi& u, vi& v) {
    int x;

    x = x0;
    for (int i=0; i<N; ++i) {
        if (u[i] == 1) { ++x; if (x == W) return true; }
        if (v[i] == -1 && x > 0) { --x; }
    }

    x = x0;
    for (int i=0; i<N; ++i) {
        if (u[i] == -1) { --x; if (x == -1) return true; }
        if (v[i] == 1 && x < W-1) { ++x; }
    }

    return false;
}

bool _horiz(int W, int N, int sc, string& s,string& t) {
    vi u(N,0), v(N,0);
    rep(i,N){
        if (s[i]=='R') u[i]=1;
        else if (s[i]=='L') u[i]=-1;

        if (t[i]=='R') v[i]=1;
        else if (t[i]=='L') v[i]=-1;
    }
    return _common(W, N, sc-1, u, v);
}

bool _vert(int H, int N, int sr, string& s,string& t) {
    vi u(N,0), v(N,0);
    rep(i,N){
        if (s[i]=='D') u[i]=1;
        else if (s[i]=='U') u[i]=-1;

        if (t[i]=='D') v[i]=1;
        else if (t[i]=='U') v[i]=-1;
    }
    return _common(H, N, sr-1, u, v);
}

bool solve(int H,int W,int N, int sr,int sc, string& s,string& t) {
    return _horiz(W,N, sc, s,t) || _vert(H,N, sr, s,t);
}

int main() {
    int H,W,N; cin >> H >> W >> N;
    int sr,sc; cin >> sr >> sc;
    string s,t; cin >> s >> t;
    cout << (solve(H,W,N,sr,sc,s,t) ? "NO":"YES") << endl;
    return 0;
}

