void step(int&x, int&y, char c)
{
    switch (c){
        case 'R':
            y ++;
            break;
        case 'L':
            y --;
            break;
        case 'U':
            x --;
            break;
        case 'D':
            x ++;
            break;
    }
}
bool work(int x, int y, char ca, char cb)
{
    for (int i = 0; i < n ; i ++)
    {
        if (a[i] == ca)
        {
            int xx = x, yy = y;
            step(xx, yy, ca);
            if (xx < 1 || yy < 1 || xx > h || yy > w)
                return 0;
            x = xx;
            y = yy;
        }
        if (b[i] == cb)
        {
            int xx = x, yy = y;
            step(xx, yy, cb);
            if (xx < 1 || yy < 1 || xx > h || yy > w)
                continue;
            x = xx;
            y = yy;
        }
    }
    return 1;
}
