const int N = 200005;
int h, w, n, gx, gy;
char A[N], B[N];

bool solve(int L, int x, char l, char r) {
    int a = x, b = x;
    REP(i, n) {
        int la = a, lb = b;
        int da = A[i] == l ? -1 : (A[i] == r ? 1 : 0);
        int db = B[i] == l ? -1 : (B[i] == r ? 1 : 0);
        a = min(a, a + da);
        b = max(b, b + da);
        // printf("%d  %d %d  A %d %d\n", i, da, db, a, b);
        if (a < 0 || b > L)
            return true;
        a = max(a, a + db);
        b = min(b, b + db);
        a = min(a, lb);
        b = max(b, la);
        // printf("%d  %d %d  B %d %d\n", i, da, db, a, b);
    }
    return false;
}

int main() {
    scanf("%d%d%d", &h, &w, &n);
    scanf("%d%d", &gx, &gy);
    scanf("%s", &A);
    scanf("%s", &B);
    if (solve(h, gx, 'D', 'U') || solve(w, gy, 'L', 'R'))
        cout << "NO" << endl;
    else 
        cout << "YES" << endl;
    return 0;
}

