char S[222222];
char T[222222];

bool safe(char d1, char d2, int s, int bsize, int N)
{
    int lb = 1, rb = bsize;
    if (S[N-1] == d1)
        lb++;
    if (S[N-1] == d2)
        rb--;
    for (int i = N-2 ; i >= 0 ; i--) {
        if (S[i] == d1) {
            if (T[i] == d2) {
                if (lb == 1)
                    lb++;
            }
            else
                lb++;
        }
        else if (S[i] == d2) {
            if (T[i] == d1) {
                if (rb == bsize)
                    rb--;
            }
            else
                rb--;
        }
        else {
            if (T[i] == d1)
                rb++;
            else if (T[i] == d2)
                lb--;
        }
        if (rb > bsize)
            rb = bsize;
        if (lb < 1)
            lb = 1;
        if (lb > rb)
            return false;
    }
    return lb <= s && s <= rb;
}

int main()
{
    int H, W, N;
    int sr, sc;
    cin >> H>> W >> N;
    cin >> sr >> sc;
    cin >> S >> T;
    if (safe('U', 'D', sr, H, N) && safe('L', 'R', sc, W, N))
        puts("YES");
    else
        puts("NO");
    return 0;
}

