int dist(pair<int, int> a, pair<int, int> b) {
	return abs(a.first - b.first) + abs(a.second - b.second);
}

mt19937_64 _gen(chrono::system_clock::now().time_since_epoch().count());
template<class T> T rd(T a, T b) { return uniform_int_distribution<T>(a, b)(_gen); }

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int h, w, n;
	cin >> h >> w >> n;
	int sy, sx;
	cin >> sy >> sx;
	string s, t;
	cin >> s >> t;

	auto move = [&](char c) -> pair<int, int> {
		if(c == 'L')
			return {-1, 0};
		else if(c == 'U')
			return {0, -1};
		else if(c == 'R')
			return {1, 0};
		else if(c == 'D')
			return {0, 1};
		return {inf, inf};
	};

	auto valid = [&](int x, int y) {
		return 1 <= x && x <= w && 1 <= y && y <= h;
	};

	int cpx = sx, cpy = sy;
	vector<int> dx = {0}, dy = {0};
	if(w % 2 == 0)
		dx.emplace_back(1);
	if(h % 2 == 0)
		dy.emplace_back(1);

	vector<bool> answs;
	for(int dxx : dx)
		for(int dyy : dy) {
			bool no = false;
			int goalx = (w + 1) / 2, goaly = (h + 1) / 2;
			goalx += dxx;
			goaly += dyy;
			sx = cpx, sy = cpy;
			REP(i, n) {
				auto mv = move(s[i]);
				int x = sx + mv.first, y = sy + mv.second;
				int d1 = dist({x, y}, {goalx, goaly}), d2 = dist({sx, sy}, {goalx, goaly});
				if(d1 > d2) {
					sx = x;
					sy = y;
				}
				if(not valid(sx, sy)) {
					no = true;
					break;
				}
				mv = move(t[i]);
				x = sx + mv.first, y = sy + mv.second;
				d1 = dist({x, y}, {goalx, goaly}), d2 = dist({sx, sy}, {goalx, goaly});
				if(d1 < d2 || (d1 == d2 && rd(0, 1))) {
					sx = x;
					sy = y;
				}
			}
			if(no == false)
				answs.emplace_back(1);
			else
				answs.emplace_back(0);
		}
	bool same = true;
	FOR(i, 1, SZ(answs) - 1)
		if(answs[i] != answs[i - 1])
			same = false;
	if(same) {
		if(answs[0])
			cout << "YES\n";
		else
			cout << "NO\n";
	} else {
		if(rd(0, 1))
			cout << "YES\n";
		else
			cout << "NO\n";
	}
}

