bool isLR() {
  ll s = sc;
  for (int i = 0; i < N; i++) {
    if (s <= W / 2) {
      if (S[i] == 'L') {
        s--;
      }
    } else {
      if (S[i] == 'R') {
        s++;
      }
    }

    if (s < 1 || s > W) {
      return false;
    }

    if (W % 2 == 1 && s == (W + 1) / 2) {
      continue;
    } else if (s >= W / 2) {
      if (T[i] == 'L') {
        s--;
      }
    } else if (s < W / 2) {
      if (T[i] == 'R') {
        s++;
      }
    }
  }
  return true;
}

bool isUD() {
  ll s = sr;
  for (int i = 0; i < N; i++) {
    if (s <= H / 2) {
      if (S[i] == 'D') {
        s--;
      }
    } else {
      if (S[i] == 'U') {
        s++;
      }
    }

    if (s < 1 || s > H) {
      return false;
    }

    if (H % 2 == 1 && s == (H + 1) / 2) {
      continue;
    } else if (s >= H / 2) {
      if (T[i] == 'D') {
        s--;
      }
    } else if (s < H / 2) {
      if (T[i] == 'U') {
        s++;
      }
    }
  }
  return true;
}

void solve() {
  if (S[0] == 'L') {
    SL[0]++;
  } else if (S[0] == 'R') {
    SR[0]++;
  } else if (S[0] == 'U') {
    SU[0]++;
  } else {
    SD[0]++;
  }
  for (int i = 1; i < N; i++) {
    if (S[i] == 'L') {
      SL[i] = SL[i - 1] + 1;
      SR[i] = SR[i - 1];
      SU[i] = SU[i - 1];
      SD[i] = SD[i - 1];
    } else if (S[i] == 'R') {
      SL[i] = SL[i - 1];
      SR[i] = SR[i - 1] + 1;
      SU[i] = SU[i - 1];
      SD[i] = SD[i - 1];
    } else if (S[i] == 'U') {
      SL[i] = SL[i - 1];
      SR[i] = SR[i - 1];
      SU[i] = SU[i - 1] + 1;
      SD[i] = SD[i - 1];
