      SL[i] = SL[i - 1];
      SR[i] = SR[i - 1];
      SU[i] = SU[i - 1];
      SD[i] = SD[i - 1] + 1;
    }
  }

  if (isLR() && isUD()) {
    cout << "YES\n";
  } else {
    cout << "NO\n";
  }

  return;
}

