            rrc[n-1-i] = rrc[n-i];
            llc[n-1-i] = llc[n-i];
            uuc[n-1-i] = maxx(uuc[n-i],0)+1;
            ddc[n-1-i] = ddc[n-i];
        }
        if(t[n-1-i] == 'L'){
            l2[n-1-i] = l2[n-i]+1;
            r2[n-1-i] = r2[n-i];
            u2[n-1-i] = u2[n-i];
            d2[n-i-1] = d2[n-i];
        }
        else if(t[n-1-i] == 'R'){
            l2[n-1-i] = l2[n-i];
            r2[n-1-i] = r2[n-i]+1;
            u2[n-1-i] = u2[n-i];
            d2[n-i-1] = d2[n-i];
        }
        else if(t[n-1-i] == 'U'){
            l2[n-1-i] = l2[n-i];
            r2[n-1-i] = r2[n-i];
            u2[n-1-i] = u2[n-i]+1;
            d2[n-i-1] = d2[n-i];
        }
        else if(t[n-1-i] == 'D'){
            l2[n-1-i] = l2[n-i];
            r2[n-1-i] = r2[n-i];
            u2[n-1-i] = u2[n-i];
            d2[n-i-1] = d2[n-i]+1;
        }
    }
    long long lc,rc,uc,dc;
    long long llcc,rrcc,uucc,ddcc;
    rep(i,n+1){
        rc = maxx((r2[0] - r2[i])-(l1[0] - l1[i]),0) + sc;
        lc = sc - maxx((l2[0] - l2[i])-(r1[0] - r1[i]),0);
        llcc = w+1-llc[i+1];
        rrcc = rrc[i+1];
        if(llcc <= lc || rc <= rrcc || llcc <= rrcc || llcc <= 1 || rrcc >= w){
            fl = false;
            break;
        }
        dc = maxx((d2[0] - d2[i])-(u1[0] - u1[i]),0) + sr;
        uc = sr - maxx((u2[0] - u2[i])-(d1[0] - d1[i]),0);
        uucc = h+1-uuc[i+1];
        ddcc = ddc[i+1];
        if(uucc <= uc || dc <= ddcc || uucc <= ddcc || uucc <= 1 || ddcc >= h){
            fl = false;
            break;
        }
    }
    if(fl){
        cout << "YES" << endl;
    }
    else{
        cout << "NO" << endl;
    }
}

