#include <bits/stdc++.h>
using namespace std;

#define int long long

using pii = pair<int, int>;

int H, W, N;
int sy, sx;
string s, t;
string g;
// それぞれの文字に対応する差分を格納
map<char, pii> mp = {
  {'U', {-1, 0}},
  {'D', {1, 0}},
  {'R', {0, 1}},
  {'L', {0, -1}},
};

// 範囲内かをチェック
bool check(int y, int x) {
  return y >= 1 and y <= H and x >= 1 and x <= W;
}

bool dfs(int idx, int y, int x) {
  // 範囲外に出たら終了
  if (check(y, x) == false) {
    return false;
  }

  // 最後まで探索し終える
  if (idx >= g.size()) {
    return true;
  }

  if (idx % 2 == 0) { // 高橋くんの手番。1つでもfalseがあってほしい
    bool ret = true;

    // no
    ret &= dfs(idx + 1, y, x);

    // yes
    int ny = y + mp[g[idx]].first;
    int nx = x + mp[g[idx]].second;
    ret &= dfs(idx + 1, ny, nx);

    return ret;
  } else { // 青木くんの手番。1つでもtrueがあってほしい
    bool ret = false;

    // no
    ret |= dfs(idx + 1, y, x);

    // yes
    int ny = y + mp[g[idx]].first;
    int nx = x + mp[g[idx]].second;
    ret |= dfs(idx + 1, ny, nx);

    return ret;
  }
}

signed main() {
  cin >> H >> W >> N;
  cin >> sy >> sx;
  cin >> s >> t;

  // 探索に使うための配列を用意。高橋→青木→高橋...といった順番になる
  for (int i = 0; i < N; i++) {
    g.push_back(s[i]);
    g.push_back(t[i]);
  }

  bool ans = dfs(0, sy, sx);

  puts(ans ? "YES" : "NO");

  return 0;
}

