  } else {
    ub[N - 1] = x;
    lb[N - 1] = 1;
  }
  for (int i = N - 2; i >= 0; i--) {
    if (S[i] == u) {
      if (T[i] == l) {
        ub[i] = min(ub[i + 1], x-1);
      } else {
        ub[i] = ub[i + 1] - 1;
      }
      lb[i] = lb[i + 1];
    } else if (S[i] == l) {
      if (T[i] == u) {
        lb[i] = max(lb[i + 1], 2LL);
      } else {
        lb[i] = lb[i + 1] + 1;
      }
      ub[i] = ub[i + 1];
    } else {
      if (T[i] == u) {
        ub[i] = min(x, ub[i + 1] + 1);
        lb[i] = lb[i + 1];
      } else if (T[i] == l) {
        ub[i] = ub[i + 1];
        lb[i] = max(1LL, lb[i + 1] - 1);
      } else {
        ub[i] = ub[i + 1];
        lb[i] = lb[i + 1];
      }
    }
  }  // i

  return (pos < lb[0] || pos > ub[0]);
}  // test

