bool hoge() {    
    int x = 1, y = W;
    for (int i = N - 1; i >= 0; --i) {
        if (i < N - 1 && S[1][i] == 'R') {
            x = max(1, x-1);
        } else if (i < N - 1 && S[1][i] == 'L') {
            y = min(W, y+1);
        }
        if (S[0][i] == 'L') {
            x += 1;
        } else if (S[0][i] == 'R') {
            y -= 1;
        }
        if (x > y) return false;
    }

    if (Sc < x || Sc > y) return false;

    x = 1, y = H;
    for (int i = N - 1; i >= 0; --i) {
        if (i < N - 1 && S[1][i] == 'D') {
