#include <iostream>
#include <string>
#include <cstdlib>
#include <vector>

using namespace std;
using lolo=int;

bool hantei(const string& S, const string& T, lolo H, lolo W, lolo N, char L, char R, lolo sc, lolo sr)
{
	lolo right;
	//lolo sc, sr;
	//if (L == 'L')
	//	right = W - 1;
	//else
	//	right = H - 1;

	if (L == 'L') {
		H = W;
		right = W - 1;
		sr = sc;

	}
	else {
		W = H;
		right = H - 1;
		sc = sr;
	}



	lolo left = 0;


	for (lolo i = N - 1; i >= 0; --i) {
		char s = S[i];
		char t = T[i];

		// キャンセルする青木くんの動き

		if (t == R) {
			if (left > 0) {
				left -= 1;
			}
		}
		else if (t == L) {
			if (right < W - 1 and right >= 0) {
				right += 1;
			}
		}

		// OUT ゾーンを増やしていく
		if (s == L) {
			left += 1;
		}
		else if (s == R) {
			right -= 1;
		}
	}
	if (left <= sc and sc <= right) {
		return true;
	}
	else {
		return false;
	}
}

int main()
{
	using namespace std;
	using lolo=int;

	lolo H, W, N, sr, sc;
	string S, T;

	cin >> H >> W >> N;
	cin >> sr >> sc;
	sr--;
	sc--;

	cin >> S;
	cin >> T;

	bool yoko_safe = hantei(S, T, H, W, N, 'L', 'R', sc, sr);
	bool tate_safe = hantei(S, T, H, W, N, 'U', 'D', sc, sr);

	if (yoko_safe and tate_safe) {
		cout << "YES" << endl;
	}
	else {
		cout << "NO" << endl;
	}

}

