void no() {
    PRINTLN("NO");
    exit(0);
}

void solve() {
    i64 H = RD();
    i64 W = RD();
    i64 N = RD();

    i64 Y = RD1();
    i64 X = RD1();

    auto S = RD<string>();
    auto T = RD<string>();

    // 縦
    {
        i64 t = 0;
        i64 b = H;
        for(i64 i = N-1; i >= 0; --i) {
            if(T[i] == 'U')
                b = min(H, b+1);
            else if(T[i] == 'D')
                t = max<i64>(0, t-1);

            if(S[i] == 'U')
                ++t;
            else if(S[i] == 'D')
                --b;
            if(t >= b) no();
        }
        if(Y < t || b <= Y) no();
    }

    // 横
    {
        i64 l = 0;
        i64 r = W;
        for(i64 i = N-1; i >= 0; --i) {
            if(T[i] == 'L')
                r = min(W, r+1);
            else if(T[i] == 'R')
                l = max<i64>(0, l-1);

            if(S[i] == 'L')
                ++l;
            else if(S[i] == 'R')
                --r;
            if(l >= r) no();
        }
        if(X < l || r <= X) no();
    }

    PRINTLN("YES");
}

