int main(){
    iosetup;
    int H, W, N; cin >> H >> W >> N;
    int sr, sc; cin >> sr >> sc;
    string S, T; cin >> S >> T;
    vector<pii> dp_h(N), dp_w(N);
    dp_h[N-1] = {0, H - 1};
    dp_w[N-1] = {0, W - 1};
    rrep(i, 0, N - 1){
        pii tmp = dp_w[i+1];
        if(S[i] == 'R'){
            if(T[i] != 'L') tmp.second--;
        }else if(S[i] == 'L'){
            if(T[i] != 'R') tmp.first++;
        }else{
            if(T[i] == 'L') if(tmp.second < W - 1) tmp.second++;
            else if(T[i] == 'R') if(tmp.first > 0) tmp.first--;
        }
        if(tmp.first > tmp.second)Exit("YES");
        dp_w[i] = tmp;
        tmp = dp_h[i+1];
        if(S[i] == 'D'){
            if(T[i] != 'U') tmp.second--;
        }else if(S[i] == 'U'){
            if(T[i] != 'D') tmp.first++;
        }else{
            if(T[i] == 'U') if(tmp.second < W - 1) tmp.second++;
            else if(T[i] == 'D') if(tmp.first > 0) tmp.first--;
        }
        if(tmp.first > tmp.second)Exit("YES");
        dp_h[i] = tmp;
    }
    if(dp_w[0].first <= sc && sc <= dp_w[0].second){
        if(dp_h[0].first <= sr && sr <= dp_h[0].second){
            Exit("NO");
        }
    }
    Exit("YES");

    return 0;
}

