    if (x < 0 || x >= H){
      pp(now);
      pp(who);
      pp(x);
      return true;
  }
    if(now == N)return false;

    // Takahasi
    if(who == 0) {
      if(T[now] == 'U'){
        return maxU(x-1, now, 1);
      }
      else{
