/*
두 그거에 대해서.
0<=t<=N에 대해서.
D[i]: t시간이ㅔ i에 있으면 타카하시가 이기는지.
t를 거꾸로 보면서. 만약 A가 내리는 거면 
*/

int h, w, sr, sc, n;
char S[200010], T[200010];

pii solve(char u, char d, int s, int e){
	pii st = {s,e};

	for(int i=n; i>=1; i--){
		if(T[i]==u) st.second = min(st.second+1, e);
		if(T[i]==d) st.first  = max(st.first-1,  s);

		if(S[i]==u) st.first  = st.first+1;
		if(S[i]==d) st.second = st.second-1;

		// cout<<st.first<<' '<<st.second<<'\n';
		if(st.first+1>=st.second) return st;
	}

	return st;
}


int main(){
	ios::sync_with_stdio(0); cin.tie(0);

	cin>>h>>w>>n>>sr>>sc;
	cin>>(S+1)>>(T+1);

	pii row = solve('U', 'D', 0, h+1);
	pii col = solve('L', 'R', 0, w+1);

	// cout<<row.first<<' '<<row.second<<'\n';
	// cout<<col.first<<' '<<col.second<<'\n';

	bool aowin = (row.first<sr && sr<row.second && col.first<sc && sc<col.second);

	cout<<(aowin ? "YES" : "NO")<<'\n';

	return 0;
}

