    for(int i=0; i<N-1; i++){
        left[i+1] =left[i];
        if(T.at(i)=='R' && (Sy -left[i] < W)) left[i+1]--;
        if(S.at(i+1)=='L') left[i+1]++;
    }

    //
    for(int i=0; i<N; i++){
        if(left[i] >= Sy){
            flag = false;
        }
    }

    if(flag) cout << "YES" << endl;
    else cout << "NO" << endl;
}

