bool check(int pos, int n, const string &s, const string &t, const string &lr)
{
	int lpos = pos, rpos = pos;
	int st;

	for (st = 0; st < (int) s.size(); st++)
	{
		if (s[st] == lr[0] || s[st] == lr[1])
			break;
		if (t[st] == lr[0])
			lpos--;
		if (t[st] == lr[1])
			rpos++;
	}

	lpos = max (0, lpos);
	rpos = min (n - 1, rpos);

	int q = 0, l = 0;

	for (int i = st; i < (int) s.size(); i++)
	{
		if (s[i] == lr[0])
			q--;
		l = min (l, q);
		if (t[i] == lr[1] && q != n - 1)
			q++;
	}

	l = -l;
	q = 0;
	int r = 0;

	for (int i = st; i < (int) s.size(); i++)
	{
		if (s[i] == lr[1])
			q++;
		r = max (r, q);
		if (t[i] == lr[0] && q != 0)
			q--;
	}

	if (n - r <= l)
		return false;
	return lpos < n - r && l <= rpos;
}


