bool solve() {
  int h, w, n; scanf("%d%d%d", &h, &w, &n);
  int sr, sc; scanf("%d%d", &sr, &sc);
  for (int i = 0; i < n; ++i) {
    scanf(" %c", s+i);
    if (s[i] == 'L') s[i] = 0;
    else if (s[i] == 'R') s[i] = 1;
    else if (s[i] == 'U') s[i] = 2;
    else s[i] = 3;
  }
  for (int i = 0; i < n; ++i) {
    scanf(" %c", t+i);
    if (t[i] == 'L') t[i] = 0;
    else if (t[i] == 'R') t[i] = 1;
    else if (t[i] == 'U') t[i] = 2;
    else t[i] = 3;
  }
  int z[4] = {0, 0, 0, 0};
  ++z[s[n-1]];
  for (int i = n-2; i >= 0; --i) {
    z[t[i]] = max(z[t[i]]-1, 0);
    ++z[s[i]];
    if (z[0] > w-z[1] || z[2] > h-z[3]) return false;
  }
  return z[0] <= sc && z[1] > w-sc && z[2] <= sr && z[3] > h-sr;
}

