#include <bits/stdc++.h>
using namespace std;

bool is_valid(int lower_bound, int upper_bound, string S, string T, const char plus, const char minus, int start, int n)
{
    int minimum = 1;
    int maximum = upper_bound;
    if (S.back() == plus)
    {
        upper_bound--;
    }
    if (S.back() == minus)
    {
        lower_bound++;
    }

    int idx = n - 2;
    while (idx >= 0)
    {
        if (lower_bound > upper_bound)
        {
            return false;
        }
        if (T[idx] == plus)
        {
            lower_bound--;
        }
        if (T[idx] == minus)
        {
            upper_bound++;
        }

        if (S[idx] == plus)
        {
            if (upper_bound > maximum)
            {
                upper_bound--;
            }
            upper_bound--;
        }
        if (S[idx] == minus)
        {
            if (lower_bound < minimum)
            {
                lower_bound++;
            }
            lower_bound++;
        }
        upper_bound = min(upper_bound, maximum);
        lower_bound = max(lower_bound, minimum);
        idx--;
    }
    if (lower_bound > start || start > upper_bound)
    {
        return false;
    }
    return true;
}

