bool solve()
{
	int H, W, N, s[2];
	scanf("%d%d%d%d%d", &H, &W, &N, s, s + 1);
	std::string S, T;
	std::cin >> S >> T;
	s[0]--;
	s[1]--;

	int left{-1}, right{W}, top{-1}, down{H};
	for (int i{N - 1}; i >= 0; i--)
	{
		if (T[i] == 'L')
			right = std::min(right + 1, W);
		else if (T[i] == 'R')
			left = std::max(left - 1, -1);
		else if (T[i] == 'U')
			down = std::min(down + 1, H);
		else
			top = std::max(top - 1, -1);

		if (S[i] == 'L')
			left = left + 1;
		else if (S[i] == 'R')
			right = right - 1;
		else if (S[i] == 'U')
			top = top + 1;
		else
			down = down - 1;
		if (left + 1 == right || top + 1 == down)
			return false;
	}
	return top < s[0] && s[0] < down && left < s[1] && s[1] < right;
}

