bool solve(int H, int W, int N, int Sr, int Sc, string& S, string& T) {
    // i回目(0..N-1)の行動終了時点でleft <= right の位置に駒があれば後手が勝てる
    int left = 1, right = W;

    RREP(i,0,N) {
        // 後手は範囲を広げようとする
        if (T[i] == 'R') {
            left = max(1, left-1);
        } else if (T[i] == 'L') {
            right = min(W, right+1);
        }

        // 先手は範囲を縮めようとする
        if (S[i] == 'L') {
            left++;
        } else if (S[i] == 'R') {
            right--;
        }

        if (left > right) return false;
    }
    if (left > Sc || right < Sc) return false;

    // i回目(0..N-1)でtop <= bottom の位置に駒があれば後手が勝てる
    int top = 1, bottom = H;

    RREP(i,0,N) {
        // 後手は範囲を広げようとする
        if (T[i] == 'U') {
            bottom = min(H, bottom+1);
        } else if (T[i] == 'D') {
            top = max(1, top-1);
        }

        // 先手は範囲を縮めようとする
        if (S[i] == 'D') {
            bottom--;
        } else if (S[i] == 'U') {
            top++;
        }

        if (top > bottom) return false;
    }
    if (top > Sr || bottom < Sr) return false;

    return true;
}

