bool check(int pos, int n, const string &s, const string &t, const string &lr)
{
	int q = pos;

	for (int i = 0; i < (int) s.size(); i++)
	{
		if (s[i] == lr[0])
			q--;
		if (q < 0)
			return false;
		if (t[i] == lr[1] && q != n - 1)
			q++;
	}

	for (int i = 0; i < (int) s.size(); i++)
	{
		if (s[i] == lr[1])
			q++;
		if (q >= n)
			return false;
		if (t[i] == lr[0] && q != 0)
			q--;
	}

	return true;
}


