bool solve(int h, int s, vector<int> &a, vector<int> &b)
{
	int l = 1, r = h;
	for (int i = N - 1; i >= 0; i--){
		if (b[i] == 1) l--;
		if (b[i] == -1) r++;

		if (l < 1) l = 1;
		if (r > h) r = h;

		if (a[i] == -1) l++;
		if (a[i] == 1) r--;
		if (l > r) return true;
	}

	return !(l <= s && s <= r);
}

