static const int AGC033_BMax = 200000;

static void AGC033_B()
{
	int H, W, N, Sr, Sc;
	static char szS[AGC033_BMax + 4] = { 0 };
	static char szT[AGC033_BMax + 4] = { 0 };

	scanf(" %d %d %d %d %d", &H, &W, &N, &Sr, &Sc);
	scanf(" %s %s", szS, szT);

	int tkLeft = 0, tkRight = 0, tkUp = 0, tkDown = 0;
	int aoLeft = 0, aoRight = 0, aoUp = 0, aoDown = 0;

	for (int i = 0; i < N; i++) {
		switch (szS[i]) {
		case 'L':
			tkLeft++;
			break;
		case 'R':
			tkRight++;
			break;
		case 'U':
			tkUp++;
			break;
		case 'D':
			tkDown++;
			break;
		}

		switch (szT[i]) {
		case 'L':
			aoLeft++;
			break;
		case 'R':
			aoRight++;
			break;
		case 'U':
			aoUp++;
			break;
		case 'D':
			aoDown++;
			break;
		}
	}

	const char* ans = "NO\n";
	if (((Sr == 1) && (szS[0] == 'U')) ||
		((Sr == H) && (szS[0] == 'D')) ||
		((Sc == 1) && (szS[0] == 'L')) ||
		((Sc == W) && (szS[0] == 'R'))){
		ans = "YES\n";
	}

	tkLeft = ((tkLeft - aoRight) > 0) ? (tkLeft - aoRight) : 0;
	tkRight = ((tkRight - aoLeft) > 0) ? (tkRight - aoLeft) : 0;
	tkUp = ((tkUp - aoDown) > 0) ? (tkUp - aoDown) : 0;
	tkDown = ((tkDown - aoUp) > 0) ? (tkDown - aoUp) : 0;

	if (((Sr - tkUp) <= 0) ||
		((Sr + tkDown) > H) ||
		((Sc - tkLeft) <= 0) ||
		((Sc + tkRight) > W)) {
		ans = "YES\n";
	}
	printf(ans);
}

