  --sr;
  --sc;

  string S, T;
  cin >> S >> T;

  bool ok = true;
  int w_min, w_max, h_min, h_max;

  w_min = h_min = 0;
  w_max = W - 1;
  h_max = H - 1;

  // 横方向
  for (int i = N - 1; i >= 0; i--)
  {
    if (S[i] == 'U' || S[i] == 'D' || !ok)
      continue;

    if (S[i] == 'L')
    {
      w_min++;
    }
    else
    {
      // 'R'
      w_max--;
    }

    if (T[i] == 'L')
    {
      w_max = min(w_max + 1, W - 1);
    }
    else
    {
      // 'R'
      w_min = max(w_min - 1, 0);
    }

    if (w_max < w_min)
      ok = false;
  }

  if (!ok)
  {
    cout << "NO" << endl;
    return 0;
  }

  // 縦方向
  for (int i = N - 1; i >= 0; i--)
  {
    if (S[i] == 'L' || S[i] == 'R' || !ok)
      continue;

    if (S[i] == 'U')
    {
      h_min++;
    }
    else
    {
      // 'D'
      h_max--;
    }

    if (T[i] == 'U')
    {
      h_max = min(h_max + 1, H - 1);
    }
    else
    {
      // 'D'
      h_min = max(h_min - 1, 0);
    }

    if (h_max < h_min)
      ok = false;
  }

  if (!ok)
  {
    cout << "NO" << endl;
    return 0;
  }

  // cout << h_min << h_max << w_min << w_max << endl;
  // cout << sr << sc << endl;
  // if スタートが範囲内
  if (h_min <= sr && sr <= h_max && w_min <= sc && sc <= w_max)
    cout << "YES" << endl;
  else
    cout << "NO" << endl;

  return 0;
}

