int n;
string s, t;
bool f(ll sx, ll w, char back, char next) {
  ll ngl = 0, ngr = w + 1;
  ll sal = sx, sar = sx;
  bool ok = true;
  for (int i = 0; i < n; i++) {
    if (s[i] == next) {
      ngr -= 1;
    } else if (s[i] == back) {
      ngl += 1;
    }
    if (ngl == ngr) {
      ok = false;
    }
    if (ngl == sar) {
      ok = false;
    }
    if (ngr == sal) {
      ok = false;
    }
    if (t[i] == next) {
      sar += 1;
    } else if (t[i] == back) {
      sal -= 1;
    }
    sar = min(sar, w);
    sal = max(sal, 1LL);
    if (ngl == sar) {
      ok = false;
    }
    if (ngr == sal) {
      ok = false;
    }
  }
  return ok;
}

