bool solveonedim(int start) {
	//printf("solveonedim(%d,%d,%s,%s)\n",len,start,c,d);
	int l=1,r=len;
	for(int i=n-1;i>=0;--i) {
		if(d[i]=='-') r=min(r+1,len);
		if(d[i]=='+') l=max(l-1,1);
		if(c[i]=='-') ++l;
		if(c[i]=='+') --r;
		if(l>r) return false;
		//printf("\tat start of %d: %d..%d\n",i,l,r);
	}
	return l<=start&&start<=r;
}

