pair<int, int> dir(char c) {
    if (c == 'L') {
        return {0, -1};
    } else if (c == 'R') {
        return {0, 1};
    } else if (c == 'U') {
        return {-1, 0};
    } else {
        return {1, 0};
    }
}

bool win(int n, int x, vector<pair<int, int> >& d) {
    for (int f : {-1, 1}) {
        int xx = x;
        for (const auto& g : d) {
            if (g.first == f) {
                xx += g.first;
            }
            if (xx <= 0 || xx > n) {
                return true;
            }
            if (g.second != f && xx + g.second > 0 && xx + g.second <= n) {
                xx += g.second;
            }
        }
    }
    return false;
}

