int H, W;

void aoki(char c, int &l, int &r, int &u, int &d)
{
    if(c == 'L') r = min(W, r+1);
    else if(c == 'R') l = max(1, l-1);
    else if(c == 'U') d = min(H, d+1);
    else if(c == 'D') u = max(1, u-1);
}
void takahashi(char c, int &l, int &r, int &u, int &d)
{
    if(c == 'L') l++;
    else if(c == 'R') r--;
    else if(c == 'U') u++;
    else if(c == 'D') d--;
}

