#include <bits/stdc++.h>
using namespace std;

map<char, int> diff_row = {{'R', 0}, {'L', 0}, {'U', -1}, {'D', 1}};
map<char, int> diff_col = {{'R', 1}, {'L', -1}, {'U', 0}, {'D', 0}};

bool dp(
    int H,
    int W,
    map<tuple<int, int, int>, string>& dp_table,
    string player,
    string S,
    string T,
    int row,
    int col
){
    auto key = make_tuple(row, col, S.size() + T.size());
    if(dp_table.find(key)!=dp_table.end()){
        return dp_table[key] == player;
    }

    string next_player = (player=="Takahashi") ? "Aoki" : "Takahashi";
    if(player=="Takahashi"){
        if(
            ((S[0] == 'R') && (col == W-1)) ||
            ((S[0] == 'L') && (col == 0)) ||
            ((S[0] == 'U') && (row == 0)) ||
            ((S[0] == 'D') && (row == H-1))
        ){
            dp_table[key] = "Takahashi";
            return true;
        }

        int new_row = row + diff_row[S[0]];
        int new_col = col + diff_col[S[0]];
        if(
            dp(H, W, dp_table, next_player, S.substr(1), T, row, col) &&
            dp(H, W, dp_table, next_player, S.substr(1), T, new_row, new_col)
        ){
            dp_table[key] = "Aoki";
            return false;
        }else{
            dp_table[key] = "Takahashi";
            return true;
        }
    }else{
        if(S.size()==0){
            if((0 <= row) && (row < H) && (0 <= col) && (col < W)){
                dp_table[key] = "Aoki";
                return true;
            }else{
                dp_table[key] = "Takahashi";
                return false;
            }
        }
        int new_row = row + diff_row[T[0]];
        int new_col = col + diff_col[T[0]];
        if((0 <= new_row) && (new_row < H) && (0 <= new_col) && (new_col < W)){
            if(
                dp(H, W, dp_table, next_player, S, T.substr(1), row, col) &&
                dp(H, W, dp_table, next_player, S, T.substr(1), new_row, new_col)
            ){
                dp_table[key] = "Takahashi";
                return false;
            }else{
                dp_table[key] = "Aoki";
                return true;
            }
        }else{
            if(
                dp(H, W, dp_table, next_player, S, T.substr(1), row, col)
            ){
                dp_table[key] = "Takahashi";
                return false;
            }else{
                dp_table[key] = "Aoki";
                return true;
            }
        }
    }
}

