		S_r.at(i+1)=S_r.at(i);
		S_u.at(i+1)=S_u.at(i);
		S_d.at(i+1)=S_d.at(i);
		if(S.at(i)=='L')	S_l.at(i+1)++;
		else if(S.at(i)=='R')	S_r.at(i+1)++;
		else if(S.at(i)=='U')	S_u.at(i+1)++;
		else if(S.at(i)=='D')	S_d.at(i+1)++;
	}
	vector<int> T_l(N+3,0);
	vector<int> T_r(N+3,0);
	vector<int> T_u(N+3,0);
	vector<int> T_d(N+3,0);
	for(int i=0;i<N;i++){
		T_l.at(i+1)=T_l.at(i);
		T_r.at(i+1)=T_r.at(i);
		T_u.at(i+1)=T_u.at(i);
		T_d.at(i+1)=T_d.at(i);
		if(T.at(i)=='L')	T_l.at(i+1)++;
		else if(T.at(i)=='R')	T_r.at(i+1)++;
		else if(T.at(i)=='U')	T_u.at(i+1)++;
		else if(T.at(i)=='D')	T_d.at(i+1)++;
		if(sc-T_l.at(i+1)+S_r.at(i+2)<=0)	T_l.at(i+1)=sc-1;
		if(sc+T_r.at(i+1)-S_l.at(i+2)>W)	T_r.at(i+1)=W-sc;
		if(sr-T_u.at(i+1)+S_d.at(i+2)<=0)	T_u.at(i+1)=sr-1;
		if(sr+T_d.at(i+1)-S_u.at(i+2)>H)	T_d.at(i+1)=H-sr;
	}

	bool flag=true;
	for(int i=1;i<N+1;i++){
		if(sc-S_l.at(i)+T_r.at(i-1)<=0)	flag=false;
		if(sc+S_r.at(i)-T_l.at(i-1)>W)	flag=false;
		if(sr-S_u.at(i)+T_d.at(i-1)<=0)	flag=false;
		if(sr+S_d.at(i)-T_u.at(i-1)>H)	flag=false;
	}
	if(flag)	cout << "YES" << endl;
	else	cout << "NO" << endl;

	return 0;
}

