int h , w , n , SR , SC ;
string s , t ;

int best ( char c )
{
    if ( c == 'L' && SC <= w / 2 + 1 )
    {
        SC -- ; return 1 ;
    }
    else if ( c == 'R' && SC >= w - w / 2 )
    {
        SC ++ ; return 1 ;
    }
    else if ( c == 'U' && SR <= h / 2 + 1 )
    {
        SR -- ; return 1 ;
    }
    else if ( c == 'D' && SR >= h - h / 2 )
    {
        SR ++ ; return 1 ;
    }
    else return 0 ;
}

void besT ( char c )
{
    if ( c == 'R' && SC < w / 2 )
    {
        SC ++ ;
    }
    else if ( c == 'L' && SC > w - w / 2 )
    {
        SC -- ;
    }
    else if ( c == 'D' && SR < h / 2 )
    {
        SR ++ ;
    }
    else if ( c == 'U' && SR > h - h / 2 )
    {
        SR -- ;
    }
    return ;
}

bool check ()
{
    return ( SR == 0 || SR > h || SC == 0 || SC > w ) ;
}

int main()
{
    cin >> h >> w >> n >> SR >> SC >> s >> t ;
    for ( int i = 0 ; i < n ; i ++ )
    {
        if ( best ( s [ i ] ) )
        {
            if ( check() )
            {
                cout << "NO" << endl ;
                return 0 ;
            }
        }
        besT ( t [ i ] ) ;
    }
    cout << "YES" << endl ;
    return 0 ;
}

