bool game(int a, int w, char up, char dow){
            int mir = a, mar = a;
            bool ok = 0;
            int tp = 0, tm = 0;
            for(int i = 0; i < n; ++i){
            if(s[i] == up){
                mar++;
            }
            if(s[i] == dow){
                mir--;
            }
            if(mar - mir >= w)ok = 1;
            if(mir <= 0){
                if(tp){
                    mir++;
                    mar++;
                    --tp;
                }
                else ok = 1;
            }
            if(mar > w){
                if(tm){
                    mir--;
                    mar--;
                    --tm;
                }
                else ok = 1;
            }
            if(t[i] == up){
                if(mar > mir){
                    mir++;
                }
                else ++tp;
            }
            if(t[i] == dow){
                if(mar > mir){
                    mar--;
                }
                else ++tm;
            }
        } 
        return ok;
}
