class B {
public:
    void solve(std::istream &in, std::ostream &out) {
        ios_base::sync_with_stdio(0);
        in.tie(0);

        int n, m, k;
        in >> n >> m >> k;
        int x, y;
        in >> x >> y;
        x--;
        y--;
        string s, t;
        in >> s >> t;


        string res = "YES";
        int mnx = -1, mxx = n;
        int mny = -1, mxy = m;
        for (int i = k - 1; i >= 0; i--) {
            if (t[i] == 'U') {
                mxx = min(n, mxx + 1);
            } else if (t[i] == 'D') {
                mnx = max(-1, mnx - 1);
            } else if (t[i] == 'L') {
                mxy = min(m, mxy + 1);
            } else if (t[i] == 'R') {
                mny = max(-1, mny - 1);
            } else
                assert(0);

            if (s[i] == 'U') {
                mnx = min(n - 1, mnx + 1);
            } else if (s[i] == 'D') {
                mxx = max(0, mxx - 1);
            } else if (s[i] == 'L') {
                mny = min(m - 1, mny + 1);
            } else if (s[i] == 'R') {
                mxy = max(0, mxy - 1);
            } else
                assert(0);

            if (mnx == n - 1 || mxx == 0 || mny == m - 1 || mxy == 0) res = "NO";
        }
//        db2(mnx, mxx);
//        db2(mny, mxy);
        if (x <= mnx || x >= mxx || y <= mny || y >= mxy) res = "NO";
        out << res << endl;
    }
};


int main() {
    B solver;
    std::istream &in(std::cin);
    std::ostream &out(std::cout);
    solver.solve(in, out);
    return 0;
}

