int H,W,N;
string S,T;
bool solve(int t, int mx, int sx){
    //Nターン後は、
    //[0, N-1]の区間に入っていられるかどうか
    char plus = 'D';
    char minu = 'U';
    if(t == 1){
        plus = 'L';
        minu = 'R';
    }
    // [l, r)の区間
    int l = 0, r = mx;
    for(int i = N-1;i >= 0;i--){
        if(l == r)return false;
        if(i != N - 1){
            if(T[i] == plus){
                r++;
                chmin(r, N);
            }
            else if(T[i] == minu){
                l--;
                chmax(l, 0);
            }
        }
        if(S[i] == plus){
            l++;
        }
        else if(S[i] == minu){
            r--;
        }
    }
    //cerr << l << " " << r << endl;
    //cerr << sx << endl;
    if(sx < l || r <= sx){
        return false;
    }
    return true;
}
int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(20);
    int sx, sy;
    cin >> H >> W >> N;
    cin >> sx >> sy;
    sx--;sy--;
    cin >> S >> T;
    bool ok = true;
    if(!solve(0, H, sx)){
        ok = false;
    } 
    if(!solve(1, W, sy)){
        ok = false;
    }
    cout << (ok ? YES :NO) << endl;
}

