void cnt(char c) {
  if (c == 'L') {
    L--;
  } else if (c == 'R') {
    R++;
  } else if (c == 'U') {
    U--;
  } else {
    D++;
  }
}

void hoge(char c) {
  if (c == 'L') {
    R--;
  } else if (c == 'R') {
    L++;
  } else if (c == 'U') {
    D--;
  } else {
    U++;
  }
}

bool check() {
  if (L < 1) {
    return true;
  } else if (R > W) {
    return true;
  } else if (U < 1) {
    return true;
  } else if (D > H) {
    return true;
  }
  return false;
}

void marume() {
  if (L > W) {
    L = W;
  }
  if (R < 1) {
    R = 1;
  }
  if (U > H) {
    U = H;
  }
  if (D < 1) {
    D = 1;
  }
}

