using namespace std;

void fail() {
    cout << "NO" << endl;
    exit(0);
}

int main() {
    int H, W, N, sy, sx;
    string S, T;
    cin >> H >> W >> N >> sy >> sx >> S >> T;
    reverse(S.begin(), S.end());
    reverse(T.begin(), T.end());

    int L = 0, R = W + 1, U = 0, D = H + 1;
    for (int i = 0; i < N; ++i) {
        // L vs R
        if (L >= 1 && T[i] == 'R') --L;
        if (S[i] == 'L') ++L;

        // R vs L
        if (R <= W && T[i] == 'L') ++R;
        if (S[i] == 'R') --R;
        if (L == W || R == 0 || L >= R - 1) fail();

        // U vs D
        if (U >= 1 && T[i] == 'D') --U;
        if (S[i] == 'U') ++U;

        // D vs U
        if (D <= H && T[i] == 'U') ++D;
        if (S[i] == 'D') --D;
        if (U == H || D == 0 || U >= D - 1) fail();
    }

    cout << (L < sx && sx < R && U < sy && sy < D ? "YES" : "NO") << endl;
    return 0;
}

