#define MOD 1000000007

ll N, sr, sc;
string S, T;

bool test(char u, char l, ll x, ll pos) {
  vll ub(N), lb(N);
  if (S[N - 1] == u) {
    ub[N - 1] = x - 1;
    lb[N - 1] = 1;
    if (ub[N-1] <= x) return true;
  } else if (S[N - 1] == l) {
    ub[N - 1] = x;
    lb[N - 1] = 2;
    if (lb[N-1] >= x) return true;
  } else {
    ub[N - 1] = x;
    lb[N - 1] = 1;
  }
  for (int i = N - 2; i >= 0; i--) {
    if (S[i] == u) {
      if (T[i] == l) {
        ub[i] = min(ub[i + 1], x-1);
      } else {
        ub[i] = ub[i + 1] - 1;
        if (ub[i] <= 1) return true;
      }
      lb[i] = lb[i + 1];
    } else if (S[i] == l) {
      if (T[i] == u) {
        lb[i] = max(lb[i + 1], 2LL);
      } else {
        lb[i] = lb[i + 1] + 1;
        if (lb[i] >= x) return true;
      }
      ub[i] = ub[i + 1];
    } else {
      if (T[i] == u) {
        ub[i] = ub[i + 1];
        lb[i] = max(1LL, lb[i + 1] - 1);
      } else if (T[i] == l) {
        ub[i] = min(x, ub[i + 1] + 1);
        lb[i] = lb[i + 1];
      } else {
        ub[i] = ub[i + 1];
        lb[i] = lb[i + 1];
      }
    }
  }  // i

  return (pos < lb[0] || pos > ub[0]);
}  // test

int main() {
  ll H, W;
  cin >> H >> W >> N >> sr >> sc >> S >> T;

  if (test('D', 'U', H, sr) || test('R', 'L', W, sc))
    puts("NO");
  else
    puts("YES");

  return 0;
}

