    threshold[0] = sc;
    threshold[1] = w - sc + 1;
    threshold[2] = sr;
    threshold[3] = h - sr + 1;

    for (int i = 0; i < 4; ++i) lim[i] = threshold[i];
    // cout << '\n';
    for (int i = 0; i < n; ++i) {
        int dir = m[s[i]];
        ++moves[0][dir];
        if (dir == 0) ++lim[1];
