        bool out = false;
        if (moves[0][0] - moves[1][1] >= threshold[0]) out = true;
        if (moves[0][1] - moves[1][0] >= threshold[1]) out = true;
        if (moves[0][2] - moves[1][3] >= threshold[2]) out = true;
