bool solve(int W, int x, const std::string& S, const std::string& T)
{
  std::string s;

  for (int i = 0, size = S.size(); i < size; i ++) {
    if (S[i] == 'L' || S[i] == 'R')
      s.push_back(S[i]);

    if (T[i] == 'L' || T[i] == 'R')
      s.push_back(tolower(T[i]));
  }

  int N = s.size(), l = 1, r = W;

  for (int i = N - 1; i >= 0; i --) {
    char c = s[i];

    if (c == 'L') {
      l ++;
    }
    else if (c == 'R') {
      r --;
    }
    else if (c == 'l') {
      r = std::min(r + 1, W);
    }
    else {
      assert(c == 'r');

      l = std::max(l - 1, 1);
    }

    if (l > r)
      return false;
  }

  return l <= x && x <= W;
}


int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);
  std::cerr << std::fixed << std::setprecision(6);

  int H, W, N, sr, sc, xm, xp, ym, yp;

  std::string S, T;

  std::cin >> H >> W >> N >> sr >> sc >> S >> T;

  std::string s(S), t(T);

  if (! solve(W, sc, s, t))
    no();

  for (int i = 0; i < N; i ++) {
    if (s[i] == 'R') {
      s[i] = 'D';
    }
    else if (s[i] == 'L') {
      s[i] = 'U';
    }
    else if (s[i] == 'U') {
      s[i] = 'L';
    }
    else {
      s[i] = 'R';
    }

    if (t[i] == 'R') {
      t[i] = 'D';
    }
    else if (t[i] == 'L') {
      t[i] = 'U';
    }
    else if (t[i] == 'U') {
      t[i] = 'L';
    }
    else {
      t[i] = 'R';
    }
  }

  if (! solve(H, sr, s, t))
    no();

  std::cout << "YES" << std::endl;

  return 0;
}

