bool check(int cur, char dec, char inc, int maxv)
{
    int left = 1;
    int right = maxv;
    for (int i = n; i >= 1; i--) {
        if (s[i] != dec && s[i] != inc) {
            if (t[i] == dec) right++;
            if (t[i] == inc) left--;
        } else if (t[i] != dec && t[i] != inc) {
            if (s[i] == dec) left++;
            if (s[i] == inc) right--;
        } else {
            if (s[i] == t[i]) {
                if (s[i] == dec) {
                    left++, right++;
                } else {
                    left--, right--;
                }
            } else {
                if (s[i] == dec) {
                    left = max(left, 2);
                } else {
                    right = min(right, maxv - 1);
                }
            }
        }
        left = max(left, 1);
        right = min(right, maxv);
        if (left > right) return true;
    }
    return cur < left || cur > right;
}

