const string ds = "LRUD";
const int dh[4] = {0, 0, -1, 1};
const int dw[4] = {-1, 1, 0, 0};

int H, W, N;
int sr, sc;
string S[2];

bool solve() {
    for (int k = 0; k < 4; k++) {
        int h = sr, w = sc;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < 2; j++) {
                if (S[j][i] == ds[k ^ j]) {
                    h += dh[k ^ j];
                    w += dw[k ^ j];
                    if ((k == 0 && w < 0) || (k == 1 && W <= w) ||
                        (k == 1 && h < 0) || (k == 3 && H <= h)

                    ) {
                        return false;
                    }
                    h = max(h, 0);
                    h = min(h, H);
                    w = max(w, 0);
                    w = min(w, W);
                }
            }
        }
    }

    return true;
}

