using namespace std;
void solve(vector<pair<int, int> > &ev, int start, int tot){
    int L = 1, R = tot;
//    for (int i=0;i<ev.size();i++) cout << ev[i].first << " " << ev[i].second << endl;
//    cout << endl;
    for (int i=ev.size() - 1; i >= 0; i--){
        if (ev[i].first == -1 && ev[i].second == 0){
            L++;
        }
        if (ev[i].first == 1 && ev[i].second == 0){
            R--;
        }
        if (ev[i].first == -1 && ev[i].second == 1){
            R=min((int) tot, R+1);
        }
        if (ev[i].first == 1 && ev[i].second == 1){
            L = max(1LL, L-1);
        }
        if (L > R){
            cout << "NO";
            exit(0);
        }
        //cout << "!!" << L << " " << R << endl;
    }
    if (start < L || start > R){
        cout << "NO";
        exit(0);
    }
}
