int H, W, N;
int SR, SC; 
string S, T;

bool solveLR() {
    int lo = 0; int hi = W - 1;
    R0F(i, N) {
        if (T[i] == 'L')             
            hi = min(hi+1, W-1);
        if (T[i] == 'R')
            lo = max(lo-1, 0);

        if (S[i] == 'L') ++lo;
        if (S[i] == 'R') --hi;

        if (lo > hi || lo > W - 1 || hi < 0) return false;
    }
    return lo <= SC && SC <= hi;
}

bool solveUD() {
    int lo = 0; int hi = H - 1;
    R0F(i, N) {
        if (T[i] == 'U')             
            hi = min(hi+1, H-1);
        if (T[i] == 'D')
            lo = max(lo-1, 0);

        if (S[i] == 'U') ++lo;
        if (S[i] == 'D') --hi;

        if (lo > hi || lo > H - 1 || hi < 0) return false;
    }
    return lo <= SR && SR <= hi;
}

