const bool IsMoreLikelyToFall(const int H, const int W, const int sr, const int sc, const char ch){
    switch(ch){
        case 'U':
            if(sr <= (H + 1) / 2) return true;
            else return false;
            break;
        case 'D':
            if(sr >= (H + 1) / 2) return true;
            else return false;
            break;
        case 'L':
            if(sc <= (W + 1) / 2) return true;
            else return false;
            break;
        case 'R':
            if(sc >= (W + 1) / 2) return true;
            else return false;
            break;
    }
}

void Move(const char ch, int &sr, int &sc){
    switch (ch)
    {
    case 'U':
        --sr;
        break;
    case 'D':
        ++sr;
        break;
    case 'L':
        --sc;
        break;
    case 'R':
        ++sc;
        break;
    }
}

bool HasFallen(const int H, const int W, const int sr, const int sc){
    return sr < 1 || sc < 1 || sr > H || sc > W;
}

