		int mn = 0, mx = dir == 0 ? W - 1 : H - 1;
		int l = mn, r = mx;

		for (int i = liv.size() - 1; i >= 0; --i) {
			int d = mm[T[i]];
			if (dir == 1 ^ d < 2) {
				int p = d & 1 ? 1 : -1;
				l = min(l, max(l - p, mn));
				r = max(r, min(r - p, mx));
			}
			d = mm[S[i]];
			ok &= l <= r;
			if (dir == 1 ^ d < 2) {
				int p = d & 1 ? 1 : -1;
				l = max(l, l - p);
				r = min(r, r - p);
			}
			ok &= l <= r;
		}

		int cx = dir == 0 ? sc : sr;
		ok &= l <= cx && cx <= r;
	}

	puts([&] {
		return ok;
	}() ? "YES": "NO");
	return 0;
}

