            if (w_dir[i] == 1) {
                R--;
            } else {
                L++;
            }
        } else {
            if (w_dir[i] == 1) {
                L = max(L - 1, 1);
            } else {
                R = min(R + 1, w);
            }
        }
        if (R < L) {
            return false;
        }
    }
    if (start >= L && start <= R) {
        return true;
    } else {
        return false;
    }
}

