int solve(int sx, string &S, string &T, int W, int dir) {

    int N = S.size();

    int l = 0, r = W - 1;
    for(int i = N - 1; i >= 0; i--) {
        if (dir == 0) {
            if (T[i] == 'L') r++;
            if (T[i] == 'R') l--;
            r = clamp(r, 0, W - 1);
            l = clamp(l, 0, W - 1);

            if (S[i] == 'L') l++;
            if (S[i] == 'R') r--;
            if (l > r) return 0;

        } else {
            if (T[i] == 'U') r++;
            if (T[i] == 'D') l--;
            r = clamp(r, 0, W - 1);
            l = clamp(l, 0, W - 1);

            if (S[i] == 'U') l++;
            if (S[i] == 'D') r--;
            if (l > r) return 0;
        }
    }

    return l <= sx && sx <= r;
}

