  int n = sz(vs);
  int l = 0, r = h + 1;
  for(int i = n - 1; i >= 0; i--){
    if(i < n - 1){
      // a
      if(vt[i] == 1){
        l = max(0, l - 1);
      }else if(vt[i] == -1){
        r = min(h + 1, r + 1);
      }
    }
    if(r <= l + 1)return false;
    // t
    if(vs[i] == 1){
      r = max(r - 1, 0);
