void move(int& sr, int& sc, char m) {
    if (m == 'U' )
        sr -= 1;
    if (m == 'D')
        sr += 1;
    if (m == 'L')
        sc -= 1;
    if (m == 'R')
        sc += 1;
}

bool simlation(vector<char>& S, vector<char>& T, int N, int H, int W, int sr, int sc) {
    rep(i, N) {
        move(sr, sc, S[i]);
        if (sr > H || sr <= 0 || sc > W || sc <= 0)
            return false;
        int new_sr, new_sc;
        new_sr = sr;
        new_sc = sc;
        move(new_sr, new_sc, T[i]);
        if (T[i] == 'U' || T[i] == 'D') {
            if (min(abs(H + 1 - new_sr), abs(0 - new_sr)) > min(abs(H + 1 - sr), abs(0 - sr))) {
                sr = new_sr;
                sc = new_sc;
            }
        }
        else {
            if (min(abs(W + 1 - new_sc), abs(0 - new_sc)) > min(abs(W + 1 - sc), abs(0 - sc))) {
                sr = new_sr;
                sc = new_sc;
            }
        }
    }
    return true;
}

int main() {
    int H, W, N, sr, sc;
    cin >> H >> W >> N >> sr >> sc;
    vector<char> S(N), T(N);

    rep(i, N) cin >> S[i];
    rep(i, N) cin >> T[i];
    vector<char> S1(N, '*'), T1(N, '*'), S2(N, '*'), T2(N, '*'), S3(N, '*'), T3(N, '*'), S4(N, '*'), T4(N, '*');
    rep(i, N) {
        if (S[i] == 'U')
            S1[i] = 'U';
        if (S[i] == 'D')
            S2[i] = 'D';
        if (S[i] == 'R')
            S3[i] = 'R';
        if (S[i] == 'L')
            S4[i] = 'L';

        if (T[i] == 'D')
            T1[i] = 'D';
        if (T[i] == 'U')
            T2[i] = 'U';
        if (T[i] == 'L')
            T3[i] = 'L';
        if (T[i] == 'R')
            T4[i] = 'R';
    }

    bool is_yes1 = simlation(S1, T1, N, H, W, sr, sc) && simlation(S2, T2, N, H, W, sr, sc);
    bool is_yes2 = simlation(S3, T3, N, H, W, sr, sc) && simlation(S4, T4, N, H, W, sr, sc);
    if (is_yes1 && is_yes2) cout << "YES" << endl;
    else cout << "NO" << endl;
}

