#include <bits/stdc++.h>
using namespace std;
#define REP(i,n) for (int i=0;i<(n);i++)
#define REP2(i,m,n) for (int i=m;i<(n);i++)
typedef long long ll;

int H, W;
string A[1010];
bool used[1010][1010];

int dr[4] = {0, 0, -1, 1};
int dc[4] = {-1, 1, 0, 0};

void solve() {
    cin >> H >> W;
    REP(i, H) cin >> A[i];

    queue<vector<int>> q;
    REP(i, H) REP(j, W) if (A[i][j] == '#') q.push({i, j, 0});
    int ans = 0;

    while (!q.empty()) {
        int r = q.front()[0];
        int c = q.front()[1];
        int d = q.front()[2];
        q.pop();
        if (used[r][c]) continue;
        used[r][c] = true;
        ans = max(ans, d);
        REP(i, 4) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
            if (used[nr][nc]) continue;
            q.push({nr, nc, d+1});
        }
    }

    cout << ans << endl;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

