			possible = false;
			break;
		}
	}

	sj = y;
	for(int i =	0; i < n; i++){
		if(s[i] == 'R'){
			sj++;
		}
		if(sj > w){
			possible = false;
			break;
		}
		if(i == n - 1) break;
		if(sj + r[i+1] > w && t[i] == 'L'){
			sj--;
		}
		if(sj <= 0){
			possible = false;
			break;
		}
	}

	si = x;
	for(int i =	0; i < n; i++){
		if(s[i] == 'U'){
			si--;
		}
		if(si <= 0){
			possible = false;
			break;
		}
		if(i == n - 1) break;
		if(si - u[i+1] <= 0 && t[i] == 'D'){
			si++;
		}
		if(si > h){
			possible = false;
			break;
		}
	}

	si = x;
	for(int i =	0; i < n; i++){
		if(s[i] == 'D'){
			si++;
		}
		if(si > h){
			possible = false;
			break;
		}
		if(i == n - 1) break;
		if(si + d[i+1] > h && t[i] == 'U'){
			si--;
		}
		if(si <= 0){
			possible = false;
			break;
		}
	}

	if(!possible){
		cout << "NO\n";
	}else{
		cout << "YES\n";
	}

    return 0;
}

