  if(t[0]=='R'&&r-tr[0]>0) ar[0]=1;
  if(t[0]=='U'&&u-tu[0]>0) au[0]=1;
  if(t[0]=='D'&&d-td[0]>0) ad[0]=1;
  fou(i,1,n){
