    ad[i]=ad[i-1];if(t[i]=='D'&&d-ad[i-1]-td[i-1]>0) ad[i]+=1;
  }

  string ans="YES";
  if(l-tl[0]<0) ans="NO";
  if(r-tr[0]<0) ans="NO";
  if(u-tu[0]<0) ans="NO";
  if(d-td[0]<0) ans="NO";
  fou(i,1,n){
    if(l+ar[i-1]-tl[i]<0) ans="NO";
    if(r+al[i-1]-tr[i]<0) ans="NO";
    if(u+ad[i-1]-tu[i]<0) ans="NO";
    if(d+au[i-1]-td[i]<0) ans="NO";
  }
  out(ans);
}

