bool check(vector<int>& A, vector<int>& B, int v)
{
  int l = 0, r = v;
  for (int i = 0; i < n; i++) {
    if (B[i] == 1) l = max(l-1, 0);
    if (B[i] == -1) r = min(r+1, v);
    if (A[i] == 1) r--;
    if (A[i] == -1) l++;
    if (l == r) return false;
  }
  return true;
}

