using namespace std;

int H, W, N;
int sr, sc;
string S, T;

int Get(int pos, char ch, char lef, char rig)
{
    if (ch == lef) return pos - 1;
    if (ch == rig) return pos + 1;
    return pos;
}

bool Hold(char lef, char rig, int lim, int L, int R, int p, int i)
{
    if (p < 1 || p > lim) return false;
    else if (p < L || p > R) {
        int fix = Get(p, T[i], lef, rig);
        if (fix < L || fix > R) return false;
        return true;
    }
    return true;
}

bool Solve(char lef, char rig, int lim, int cur)
{
    int L = 1, R = lim;
    for (int i = N - 1; i >= 0; i--) {
        int L2 = L, R2 = R;
        if (!Hold(lef, rig, lim, L, R, L, i) ||
            S[i] == lef && !Hold(lef, rig, lim, L, R, L - 1, i))
            L2 = L + 1;
        else if (!Hold(lef, rig, lim, L, R, L - 1, i) ||
                 S[i] == lef && !Hold(lef, rig, lim, L, R, L - 2, i))
            L2 = L;
        else L2 = L - 1;
        if (!Hold(lef, rig, lim, L, R, R, i) ||
            S[i] == rig && !Hold(lef, rig, lim, L, R, R + 1, i))
            R2 = R - 1;
        else if (!Hold(lef, rig, lim, L, R, R + 1, i) ||
                 S[i] == rig && !Hold(lef, rig, lim, L, R, R + 2, i))
            R2 = R;
        else R2 = R + 1;
        L = L2, R = R2;
    }
    return L <= cur && cur <= R;
}

int main()
{
    scanf("%d %d %d", &H, &W, &N);
    scanf("%d %d", &sr, &sc);
    cin >> S >> T;
    printf("%s\n", (Solve('L', 'R', W, sc) && Solve('U', 'D', H, sr))? "YES": "NO");
    return 0;
}

