        l = sc - cnt1[3];
        r = sc - cnt1[4];
        ansl = -cnt2[3];
        ansr = -cnt2[4];
    }
    while(ansl <= ansr){
        int mid = (ansl + ansr) >> 1;
        if(l + mid >= L){   // 下界ok
            if(r+mid <= R){ // 上界也ok
                return true; // 可以抵挡住
            } else { // r+mid > R // mid太大.需要小一点
                ansr = mid-1;
            }
        } else { // l+mid < L. 下界太小
            ansl = mid+1;
        }
    }
    return false;
}

