template <char c1, char c2>
bool solve(int m, int pos)
{
    b.reset();
    b[0] = true;
    b[m + 1] = true;

    for (int i = n - 1; i >= 0; i--)
    {
        if (t[i] == c1)
            b &= (b << 1);
        else if (t[i] == c2)
            b &= (b >> 1);

        b[0] = true;
        b[m + 1] = true;

        if (s[i] == c1)
            b |= (b << 1);
        else if (s[i] == c2)
            b |= (b >> 1);

        b[0] = true;
        b[m + 1] = true;
    }

    return b[pos + 1];
}

