#include <cstdio>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <cstdlib>
#include <queue>
#include <iostream>
#include <bitset>
#include <stack>
using namespace std;
#define N 200005
int h,w,n,x,y;char s[N],t[N];
int dx[]={1,0,-1,0},dy[]={0,1,0,-1};
stack<int>p[4];
int trs(char c){if(c=='U')return 2;if(c=='D')return 0;if(c=='L')return 3;return 1;}
bool check(int op1,int op2)
{
	for(int i=0;i<4;i++)while(!p[i].empty())p[i].pop();
	for(int i=1;i<=n;i++)
	{
		int op=trs(s[i]),tx,ty;
		if(op==op1||op==op2)tx=x+dx[op],ty=y+dy[op];else tx=x,ty=y;
		if((tx<=0||tx>h)||(ty<=0||ty>w))
		{
			if(!p[op^2].empty())p[op^2].pop();
			else return 0;
		}else x=tx,y=ty;
		p[trs(t[i])].push(i);
		for(int j=0;j<4;j++)
		{
			int tx=x+dx[j],ty=y+dy[j];
			if((tx<=0||tx>h)||(ty<=0||ty>w))
				while(!p[j].empty())p[j].pop();
		}
	}
	return 1;
}
int main()
{
	scanf("%d%d%d%d%d%s%s",&h,&w,&n,&x,&y,s+1,t+1);
	for(int i=0;i<4;i++)
		for(int j=i+1;j<4;j++)
			if(!check(i,j))return puts("NO"),0;
	puts("YES");
}

