    cin >> H >> W >> N;

    int r, c;
    cin >> r >> c;

    string S, T;
    cin >> S >> T;

    bool good = false;
    //leftを目指す
    {
        int y = r;
        int x = c;
        for (int i = 0; i < N; i++) {
            if (S[i] == 'L') {
                x--;
            }
            if (x <= 0) {
                good = true;
            }
            if (T[i] == 'R') {
                if (x < W) x++;
            }
        }
    }

    //rightを目指す
    {
        int y = r;
        int x = c;
        for (int i = 0; i < N; i++) {
            if (S[i] == 'R') {
                x++;
            }
            if (x > W) {
                good = true;
            }
            if (T[i] == 'L') {
                if (x > 1) x--;
            }

        }
    }

    //upを目指す
    {
        int y = r;
        int x = c;
        for (int i = 0; i < N; i++) {
            if (S[i] == 'U') {
                y--;
            }
            if (y <= 0) {
                good = true;
            }
            if (T[i] == 'D') {
                if (y < H) {
                    y++;
                }
            }

        }
    }

    //downを目指す
    {
        int y = r;
        int x = c;
        for (int i = 0; i < N; i++) {
            if (S[i] == 'D') {
                y++;
            }
            if (y > H) {
                good = true;
            }
            if (T[i] == 'U') {
                if (y > 1) {
                    y--;
                }
            }

        }
    }

    if (good) NO();
    else
        YES();


    return 0;
}

