int min(int a,int b){return a>b?b:a;}
int max(int a,int b){return a>b?a:b;}
bool judge(int pos,int lim,int s,int a[],int b[]){
  reverse(a,a+s);
  reverse(b,b+s);
  int ml=1,mr=lim;
  if(a[0]==1)mr=lim-1;
  else if(a[0]==-1)ml=1;
  if(ml>mr)return true;
  for(int i=1;i<s;i++){
  	if(b[i]==1)ml--;
    else if(b[i]==-1)mr++;
    mr=min(mr,lim);
    ml=max(ml,0);
    if(a[i]==1)mr--;
    else if(a[i]==-1)ml++;
    mr=min(mr,lim);
    ml=max(ml,0);
    if(ml>mr)return true;
  }
  return false;
}
