    cin >> T;

    vector<int> h(H, 0);
    vector<int> w(W, 0);

    int up = 1, down = H;
    int left = 1, right = W;
    int updown = 0;
    int leftright = 0;

    for(int i=N-1;i>-1;i--){

        if(T[i] == 'D' && up > 1 && h.at(up-2) == 1){
            up--;
            h.at(up-1) = 0;
            updown--;
        }
        else if(T[i] == 'U' && down < H && h.at(down) == 1){
            down++;
            h.at(down-1) = 0;
            updown--;
        }
        if(updown == H){
            break;
        }        
        if(S[i] == 'U' && up <= down && h.at(up-1) == 0){
            h.at(up-1) = 1;
            up++;
            updown++;
        }
        else if(S[i] == 'D' && down >= up && h.at(down-1)==0){
            h.at(down-1) = 1;
            down--;
            updown++;
        }
    }


    for(int i=N;i>0;i--){

        if(T[i] == 'R' && left > 1 && w.at(left-2) == 1){
            left--;
            w.at(left-1) = 0;
            leftright--;
        }
        else if(T[i] == 'L' && right < W && w.at(right) == 1){
            right++;
            w.at(right-1) = 0;
            leftright--;
        }
        if(leftright == W){
