bool solve(ll h, ll w, ll n, ll start_h, ll start_w,
           const string &s, const string &t, char direction)
{
    char rev_direction;
    ll unit = 0;

    if (direction == 'D') {
        rev_direction = 'U';
        unit = 1;
    }
    if (direction == 'U') {
        rev_direction = 'D';
        unit = -1;
    }
    if (direction == 'L') {
        rev_direction = 'R';
        unit = -1;
    }
    if (direction == 'R') {
        rev_direction = 'L';
        unit = 1;
    }

    ll now;
    if (direction == 'D' || direction == 'U') now = start_h;
    else now = start_w;

    ll border;
    if (direction == 'D' || direction == 'U') border = h;
    else border = w;

    rep (i, n) {
        if (s[i] == direction) now += unit;
        debug_printf("  direction=%c now=%lld\n", direction, now);
        if (now < 0 || border <= now) return true;
        if (t[i] == rev_direction) {
            ll tmp = now - unit;
            if (0 <= tmp && tmp < border) now = tmp;
        }
    }

    return false;
}

