{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll h; llin(h);
    ll w; llin(w);
    ll n; llin(n);
    ll start_h; llin(start_h); start_h--;
    ll start_w; llin(start_w); start_w--;
    string s; CIN(s);
    string t; CIN(t);

    if (solve(h, w, n, start_h, start_w, s, t, 'L')) {
        debug_printf("xx1 \n");
        cout << "NO" << endl;
        return;
    }
    if (solve(h, w, n, start_h, start_w, s, t, 'R')) {
        debug_printf("xx2 \n");
        cout << "NO" << endl;
        return;
    }
    if (solve(h, w, n, start_h, start_w, s, t, 'U')) {
        debug_printf("xx3 \n");
        cout << "NO" << endl;
        return;
    }
    if (solve(h, w, n, start_h, start_w, s, t, 'D')) {
        debug_printf("xx4 \n");
        cout << "NO" << endl;
        return;
    }

    cout << "YES" << endl;
}

