bool f(vpll &z, ll n, ll s){
  ll l=1,r=n;
  reverse(all(z));

  for(pll p:z){
   ll w=p.first;
    if(p.second){
      if(w==-1) r=min(r+1ll,n);
      else l=max(1ll,l-1ll);
    }else{
      if(w==-1) l++;
      else r--;
    }
    if(l>r) return false;
  }
  return (l<=s&&s<=r);
}
