bool  solve(vector<int> &A, vector<int> &B, int W, int X) {
	vector<int> dpR(2 * N + 1);
	vector<int> dpL(2 * N + 1);
	dpR[2 * N] = W + 1;
	dpL[2 * N] = 0;
	for (int i = N - 1; i >= 0; i--) {
		int t;
		t = 2 * i + 1;
		dpR[t] = dpR[t + 1];
		dpL[t] = dpL[t + 1];
		if (B[i] == -1) {
			if (dpR[t + 1] < W + 1) {
				dpR[t] = dpR[t + 1] + 1;
			}
		}

		if (B[i] == 1) {
			if (dpL[t + 1] > 0) {
				dpL[t] = dpL[t + 1] - 1;
			}
		}


		t = 2 * i;
		dpR[t] = dpR[t + 1];
		dpL[t] = dpL[t + 1];

		if (A[i] == 1) {
			dpR[t] = dpR[t + 1] - 1;
		}

		if (A[i] == -1) {
			dpL[t] = dpL[t + 1] + 1;
		}
	}

	if (dpR[0] <= X || dpL[0] >= X)return false;

	for (int i = 0; i < 2 * N; i++) {
		//cerr << i <<" " << dpL[i] << " " << dpR[i] << endl;
		if (dpL[i] + 1 >= dpR[i])return false;
	}
	return true;

}


