  cin>>h>>w>>n>>y>>x>>s>>t;

  vector<vector<int>> c(2,vector<int>(4,0)),pc;
  bool isin=true;
  for(int i=0;i<n;++i){
    pc=c;
    switch(s[i]){
      case 'L':
        c[0][0]++;
        break;
      case 'R':
        c[0][1]++;
        break;
      case 'U':
        c[0][2]++;
        break;
      case 'D':
        c[0][3]++;
        break;
    }
    switch(t[i]){
      case 'L':
        if(x-pc[1][0]>1)c[1][0]++;
        break;
      case 'R':
        if(x+pc[1][1]<w)c[1][1]++;
        break;
      case 'U':
        if(y-pc[1][2]>1)c[1][2]++;
        break;
      case 'D':
        if(y+pc[1][3]<h)c[1][3]++;
        break;
    }
    //left against right
    if(x-c[0][0]<1){
      int crd=x-c[0][0]+pc[1][1];
      if(0<crd)continue;
      else{
        isin=false;
        break;
      }
    }
    //right against left
    if(x+c[0][1]>w){
      int crd=x+c[0][1]-pc[1][0];
      if(crd<=w)continue;
      else{
        isin=false;
        break;
      }
    }
    //up against down
    if(y-c[0][2]<1){
      int crd=y-c[0][2]+pc[1][3];
      if(0<crd)continue;
      else{
        isin=false;
        break;
      }
    }
    //down against up
    if(y+c[0][3]>h){
      int crd=y+c[0][3]-pc[1][2];
      if(crd<=h)continue;
      else{
        isin=false;
        break;
      }
    }
  }
  cout<<(isin?"YES":"NO");
  return 0;
}

