bool solve(ll W, ll N, ll C, vector<ll> S, vector<ll> T) {
  ll l = 0, r = W;

  for (int i = N - 1; i >= 0; i--) {
    if (S[i] == +1) r--;
    if (S[i] == -1) l++;
    r = min(r, W);
    l = max(l, 0LL);

    if (l == r) return false;

    if (i - 1 >= 0) {
      if (T[i - 1] == +1) l--;
      if (T[i - 1] == -1) r++;
      r = min(r, W);
      l = max(l, 0LL);
    }
  }

  return l <= C && C < r;
}

vector<ll> row(string &S, ll N) {
  vector<ll> r(N);
  REP(i, 0, N) {
    if (S[i] == 'L') r[i] = -1;
    if (S[i] == 'R') r[i] = +1;
  }
  return r;
}

vector<ll> col(string &S, ll N) {
  vector<ll> c(N);
  REP(i, 0, N) {
    if (S[i] == 'U') c[i] = -1;
    if (S[i] == 'D') c[i] = +1;
  }
  return c;
}

int main(void) {
  ll H, W, N;
  cin >> H >> W >> N;
  ll R, C;
  cin >> R >> C, R--, C--;
  string S, T;
  cin >> S >> T;

  bool ans = true;
  ans = ans && solve(W, N, C, row(S, N), row(T, N));
  ans = ans && solve(H, N, R, col(S, N), col(T, N));
  cout << (ans ? "YES" : "NO") << endl;
}

