bool judge(const string &s, const string &t, ll n, ll len, ll start,
           char ac, char bc)
{
    ll safe_min = 0LL;
    ll safe_max = len - 1LL;

    rrep (i, n) {
        if (t[i] == ac) safe_min = max(safe_min - 1LL, 0LL);
        if (t[i] == bc) safe_max = min(safe_max + 1LL, len - 1LL);
        if (s[i] == ac) safe_max--;
        if (s[i] == bc) safe_min++;
        if (safe_max < safe_min) return true;
    }

    return !(safe_min <= start && start <= safe_max);
}

