void proc(char s[max_n], int x[max_n], int y[max_n]) {
    for (int i = 0; i < n; ++i) {
        if (s[i] == 'L') {
            y[i] = -1;
        } else if (s[i] == 'R') {
            y[i] = 1;
        } else if (s[i] == 'U') {
            x[i] = -1;
        } else {
            x[i] = 1;
        }
    }
}

bool solve(int mx, int st, int a[], int b[]) {
    int l = 0, r = mx - 1;
    for (int i = n - 1; i >= 0; --i) {
        if (b[i] == 1) {
            --l;
        } else if (b[i] == -1) {
            ++r;
        }
        l = max(l, 0);
        r = min(r, mx - 1);
        if (a[i] == 1) {
            --r;
        } else if (a[i] == -1) {
            ++l;
        }
        //cout << l << " " << r << endl;
        if (l > r) {
            return true;
        }
    }
    //cout << l << " " << r << ", " << st << endl;
    if (l <= st && st <= r) {
        return false;
    }
    return true;
}

