bool solve() {
  VI res;
  res.push_back(f(S,T,sj));
  swap(S,T,'L','R');
  res.push_back(f(S,T,W-sj+1));
  swap(S,T,'L','R');
  swap(S,T,'L','U');
  swap(S,T,'R','D');
  swap(H,W);
  res.push_back(f(S,T,si));
  swap(S,T,'L','R');
  res.push_back(f(S,T,W-si+1));
  dumpc(res);
  bool fall=count(ALL(res),0);
  return !fall;
}

