		chmax(L[i + 1], L_min[i + 1] + 1);
		chmin(R[i + 1], R_max[i + 1] - 1);
	}

	DMP(L_min, R_max, L, R);

	for (int i = 1; i <= N; i++) {
		if (L[i] > R[i]) {
