			return 0;
		}
	}

	vector<int> U_min(N + 1, 0), D_max(N + 1, W + 1);
	for (int i = (int)S.size() - 1; i >= 0; i--) {
		if (S[i] == 'U') U_min[i] = U_min[i + 1] + 1;
		if (S[i] == 'D') D_max[i] = D_max[i + 1] - 1;
	}

	vector<int> U(N + 1, sr), D(N + 1, sr);
	for (int i = 0; i < N; i++) {
		if (T[i] == 'U') U[i + 1] = U[i] - 1;
		if (T[i] == 'D') D[i + 1] = D[i] + 1;
		chmax(U[i + 1], U_min[i + 1] + 1);
		chmin(D[i + 1], D_max[i + 1] - 1);
	}

	for (int i = 0; i <= N; i++) {
		if (U[i] > D[i]) {
			cout << "NO" << "\n";
			return 0;
		}
	}

	cout << "YES" << "\n";

	return 0;
}

