bool check(ll h, ll r, const vector<ll> & a) {
  ll lft = -1;
  ll rgt = h;
  REP_REV(i, sz(a)) {
    if(i % 2 == 0) {
      if(a[i] == 1) {
        rgt--;
      }
      else if(a[i] == - 1) {
        lft++;
      }
    }
    else {
      if(a[i] == 1) {
        lft--;
      }
      else if(a[i] == - 1) {
        rgt++;
      }
    }
    if(rgt - lft) return true;
    if(lft < 0) lft = -1;
    if(rgt > h) rgt = h;
  }
  return r <= lft || rgt <= r;
}


