void inv(string& s) {
    for (int i = 0; i < s.size(); ++i) {
        if (s[i] == 'D') {
            s[i] = 'R';
        }
        if (s[i] == 'U') {
            s[i] = 'L';
        }
    }
}

bool solve(string s, string t, int pos, int mx) {
    int l = -1, r = mx;
    for (int i = s.size() - 1; i >= 0; --i) {
        if (s[i] == 'L') {
            ++l;
        }
        if (s[i] == 'R') {
            --r;
        }
        if (t[i] == 'L') {
            ++r;
        }
        if (t[i] == 'R') {
            --l;
        }
        l = max(-1, l);
        r = min(mx, r);
        if (s[i] == 'R') {
            r = min(mx - 1, r);
        }
        if (s[i] == 'L') {
            l = max(0, l);
        }
        if (r - l <= 1) return true;
    }
    if (pos <= l || pos >= r) return true;
    return false;
}

