string S, T;

int Get(int pos, char ch, char lef, char rig)
{
    if (ch == lef) return pos - 1;
    if (ch == rig) return pos + 1;
    return pos;
}

bool Solve(char lef, char rig, int lim, int cur)
{
    int L = 1, R = lim;
    for (int i = N - 1; i >= 0; i--) {
        int L2 = L, R2 = R;
        int nL = Get(L, S[i], lef, rig);
        if (nL < 1 || nL > lim) L2 = L + 1;
        else if (nL < L || nL > R) {
            int fix = Get(nL, T[i], lef, rig);
            if (fix < L || fix > R) L2 = L + 1;
        }
        int nR = Get(R, S[i], lef, rig);
        if (nR < 1 || nR > lim) R2 = R - 1;
        else if (nR < L || nR > R) {
            int fix = Get(nR, T[i], lef, rig);
            if (fix < L || fix > R) R2 = R - 1;
        }
        L = L2, R = R2;
    }
    return L <= cur && cur <= R;
}

