bool calc(vector<P> &vec, int s, int n)
{
	int l = 0, r = n+1;
	for(int i = (int)vec.size()-1; i >= 0; i--){

		if(vec[i].first == 1){
			if(vec[i].second == 1) r--;
			if(vec[i].second == -1) l++;
		}
		else{
			if(vec[i].second == 1) l--;
			if(vec[i].second == -1) r++;
		}
		if(l+1 >= r) return false;
		l = max(0, l), r = min(n+1, r);
		//cout << l << "  " << r << endl;
	}
	return l < s && s < r;
}

