string chars = "LRUD";

//高橋君が勝つかどうかを返す
bool solve() {
    for(int i = 0; i < N; ++i) {
        bool to_left, to_up;
        //高橋君
        to_left = x + cnt_S[1][i] - cnt_T[0][i] - W < 
                         - (x - cnt_S[0][i] + cnt_T[1][i]);

        to_up = y + cnt_S[3][i] - cnt_T[2][i] - H < 
                         - (y - cnt_S[2][i] + cnt_T[3][i]);

        if(S[i] == 'L' && to_left) x--;
        if(S[i] == 'R' && !to_left) x++;
        if(S[i] == 'U' && to_up) y--;
        if(S[i] == 'D' && !to_up) y++;

        if(x < 0 || x >= W || y < 0 || y >= H) return false;

        //青木君
        to_left = x + cnt_S[1][i + 1] - cnt_T[0][i] - W < 
                         - (x - cnt_S[0][i + 1] + cnt_T[1][i]);

        to_up = y + cnt_S[3][i + 1] - cnt_T[2][i] - H < 
                         - (y - cnt_S[2][i + 1] + cnt_T[3][i]);

        if(T[i] == 'L' && !to_left) x--;
        if(T[i] == 'R' && to_left) x++;
        if(T[i] == 'U' && !to_up) y--;
        if(T[i] == 'D' && to_up) y++;

        if(x < 0 || x >= W || y < 0 || y >= H) return false;
    }

    return true;
}

int main(int argc, char **argv) {
