    cin >> S >> T;
    y--, x--;

    cnt_S[0][N] = cnt_S[1][N] = cnt_S[2][N] = cnt_S[3][N] = 0;
    cnt_T[0][N] = cnt_T[1][N] = cnt_T[2][N] = cnt_T[3][N] = 0;

    for(int i = N - 1; i >= 0; --i)
        for(int j = 0; j < 4; ++j) {
            cnt_S[j][i] = cnt_S[j][i + 1] + (S[i] == chars[j]);
            cnt_T[j][i] = cnt_T[j][i + 1] + (T[i] == chars[j]);;
        }


    cout << (solve() ? "YES" : "NO") << endl;
}

