bool ok(int siz, int pos, vector<pair<int, int>> v) {
  int l = 1, r = siz;
  reverse(v.begin(), v.end());
  for (int i = 0; i < (int) v.size(); i++) {
    int dir = v[i].first;
    int who = v[i].second;
    if (who == 0) {
      if (dir) {
        r--;
      } else {
        l++;
      }
    } else {
      if (dir) {
        l = max(l - 1, 1);
      } else {
        r = min(r + 1, siz);
      }
    }
    if (l > r) return false;
  }
  return (l <= pos && pos <= r);
}
