bool ochiru(int y0, int H, int N, string S, string T, char c0, char c1){
    int l = 0;
    int r = H+1;
    for(int i=N-1; i>=0; i--){
        if(T[i] == c0) r = min(H+1, r+1);
        if(T[i] == c1) l = max(0, l-1);
        if(r <= l || l == H || r == 1) return true;
        if(S[i] == c1) r--;
        if(S[i] == c0) l++;
        if(r <= l || l == H || r == 1) return true;
    }
    if(y0 <= l || r <= y0) return true;
    else return false;
}

