bool solve_game(vector<pii> v,int size,int start){
  int lo,hi;
  lo=0;
  hi=size+1;
  //r(int i=0;i<v.size();i++)cout<<v[i].first<<" "<<v[i].second<<endl;
  for(int i=v.size()-1;i>-1;i--){
    if(v[i].first== 1){
      if(v[i].second==-1){
	lo++;
      }else hi--;
    }else{
      if(v[i].second==+1){
	lo=max(lo-1,0);
      }else hi=min(hi+1,size+1);
    }
    //ut<<lo<<" "<<hi<<endl;
    if(hi-lo<=1)return false;
  }
  if(lo<start && start<hi)return true;
  return false;
}
int main(){
