  for(int i=0;i<n;i++){
    char c=A[i];
    if(c=='R'){
      v2.push_back(pii(1,1));
    }
    if(c=='L'){
      v2.push_back(pii(1,-1));
    }
    if(c=='U'){
      v1.push_back(pii(1,-1));
    }
    if(c=='D'){
      v1.push_back(pii(1,1));
