		if (t[i] == add) l = max(l - 1, 1);
		else if (t[i] == sub) r = min(r + 1, len);
		if (s[i] == add) r--;
		else if (s[i] == sub) l++;
		if (l > r) return false;
	}
	return p >= l && p <= r;
}

