// 0:判断横坐标 1:判断纵坐标. 当前Aoki 是不是能阻止Takahashi
bool ok(int flag){
    int l = 0, r = 0;
    int L = 1, R = 0;
    int ansl = 0, ansr = 0;
    if(flag == 0) {
        R = H;
        l = sr - cnt1[1];
        r = sr + cnt1[2];
        ansl = -cnt2[1];
        ansr = cnt2[2];
    } else {
        R = W;
        l = sc - cnt1[3];
        r = sc + cnt1[4];
        ansl = -cnt2[3];
        ansr = cnt2[4];
    }
    while(ansl <= ansr){
        int mid = (ansl + ansr) >> 1;
        if(l + mid >= L){   // 下界ok
            if(r+mid <= R){ // 上界也ok
                return true; // 可以抵挡住
            } else { // r+mid > R // mid太大.需要小一点
                ansr = mid-1;
            }
        } else { // l+mid < L. 下界太小
            ansl = mid+1;
        }
    }
    return false;
}

