    bool concheck(int h, int w) {
        return h >= 0 && h < H && w >= 0 && w < W;
    }

    bool up() {
        int h = sr;
        int w = sc;

        for (int i = 0; i < N; ++i) {
            if (S[i] == 'U') h--;

            if (!concheck(h, w)) return true;
            if (T[i] == 'D') h++;
            if (!concheck(h, w)) h--;
        }
        return false;
    }

    bool down() {
        int h = sr;
        int w = sc;

        for (int i = 0; i < N; ++i) {
            if (S[i] == 'D')h++;
            if (!concheck(h, w)) return true;
            if (T[i] == 'U') h--;
            if (!concheck(h, w)) h++;
        }
        return false;
    }

    bool right() {
        int h = sr;
        int w = sc;

        for (int i = 0; i < N; ++i) {
            if (S[i] == 'R') w++;
            if (!concheck(h, w)) return true;
            if (T[i] == 'L') w--;
            if (!concheck(h, w)) w++;
        }
        return false;
    }

    bool left() {
        int h = sr;
        int w = sc;

        for (int i = 0; i < N; ++i) {
            if (S[i] == 'L') w--;
            if (!concheck(h, w)) return true;
            if (T[i] == 'R') w++;
            if (!concheck(h, w)) w--;
        }
        return false;
    }

    void solve() {
        input();
        if (up()) {
            cout << "NO" << endl;
            return;
        }

        if (down()) {
            cout << "NO" << endl;
            return;
        }
        if (left()) {
            cout << "NO" << endl;
            return;
        }
        if (right()) {
            cout << "NO" << endl;
            return;
        }
        cout << "YES" << endl;
    }
};


