int dealT(int i, int x, int y) {
	if (i == N) return INT_MAX/2;
	if (x < 1 || x > W) return 0;
	if (y < 1 || y > H) return 0;
	//takashi takes min
	int nx = x;
	int ny = y;
	switch (S[i]) {
		case 'L':
			nx--;
			break;
		case 'R':
			nx++;
			break;
		case 'U':
			ny++;
			break;
		case 'D':
			ny--;
			break;
	}
	return min(dealA(i, x, y), dealA(i, nx, ny));
}

int dealA(int i, int x, int y) {
	if (i == N) return INT_MAX/2;
	if (x < 1 || x > W) return 0;
	if (y < 1 || y > H) return 0;
	//aoki takes max
	int nx = x;
