using namespace std;

int H, W, N;
int px, py;
string S, T;
vector<int> dists(4); // distance from the piece to bounds: L, R, U, D

void UpdateDists() {
    dists[0] = px;
    dists[1] = W - px - 1;
    dists[2] = py;
    dists[3] = H - py - 1;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> H >> W >> N >> py >> px >> S >> T;
    --py; --px; // 0-indexed

    // rest commands: L, R, U, D
    vector<int> cTaka, cAoki;
    cTaka = vector<int>(4, 0);
    cAoki = vector<int>(4, 0);

    rep(i, 0, N) {
        switch(S[i]) {
            case 'L': ++cTaka[0]; break;
            case 'R': ++cTaka[1]; break;
            case 'U': ++cTaka[2]; break;
            case 'D': ++cTaka[3]; break;
        }
        switch(T[i]) {
            case 'L': ++cAoki[0]; break;
            case 'R': ++cAoki[1]; break;
            case 'U': ++cAoki[2]; break;
            case 'D': ++cAoki[3]; break;
        }
    }

    vector<int> cScores(4);

    rep(i, 0, N) {
        UpdateDists();

        // Takahashi's turn
        rep(i, 0, 4) {
            cScores[i] = cTaka[i] - dists[i];
        }
        bool wantsToUseL = (cScores[0] >= cScores[1]) ? true : false;
        bool wantsToUseU = (cScores[2] >= cScores[3]) ? true : false;

        switch(S[i]) {
            case 'L':
                if (wantsToUseL) px--;
                break;
            case 'R':
                if (!wantsToUseL) px++;
                break;
            case 'U':
                if (wantsToUseU) py--;
                break;
            case 'D':
                if (!wantsToUseU) py++;
                break;
        }

        if (py < 0 or px < 0 or py >= H or px >= W) {
            cout << "NO\n";
            return 0;
        }

        UpdateDists();

        // Aoki's turn
        rep(i, 0, 4) {
            cScores[i] = cAoki[i] + dists[i];
        }
        wantsToUseL = (cScores[0] >= cScores[1]) ? true : false;
        wantsToUseU = (cScores[2] >= cScores[3]) ? true : false;

        switch(T[i]) {
            case 'L':
                if (wantsToUseL) px--;
                break;
            case 'R':
                if (!wantsToUseL) px++;
                break;
            case 'U':
                if (wantsToUseU) py--;
                break;
            case 'D':
                if (!wantsToUseU) py++;
                break;
        }
    }

    cout << "YES\n";
}

