  for (int i = 0; i < n; i++) {
    if (a[i] == 'L') ty--;
    if (ty <= 0 || ty > w) {
      cout << "NO" << endl;
      return 0;
    }
    if (b[i] == 'R' && ty < w) {
      ty++;
    }
  }
  // rig
  ty = sy;
  for (int i = 0; i < n; i++) {
    if (a[i] == 'R') {
      ty++;
    }
    if (ty <= 0 || ty > w) {
      cout << "NO" << endl;
      return 0;
    }
    if (b[i] == 'L' && ty > 1) {
      ty--;
    }
  }
  // up
  int tx = sx;
  for (int i = 0; i < n; i++) {
    if (a[i] == 'U') {
      tx--;
    }
    if (tx <= 0 || tx > h) {
      cout << "NO" << endl;
      return 0;
