    if (b[i] == 'D' && tx < h) {
      tx++;
    }
  }
  // down
  for (int i = 0; i < n; i++) {
    if (a[i] == 'D') {
      tx++;
    }
    if (tx <= 0 || tx > h) {
      cout << "NO" << endl;
      return 0;
    }
    if (b[i] == 'U' && tx > 1) {
      tx--;
    }
  }
  cout << "YES" << endl;
  return 0;
}

