bool solve() {
  int minx=1,maxx=W,miny=1,maxy=H;
  for(int i=N-1; i>=0; --i) {
    if(T[i]=='R') --minx;
    if(T[i]=='L') ++maxx;
    if(T[i]=='U') --miny;
    if(T[i]=='D') ++maxy;

    minx=max(1,minx);
    miny=max(1,miny);
    maxx=min(W,maxx);
    maxy=min(H,maxy);

    if(S[i]=='R') --maxx;
    if(S[i]=='L') ++minx;
    if(S[i]=='U') --maxy;
    if(S[i]=='D') ++miny;

    if(minx>maxx) return false;
    if(miny>maxy) return false;
  }
