using namespace std;
#define REP(i,n) for (int i=0;i<(n);i++)
#define REP2(i,m,n) for (int i=m;i<(n);i++)
typedef long long ll;

int H, W, N;
int Sr, Sc;
string S[2];

/*
int L[3][202020];
int R[3][202020];
int D[3][202020];
int U[3][202020];
*/

int L[202020];
int R[202020];
int D[202020];
int U[202020];

bool hoge() {    
    int x = Sc;
    REP(i, N) {
        if (S[0][i] == 'L') x -= 1;
        if (x <= 0) return false;
        if (S[1][i] == 'R' && x + R[i+1] + 1 <= W) x += 1;
    }
    x = Sc;
    REP(i, N) {
        if (S[0][i] == 'R') x += 1;
        if (x > W) return false;
        if (S[1][i] == 'L' && x - L[i+1] - 1 >= 1) x -= 1;
    }
    x = Sr;
    REP(i, N) {
        if (S[0][i] == 'D') x -= 1;
        if (x <= 0) return false;
        if (S[1][i] == 'U' && x + U[i+1] + 1 <= H) x += 1;
    }
    x = Sr;
    REP(i, N) {
        if (S[0][i] == 'U') x += 1;
        if (x > H) return false;
        if (S[1][i] == 'D' && x - D[i+1] - 1 >= 1) x -= 1;
    }
    return true;
}

void solve() {
    cin >> H >> W >> N;
    cin >> Sr >> Sc;
    cin >> S[0] >> S[1];

/*
    REP(x, 2) REP(i, N) L[x][i+1] += S[x][i] == 'L';
    REP(x, 2) REP(i, N) R[x][i+1] += S[x][i] == 'R';
    REP(x, 2) REP(i, N) U[x][i+1] += S[x][i] == 'U';
    REP(x, 2) REP(i, N) D[x][i+1] += S[x][i] == 'D';
    */

    for (int i = N - 1, x = 0; i >= 0; --i) {
        if (i < N - 1 && S[1][i] == 'R')  x -= 1;
        if (S[0][i] == 'L') x += 1;
        L[i] = x;
    }  
    for (int i = N - 1, x = 0; i >= 0; --i) {
        if (i < N - 1 && S[1][i] == 'L')  x -= 1;
        if (S[0][i] == 'R') x += 1;
        R[i] = x;
    }    
    for (int i = N - 1, x = 0; i >= 0; --i) {
        if (i < N - 1 && S[1][i] == 'D')  x -= 1;
        if (S[0][i] == 'U') x += 1;
        U[i] = x;
    }  
    for (int i = N - 1, x = 0; i >= 0; --i) {
        if (i < N - 1 && S[1][i] == 'U')  x -= 1;
        if (S[0][i] == 'D') x += 1;
        D[i] = x;
    }

    cout << (hoge() ? "YES" : "NO") << endl;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

