char s[200005],t[200005];
int h,w,n,sr,sc;
int walk1(){
	int l=1,r=h;
	for(int i=n;i>=1;i--){
		if(t[i]=='U')
			r=min(h,r+1);
		else if(t[i]=='D')
			l=max(l-1,1);
		if(s[i]=='U')
			l++;
		else if(s[i]=='D')
			r--;
		if(l>r)
			return 1;
	}
	return (sr<l||sr>r); 
}
int walk2(){
	int l=1,r=w;
	for(int i=n;i>=1;i--){
		if(t[i]=='L')
			r=min(w,r+1);
		else if(t[i]=='R')
			l=max(l-1,1);
		if(s[i]=='R')
			r--;
		else if(s[i]=='L')
			l++;
		if(l>r)
			return 1;
	}
	return (sc<l||sc>r); 
}
int main(){
	scanf("%d%d%d",&h,&w,&n);
	scanf("%d%d",&sr,&sc);
	scanf("%s",s+1);
	scanf("%s",t+1);
	if(walk1()||walk2())
		puts("NO");
	else puts("YES");
}

#include <stdio.h>

#define rREP(i, n) for(int (i) = (n) - 1; (i) >= 0; --(i))

constexpr int N = 2e5;
char S[N+10], T[N+10];

int main(void){
    int H, W, n; scanf("%d%d%d", &H, &W, &n);
    int sx, sy; scanf("%d%d", &sx, &sy);
    scanf("%s%s", S, T);

    // (l, r) は ok
    int l = -1, r = W, u = -1, d = H;
    rREP(i, n){
        // 落とされないようにする
        switch(T[i]){
            case 'L':
                if(r != W) r++;
                break;
            case 'R':
                if(l != -1) l--;
                break;
            case 'U':
                if(d != H) d++;
                break;
            case 'D':
                if(u != -1) u--;
                break;
        }

        // 落とすようにする
        switch(S[i]){
            case 'L':
                l++;
                break;
            case 'R':
                r--;
                break;
            case 'U':
                u++;
                break;
            case 'D':
                d--;
                break;
        }
        // 空となるなる場合があるときはダメ
        if(r - l - 1 <= 0 or d - u - 1 <= 0) break;
    }
    puts((l <= sy and sy <= r and u <= sx and sx <= d) ? "YES" : "NO");
    return 0;
}

