namespace c{
	//	Union Find
	class UnionFind{
	public:
		//	x, y は同じ
		void uniom(int x, int y){ mP[ find(x) ]= find(y); }
		//	x の親を取得
		int find(int x){ return mP[x]== x ? x : mP[x]= find( mP[x] ); }
		//	x が属する集合の親を x にする
		void toBeParent(int x){ mP[ find( x ) ]= x; mP[x]= x; }

		//	要素数 N, [ 0, N )
		UnionFind(int N) : mP(N){ For( i, N ) mP[i]= i; }
	private:
		std::vector<int> mP;
	};
	//	SegmentTree
	template <typename T, T Calc(T,T)> class SegTree{
		//	使い方
		//	SegTree<int, Gcd> tr( N );
		//	For( i, N ) tr.add( x );
		//	tr.setup();
		//	tr.get( i, k );

		//	root の idx を 1 からにするといろいろ楽
		//	- 配列のサイズは N*2
		//	- 生データが始まるのは idx= N から
		//	- 親子のノードが辿りやすい. 親(i) -> 子( 2i, 2i+1 ), 子(i) -> 親(i/2)
	public:
		//	要素を加える O(1). idx ∈ [ 0, N )
		inline void add(int idx, T x){
			mAr[idx +mStt]= x;
		}
		//	準備 O(N)
		void setup(){
			std::vector<bool> has( mStt *2, false );
			ForA( i, mStt, mStt +mN ) has[i]= true;

			for(int st= mStt /2, gl= mStt; st>= 1; st/= 2, gl/= 2){
				for(int idx= st; idx < gl; idx++){
					const int lft= idx *2;
					const int rgt= lft +1;

					if( has[lft] ){
						mAr[idx]= has[rgt] ? Calc( mAr[lft], mAr[rgt] ) : mAr[lft];
						has[idx]= true;
					}
				}
			}
		}
		//	[ lft, rgt ) の区間の結果を返す O(log N). lft, rgt ∈ [ 0, N )
		inline T get(int lft, int rgt) const{
			mLft= lft; mRgt= rgt;
			return getImpl( 0, mStt, 1 );
		}
		//	要素数 N
		SegTree(int N, T initVal= T()) : mN(N), mStt(N){
			if( ( mStt & ( mStt -1 ) ) != 0 ){
				mStt|= mStt >> 1;
				mStt|= mStt >> 2;
				mStt|= mStt >> 4;
				mStt|= mStt >> 8;
				mStt|= mStt >> 16;
				mStt++;
			}
			mAr.resize( mStt *2, initVal );
		}
		T operator [](int idx) const{ return mAr[idx+mStt]; }

	private:
		T getImpl(int bot, int top, int idx) const{
			if( mLft <= bot && top <= mRgt ) return mAr[idx];

			const int mid= ( bot +top ) /2;
			const int lft= idx *2;
			const int rgt= idx *2 +1;

			if( mid <= mLft ){
				return getImpl( mid, top, rgt );
			}else if( mRgt <= mid ){
				return getImpl( bot, mid, lft );
			}else{
				return Calc( getImpl( bot, mid, lft ), getImpl( mid, top, rgt ) );
			}
		}

		std::vector<T> mAr;
		int mN, mStt;

		mutable int mLft, mRgt;
	};
	//	累積和の class はありゃせん
}
