bool check(int W, int H, int N, int X, int Y){
	int l= 0, r= W-1, t= 0, b= H -1;
	for(int i= N -1; i>= 0; i--){
		//	T
		if( i!= N -1 ){
			switch( T[i] ){
				CASE( 'U' ){
					b= std::min( b +1, H -1 );
				}
				CASE( 'D' ){
					t= std::max( t -1, 0 );
				}
				CASE( 'L' ){
					r= std::min( r +1, W -1 );
				}
				CASE( 'R' ){
					l= std::max( l -1, 0 );
				}
			}
		}

		//	S
		switch( S[i] ){
			CASE( 'U' ){
				t++;
				if( t < b ) return false;
			}
			CASE( 'D' ){
				b--;
				if( t < b ) return false;
			}
			CASE( 'L' ){
				l++;
				if( r < l ) return false;
			}
			CASE( 'R' ){
				r--;
				if( r < l ) return false;
			}
		}
	}

	return l <= X && X <= r && t <= Y && Y <= b;
}
