bool solve(string S,string T,int W,int sta){
	//LRときます
	sta--;
	//0未満かW以上になるならfalseを返します
	int hi=0,mg=W-1,n=S.size();
	for(int i=n-1;i>=0;i--){
		if(T[i]=='L'){mg++;}
		if(T[i]=='R'){hi--;}
		if(mg>=W){mg=W-1;}
		if(hi<0){hi=0;}
		if(S[i]=='L'){hi++;}
		if(S[i]=='R'){mg--;}
		if(hi>mg){return false;}
		//cerr<<hi<<" "<<mg<<endl;
	}
	if(sta<hi||mg<sta){return false;}
	return true;
}
