    std::cout << "NO" << std::endl;
    return 0;
  }

  // horizontal
  std::deque<int> h;
  for(int i=1; i<=W; i++) h.push_back(i);

  for(int i=N-1; i>=0; i--) {
    if ( T[i] == 'L' && h.back() != W ) {
      h.push_back(h.back()+1);
