using namespace std;

#define REP(i,n) for(int i = 0; i < (int)(n); i++)
typedef long long ll;
typedef pair<int, int> pint;

bool solve(const int N, const vector<int> &sdir, const vector<int> &tdir, 
	   const int cur, const int len) 
{
  int pmax = 0, nmax = 0, left = cur, right = cur;
  REP(i,N) {
    if(sdir[i] > 0) right++;
    else if(sdir[i] < 0) left--;

    if(right > len) { // 大きい方に抜ける
      int d = right - len;
      if(nmax >= d) {
	nmax -= d;
	right = len;
      } else {
	//	cout << "Out to RIGHT" << endl;
	return false;
      }

    }
    if(left <= 0) {
      int d = -left + 1;
      if(pmax >= d) {
	pmax -= d;
	left = 1;
      } else {
	//	cout << "Out to LEFT" << endl;
	return false;
      }
    }
    if(left - nmax <= 0) {
      nmax = left - 1;
    }
    if(right + pmax > len) {
      pmax = len - right;
    }
#ifdef DEBUG
    cout << i << " " << left << " " << right << ":" ;
    cout << nmax << " " << pmax << " " << len << endl;
#endif
    if(pmax < 0) {
      //cout << "Out to LEFT 2" << endl;
       return false;
    }
    if(nmax < 0) {
      //cout << "out to RIGHT 2" << endl;
       return false;
    }
#ifdef DEBUG
#endif
    if(tdir[i] > 0) {
      pmax++;
    }else if(tdir[i] < 0) {
      nmax++;
    }


  }
  return true;
}

int main() {
  int H, W, N; cin>>H>>W>>N;
  int sr, sc; cin>>sr>>sc;
  string S, T; cin>>S>>T;
  vector<int> sh(N,0), th(N,0), sw(N,0), tw(N,0) ;
  REP(i,N) {
    switch (S[i]) {
    case 'L': sw[i]=-1; break;
    case 'R': sw[i]=+1; break;
    case 'U': sh[i]=-1; break;
    case 'D': sh[i]=+1; break;
    }
    switch (T[i]) {
    case 'L': tw[i]=-1; break;
    case 'R': tw[i]=+1; break;
    case 'U': th[i]=-1; break;
    case 'D': th[i]=+1; break;
    }

  }
  bool ans1 = solve(N, sh, th, sr, H);
  bool ans2 = solve(N, sw, tw, sc, W);
  cout << ((ans1 && ans2)  ? "YES" : "NO") << endl;
  return 0;
}

