string s, t;

bool solve(char cRight, char cLeft, int Max, int start) {
  int left = 1, right = Max;
  // 一番最後の手
  if (s[N-1] == cRight) right--;
  if (s[N-1] == cLeft) left++;

  for (int i = N-2; i >= 0; i--) {
    // 青木
    if (t[i] == cRight) {
      left = max(1ll, left - 1);
    }
    if (t[i] == cLeft) {
      right = min(Max, right + 1);
    }

    // 高橋
    if (s[i] == cRight) {
      right--;
    }
    if (s[i] == cLeft) {
      left++;
    }

    // 青木が移動できる範囲がなくなったら終了
    if (left > right) return false;
  }

  return left <= start and start <= right;
}

