bool check(ll h, ll r, const vector<ll> & a) {
  ll lft = r;
  ll rgt = r;
  REP(i, sz(a)) {
    if(i % 2 == 0) {
      if(a[i] == 1) {
        rgt++;
      }
      else if(a[i] == - 1) {
        lft--;
      }
      if(lft < 0 || h <= rgt) return true;
    }
    else {
      if(a[i] == 1 && lft < h - 1) {
        lft++;
      }
      else if(a[i] == - 1 &&  0 < rgt) {
        rgt--;
      }
    }
  }
  return false;
}


