bool solve() {
  int minx=1,maxx=W,miny=1,maxy=H;
  for(int i=N-1; i>=0; --i) {
    if(T[i]=='R') --minx;
    if(T[i]=='L') ++maxx;
    if(T[i]=='U') --miny;
    if(T[i]=='D') ++maxy;

    if(minx>W) return false;
    if(maxx<=0) return false;
    if(miny>H) return false;
    if(maxy<=0) return false;

    if(S[i]=='R') --maxx;
    if(S[i]=='L') ++minx;
    if(S[i]=='U') --maxy;
    if(S[i]=='D') ++miny;

    if(minx>W) return false;
    if(maxx<=0) return false;
    if(miny>H) return false;
    if(maxy<=0) return false;
  }
//  dump(minx,sj,maxx);
//  dump(miny,si,maxy);
  if(sj<minx||sj>maxx) return false;
  if(si<miny||si>maxy) return false;
  return true;
}

