struct Edge {
	int from, to;
	ll w;
	bool operator<(const Edge& rhs) const {
		return MP(w, MP(from, to)) < MP(rhs.w, MP(rhs.from, rhs.to));
	}
};
ll mod_pow(ll x, ll n, ll mod) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = res * x %mod;
		x = x * x%mod;
		n >>= 1;
	}
	return res;
}
typedef vector<vector<Edge>> Graph;


bool solve(int r, int sp, vector<pii> c) {
	sp--;
	pii inter = { 0, r - 1 };

	REP(i, c.size()) {
		if (c[i].first == 0) {
			inter.first = max(inter.first, inter.first - c[i].second);
			inter.second = min(inter.second, inter.second - c[i].second);
		}
		else {
			inter = MP(min(inter.first, inter.first - c[i].second), max(inter.second, inter.second - c[i].second));
		}

		if (inter.second < inter.first) {
			return 1;
		}
		inter.first = max(0, inter.first);
		inter.second = min(r - 1, inter.second);
	}

	if (inter.first <= sp && inter.second >= sp) {
		return 0;
	}
	else
	{
		return 1;
	}
}

signed main(void) {
	int h, w, n;
	cin >> h >> w >> n;

	int sr, sc;
	cin >> sr >> sc;

	string s, t;
	cin >> s >> t;
	vector<pii> hc, wc;

	REP(i, n) {
		if (s[i] == 'U') {
			hc.push_back({ 0,-1 });
		}
		if (s[i] == 'D') {
			hc.push_back({ 0,1 });
		}
		if (s[i] == 'R') {
			wc.push_back({ 0,1 });
		}
		if (s[i] == 'L') {
			wc.push_back({ 0,-1 });
		}
		if (t[i] == 'U') {
			hc.push_back({ 1,-1 });
		}
		if (t[i] == 'D') {
			hc.push_back({ 1,1 });
		}
		if (t[i] == 'L') {
			wc.push_back({ 1,-1 });
		}
		if (t[i] == 'R') {
			wc.push_back({ 1,1 });
		}

	}

	reverse(ALL(hc));

	reverse(ALL(wc));

	int ans = 0;
	ans |= solve(h, sr, hc);
	ans |= solve(w, sc, wc);

	if (ans) {
		cout << "NO" << endl;
	}
	else
	{
		cout << "YES" << endl;
	}

	return 0;
}

