map<char,P> mv;
map<P,bool> memo;
int h, w, n;
string s, t;

bool dfs(int y, int x, int turn) {
    if (memo.count(P(y,x))) return memo[P(y,x)];
    if (y < 0 || y >= h || x < 0 || x >= w) return false;
    if (turn == 2*n) return true;
    bool res;
    if (turn&1) {
        //青木turn
        res = true;
        int n_y = y+mv[t[turn/2]].first, n_x = x+mv[t[turn/2]].second;
        if (!dfs(n_y,n_x,turn+1) && !dfs(y,x,turn+1)) res = false;
    } else {
        //高橋turn
        res = false;
        int n_y = y+mv[s[turn/2]].first, n_x = x+mv[s[turn/2]].second;
        if (dfs(n_y,n_x,turn+1) && dfs(y,x,turn+1)) res = true;
    }
    return memo[P(y,x)] = res;
}

