bool check(char l, char r, int X, int lim)
{
  int n = S.size();
  int lo = 1, hi = lim;
  for (int i = n - 1; i >= 0; i--)
  {
    if (T[i] == r)
      lo = max(lo - 1, 1);
    if (T[i] == l)
      hi = min(hi + 1, lim);
    if (S[i] == r)
      hi--;
    if (S[i] == l)
      lo++;
  }
  return lo <= X and X <= hi;
}

int main()
{
