bool solve(i64 X, i64 x, const vector<i64>& ss, const vector<i64>& tt, bool check) {
  i64 LL = 0;
  i64 RR = 0;
  i64 n = ss.size();
  i64 now = x;
  //cout << "solve" << endl;
  for(int i = 0;i < n;i++) {
    if(ss[i] == 1) RR++;
    else if(ss[i] == -1) LL++;
    if(tt[i] == -1) {
      //cout << now << " " << RR << " " << LL << endl;
      if(check && now - LL <= 0) return false;
      else {
        now += RR;
        if(now > X) return false;
        if(now >= 2) now--;
      }
      LL = 0;
      RR = 0;
    }
  }
  if(check && now - LL <= 0) return false;
  else {
    now += RR;
    if(now > X) return false;
  }
  return true;
}

