public:
	void solve(std::istream& in, std::ostream& out) {
        int h, w, sr, sc, n;
        string s, t;
        in >> h >> w >> n >> sr >> sc >> s >> t;
        --sr; --sc;

        map<char, int> mp;
        bool flg = true;
