            else mp[s[i]]--;

            if(mp['R'] >= w || mp['L'] < 0 || mp['U'] < 0 || mp['D'] >= h){
                flg = false;
                break;
            }

            if(t[i] == 'L') mp['R'] = max(mp['R']-1, 0);
