int check(string S, string T, int X, int W){
  int N = S.size();
  reverse(S.begin(), S.end());
  reverse(T.begin(), T.end());
  T[0] = '.';

  int res = 1;
  int l = 1, r = W;
  for(int i=0;i<N;i++){
    //落とされたくない
    if(T[i] == 'R') l--; 
    if(T[i] == 'L') r++;

    //落としたい
    if(S[i] == 'R') r--;
    if(S[i] == 'L') l++;

    res &= (X <= r && X >= l);
    Max(l, 1);Max(r, 1);Min(l, W);Min(r, W);
  }
  return res;
}

signed main(){
  srand((unsigned)time(NULL));
  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(12);

  int H, W, N;
  cin>>H>>W>>N;
  int sy, sx;
  cin>>sy>>sx;

  string S, T;
  cin>>S>>T;

  string Sx, Sy, Tx, Ty;

  for(int i=0;i<N;i++){
    if(S[i] == 'L' || S[i] == 'R') Sx += S[i], Sy += '.';
    else Sy += S[i] == 'U'? 'L':'R', Sx += '.';

    if(T[i] == 'L' || T[i] == 'R') Tx += T[i], Ty += '.';
    else Ty += T[i] == 'U'? 'L':'R', Tx += '.';
  }

  int a = check(Sy, Ty, sy, H);
  int b = check(Sx, Tx, sx, W);
  int ans = a & b;
  cout<<(ans? "YES":"NO")<<endl;

  return 0;
}

