bool can_remove(char which) {
	printf("------ %c\n", which);
	int len, start;
	char c0, c1;
	if (which == 'x') {
		len = w;
		start = sc;
		c0 = 'L';
		c1 = 'R';
	} else {
		len = h;
		start = sr;
		c0 = 'U';
		c1 = 'D';
	}
	int lower = -1;
	int upper = len;

	for (int i = S.size() - 1; i >= 0; i--) {
		auto move_s = make_pair(0, 0);
		if (S[i] == c0) { move_s.first = -1; }
		if (S[i] == c1) { move_s.second = 1; }

		auto move_t = make_pair(0, 0);
		if (T[i] == c0) { move_t.first = -1; }
		if (T[i] == c1) { move_t.second = 1; }


		if (i == S.size() - 1) {
			if (move_s.first < 0) { lower++; }
			if (move_s.second > 0) { upper--; }
		} else {
			if (move_s.first + move_t.second < 0) { lower++; }
			if (move_s.second + move_t.first > 0) { upper--; }
		}

		// printf("i %d, S %c %2d %2d, T %c %2d %2d: %2d %2d\n",
		// 	i, S[i], move_s.first, move_s.second, T[i], move_t.first, move_t.second,
		// 	lower, upper);
	}

	if (start <= lower || upper <= start) {
		return true;
	}
	return false;
}

