        }
        if (T[i] == 'U')
        {
            hmax = min(hmax + 1, H - 1);
        }
        if (T[i] == 'D')
        {
            hmin = max(hmin - 1, 0);
        }

        if (S[i] == 'L')
        {
            wmax = wmax - 1;
        }
        if (S[i] == 'R')
        {
            wmin = wmin + 1;
        }
        if (S[i] == 'U')
        {
            hmin = hmin + 1;
        }
        if (S[i] == 'D')
        {
            hmax = hmax - 1;
        }

        if (hmax < hmin)
        {
            YN(false);
            return 0;
        }
        if (wmax < wmin)
        {
            YN(false);
            return 0;
        }
    }

    YN(sr >= hmin && sr <= hmax && sc >= wmin && sc <= wmax);

    return 0;
}

