int what(char c) {
  if (c == 'U') return up;
  if (c == 'D') return down;
  if (c == 'L') return lef;
  return rig;
}

int main() {
  cin >> h >> w >> n >> sx >> sy >> a >> b;
  for (int i = 0; i < a.size(); i++) {
    if (i > 0) {
      for (int j = 0; j < 4; j++) {
        p1[i][j] = p1[i - 1][j];
        p2[i][j] = p2[i - 1][j];
      }
    }
    p1[i][what(a[i])]++;
    p2[i][what(b[i])]++;
  }
  // lef
  int ty = sy;
  for (int i = 0; i < n; i++) {
    if (a[i] == 'L') ty--;
    if (ty <= 0 || ty > w) {
      cout << "NO" << endl;
      return 0;
    }
    if (b[i] == 'R' && ty < w) {
      ty++;
    }
  }
  // rig
  ty = sy;
  for (int i = 0; i < n; i++) {
    if (a[i] == 'R') {
      ty++;
    }
    if (ty <= 0 || ty > w) {
      cout << "NO" << endl;
      return 0;
    }
    if (b[i] == 'L' && ty > 1) {
      ty--;
    }
  }
  // up
  int tx = sx;
  for (int i = 0; i < n; i++) {
    if (a[i] == 'U') {
      tx--;
    }
    if (tx <= 0 || tx > h) {
      cout << "NO" << endl;
      return 0;
