    if (a[i] == 'D') {
      tx++;
    }
    if (tx <= 0 || tx > h) {
      cout << "NO" << endl;
      return 0;
    }
    if (b[i] == 'U' && tx > 1) {
      tx--;
    }
  }
  cout << "YES" << endl;
