// コンテスト中に提出したのは嘘解法であった。。。


bool check(char cl, char cg, int init, int mg, string& S, string& T)
{
	int l = 1, g = mg;
	int N = S.size();
	for (int i = N - 1; i >= 0; --i) {
		if (T[i] == cl) {
			g = min(mg, g + 1);
		}
		else if (T[i] == cg) {
			l = max(1, l - 1);
		}

		if (S[i] == cl) {
			++l;
		}
		else if (S[i] == cg) {
			--g;
		}

		if (l > g) {
			return false;
		}
	}
	if (init < l || init > g) {
		return false;
	}
	else {
		return true;
	}
}


int main()
{
	int H, W, N;
	cin >> H >> W >> N;

	int sr, sc;
	cin >> sr >> sc;

	string S, T;
	cin >> S >> T;

	bool ans = true;
	ans &= check('L', 'R', sc, W, S, T);
	ans &= check('U', 'D', sr, H, S, T);

	cout << (ans ? "YES" : "NO") << endl;
}

