    sr--;
    sc--;
    cin >> s >> t;

    bool ans = false;
    if (solve<'L', 'R'>(w, sc) || solve<'U', 'D'>(h, sr))
    {
        ans = true;
    }

    cout << (ans ? "NO" : "YES") << endl;

    return 0;
}

