  for (int i = 0; i < 4; ++i) {
    index[vals[i]] = i;
  }
  vector<int> positions = {y, y, x, x};
  vector<int> need = {-1, m, -1, n};
  for (int i = 0; i < len; ++i) {
    auto ind = index[s[0][i]];
    if (ind % 2 == 0) {
      --positions[ind];
    } else {
      ++positions[ind];
    }
    for (int j = 0; j < 4; ++j) {
      if (positions[j] == need[j]) {
        cout << "NO\n";
        return;
      }
    }
    ind = index[s[1][i]];
    ind ^= 1;
    if (ind % 2 == 0) {
      positions[ind] = min(positions[ind] + 1, need[ind ^ 1] - 1);
    } else {
      positions[ind] = max(0, positions[ind] - 1);
    }
  }
  cout << "YES\n";
}

