bool judge(vector<int> w_dir, vector<int> w_who, int w, int start) {
    int L = 1, R = w;
    for (int i = w_dir.size() - 1; i >= 0; i--) {
        if (w_who[i] == 1) {
            if (w_dir[i] == 1) {
                R--;
            } else {
                L++;
            }
        } else {
            if (w_dir[i] == 1) {
                L = max(L - 1, 1);
            } else {
                R = min(R + 1, w);
            }
        }
        if (R < L) {
            return false;
        }
    }
    if (start >= L && start <= R) {
        return true;
    } else {
        return false;
    }
}

