std::pair<int, int> calc_range(int length, const char dec, const char inc) {
    int lb = 1;
    int ub = length;

    for (int i = N - 1; 0 <= i; i--) {
        if (T[i] == dec) {
            ub = std::min(ub + 1, length);
        } else if (T[i] == inc) {
            lb = std::max(lb - 1, 1);
        }

        if (S[i] == dec) {
            lb++;
        } if (S[i] == inc) {
            ub--;
        }
        if (lb > ub) {
            return std::pair<int, int>({-1, -1});
        }
    }
    return std::pair<int, int>({lb, ub});
}

