bool solve(vector<int> moves, int h, int p) {
	int l = 1, r = h;
	reverse(moves.begin(), moves.end());
	for (auto &i : moves) {
		if (i == 1) {
			l = max(1, l - 1);
		} else if (i == -1) {
			r = min(h, r + 1);
		} else if (i == 2) {
			--r;
		} else {
			++l;
		}
		if (l > r) {
			return false;
		}
	}
	return (l <= p and p <= r);
}

