            rr = rr - 1;
        } else if (s[i] == 'D') {
            lr = lr + 1;
        }
        if (lr + 1 >= rr) {
            cout << "NO" << endl;
            return 0;
        }
    }

    int lc = 0, rc = w + 1;
    rrep(i, n)
    {
        if (lc + 1 < rc) {
            if (t[i] == 'R') {
                lc = max(lc - 1, 0);
            } else if (t[i] == 'L') {
                rc = min(rc + 1, w + 1);
            }
        }

        if (s[i] == 'R') {
            rc = rc - 1;
        } else if (s[i] == 'L') {
            lc = lc + 1;
        }
        if (lc + 1 >= rc) {
            cout << "NO" << endl;
            return 0;
        }
    }

    if (sr <= lr || sr >= rr || sc <= lc || sc >= rc) {
        cout << "NO" << endl;
    } else {
        cout << "YES" << endl;
    }

    return 0;
}

