		if(i == 3) c = 'D', c1 = 'U';
		int x1 = x, y1 = y;
		rep(j, n){
			if(s[j] == c){
				if(c == 'L') y1--;
				if(c == 'R') y1++;
				if(c == 'U') x1--;
				if(c == 'D') x1++;
				if(c == 'L' && y1 < 1){
					cout << "NO" << endl;
					return 0;
				}
				if(c == 'R' && y1 > w){
					cout << "NO" << endl;
					return 0;
				}
				if(c == 'U' && x1 < 1){
					cout << "NO" << endl;
					return 0;
				}
				if(c == 'D' && x1 < h){
					cout << "NO" << endl;
					return 0;
				}
			}
			if(t[j] == c1){
				if(c1 == 'L' && y1 > 1) y1--;
				if(c1 == 'R' && y1 < w) y1++;
				if(c1 == 'U' && x1 > 1) x1--;
