void dfs(int x,int y,int t)
{
	//cout <<x<<" "<<y<<" "<<t<<" ##\n";
	if (!ok(x,y))
	{
		cout <<"NO";
		exit(0);
	}
	if (t==k*2)
	{
		cout <<"YES";
		exit(0);
	}
	if (t%2==0)
	{
		int r,c,ri,ci;
		int xi=x+d1[a[0][t/2]];
		int yi=y+d2[a[0][t/2]];
		r=min(x+1,m-x);
		ri=min(xi+1,m-xi);
		c=min(y+1,m-y);
		ci=min(yi+1,m-yi);
		bool fl=0;
		if (min(r,c)!=min(ri,ci)) fl=min(r,c)>min(ri,ci);
		else if (max(r,c)!=max(ri,ci)) fl=max(r,c)>max(ri,ci);
		if (fl) dfs(xi,yi,t+1);
		else dfs(x,y,t+1);
	}
	else
	{
		int r,c,ri,ci;
		int xi=x+d1[a[1][t/2]];
		int yi=y+d2[a[1][t/2]];
		r=min(x+1,m-x);
