        if ( S[n] == 'L' )
            dir = L;
        else if ( S[n] == 'R' )
            dir = R;
        else if ( S[n] == 'U' )
            dir = U;
        else if ( S[n] == 'D' )
            dir = D;

        for ( int d = 0; d < DIR; d++ )
            cum[d][n] = ( d == dir ? 1 : 0 ) + ( n == 0 ? 0 : cum[d][n - 1] );
    }
}

bool solve()
{
    if ( sr - cumS[U][0] <= 0 || H < sr + cumS[D][0] ) return false;
    if ( sc - cumS[L][0] <= 0 || W < sc + cumS[R][0] ) return false;

    dp[L][0] = max( 1, sc - cumT[L][0] + cumS[R][0] );
    dp[R][0] = min( W, sc + cumT[R][0] - cumS[L][0] );
    dp[U][0] = max( 1, sr - cumT[U][0] + cumS[D][0] );
    dp[D][0] = min( H, sr + cumT[D][0] - cumS[U][0] );

    for ( int n = 1; n < N; n++ )
    {
        // n 文字目まで処理した時の判定

        // 縦方向の判定
        if ( dp[D][n - 1] - cumS[U][n] <= 0 ) return false;
        if ( dp[U][n - 1] + cumS[D][n] > H ) return false;

        dp[D][n] = min( W, sc + cumT[D][n] - cumS[U][n] );
        dp[U][n] = max( 1, sc - cumT[U][n] + cumS[D][n] );

        // 横方向の判定
        if ( dp[R][n - 1] - cumS[L][n] <= 0 ) return false;
        if ( dp[L][n - 1] + cumS[R][n] > W ) return false;

        dp[R][n] = min( W, sc + cumT[R][n] - cumS[L][n] );
        dp[L][n] = max( 1, sc - cumT[L][n] + cumS[R][n] );
    }

    return true;
}

int main( int argc, char **argv )
{
    cin >> H >> W >> N;
    cin >> sr >> sc;
    cin >> S;
    cin >> T;

    calc_cum( S, cumS );
    calc_cum( T, cumT );

    bool ans = solve();

    if ( ans )
        cout << "YES" << endl;
    else
        cout << "NO" << endl;

    return 0;
}

