bool CanPush(int len, int s, const vi& a, const vi& b){
  int lo, hi;

  if(a[n - 1] == 0) lo = 1, hi = len;
  if(a[n - 1] == -1) lo = 2, hi = len;
  if(a[n - 1] == +1) lo = 1, hi = len - 1;
  if(lo > hi) return true;

  for(int i = n - 2;i >= 0;--i){
    if(b[i] == -1) hi = min(hi + 1, len);
    if(b[i] == +1) lo = max(lo - 1, 1);
    if(a[i] == -1) lo = lo + 1;
    if(a[i] == +1) hi = hi - 1;
    if(lo > hi) return true;
  }

  if(lo <= s && s <= hi) return false;
  return true;
}

