tuple<vi, vi> split(int N, string& s) {
    vi row(N, 0), col(N, 0);
    for (int i = 0; i < N; i++) {
        if (s[i] == 'U') row[i] = 1;
        else if (s[i] == 'D') row[i] = -1;
        else if (s[i] == 'L') col[i] = -1;
        else col[i] = 1;
    }
    return { row, col };
}

bool safe(int N, vi& atk, vi& def, int loc, int D) {
    vi moves;
    for (int i = 0; i < N; i++) {
        moves.push_back(atk[i]);
        moves.push_back(def[i]);
    }
    N *= 2;

    vector<array<int, 2>> safe(N);
    safe[N - 1] = { 0, D - 1 };
    for (int m = N - 2; m >= 0; m--) {
        safe[m] = safe[m+1];
        int &l = safe[m][0],
            &r = safe[m][1];
        if (l > r) continue;

        if ((m&1)) {
            // defender
            if (moves[m] == 1)
                l = max(l - 1, 0);
            if (moves[m] == -1)
                r = min(r + 1, D - 1);
        } else {
            // attacker
            if (moves[m] == 1)
                r--;
            if (moves[m] == -1)
                l++;
        }
    }

    return safe[0][0] <= loc && loc <= safe[0][1];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int H, W, N;
