void solve(ll a,ll b,vector<pll>&move){
    ll n=move.size();
    vector<ll>l(n+1,0),r(n+1,b+1);
    rrep(n){
        if(move[i].first){
            if(move[i].second==1){
                update_max(l[i],l[i+1]-1);
                r[i]=r[i+1];
            }else{
                update_min(r[i],r[i+1]+1);
                l[i]=l[i+1];
            }
        }else{
            r[i]=r[i+1];
            l[i]=l[i+1];
            if(move[i].second==1){
                r[i]--;
            }else{
                l[i]++;
            }
        }
    }
    ll min=a,max=a;
    rep(n){
        update_max(min,l[i]+1);
        update_min(max,r[i]-1);
        if(min>max){
            YES(0);
            exit(0);
        }
        if(move[i].first){
            if(move[i].second==1){
                max++;
            }else{
                min--;
            }
        }
    }
}
