    string s, t;
    cin >> s >> t;

    queue<char> T, A;
    for (int i = 0; i < N; i++) {
        T.push(s[i]);
        A.push(t[i]);
    }

    int x, y;
    queue<char> subT = T;
    queue<char> subA = A;
    // 上から
    x = sx, y = sy;
    for (int i = 0; i < 2 * N; i++) {
        if (i % 2 == 0) {
            if (T.front() == 'U') {
                x--;
            }
            T.pop();
        } else {
            if (A.front() == 'D' && x + 1 <= H) {
                x++;
            }
            A.pop();
        }
        if (x <= 0) {
            cout << "NO" << endl;
            return 0;
        }
    }

    // 下から
    x = sx, y = sy;
    T = subT;
    A = subA;
    for (int i = 0; i < 2 * N; i++) {
        if (i % 2 == 0) {
            if (T.front() == 'D') {
                x++;
            }
            T.pop();
        } else {
            if (A.front() == 'U' && x - 1 > 0) {
                x--;
            }
            A.pop();
        }
        if (x > H) {
            cout << "NO" << endl;
            return 0;
        }
    }

    // 左から
    x = sx, y = sy;
    T = subT;
    A = subA;
    for (int i = 0; i < 2 * N; i++) {
        if (i % 2 == 0) {
            if (T.front() == 'L') {
                y--;
            }
            T.pop();
        } else {
            if (A.front() == 'R' && y + 1 <= W) {
                y++;
            }
            A.pop();
        }
        if (y <= 0) {
            cout << "NO" << endl;
            return 0;
        }
    }

    // 右から
    x = sx, y = sy;
    T = subT;
    A = subA;
    for (int i = 0; i < 2 * N; i++) {
        if (i % 2 == 0) {
            if (T.front() == 'R') {
                y++;
            }
            T.pop();
        } else {
            if (A.front() == 'L' && y - 1 > 0) {
                y--;
            }
            A.pop();
        }
        if (y > W) {
            return 0;
        }
    }

    cout << "YES" << endl;
}

