bool f(string S, string T, int p) {
  dump(p,W);
  dump(S);
  dump(T);
  int cntrT=0;
  REP(i,N) {
    if(S[i]=='R') cntrT++;
  }
  REP(i,N) {
    if(S[i]=='L') --p;
    if(S[i]=='R') cntrT--;
    if(p<=0||p>W) return false;
    if(T[i]=='R'&&p<W) ++p;
    p=min(p,N-cntrT);
    dump(i,p);
    if(p<=0||p>W) return false;
  }
  return true;
}

void swap(string &s, string &t, char x, char y) {
  REP(i,N) {
    if(S[i]==x) S[i]=y;
    else if(S[i]==y) S[i]=x;
    if(T[i]==x) T[i]=y;
    else if(T[i]==y) T[i]=x;
  }
}

bool solve_org() {
  VI res;
  res.push_back(f(S,T,sj));
  swap(S,T,'L','R');
  res.push_back(f(S,T,W-sj+1));
  swap(S,T,'L','R');
  swap(S,T,'L','U');
  swap(S,T,'R','D');
  swap(H,W);
  res.push_back(f(S,T,si));
  swap(S,T,'L','R');
  res.push_back(f(S,T,W-si+1));
  dumpc(res);
  bool fall=count(ALL(res),0);
  return !fall;
}

bool g(vector<II> C, int p, int L) {
  int l=p,r=p;
  FORR(kvp, C) {
    if(kvp.first==0) {
      (kvp.second==1?r:l)+=kvp.second;
    } else {
      (kvp.second==1?l:r)+=kvp.second;
      l=max(1,l), r=min(L,r);
    }
    if(l<1||r>L) return false;
  }
  return true;
}

bool solve() {
  string ss[2]={S,T};
  vector<II> h,v;
  REP(i,2)REP(j,N) {
    if(ss[i][j]=='U'||ss[i][j]=='L') {
      v.emplace_back(i,ss[i][j]=='U'?-1:1);
    } else {
      h.emplace_back(i,ss[i][j]=='L'?-1:1);
    }
  }
  bool hres=g(h,sj,W),vres=g(v,si,H);
  if(hres||vres) return false;
  return true;
}

