        else if(t[i] == 'U' && d != h) d++;
        else if(t[i] == 'D' && u != 1) u--;
        if(s[i] == 'L') l++;
        else if(s[i] == 'R') r--;
        else if(s[i] == 'U') u++;
        else d--;
        if(l > r || u > d) return puts("NO")*0;
    }
    puts(l <= y && y <= r && u <= x && x <= d ? "YES" : "NO");
}

