int h,w,n,x,y;
string s,t;

struct dp{

	int x1,x2,y1,y2;
	dp(int x1,int x2,int y1,int y2):x1(x1),y1(y1),x2(x2),y2(y2){}

	void U(bool pre){
		if(pre)x2 = min(h + 1,x2 + 1);
		else x1 = min(x2,x1 + 1);	
	}
	void D(bool pre){
		if(pre)x1 = max(0,x1 - 1);
		else x2 = max(x1,x2 - 1);
	}
	void L(bool pre){
		if(pre)y2 = min(w + 1,y2 + 1);
		else y1 = min(y2,y1 + 1);
	}
	void R(bool pre){
		if(pre)y1 = max(0,y1 - 1);
		else y2 = max(y1,y2 - 1);
	}


	void print(){
		cerr << x1 << ' ' << x2 << ' ' << y1 << ' ' << y2 << '\n';
	}
};

int main(int argc, char const *argv[])
{
	ioboost();

	cin >> h >> w >> n >> x >> y >> s >> t;
	x--,y--;

	dp ans(0,h+1,0,w+1);

	for(int i = n-1;i >= 0;i--){
		char lat = t[i],pre = s[i];

		if(lat == 'L')ans.L(false);
		if(lat == 'U')ans.U(false);
		if(lat == 'R')ans.R(false);
		if(lat == 'D')ans.D(false);

		//ans.print();

		if(pre == 'L')ans.L(true);
		if(pre == 'U')ans.U(true);
		if(pre == 'R')ans.R(true);
		if(pre == 'D')ans.D(true);

		//ans.print();
	}

	//ans.print();

	if(ans.x1 <= x and x < ans.x2 and ans.y1 <= y and y < ans.y2){
		cout << "YES" << '\n';
	}else{
		cout << "NO" << '\n';
	}

	return 0;
}

