template<typename T> inline T chmax(T& a, const T b) { return a = (a < b) ? b : a; }
template<typename T> inline T chmin(T& a, const T b) { return a = (a > b) ? b : a; }

ll power(ll base, ll exponent){ if(exponent % 2){ return power(base, exponent - 1) * base % mod; }else if(exponent){ ll root_ans = power(base, exponent / 2); return root_ans * root_ans % mod; }else{ return 1; }}
ll inverse(ll x){ return power(x, mod - 2);}
ll gcd(ll a, ll b) {if(a < b) gcd(b, a);ll r;while(r=a%b) {a=b;b=r;}return b;}
template<typename T> ll sum(T begin, T end) {return accumulate(begin, end, 0ll);}
struct combination{ vector<ll> fact, inv; combination(int sz) : fact(sz + 1), inv(sz + 1){ fact[0] = 1; for(int i = 1; i <= sz; i++){ fact[i] = fact[i - 1] * i % mod; } inv[sz] = power(fact[sz], mod - 2); for(int i = sz - 1; i >= 0; i--){ inv[i] = inv[i + 1] * (i + 1) % mod; } } ll C(int p, int q) const{ if(q < 0 || p < q) return 0; return (fact[p] * inv[q] % mod * inv[p - q] % mod); } };

using Pair = pair<ll, ll>;

template <ll Modulus> struct ModInt {
    ll a;
    constexpr ModInt(const ll x = 0) noexcept  : a((x%mod+mod) % mod){}
    constexpr ll &value() noexcept {return a;}
    constexpr const ll &value() const noexcept {return a;}
    constexpr ModInt operator+(const ModInt x) const noexcept {
      return ModInt(*this) += x;
    }
    constexpr ModInt operator-(const ModInt x) const noexcept {
      return ModInt(*this) -= x;
    }
    constexpr ModInt operator*(const ModInt x) const noexcept {
      return ModInt(*this) *= x;
    }
    constexpr ModInt operator/(const ModInt x) const noexcept {
      return ModInt(*this) /= x;
    }
    constexpr ModInt &operator+=(const ModInt x) noexcept {
      a += x.a;
      if (a >= Modulus) {
        a -= Modulus;
      }
      return *this;
    }
    constexpr ModInt &operator-=(const ModInt x) noexcept {
      if (a < x.a) {
        a += Modulus;
      }
      a -= x.a;
      return *this;
    }
    constexpr ModInt &operator*=(const ModInt x) noexcept {
      a = a * x.a % Modulus;
      return *this;
    }
    constexpr ModInt &operator/=(ModInt x) noexcept {
      ll exp = Modulus - 2;
      while (exp) {
        if (exp % 2) {
          *this *= x;
        }
        x *= x;
        exp /= 2;
      }
      return *this;
    }
    constexpr  ModInt operator-() noexcept {
      return ModInt(-a);
    }
    friend ostream& operator<<(ostream& os, const ModInt& m){
      os << m.a;
      return os;
    }
};
using mint = ModInt<mod>;

bool check(ll h, ll r, const vector<ll> & a) {
  ll lft = -1;
  ll rgt = h;
  REP_REV(i, sz(a)) {
    if(i % 2 == 0) {
      if(a[i] == 1) {
        rgt--;
      }
      else if(a[i] == - 1) {
        lft++;
      }
    }
    else {
      if(a[i] == 1) {
        lft--;
      }
      else if(a[i] == - 1) {
        rgt++;
      }
    }
    if(rgt - lft == 1) return true;
    if(lft < 0) lft = -1;
    if(rgt > h) rgt = h;
  }
  return r <= lft || rgt <= r;
}


