class BLRUDGame {
public:
	void solve(std::istream& in, std::ostream& out) {
        int h, w, sr, sc, n;
        string s, t;
        in >> h >> w >> n >> sr >> sc >> s >> t;
        --sr; --sc;

        map<char, int> mp;
        mp['U'] = mp['D'] = sr;
        mp['L'] = mp['R'] = sc;
        bool flg = true;
        for(int i=0; i<n; i++){
            if(s[i] == 'R' || s[i] == 'D'){
                mp[s[i]]++;
                if((s[i] == 'R' && mp[s[i]] >= w) || (s[i] == 'D' && mp[s[i]] >= h)){
                    flg = false;
                    break;
                }
            }else{
                mp[s[i]]--;
                if(mp[s[i]] < 0){
                    flg = false;
                    break;
                }
            }
            if(t[i] == 'L' || t[i] == 'R'){
                for(auto e : {'R', 'L'}) {
                    if(mp[e] > w/2 && t[i] == 'L') mp[e]--;
                    else if(mp[e] < w/2 && t[i] == 'R') mp[e]++;
                    else if(mp[e] == w/2) {
                        if(e == 'R' && t[i] == 'L') mp[e]--;
                        if(e == 'L' && t[i] == 'R') mp[e]++;
                    }
                }
            }else{
                for(auto e : {'U', 'D'}) {
                    if(mp[e] > w/2 && t[i] == 'U') mp[e]--;
                    else if(mp[e] < w/2 && t[i] == 'D') mp[e]++;
                    else if(mp[e] == w/2) {
                        if(e == 'U' && t[i] == 'U') mp[e]--;
                        if(e == 'D' && t[i] == 'D') mp[e]++;
                    }
                }
            }
        }

        ans2(flg, out);
	}
};


