using namespace std;
bool interval(vector<pair<int,int> > mvs, int sz, int p){
	int l = 1, r = sz;
	while(!mvs.empty()){
		int dx, id; tie(dx, id) = mvs.back(); mvs.pop_back();
		if(id == 0){
			if(dx == -1) l++;
			else r--;
		} else {
			if(dx == -1) r = min(r + 1, sz);
			else l = max(l - 1, 1);
		}
		if(l > r) return false;
	}
	return l <= p && p <= r;
}
int main(){
	int h, w, n; cin >> h >> w >> n;
	int sr, sc; cin >> sr >> sc;
	string s, t; cin >> s >> t;
	vector<pair<int,int> > uph, upw;
	for(int i = 0; i < n; i++){
		int id = 0;
		for(int rot = 0; rot < 2; rot++, id ^= 1){
			if(s[i] == 'U') uph.push_back({-1,id});
			else if(s[i] == 'D') uph.push_back({1,id});
			else if(s[i] == 'L') upw.push_back({-1,id});
			else if(s[i] == 'R') upw.push_back({1,id});
			swap(s, t);
		}
	}
	if(interval(uph, h, sr) && interval(upw, w, sc)) cout << "YES" << endl;
	else cout << "NO" << endl;
	return 0;
}

