    for (int i = 0; i < n; i++)
    {
        switch (s[i])
        {
        case 'L':
            left--;
            break;
        case 'R':
            right++;
            break;
        case 'U':
            up--;
            break;
        case 'D':
            down++;
            break;
        default:
            break;
        }

        if (left < 0 || right > w - 1 || up < 0 || down > h - 1)
        {
