            {
                left++;
            }
            break;
        case 'U':
            if (down != h - 1)
            {
                down--;
            }
            break;
        case 'D':
            if (up != 0)
            {
                up++;
            }
            break;
        default:
            break;
        }
    }

    if (yes)
    {
        cout << "YES" << endl;
