    int l = -1;
    int r = W;

    if (S[N - 1] == 'L') l++;
    if (S[N - 1] == 'R') r--;
    for (int i = N - 2; i >= 0; i--) {
        if (r - l <= 1) break;
        if (T[i] == 'R') l = max(l - 1, -1);
        if (T[i] == 'L') r = min(r + 1, W);
        if (S[i] == 'L') l++;
        if (S[i] == 'R') r--;
    }
    if (Sc <= l || r <= Sc) {
        cout << "NO" << endl;
        return 0;
    }

    // 縦   u < Sr < d で落ちない
    int u = -1;
    int d = H;

    if (S[N - 1] == 'U') u++;
    if (S[N - 1] == 'D') d--;
    for (int i = N - 2; i >= 0; i--) {
        if (d - u <= 1) break;
        if (T[i] == 'D') u = max(u - 1, -1);
        if (T[i] == 'U') d = min(d + 1, H);
        if (S[i] == 'U') u++;
        if (S[i] == 'D') d--;
    }
    if (Sr <= u || d <= Sr) {
        cout << "NO" << endl;
        return 0;
    }

    cout << "YES" << endl;
    return 0;
}

