int main(){
	int h, w, n; cin >> h >> w >> n;
	int sr, sc; cin >> sr >> sc;
	string s, t; cin >> s >> t;
	auto getId = [](char c){
		if(c == 'L') return 0;
		if(c == 'R') return 1;
		if(c == 'U') return 2;
		return 3;
	};
	auto build = [&](string u){
		vector<vector<int>> acc(4, vector<int>(n, 0));
		for(int i = 0; i < 4; i++){
			int sum = 0;
			for(int j = 0; j < n; j++){
				if(getId(u[j]) == i) sum++;
				acc[i][j] = sum;
			}
		}
		return acc;
	};
	auto query = [&](vector<vector<int> > p, int c, int l, int r){
		int ans = p[c][r];
		if(l) ans -= p[c][l - 1];
		return ans;
	};
	vector<vector<int> > ds = build(s);
	for(int i = 0; i <= 1; i++){
		for(int j = 2; j <= 3; j++){
			int xx = sr, yy = sc;
			for(int k = 0; k < n; k++){
				int curId = getId(s[k]);
				if(curId == i || curId == j){
					if(curId == 0) yy--;
					if(curId == 1) yy++;
					if(curId == 2) xx--;
					if(curId == 3) xx++;
				}
				if(xx < 1 || xx > h || yy < 1 || yy > w){
					cout << "NO" << endl;
					return 0;
				}
				curId = getId(t[k]);
				if(curId == 0){
					int mvs = query(ds, 1, k + 1, n - 1);
					if(yy + mvs > w) if(yy - 1 > 0) yy--;
				}
				if(curId == 1){
					int mvs = query(ds, 0, k + 1, n - 1);
					if(yy - mvs < 1) if(yy + 1 < w) yy++;
				}
				if(curId == 2){
					int mvs = query(ds, 3, k + 1, n - 1);
					if(xx + mvs > h) if(xx - 1 > 0) xx--;
				}
				if(curId == 3){
					int mvs = query(ds, 2, k + 1, n - 1);
					if(xx - mvs < 1) if(xx + 1 < h) xx++;
				}
				if(xx < 1 || xx > h || yy < 1 || yy > w){
					cout << "NO" << endl;
					return 0;
				}
			}
		}
	}
	cout << "YES" << endl;
	return 0;
}

