bool solve(const vector<pair<int, int>>& v, int r, int s) {
  int safe_l = 1, safe_r = r;
  for (int i = v.size() - 1; i >= 0; --i) {
    safe_r = min(safe_r, r);
    safe_l = max(safe_l, 1);

    auto curr = v[i];
    if (curr.first == 0) {
      if (curr.second == -1) {
        safe_l += 1;
      } else {
        safe_r -= 1;
      }
    } else {
      if (curr.second == -1) {
        safe_r += 1;
      } else {
        safe_l -= 1;
      }
    }
    if (safe_l > r || safe_r < 1 || safe_l > safe_r) {
      return false;
    }
  }

  return safe_l <= s && s <= safe_r;
}

