bool solve (int N, int ps, char str1[], char str2[], char mv1, char mv2, int L)
{
	int lef = 1, rig = L;
	for (int i = N; i >= 1; --i) {
		if (str2[i] == mv1) { rig = min(rig + 1, L); }
		if (str2[i] == mv2) { lef = min(lef, 1); }
		if (str1[i] == mv1) { ++lef; }
		if (str1[i] == mv2) { --rig; }
		if (lef > rig) { return false; }
	}
	return lef <= ps and ps <= rig;
}

