bool solve(char* S, char* T, int fr, int to, int pos, int edge, char add, char sub) {
    int l = 1; int r = edge;

    for(int i = to; i >= fr; --i) {
        // printf("%d %c %c %c: ", i, T[i], S[i], add);
        if(T[i] == add) { 
            l --;
        } else if(T[i] == sub) {
            r ++;
        }

        l = max(l, 1);
        r = min(r, edge);

        if(S[i] == add) {
            r --;
        } else if(S[i] == sub) {
            l ++;
        }

        if(l > r) return false;
    }
    if(l <= pos && pos <= r) return true;
    else return false;
}
