int dist(pair<int, int> a, pair<int, int> b) {
	return abs(a.first - b.first) + abs(a.second - b.second);
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int h, w, n;
	cin >> h >> w >> n;
	int sy, sx;
	cin >> sy >> sx;
	string s, t;
	cin >> s >> t;

	auto move = [&](char c) -> pair<int, int> {
		if(c == 'L')
			return {-1, 0};
		else if(c == 'U')
			return {0, -1};
		else if(c == 'R')
			return {1, 0};
		else if(c == 'D')
			return {0, 1};
		return {inf, inf};
	};

	auto valid = [&](int x, int y) {
		return 1 <= x && x <= w && 1 <= y && y <= h;
	};

	int goalx = (w + 1) / 2, goaly = (h + 1) / 2;
	REP(i, n) {
		auto mv = move(s[i]);
		int x = sx + mv.first, y = sy + mv.second;
		if(dist({x, y}, {goalx, goaly}) > dist({sx, sy}, {goalx, goaly})) {
			sx = x;
			sy = y;
		}
		if(not valid(sx, sy))
			return cout << "NO\n", 0;
		mv = move(t[i]);
		x = sx + mv.first, y = sy + mv.second;
		if(dist({x, y}, {goalx, goaly}) < dist({sx, sy}, {goalx, goaly})) {
			sx = x;
			sy = y;
		}
	}
	cout << "YES\n";

}

