bool isOverLeft(std::string s, std::string t, int x, int w) {
	REP(i, s.size()) {
		{
			if (s[i] == '-') {
				--x;
				if (x < 0) return true;
			}
		}
		{
			if (t[i] == '+') {
				if (x + 1 < w) ++x;
			}
		}
	}
	return false;
}

bool isWinTakahashi(std::string s, std::string t, int x, int w) {
	if (isOverLeft(s, t, x, w)) return true;

	for (auto& c : s) {
		/* */if (c == '-') c = '+';
		else if (c == '+') c = '-';
	}
	for (auto& c : t) {
		/* */if (c == '-') c = '+';
		else if (c == '+') c = '-';
	}
	x = w - 1 - x;

	if (isOverLeft(s, t, x, w)) return true;
	return false;
}

