using namespace std;
using lolo=int;
using vec=vector<lolo>;

void soinsu(lolo N, lolo K)
{

	lolo size = lolo(pow(N, 0.5) + 100);

	lolo subN = N;
	lolo totalcnt = 0;
	for (lolo i = 2; i < size; ++i) {
		if (N % i == 0) {
			lolo cnt = 0;
			while (N % i == 0) {
				cnt += 1;
				N /= i;
			}
			//A[i] = cnt;
			totalcnt += cnt;
		}
	}
	if (totalcnt < K) {
		cout << -1 << endl;
		exit(0);
	}

	N = subN;
	lolo nowseki = 1;
	for (lolo i = 2; i < size; ++i) {
		if (N % i == 0) {
			lolo cnt = 0;
			while (N % i == 0) {
				if (K > 1) {
					cout << i << " ";
					K -= 1;
					nowseki *= i;
					N /= i;
				}
				else if (K == 1){
					cout << subN / nowseki << endl;
					return;						
				}

			}
		}
	}

}
