int main(){
	cin>>h>>w>>n;
	cin>>sp.x>>sp.y; 
	cin>>s>>t;
	bool won = false;
	//possible to reach top
	int vu = 0, vd = 0, hl = 0, hr = 0;
	for(int i = n-1; i >= 0; i--){
		//start with t[i]
		if(t[i] == 'L'){
			sub(hr);
		}else if(t[i] == 'R'){
			sub(hl);
		}else if(t[i] == 'U'){
			//down
			sub(vd);
		}else if(t[i] == 'D'){
			sub(vu);
		}

		if(s[i] == 'L')	{
			hl++;
		}else if(s[i] == 'R'){
			hr++;
		}else if(s[i] == 'U'){
			vu++;
		}else{
			vd++;
		}

		if(hl + hr == w){
			won = true;
			break;
		}
		if(vu + vd == h){
			won = true;
			break;
		}
	}
	if(won){
		cout<<"NO"<<endl;
	}else{
		if((sp.x <= vu || (h - sp.x+1) <= vd) || (sp.y <= hl || (w - sp.y+1) <= hr)){
			cout<<"NO"<<endl;
		}else{
			cout<<"YES"<<endl;
		}
	}
}

