bool check(char l, char r, int start, int width) {
    int left = 1, right = width;
    REP (i, N) {
        if (S[i] == l) left += 1;
        else if (S[i] == r) right -= 1;
        if (left > right) return false;

        if (T[i] == l) right = min(width, right+1);
        else if (T[i] == r) left = max(1, left-1);
