int main(){
    int H, W, N; cin >> H >> W >> N;
    int sr, sc; cin >> sr >> sc;

    string s, t; cin >> s >> t;

    int north = sr, south = H+1-sr, left = sc, right = W+1-sc;

    vector<int> tol(N+1, 0), tor(N+1, 0), ton(N+1, 0), tos(N+1, 0);

    if(s[0] == 'L') tol[0] = 1;
    if(s[0] == 'R') tor[0] = 1;
    if(s[0] == 'U') ton[0] = 1;
    if(s[0] == 'D') tos[0] = 1;


    for(int i=1; i<N; i++){
        if(s[i] == 'L'){
            tol[i] = tol[i-1]+1;
            tor[i] = tor[i-1];
            ton[i] = ton[i-1];
            tos[i] = tos[i-1];
        }
        else if(s[i] == 'R'){
            tol[i] = tol[i-1];
            tor[i] = tor[i-1]+1;
            ton[i] = ton[i-1];
            tos[i] = tos[i-1];
        }
        else if(s[i] == 'U'){
            tol[i] = tol[i-1];
            tor[i] = tor[i-1];
            ton[i] = ton[i-1]+1;
            tos[i] = tos[i-1];
        }
        else if(s[i] == 'D'){
            tol[i] = tol[i-1];
            tor[i] = tor[i-1];
            ton[i] = ton[i-1];
            tos[i] = tos[i-1]+1;
        }

        if(t[i-1] == 'L'){
            if(sc+tor[i-1] > 1)tor[i]--;
        }
        else if(t[i-1] == 'R'){
            if(sc-tol[i-1] < W )tol[i]--;
        }
        else if(t[i-1] == 'U'){
            if(sr+tos[i-1] > 1) tos[i]--;
        }
        else if(t[i-1] == 'D'){
            if(sr-ton[i-1] < H) ton[i]--;
        }
    }


    for(int i=0; i<N; i++){
        if(tol[i] >= left || tor[i] >= right || tos[i] >= south || ton[i] >= north){
            cout << "NO" << endl;
            return 0;
        }
    }

    cout << "YES" << endl;

}

