int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int H,W,N,fix,fiy;
    string act,def;
    cin >> H >> W >> N >> fix >> fiy >> act >> def;
    int left = fiy,right = W-fiy+1,up = fix,down = H-fix+1;
    int r=0,l=0,u=0,d=0;
    bool on = 1;
    REP(i,N){
        if(act.at(i) == 'U'){
            u++;
            if(u==up){
                on = 0;
                break;
            }
        }
        if(act.at(i) == 'D'){
            d++;
            if(d==down){
                on = 0;
                break;
            }
        }
        if(act.at(i) == 'R'){
            r++;
            if(r==right){
                on = 0;
                break;
            }
        }
        if(act.at(i) == 'L'){
            l++;
            if(l==left){
                on = 0;
                break;
            }
        }
        if(def.at(i) == 'U'){
            d--;
            if(abs(d)==up)d++;
        }
        if(def.at(i) == 'D'){
            u--;
            if(abs(u)==down)u++;
        }
        if(def.at(i) == 'R'){
            l--;
            if(abs(l)==right)r++;
        }
        if(def.at(i) == 'L'){
            r--;
            if(abs(r)==left)r++;
        }
    }
    if(on == 0)std::cout << "NO" << "\n";
    else std::cout << "YES" << "\n";
}

