#define rep(i,a,b) for(int i = (a); i < (b); ++i)
#define rrep(i,a,b) for(int i = (b); i --> (a);)
#define all(v) (v).begin(),(v).end()
#define trav(x,v) for(auto &x : v)
#define sz(v) int(v.size())
typedef vector<int> vi;
typedef long long ll;
typedef pair<int,int> pii;

bool solve(){
	int h, w, n, sr, sc;
	cin >> h >> w >> n >> sr >> sc;
	string s, t;
	cin >> s >> t;
	int rlo = 1, rhi = h, clo = 1, chi = w;

	rrep(i,0,n){
		switch(t[i]){
			case 'U': rhi = min(rhi+1, h); break;
			case 'D': rlo = max(rlo-1, 1); break;
			case 'L': chi = min(chi+1, w); break;
			case 'R': clo = max(clo-1, 1); break;
		}
		switch(s[i]){
			case 'U': rlo++; break;
			case 'D': rhi--; break;
			case 'L': clo++; break;
			case 'R': chi--; break;
		}
		if(rlo > rhi || clo > chi) return false;
	}

	return rlo <= sr && sr <= rhi &&
	   clo <= sc && sc <= chi;
}

int main(){
	cin.sync_with_stdio(0);
	cin.tie(0);

	cout << (solve() ? "YES" : "NO") << endl;
}

