using namespace std;

int H, W, N;
int sr, sc;
string S, T;

int IsRight(void) {

	int pos = sc;

	for (int i = 0; i < N; i++) {
		if (S[i] == 'R') { pos++; }
		if (pos > W) { return 1; }
		if ((T[i] == 'L') && pos >= 2) { pos--; }
	}
	return 0;
}
int IsLeft(void) {

	int pos = sc;

	for (int i = 0; i < N; i++) {
		if (S[i] == 'L') { pos--; }
		if (pos <1) { return 1; }
		if ((T[i] == 'R') && pos <W ) { pos++; }
	}
	return 0;
}

int IsUp(void) {

	int pos = sr;

	for (int i = 0; i < N; i++) {
		if (S[i] == 'U') { pos--; }
		if (pos <1) { return 1; }
		if ((T[i] == 'D') && pos <H) { pos++; }
	}
	return 0;
}

int IsDown(void) {

	int pos = sr;

	for (int i = 0; i < N; i++) {
		if (S[i] == 'D') { pos++; }
		if (pos >H) { return 1; }
		if ((T[i] == 'U') && pos >1) { pos--; }
	}
	return 0;
}

int main(void) {

	cin >> H >> W >> N;
	cin >> sr >> sc;

	cin >> S >> T;

	int flag = 1;

	if (IsRight() == 1) { flag = 0; }
	if (IsLeft() == 1) { flag = 0; }
	if (IsUp() == 1) { flag = 0; }
	if (IsDown() == 1) { flag = 0; }

	if (flag == 1) { cout << "YES" << endl; }
	else { cout << "NO" << endl; }

	return 0;
}

