    if(S[i] == 'R') { right += 1; rightHigh = std::max(rightHigh, right); }
    if(S[i] == 'U') { down += 1; downHigh = std::max(downHigh, down); }
    if(S[i] == 'D') { up += 1; upHigh = std::max(upHigh, up); }
  }
  if( X <= leftHigh ) { std::cout << "NO"; return 0; }
  if( W-X < rightHigh ) { std::cout << "NO"; return 0; }
  if( Y <= upHigh ) { std::cout << "NO"; return 0; }
  if( H-Y < downHigh ) { std::cout << "NO"; return 0; }
