const int MAXN = 2e5 + 5;
char S[MAXN];
char T[MAXN];
char* templates = "LRUD";
int cnt[MAXN][2][5];

int main() {
    int H, W, N;
    int x, y;
    while(~scanf("%d %d %d", &H, &W, &N)) {
        memset(cnt, 0, sizeof(cnt));

        scanf("%d %d", &x, &y);
        scanf("%s", S);
        scanf("%s", T);


        for(int i = 0, len = strlen(S); i < len; ++i) {
            for(int j = 0; j < 4; ++j) {
                if(templates[j] == S[i]) {
                    cnt[i][0][j] ++;
                    break;
                }
            }
            for(int j = 0; j < 4; ++j) {
                if(templates[j] == T[i]) {
                    cnt[i][1][j] ++;
                    break;
                }
            }
        }

        for(int i = 1; i < N; ++i) {
            for(int j = 0; j < 4; ++j) {
                cnt[i][0][j] += cnt[i - 1][0][j];
                cnt[i][1][j] += cnt[i - 1][1][j];
            }
        }

        bool suc = true;
        for(int i = 0, len = strlen(S), xx = x, yy = y; i < len && suc; ++i) {
            if(S[i] == 'L')
                yy --;
            if(yy <= 0) suc = false; 

            if(T[i] == 'R') {
                yy = min(yy + 1, W);
            }

            if(yy + (cnt[N - 1][0][1] - cnt[i][0][1] - cnt[N - 1][1][0] + cnt[i][1][0]) > W) suc = false;
        }

        for(int i = 0, len = strlen(S), xx = x, yy = y; i < len && suc; ++i) {
            if(S[i] == 'R')
                yy ++;
            if(yy > W) suc = false; 

            if(T[i] == 'L') {
                yy = max(yy - 1, 1);
            }

            if(yy - (cnt[N - 1][0][0] - cnt[i][0][0] - cnt[N - 1][1][1] + cnt[i][1][1]) <= 0) suc = false;

        }

        for(int i = 0, len = strlen(S), xx = x, yy = y; i < len && suc; ++i) {
            if(S[i] == 'U')
                xx --;
            if(xx <= 0) suc = false; 

            if(T[i] == 'D') {
                xx = min(xx + 1, H);
            }

            if(xx + (cnt[N - 1][0][3] - cnt[i][0][3] - cnt[N - 1][1][2] + cnt[i][1][2]) > H) suc = false;
        }

        for(int i = 0, len = strlen(S), xx = x, yy = y; i < len && suc; ++i) {
            if(S[i] == 'U')
                xx ++;
            if(xx > H) suc = false; 

            if(S[i] == 'L') {
                xx = max(xx - 1, 1);
            }

            if(yy - (cnt[N - 1][0][2] - cnt[i][0][2] - cnt[N - 1][1][3] + cnt[i][1][3]) <= 0) suc = false;
        }

        printf("%s\n", suc ? "YES" : "NO");

    }
    return 0;
}

