    scanf("%d %d",&sr,&sc);
    cin >> a >> b;
    for(int i = N-1;i >= 0;i--){
        char ch = a[i];
        if(ch == 'R') RA[i] = 1;
        else if(ch == 'L') LA[i] = 1;
        else if(ch == 'U') UA[i] = 1;
        else DA[i] = 1;
        RA[i] += RA[i+1];
        LA[i] += LA[i+1];
        UA[i] += UA[i+1];
        DA[i] += DA[i+1];
    }
     for(int i = N-1;i >= 0;i--){
        char ch = b[i];
        if(ch == 'R') RB[i] = 1;
        else if(ch == 'L') LB[i] = 1;
        else if(ch == 'U') UB[i] = 1;
        else DB[i] = 1;
        RB[i] += RB[i+1];
        LB[i] += LB[i+1];
        UB[i] += UB[i+1];
        DB[i] += DB[i+1];
    }
    int ok = 1;
    int xmin,xmax;
    int ymin,ymax;
    xmin = xmax = sr;
    ymin = ymax = sc;
    _for(i,0,N){
        int l = RB[i] - LA[i] + 1;
        int r = W + LB[i]-RA[i];
        if(r <= l){ok = 0; break;}

        if(xmin > r || (xmin == r && a[i] == 'R' )){ok = 0;break;}
        if(xmax < l || (xmax == l && a[i] == 'L')){ok = 0;break;}


        if(a[i] == 'L' && b[i] != 'R'){
            xmin = max(1,max(l,xmin-1));
        }
        else{
            xmin = max(1,max(l,xmin));
        }

        if(a[i] == 'R' && b[i] != 'L'){
            xmax = min(W,min(r,xmax+1));
        }
        else{
            xmax = min(W,min(r,xmax));
        }
    }

    _for(i,0,N){
        int l = DB[i] - UA[i] + 1;
        int r = W + UB[i]-DA[i];
        if(r <= l){ok = 0; break;}

        if(ymin > r || (ymin == r && a[i] == 'D')){ok = 0;break;}
        if(ymax < l || (ymax == l && a[i] == 'U')){ok = 0;break;}

        if(a[i] == 'U' && b[i] != 'D'){
            ymin = max(1,max(l,ymin-1));
        }
        else{
            ymin = max(1,max(l,ymin));
        }

        if(a[i] == 'D' && b[i] != 'U'){
            ymax = min(W,min(r,ymax+1));
        }
        else{
            ymax = min(W,min(r,ymax));
        }
    }

    if(ok) printf("YES");
    else printf("NO");
    return 0;
}

