int find_optimal(int st, int en, char l, char r) {
  int ll = 0, rr = en-1, ans = -1;
  while (ll <= rr) {
    int mid = ll + rr >> 1;

    bool can = true;
    int cur = st;

    for (int i=0; i<n; i++) {
      if (s[i] == l) --cur;
      if (cur < 0) {
        can = false;
        break;
      }

      if (t[i] == r) cur = min(cur+1, max(cur, mid));
    }

    if (can) {
      ans = mid;
      rr = mid - 1;
    } else ll = mid + 1;
  }

  return ans;
}


bool okay(int st, int en, int opt, char l, char r) {
  vector<int> v;
  for (int i=0; i<n; i++) {
    if (s[i] == r) v.push_back(1);
    else v.push_back(0);

    if (t[i] == l) v.push_back(-1);
    else v.push_back(0);
  }
}

int solve(int st, int en, char l, char r) {
  int tmp1 = find_optimal(st, en, l, r);
  if (tmp1 == -1) return 0;

  int tmp2 = find_optimal(en - st - 1, en, r, l);
  if (tmp2 == -1) return 0;
  tmp2 = en - tmp2 - 1;

  return 1;
}



