                --ma;
            tmp_mi = mi;
            mi = min(mi, ma);
            ma = max(tmp_mi, ma);
            if(mi <= down[i + 1] || ma >= up[i + 1])
                return false;
        }
        return true;
    };
    if(!f('U', 'D')){
        cout << "NO" << endl;
        return 0;
    }
    swap(h, w);
    swap(sx, sy);
    if(!f('R', 'L')){
        cout << "NO" << endl;
        return 0;
    }
    cout << "YES" << endl;
}

