      if (c == 'L') dir[1][i]--;
      if (c == 'R') dir[1][i]++;
    }
    swap(dir, eir);
  }

  for (int q = 0; q < 2; q++) {
    int l(0), r(w[q]);
    for (int i = n - 1; i >= 0; i--) {
      if (eir[q][i] == -1) r++, chmin(r, w[q]);
      if (eir[q][i] == +1) l--, chmax(l, 0);
      if (dir[q][i] == -1) l++;
      if (dir[q][i] == +1) r--;
      if (r - l < 1) err();
    }
    if (s[q] < l || r <= s[q]) err();
  }
  cout << "YES" << endl;
  return 0;
}

