int h, w;

bool is_exterior(int i, int j) {
    return i < 0 || i >= h || j < 0 || j >= w;
}

int dist(int i, int j) {
    return min(i, h - i - 1) + min(j, w - j - 1);
}

int main() {
    int n; cin >> h >> w >> n;
    int ci, cj; cin >> ci >> cj; ci--, cj--;
    string s, t; cin >> s >> t;
    int ch;
    for (int i = 0; i < n; i++) {
        ch = s[i];
        if (ch == 'L' && dist(ci, cj) > dist(ci, cj - 1)) cj--;
        if (ch == 'R' && dist(ci, cj) > dist(ci, cj + 1)) cj++;
        if (ch == 'U' && dist(ci, cj) > dist(ci - 1, cj)) ci--;
        if (ch == 'D' && dist(ci, cj) > dist(ci + 1, cj)) ci++;
        if (is_exterior(ci, cj)) {
            cout << "NO" << endl;
            return 0;
        }
        ch = t[i];
        if (ch == 'L' && dist(ci, cj) < dist(ci, cj - 1)) cj--;
        if (ch == 'R' && dist(ci, cj) < dist(ci, cj + 1)) cj++;
        if (ch == 'U' && dist(ci, cj) < dist(ci - 1, cj)) ci--;
        if (ch == 'D' && dist(ci, cj) < dist(ci + 1, cj)) ci++;
        if (is_exterior(ci, cj)) {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
    return 0;
}

