    REP(i, N) {
        if (S[0][i] == 'R') x += 1;
        if (x > W) return false;
        if (S[1][i] == 'L' && x - L[i+1] - 1 >= 1) x -= 1;
    }
    x = Sr;
    REP(i, N) {
        if (S[0][i] == 'D') x -= 1;
        if (x <= 0) return false;
        if (S[1][i] == 'U' && x + U[i+1] + 1 <= H) x += 1;
    }
    x = Sr;
    REP(i, N) {
        if (S[0][i] == 'U') x += 1;
        if (x > H) return false;
        if (S[1][i] == 'D' && x - D[i+1] - 1 >= 1) x -= 1;
    }
    return true;
}

