  ios::sync_with_stdio(false);
  int h, w, sx, sy;
  cin >> h >> w >> n >> sy >> sx;
  cin >> s >> t;
  if (f(sx, w, 'L', 'R') && f(sy, h, 'U', 'D')) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }

  return 0;
}

