const string YES = "YES";
const string NO = "NO";

void solve(long long H, long long W, long long N, long long s_r, long long s_c,
           std::string S, std::string T) {
  int u = 0, r = 0, l = 0, d = 0;

  for (int i = N - 1; i >= 0; i--) {
    if (T[i] == 'U') d = max(0, d - 1);
    if (T[i] == 'R') l = max(0, l - 1);
    if (T[i] == 'L') r = max(0, r - 1);
    if (T[i] == 'D') u = max(0, u - 1);

    if (S[i] == 'U') u++;
    if (S[i] == 'R') r++;
    if (S[i] == 'L') l++;
    if (S[i] == 'D') d++;
    if (u + d >= H || r + l >= W) {
      cout << NO << endl;
      return;
    }
  }
  if (l >= s_c) {
    cout << NO << endl;
    return;
  }

  if (r >= W + 1 - s_c) {
    cout << NO << endl;
    return;
  }
  if (d >= H + 1 - s_r) {
    cout << NO << endl;
    return;
  }

  if (u >= s_r) {
    cout << NO << endl;
    return;
  }
  cout << YES << endl;
}

