bool solve(vector<int> &taka,vector<int> &aoki,int W,int s){
  int l=1;
  int r=W;
  rep(i,N){
    int x=aoki.at(i);
    if(x==1)  r=min(W,r+1);
    if(x==-1) l=max(1,l-1);

    x=taka.at(i);
    if(x==1)  l++;
    if(x==-1) r--;

