bool CanDrop(char A, char B)
{
  int x = sr;
  int y = sc;
  for (int i = 0; i < N; ++i) {
    if (S[i] == A) {
      x += dx[A];
      y += dy[A];
    }
    if (x < 0 or x >= H or y < 0 or y >= W) {
      return true;
    }
    if (T[i] == B) {
      int nx = x + dx[B];
      int ny = y + dy[B];
      if (0 <= nx and nx < H and 0 <= ny and ny < W) {
	x = nx;
	y = ny;
      }
    }
  }
  return false;
}

