bool must_fall(int m, int sp, char dec, char inc){
	// one-dimensional version
	// try < 1
	int cp = sp;
	for(int i = 1; i <= n; i++){
		if(str1[i] == dec){
			cp--;
			if(cp == 0){
				return true;
			}
		}
		if(str2[i] == inc && cp < m){
			cp++;
		}
	}
	// try > m
	cp = sp;
	for(int i = 1; i <= n; i++){
		if(str1[i] == inc){
			cp++;
			if(cp > m){
				return true;
			}
		}
		if(str2[i] == dec && cp > 1){
			cp--;
		}
	}
	return false;
}

