  std::cin >> S >> T;

  ll cntl = 0LL;
  ll cntr = 0LL;
  ll cntu = 0LL;
  ll cntd = 0LL;
  for (ll i = 0; i < N; i++) {
    if (S[i] == 'L') cntl++;
    if (S[i] == 'R') cntr++;
    if (S[i] == 'U') cntu++;
    if (S[i] == 'D') cntd++;
  }

  ll lon = 0LL;
  ll ron = 0LL;
  ll uon = 0LL;
  ll don = 0LL;
  if (px - cntl <  0) lon = 1;
  if (px + cntr >= W) ron = 1;
  if (py - cntu <  0) uon = 1;
  if (py + cntd >= H) don = 1;

  if (lon == 1 && ron == 1) {
    if (cntl >= cntr) ron = 0LL;
    else lon = 0LL;
  }

  if (uon == 1 && don == 1) {
    if (cntu >= cntd) don = 0LL;
    else uon = 0LL;
  }

  //print('X', 'X', "y", py, "x", px, H, W);

  bool judge = true;
  for (ll i = 0; i < N; i++) {
    if ((S[i] == 'L' && T[i] == 'R') ||
	(S[i] == 'R' && T[i] == 'L') ||
	(S[i] == 'U' && T[i] == 'D') ||
	(S[i] == 'D' && T[i] == 'U')) {
      continue;
    }

    if (S[i] == 'L') {
      if (lon == 1LL) px--;
    }
    if (S[i] == 'R') {
      if (ron == 1LL) px++;
    }
    if (S[i] == 'U') {
      if (uon == 1LL) py--;
    }
    if (S[i] == 'D') {
      if (don == 1LL) py++;
    }

    if (T[i] == 'L' || T[i] == 'R') {
      if (W % 2 == 1 && px == W / 2) continue;
    }
    if (T[i] == 'U' || T[i] == 'D') {
      if (H % 2 == 1 && px == H / 2) continue;
