bool solve() {
  int minx=1,maxx=W,miny=1,maxy=H;
  for(int i=N-1; i>=0; --i) {
    if(i<N-1) {
      if(T[i]=='U') ++miny;
      if(T[i]=='D') --maxy;
      if(T[i]=='L') ++maxx;
      if(T[i]=='R') --minx;
    }

    minx=max(1,minx);
    miny=max(1,miny);
    maxx=min(W,maxx);
    maxy=min(H,maxy);

    if(S[i]=='U') ++maxy;
    if(S[i]=='D') --miny;
    if(S[i]=='L') ++minx;
    if(S[i]=='R') --maxx;

    if(minx>maxx) return false;
    if(miny>maxy) return false;
  }
  //  dump(minx,sj,maxx);
  //  dump(miny,si,maxy);
  if(sj<minx||sj>maxx) return false;
  if(si<miny||si>maxy) return false;
  return true;
}
bool solve_org() {
  int minx=1,maxx=W,miny=1,maxy=H;
  for(int i=N-1; i>=0; --i) {
    if(T[i]=='U') ++miny;
    if(T[i]=='D') --maxy;
    if(T[i]=='L') ++maxx;
    if(T[i]=='R') --minx;

    minx=max(1,minx);
    miny=max(1,miny);
    maxx=min(W,maxx);
    maxy=min(H,maxy);

    if(S[i]=='U') ++maxy;
    if(S[i]=='D') --miny;
    if(S[i]=='L') ++minx;
    if(S[i]=='R') --maxx;

    if(minx>maxx) return false;
    if(miny>maxy) return false;
  }
//  dump(minx,sj,maxx);
//  dump(miny,si,maxy);
  if(sj<minx||sj>maxx) return false;
  if(si<miny||si>maxy) return false;
  return true;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout<<setprecision(12)<<fixed;

  cin>>H>>W>>N>>si>>sj>>S>>T;
