bool isOut(int d, vector<int>& sv, vector<int>& tv)
{
  int y = sr, x = sc;
  REP(i, sv.size()) {
    if (sv[i] == d) {
      x += dx[d];
      y += dy[d];
    }
    if (x < 0 || x >= W || y < 0 && y >= H) return true;
    if (tv[i] == rev[d]) {
      int nx = x + dx[rev[d]];
      int ny = y + dy[rev[d]];
      if (nx < 0 || nx >= W || ny < 0 && ny >= H) continue;
      x = nx;
      y = ny;
    }
  }
  return false;
}

