using ll = long long;

const std::string LRUD = "LRUD";
const ll dj[4] = { -1, 1, 0, 0 }, di[4] = { 0, 0, -1, 1 };

ll H, W, N, sr, sc;
std::string S, T;

ll border( ll r, ll c )
{
  return std::min( { r+1, H-r, c+1, W-c } );
}

bool safe( ll r, ll c )
{ return r >= 0 && r < H && c >= 0 && c < W; }

bool rec( ll i, ll r, ll c, bool fl )
{
  if( i == N )
  {
    return !safe( r, c );
  }

  if( !fl )
  {
    ll d = LRUD.find( S[i] );
    ll nr = r+di[d], nc = c+dj[d];

    if( !safe( nr, nc ) || rec( i, nr, nc, fl^1 ) )
      return true;

    return false;
  }
  else
  {
    ll d = LRUD.find( T[i] );
    ll nr = r+di[d], nc = c+dj[d];

    if( safe( nr, nc ) && !rec( i+1, nr, nc, fl^1 ) )
      return false;

    return true;
  }
}

int main()
{
  std::cin >> H >> W >> N >> sr >> sc >> S >> T;

  --sr, --sc;

  puts( rec( 0, sr, sc, 0 ) ? "NO" : "YES" );

  return 0;
}

