ll H, W, N, sr, sc;


bool ch(vector<ll> a, vector<ll> b , ll L, ll s) {


	vector<ll> c(2 * N + 1);

	repn(i, N) {
		c[2 * i - 1] = b[N + 1 - i];
		c[2 * i] = a[N + 1 - i];
	}

	ll le = 1;
	ll ri = L;

	for (ll i = 2; i <= 2 * N; i++) {
		if (i % 2 == 0) {
			if (c[i] == 1) { ri--; }
			if (c[i] == -1) { le++; }
		}

		if (i % 2 == 1) {
			if (c[i] == 1) { le = max(le - 1, 1); }
			if (c[i] == -1) { ri = max(ri + 1, L); }
		}


		if (le > ri) { return false; }
	}

	if (s<le || s>ri) { return false; }
	return true;

}

