// L, U, D, R
int dx[]={-1, 0, 0, 1};
int dy[]={0, 1, -1, 0};
bool ok(int x, int y){
  return (0<=x&&x<w&&0<=y&&y<h);
}

void solve(int x, int y, char c1, char c2){
  for(int i=0;i<n;i++){
    if(s[i]==c1){
      auto mv = moves[c1];
      x += dx[mv];
      y += dy[mv];
      if(!ok(x, y)){
        f=false;
        return;
      }
    }
    if(t[i]==c2){
      // 相手のL, Rが到達できる位置まで戻す
      auto mv = moves[c2];
      int nx = x+dx[mv];
      int ny = y+dy[mv];
      if(ok(nx, ny)){
        x = nx;y=ny;
      }
    }
  }
}

