inline bool ok(int x,int y)
{
	return x>=0 && y>=0 && x<n && y<m;
}
bool dfs(int x,int y,int t)
{
	//cout <<x<<" "<<y<<" "<<t<<" ##\n";
	if (!ok(x,y)) return 0;
	if (t==k*2) return 1;
	if (t%2==0)
	{
		int r,c,ri,ci;
		int xi=x+d1[a[0][t/2]];
		int yi=y+d2[a[0][t/2]];
		r=min(x+1,n-x);
		ri=min(xi+1,n-xi);
		c=min(y+1,m-y);
		ci=min(yi+1,m-yi);
		bool fl=0;
		if (min(r,c)!=min(ri,ci))
		{
			fl=min(r,c)>min(ri,ci);
			if (fl) return dfs(xi,yi,t+1);
			else return dfs(x,y,t+1);
		}
		else if (max(r,c)!=max(ri,ci))
		{
			fl=max(r,c)>max(ri,ci);
			if (fl) return dfs(xi,yi,t+1);
			else return dfs(x,y,t+1);
		}
		else
		{
			if (!dfs(xi,yi,t+1)) return 0;
			else if (!dfs(x,y,t+1)) return 0;
			else return 1;
		}
	}
	else
	{
		int r,c,ri,ci;
		int xi=x+d1[a[1][t/2]];
		int yi=y+d2[a[1][t/2]];
		r=min(x+1,n-x);
		ri=min(xi+1,n-xi);
		c=min(y+1,m-y);
		ci=min(yi+1,m-yi);
		bool fl=0;
		if (min(r,c)!=min(ri,ci))
		{
			fl=min(r,c)<min(ri,ci);
			if (fl) return dfs(xi,yi,t+1);
			else return dfs(x,y,t+1);
		}
		else if (max(r,c)!=max(ri,ci))
		{
			fl=max(r,c)<max(ri,ci);
			if (fl) return dfs(xi,yi,t+1);
			else return dfs(x,y,t+1);
		}
		else
		{
			if (dfs(xi,yi,t+1)) return 1;
			else if (dfs(x,y,t+1)) return 1;
			else return 0;
		}
	}
}
