bool stays(string &S, string &T, char back, char fwd, int H, int pos){
  int L=1; int R=H;
  int N=S.size();
  for(int i=N-1;i>=0;--i){
    char a = T[i];
    if(a==back){
      L = max(L-1,1);
    } else if (a==fwd){
      R = min(R+1,H);
    }
    char b = S[i];
    if(b==back){
      R--;
    } else if (b==fwd){
      L++;
    }
    if(R<L) return false;
  }
  return (L<=pos && pos<=R);
}
