    if (min(h - nx + 1, nx) < min(h - sx + 1, sx)) sx = nx;
    if (min(w - ny + 1, ny) < min(w - sy + 1, sy)) sy = ny;
    // aoki
    switch (t[i]) {
      case 'L':
        nx = sx + dx[0];
        ny = sy + dy[0];
        break;
      case 'R':
        nx = sx + dx[1];
        ny = sy + dy[1];
        break;
      case 'U':
        nx = sx + dx[2];
        ny = sy + dy[2];
        break;
      case 'D':
        nx = sx + dx[3];
        ny = sy + dy[3];
        break;
    }
    if (nx < 1 || nx > h || ny < 1 || ny > w) continue;
    if (min(h - nx + 1, nx) > min(h - sx + 1, sx)) sx = nx;
    if (min(w - ny + 1, ny) > min(w - sy + 1, sy)) sy = ny;
  }
  puts("YES");
}

