	bool flag = true;
	REP(i, N)
	{
		if(S[i]=='L'){
			if(sc<=cW){
				sc--;
			}
		}
		else if(S[i]=='R'){
			if(sc>=cW){
				sc++;
			}
		}else if(S[i]=='U'){
			if(sr<=cH){
				sr--;
			}
		}else{
			if(sr>=cH){
				sr++;
			}
		}

		if(sr==0||sc==0||sr==H+1||sc==W+1){
			flag = false;
			break;
		}

		if(T[i]=='L'){
			if(sc>cW){
				sc--;
			}
		}
		else if(T[i]=='R'){
			if(sc<cW){
				sc++;
			}
		}else if(T[i]=='U'){
			if(sr>cH){
				sr--;
			}
		}else{
			if(sr<cH){
				sr++;
			}
		}
	}

	if(flag){
		cout << "YES" << endl;
	}else{
		cout << "NO" << endl;
	}

	return 0;
}

