	lint extGCD(lint a, lint b, lint& x, lint& y) {
		if (b == 0) {
			x = 1;
			y = 0;
			return a;
		}
		lint d = extGCD(b, a % b, y, x);
		y -= a / b * x;
		return d;
	}

	template<class It>
	auto carr(It begin, It end) {
		vec c;
		c.push_back(1);
		auto before = *begin;
		for (auto it = begin + 1; it != end; it++) {
			if (before != *it) {
				c.push_back(0);
				before = *it;
			}
			c.back()++;
		}
		return c;
	}

