int main(){
  int H, W, N;cin>>H>>W>>H;
  int r,c;cin>>r>>c;
  string S,T;cin>>S>>T;

  bool ans=true;

  int left_out_lim=0, right_out_lim=W;
  int upper_out_lim=0, lower_out_lim=H;

  if(S[N-1]=='L') left_out_lim++;
  if(S[N-1]=='R') right_out_lim--;

  for (int i=N-2;i>=0;--i){
    if(T[i]=='R') left_out_lim=min(left_out_lim-1, 0);
    if(T[i]=='L') right_out_lim=max(right_out_lim+1, W);

    if(S[i]=='L') left_out_lim++;
    if(S[i]=='R') right_out_lim--; 
  }

  if (S[N-1]=='U') upper_out_lim++;
  if(S[N-1]=='D') lower_out_lim--;

  for (int i=N-2;i>=0;--i){
    if(T[i]=='D') upper_out_lim=min(upper_out_lim-1,0);
    if(T[i]=='U') lower_out_lim=max(lower_out_lim+1,H);

    if(S[i]=='U') upper_out_lim++;
    if(S[i]=='D') lower_out_lim--;
  }

  if(left_out_lim>=c|| right_out_lim<=c) ans=false;
  if(upper_out_lim>=r|| lower_out_lim<=r) ans=false;

  if(ans) cout << "YES" << endl;
  else cout << "NO" << endl;
  return 0;
}

