	for(int i = n - 1; i >= 0; i--){
		int h1 = A[i] % 2 == 0 ? (A[i] - 1) : 0;
		int h2 = B[i] % 2 == 0 ? B[i] - 1 : 0;
		int L1 = L, R1 = R;
		if(h1 == 1 && h2 == -1){
			R = min(R, w - 1);
		} else if(h1 == -1 && h2 == 1){
			L = max(L, 2);
		} else if(h1 == 1 && h2 == 1){
			L--; R--; L = max(L, 1);
		} else if(h1 == -1 && h2 == -1){
			L++; R++;
			R = min(R, w);
		} else if(h1 == 0 && h2 == 1){
			L--; L = max(L, 1);
		} else if(h1 == 0 && h2 == -1){
			R++; R = min(R, w);
		} else if(h1 == 1 && h2 == 0){
			R--;
		} else if(h1 == -1 && h2 == 0){
			L++;
		}
		if(L > R){
			return 1;
		}
	}
	return !(pos >= L && pos <= R);
}

void rot(int n){
	for(int i = 0; i < n; i++) A[i] = p[A[i]];
	for(int i = 0; i < n; i++) B[i] = p[B[i]];
}

