void solve() {
  int h, w, n; scanf("%d%d%d", &h, &w, &n);
  int sr, sc; scanf("%d%d", &sr, &sc);
  int x[4] = {sc-1, w-sc, sr-1, h-sr};
  for (int i = 0; i < n; ++i) {
    scanf(" %c", s+i);
    if (s[i] == 'L') s[i] = 0;
    else if (s[i] == 'R') s[i] = 1;
    else if (s[i] == 'U') s[i] = 2;
    else s[i] = 3;
  }
  for (int i = 0; i < n; ++i) {
    scanf(" %c", t+i);
    if (t[i] == 'L') t[i] = 0;
    else if (t[i] == 'R') t[i] = 1;
    else if (t[i] == 'U') t[i] = 2;
    else t[i] = 3;
  }
  int z[4] = {};
  for (int i = n-1; i >= 1; --i) {
    ++z[s[i]];
    if (z[s[i]] > x[s[i]]) {
      puts("NO");
      return;
    }
    int other = t[i-1]+1;
    if (t[i-1]%2) other = t[i-1]-1;
    if (z[other]) --z[other];
  }
  ++z[s[0]];
  if (z[s[0]] > x[s[0]]) {
    puts("NO");
    return;
  }
  puts("YES");
}

