using namespace std;

int main()
{
	int h, w, n; cin >> h >> w >> n;
	int sr, sc; cin >> sr >> sc;
	string s, t; cin >> s >> t;

	int lpos = 0;
	int rpos = w + 1;
	int upos = 0;
	int dpos = h + 1;
	//cout << lpos << " " << rpos << " " << upos << " " << dpos << endl;

	FOR_DW(i, n - 1, 0) {
		if (i != n - 1) {
			switch (t[i]) {
			case 'U':
				if (dpos <= h) dpos++;
				break;
			case 'D':
				if (1 < upos) upos--;
				break;
			case 'L':
				if (rpos <= w) rpos++;
				break;
			case 'R':
				if (1 < lpos) lpos--;
				break;
			}
		}
		switch (s[i]) {
		case 'U': upos++; break;
		case 'D': dpos--; break;
		case 'L': lpos++; break;
		case 'R': rpos--; break;
		}

		//cout << rpos << " " << lpos << " " << dpos << " " << upos << endl;

		if (rpos <= 1 || w <= lpos || dpos <= 1 || h <= upos) {
			cout << "NO" << endl;
			return 0;
		}
		if (rpos - 1 <= lpos || dpos - 1 <= upos) {
			cout << "NO" << endl;
			return 0;
		}
	}

	if (sr <= upos || dpos <= sr || sc <= lpos || rpos <= sc) {
		cout << "NO" << endl;
	}
	else {
		cout << "YES" << endl;
	}

	return 0;
}

