	for(int i=1;i<=len;i++){
		if(a[i]=='D') posx++;
		if(posx>n){
			printf("NO\n");
			return 0;
		}else if(b[i]=='U'&&posx-1>=1) posx--;
	}
	posy=sy;
	for(int i=1;i<=len;i++){
		if(a[i]=='L') posy--;
		if(!posy){
			printf("NO\n");
