int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	// LとR、UとD独立で考える
	// Nターン目までにLに落とす場合とRを後ろから考える
	// iターン目にxL_iだとLに落ち、xR_iだとRに落ちるとしたら,
	// xL_i < x_i < xR_iを毎ターン保つことができるなら落ちない

	int H, W, N;
	cin >> H >> W >> N;
	int sr, sc;
	cin >> sr >> sc;

	string S, T;
	cin >> S >> T;

	vector<int> L_min(N + 1, 0), R_max(N + 1, W + 1);
	for (int i = (int)S.size() - 1; i >= 0; i--) {
		if (S[i] == 'L') L_min[i] = L_min[i + 1] + 1;
		else L_min[i] = L_min[i + 1];
		if (S[i] == 'R') R_max[i] = R_max[i + 1] - 1;
		else R_max[i] = R_max[i + 1];
	}

	vector<int> L(N + 1, sc), R(N + 1, sc);
	for (int i = 0; i < N; i++) {
		if (T[i] == 'R') L[i + 1] = L[i] - 1;
		else L[i + 1] = L[i];
		if (T[i] == 'L') R[i + 1] = R[i] + 1;
		else R[i + 1] = R[i];
		chmax(L[i + 1], L_min[i] + 1);
		chmin(R[i + 1], R_max[i] - 1);
	}

	DMP(L_min, R_max, L, R);

	for (int i = 0; i < N; i++) {
		if (L[i + 1] >= R_max[i] || R[i] <= L_min[i + 1]) {
			cout << "NO" << "\n";
			return 0;
		}
	}

	vector<int> U_min(N + 1, 0), D_max(N + 1, H + 1);
	for (int i = (int)S.size() - 1; i >= 0; i--) {
		if (S[i] == 'U') U_min[i] = U_min[i + 1] + 1;
		else  U_min[i] = U_min[i + 1];
		if (S[i] == 'D') D_max[i] = D_max[i + 1] - 1;
		else D_max[i] = D_max[i + 1];
	}

	vector<int> U(N + 1, sr), D(N + 1, sr);
	for (int i = 0; i < N; i++) {
		if (T[i] == 'D') U[i + 1] = U[i] - 1;
		else U[i + 1] = U[i];
		if (T[i] == 'U') D[i + 1] = D[i] + 1;
		else D[i + 1] = D[i];
		chmax(U[i + 1], U_min[i] + 1);
		chmin(D[i + 1], D_max[i] - 1);
	}

	for (int i = 1; i < N; i++) {
		if (U[i] >= D_max[i + 1] || D[i] <= U_min[i + 1]) {
			cout << "NO" << "\n";
			return 0;
		}
	}

	cout << "YES" << "\n";

	return 0;
}

