  else if(a[0]==-1)ml=2;
  if(ml>mr)return true;
  for(int i=1;i<s;i++){
  	if(b[i]==1)ml--;
    else if(b[i]==-1)mr++;
    mr=min(mr,lim);
    ml=max(ml,1);
