  vll ub(N), lb(N);
  if (S[N - 1] == 'D') {
    ub[N - 1] = H - 1;
    lb[N - 1] = 1;
  } else if (S[N - 1] == 'U') {
    ub[N - 1] = H;
    lb[N - 1] = 2;
  } else {
    ub[N - 1] = H;
    lb[N - 1] = 1;
  }
  for (int i = N - 2; i >= 0; i--) {
    if (S[i] == 'D') {
      if (T[i] == 'U') {
        ub[i] = ub[i + 1];
      } else {
        ub[i] = ub[i + 1] - 1;
      }
      ub[i] = min(ub[i], H - 1);
      lb[i] = lb[i + 1];
    } else if (S[i] == 'U') {
      if (T[i] == 'D') {
        lb[i] = lb[i + 1];
      } else {
        lb[i] = lb[i + 1] + 1;
