        ub[i] = min(H, ub[i + 1] + 1);
        lb[i] = lb[i + 1];
      } else if (T[i] == 'D') {
        ub[i] = ub[i + 1];
        lb[i] = max(1LL, lb[i + 1] - 1);
      } else {
        ub[i] = ub[i + 1];
        lb[i] = lb[i + 1];
      }
    }
  }  // i

  if (sr < lb[0] || sr > ub[0]) {
    puts("NO");
    return 0;
  }

  // LR
  if (S[N - 1] == 'R') {
    ub[N - 1] = W - 1;
    lb[N - 1] = 1;
  } else if (S[N - 1] == 'L') {
    ub[N - 1] = W;
    lb[N - 1] = 2;
  } else {
    ub[N - 1] = W;
    lb[N - 1] = 1;
  }
  for (int i = N - 2; i >= 0; i--) {
    if (S[i] == 'R') {
      if (T[i] == 'L') {
        ub[i] = ub[i + 1];
      } else {
        ub[i] = ub[i + 1] - 1;
      }
      ub[i] = min(ub[i], W - 1);
      lb[i] = lb[i + 1];
    } else if (S[i] == 'L') {
      if (T[i] == 'R') {
        lb[i] = lb[i + 1];
      } else {
        lb[i] = lb[i + 1] + 1;
      }
      lb[i] = max(lb[i], 2LL);
      ub[i] = ub[i + 1];
    } else {
      if (T[i] == 'R') {
        ub[i] = min(H, ub[i + 1] + 1);
        lb[i] = lb[i + 1];
      } else if (T[i] == 'L') {
        ub[i] = ub[i + 1];
        lb[i] = max(1LL, lb[i + 1] - 1);
      } else {
        ub[i] = ub[i + 1];
        lb[i] = lb[i + 1];
      }
    }
  }  // i

  if (sc < lb[0] || sc > ub[0]) {
    puts("NO");
    return 0;
  }

  puts("YES");

  return 0;
}

