        if (T[i] == d) ll--;
        chmin(rr, ub[i][1]);
        chmax(ll, lb[i][1]);
        if (ll >= rr) {
            cerr << i << endl;
            cerr << ll << " " << rr << endl;
            return true;
        }
        // cerr << i << " " << ll << " " << rr << endl;
    }
    return false;
