void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>H>>W>>N>>Y>>X>>S>>T;
	Y--,X--;

	int L=0,R=W-1,U=0,D=H-1;
	for(i=N-1;i>=0;i--) {
		if(i!=N-1) {
			if(T[i]=='U') D=min(D+1,H-1);
			if(T[i]=='D') U=max(U+1,0);
			if(T[i]=='L') R=min(R+1,W-1);
			if(T[i]=='R') L=max(L+1,0);
		}
		if(S[i]=='U') U++;
		if(S[i]=='D') D--;
		if(S[i]=='L') L++;
		if(S[i]=='R') R--;
		if(R<L || D<U) return _P("NO\n");
	}

	if(X<L || X>R || Y<U || Y>D) cout<<"NO"<<endl;
	else cout<<"YES"<<endl;

}


