bool judge(const string &s, const string &t, ll n, ll h, char uc, char dc, ll pos)
{
    ll safe_min = 0;
    ll safe_max = h-1;

    rrep (i, n) {
        if (t[i] == uc) safe_max = min(safe_max+1, h-1);
        if (t[i] == dc) safe_min = max(safe_min-1, 0LL);
        if (s[i] == uc) safe_min++;
        if (s[i] == dc) safe_max--;
        debug_printf("i=%lld safe_min=%lld safe_max=%lld\n", i, safe_min, safe_max);
        if (safe_min > safe_max) return true;
    }

    if (pos < safe_min) return true;
    if (pos > safe_max) return true;

    return false;
}

