    for(int i = s.size()-1; i >= 0; i--){
        if(i != s.size() - 1){
            taka[i] = taka[i+1];
        }
        if(s[i] == 'L') taka[i].l++;
        if(s[i] == 'R') taka[i].r++;
        if(s[i] == 'D') taka[i].d++;
        if(s[i] == 'U') taka[i].u++;
    }
    CMD ao[t.size()];
    for(int i = s.size()-1; i >= 0; i--){
        if(i != s.size() - 1){
            ao[i] = ao[i+1];
        }
        if(t[i] == 'L') ao[i].l++;
        if(t[i] == 'R') ao[i].r++;
        if(t[i] == 'D') ao[i].d++;
        if(t[i] == 'U') ao[i].u++;
    }

    int maxHeight = h;
    int minHeight = 1;
    int minWidth = 1;
    int maxWidth = w;
    for(int i = n-1; i >= 0; i--){
        if(t[i] == 'D') minHeight = max(1,minHeight-1);
        if(t[i] == 'L') maxWidth = min(maxWidth+1,w);
        if(t[i] == 'U') maxHeight = min(maxHeight+1,h);
        if(t[i] == 'R') minWidth = max(1,minWidth-1);

        if(s[i] == 'U') maxHeight--;
        if(s[i] == 'R') maxWidth --;
        if(s[i] == 'D') minHeight ++;
        if(s[i] == 'L') minWidth ++;
        if(minWidth > maxWidth || maxHeight < minHeight){
            cout << "NO" << endl;
            return 0;
        }
    }
    if(minHeight <= sr && sr <= maxHeight &&
       minWidth <= sc && sc <= maxWidth ){
           cout << "YES" << endl;
       }else{
           cout << "NO" << endl;
       }
    return 0;
}

