int dx[5] = {0, 0, 0, -1, 1}, dy[5] = {0, -1, 1, 0, 0};

bool safe(int x, int y) {
    if(x && x <= N && y && y <= M) return 1;
    return 0;
}

bool solve(int dir, int opdir, char c1, char c2) {
    int x = sx, y = sy;
    for(int i=1; i<=K; i++) {
        if(A[i] == c1) {
            int nx = x + dx[dir], ny = y + dy[dir];
            if(!safe(nx, ny)) return 0;
            x = nx, y = ny;
        }
        if(B[i] == c2) {
            int nx = x + dx[opdir], ny = y + dy[opdir];
            if(safe(nx, ny)) x = nx, y = ny;
        }
    }
    return 1;
}

