  int fallL, fallR, fallU, fallD;
  fallL = sx + 1;
  fallR = W - sx;
  fallU = sy + 1;
  fallD = H - sy;

  //初期状態における*minus*を入れる
  int LminusR = 0;
  int RminusL = 0;
  int UminusD = 0;
  int DminusU = 0;

