int solve(string a, string b, int m, int s)
{
    int n = SZ(a);
    vi kek(n);

    kek.back() = m;
    if (a.back() == 'R')
        kek.back()--;

    for (int i = n - 2; i >= 0; --i)
    {
        kek[i] = kek[i + 1];

        if (b[i] == 'L' && a[i] != 'R')
            kek[i]++;
        else if (b[i] != 'L' && a[i] == 'R')
            kek[i]--;

        if (a[i] == 'R')
            kek[i] = min(kek[i], m - 1);
        else
            kek[i] = min(kek[i], m);


        if (kek[i] <= 0)
            return 1;
    }


    for (int i = 0; i < n; ++i)
    {
        if (s > kek[i])
            return 1;

        if (a[i] == 'L')
            s--;

        if (s <= 0)
            return 1;

        if (i + 1 != n) {

            if (b[i] == 'R' && s + 1 <= kek[i + 1])
            {
                s++;
            }

            if (b[i] == 'L' && s > kek[i + 1])
            {
                s--;
            }
        }
    }

    return 0;
}


