// 0-L 1-R 2-U 3-D
int h, w, n;
P s, k;
bool ok = true;
string tak, aok, dir = "LRUD";

char gy(char d){
	if(d == 'L') return 'R';
	if(d == 'R') return 'L';
	if(d == 'U') return 'D';
	if(d == 'D') return 'U';
	return 'L';
}
P mov(P p, char d){
	if(d == 'L') return make_pair(p.first - 1, p.second);
	if(d == 'R') return make_pair(p.first + 1, p.second);
	if(d == 'U') return make_pair(p.first, p.second - 1);
	if(d == 'D') return make_pair(p.first, p.second + 1);
	return make_pair(-1, -1);
}
bool isok(P p, int h, int w){
	if(1 <= p.first && p.first <= w 
	&& 1 <= p.second && p.second <= h) return true;
	else return false;
}
// recursive func.
bool game(int i, P s){
	bool ok = true;
	for(char d : dir){
		// cout << i << " " << d << " " << s.first << " " << s.second << endl;
		k = s;
		repp(j, i / 2 + 1, n){
			// tak
				if(i % 2 == 0){
				if(tak[i] == d) k = mov(k, d);
				if(!isok(k, h, w)){
					return false;
				}
				// cout << k.first << " " << k.second << "  ";
			}
			// aok
			if(aok[i] == gy(d) && isok(mov(k, gy(d)), h, w))
				k = mov(k, gy(d));
			// cout << k.first << " " << k.second << endl;
		}
		if(i != 2 * n){
			if(i % 2 == 0) ok &= game(i + 1, k);
			else ok |= game(i + 1, k);
		}
		else ok |= isok(k, h, w);
	}
	return ok;
}

