#include<boost/multi_array.hpp>
#include<boost/optional.hpp>
#include<boost/range/irange.hpp>
#include<boost/range/algorithm.hpp>
#include<boost/range/adaptors.hpp>
#include<boost/algorithm/clamp.hpp>
#include<boost/dynamic_bitset.hpp>
namespace adaptor = boost::adaptors;

enum class winner
{
	takahashi,
	aoki
};
winner run(int H, int W, int N, int sr, int sc, std::string const& taka, std::string const& aoki)
{
	using boost::algorithm::clamp;
	enum vector
	{
		up, down, left, right
	};
	std::map<char, vector> move;
	move.emplace('U', up);
	move.emplace('D', down);
	move.emplace('L', left);
	move.emplace('R', right);
	boost::multi_array<int, 2> taka_move(boost::extents[N + 1][4]);
	boost::multi_array<int, 2> aoki_move(boost::extents[N + 1][4]);
	boost::multi_array<int, 2> move_max(boost::extents[N + 1][4]);
	for (int i : boost::irange(0, N))
	{
		auto t = move[taka[i]];
		auto a = move[aoki[i]];
		for (auto k : boost::irange(0, 4))
		{
			taka_move[i + 1][k] = taka_move[i][k] + (t == k);
			aoki_move[i + 1][k] = aoki_move[i][k] + (a == k);
		}
	}
	for (int i : boost::irange(0, N))
	{
		move_max[i + 1][up] = std::max(taka_move[i][up] - aoki_move[i][down], -sr + 1);
		move_max[i + 1][down] = std::max(taka_move[i][down] - aoki_move[i][up], sr - H);
		move_max[i + 1][left] = std::max(taka_move[i][left] - aoki_move[i][right], -sc + 1);
		move_max[i + 1][right] = std::max(taka_move[i][right] - taka_move[i][left], sc - W);
	}
	for (int i : boost::irange(0, N))
	{
		switch (move[taka[i]])
		{
		case up:
			if (sr - move_max[i][up] <= 1)
			{
				return winner::takahashi;
			}
			break;
		case down:
			if (sr + move_max[i][down] >= H)
			{
				return winner::takahashi;
			}
			break;
		case right:
			if (sc - move_max[i][right] <= 1)
			{
				return winner::takahashi;
			}
			break;
		case left:
			if (sc + move_max[i][left] >= W)
			{
				return winner::takahashi;
			}
			break;
		}
	}
	return winner::aoki;
}

void Main()
{
	int H, W, N;
	std::cin >> H >> W >> N;
	int sr, sc;
	std::cin >> sr >> sc;
	std::string takahashi;
	std::string aoki;
	std::cin >> takahashi;
	std::cin >> aoki;
	if (run(H, W, N, sr, sc, takahashi, aoki) == winner::takahashi)
	{
		std::cout << "NO" << std::endl;
	}
	else
	{
		std::cout << "YES" << std::endl;
	}
}

int main()
{
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);
	std::cout << std::fixed << std::setprecision(15);
	Main();
}

