bool nyan(int H, int s,
          const std::vector<size_t>& S, const std::vector<size_t>& T) {

  size_t N = S.size();

  int sl = s;
  int sr = s;

  size_t m1 = -1;
  for (size_t i = 0; i < N; ++i) {
    if (S[i] == m1) {
      --sl;
    } else if (S[i] == 1) {
      ++sr;
    }
    if (sl < 0 || sr >= H) return true;

    if (T[i] == m1 && sr > 0) {
      --sr;
    } else if (T[i] == 1 && sl+1 < H) {
      ++sl;
    }
  }
  return false;
}

