    max_value['U'] = sr;
    max_value['D'] = sr;
    max_value['L'] = sc;
    max_value['R'] = sc;

    for (int i = 0; i < n; i++) {
        switch (s[i]) {
        case 'U':
            max_value[s[i]]--;
            if (max_value[s[i]] < 1)
                return "NO";
            break;
        case 'D':
            max_value[s[i]]++;
            if (max_value[s[i]] > h)
                return "NO";
            break;
        case 'L':
            max_value[s[i]]--;
            if (max_value[s[i]] < 1)
                return "NO";
            break;
        case 'R':
            max_value[s[i]]++;
            if (max_value[s[i]] > w)
                return "NO";
            break;
        }

        switch (t[i]) {
        case 'U':
            max_value['D'] = max(1, max_value['D'] - 1);
            break;
        case 'D':
            max_value['U'] = min(h, max_value['U'] + 1);
            break;
        case 'L':
            max_value['R'] = max(1, max_value['R'] - 1);
            break;
        case 'R':
            max_value['L'] = max(w, max_value['L'] + 1);
            break;
        }
    }

    return "YES";
}

