struct direction_t {
  constexpr direction_t(int y_, int x_) : y(y_), x(x_) {}
  int y;
  int x;
};
bool operator==(const direction_t& lhs, const direction_t& rhs) {
  return lhs.y == rhs.y && lhs.x == rhs.x;
}

static constexpr direction_t nothing = direction_t(0, 0);
static constexpr direction_t left = direction_t(0, -1);
static constexpr direction_t right = direction_t(0, 1);
static constexpr direction_t up = direction_t(-1, 0);
static constexpr direction_t down = direction_t(1, 0);

struct position_t {
  constexpr position_t(int y_, int x_) : y(y_), x(x_) {}

  int y;
  int x;
};

static std::string const YES = "YES";
static std::string const NO = "NO";

static std::vector<direction_t> sCandidates;
static std::vector<direction_t> tCandidates;

static std::vector<int> lefts;
static std::vector<int> rights;
static std::vector<int> ups;
static std::vector<int> downs;

static int h;
static int w;
static int n;

static int minimax(position_t position, bool turn, int moves, bool horizontal) {
  if (n * 2 - moves <= 0) {
    return -1;
  }

  int const movableIdx = n - (moves + 1) / 2;
  if (position.y - ups[movableIdx] >= 0 && position.y + downs[movableIdx] < h &&
      position.x - lefts[movableIdx] >= 0 &&
      position.x + rights[movableIdx] < w) {
    return -1;
  }

  direction_t candidate =
      turn ? sCandidates[moves / 2] : tCandidates[moves / 2];
  if (horizontal) {
    if (candidate == up || candidate == down) {
      return minimax(position, !turn, moves + 1, horizontal);
    }
  } else {
    if (candidate == left || candidate == right) {
      return minimax(position, !turn, moves + 1, horizontal);
    }
  }
  position_t const newPosition =
      position_t(position.y + candidate.y, position.x + candidate.x);
  if (newPosition.y < 0 || h <= newPosition.y || newPosition.x < 0 ||
      w <= newPosition.x) {
    if (turn) {
      return 1;
    } else {
      return minimax(position, !turn, moves + 1, horizontal);
    }
  }

  int const distance = abs(position.y - h / 2) + abs(position.x - w / 2);
  int const newDistance =
      abs(newPosition.y - h / 2) + abs(newPosition.x - w / 2);
  if (newDistance < distance) {
    if (turn) {
      if (minimax(newPosition, !turn, moves + 1, horizontal) > 0) {
        return 1;
      }
      return minimax(position, !turn, moves + 1, horizontal);
    } else {
      if (minimax(position, !turn, moves + 1, horizontal) < 0) {
        return -1;
      }
      return minimax(newPosition, !turn, moves + 1, horizontal);
    }
  } else {
    if (turn) {
      if (minimax(position, !turn, moves + 1, horizontal) > 0) {
        return 1;
      }
      return minimax(newPosition, !turn, moves + 1, horizontal);
    } else {
      if (minimax(newPosition, !turn, moves + 1, horizontal) < 0) {
        return -1;
      }
      return minimax(position, !turn, moves + 1, horizontal);
    }
  }
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> h;
  std::cin >> w;
  std::cin >> n;
  int s_r;
  std::cin >> s_r;
  s_r--;
  int s_c;
  std::cin >> s_c;
  s_c--;
  std::string s;
  std::cin >> s;
  sCandidates.reserve(n);
  lefts.reserve(n + 1);
  rights.reserve(n + 1);
  ups.reserve(n + 1);
  downs.reserve(n + 1);
  lefts.emplace_back(0);
  rights.emplace_back(0);
  ups.emplace_back(0);
  downs.emplace_back(0);
  for (int i = n - 1; i >= 0; --i) {
    char const ch = s[i];
    lefts.push_back(lefts.back());
    rights.push_back(rights.back());
    ups.push_back(ups.back());
    downs.push_back(downs.back());
    switch (ch) {
      case 'L':
        lefts.back()++;
        break;
      case 'R':
        rights.back()++;
        break;
      case 'U':
        ups.back()++;
        break;
      case 'D':
        downs.back()++;
        break;
    }
  }
  bool const leftEnabled = s_c - lefts.back() < 0;
  bool const rightEnabled = s_c + rights.back() >= w;
  bool const upEnabled = s_r - ups.back() < 0;
  bool const downEnabled = s_r + downs.back() >= h;
  for (auto const ch : s) {
    switch (ch) {
      case 'L':
        sCandidates.push_back(left);
        break;
      case 'R':
        sCandidates.push_back(right);
        rights.back()++;
        break;
      case 'U':
        sCandidates.push_back(up);
        ups.back()++;
        break;
      case 'D':
        sCandidates.push_back(down);
        downs.back()++;
        break;
    }
  }
  std::string t;
  std::cin >> t;
  tCandidates.reserve(n);
  for (auto const ch : t) {
    switch (ch) {
      case 'L':
        tCandidates.push_back(left);
        break;
      case 'R':
        tCandidates.push_back(right);
        break;
      case 'U':
        tCandidates.push_back(up);
        break;
      case 'D':
        tCandidates.push_back(down);
        break;
    }
  }
  if (leftEnabled || rightEnabled) {
    if (minimax(position_t(s_r, s_c), true, 0, true) > 0) {
      std::cout << NO << std::endl;
      return 0;
    }
  }
  if (upEnabled || downEnabled) {
    if (minimax(position_t(s_r, s_c), true, 0, false) > 0) {
      std::cout << NO << std::endl;
      return 0;
    }
  }
  std::cout << YES << std::endl;
  return 0;
}

