        if ( S[j] == 'R' )
            ++Y;
        if ( Y > W ) {
            cout << "NO";
            return;
        }
        if ( T[j] == 'L' && Y > 1 )
            --Y;
    }
    X = x, Y = y;
    for ( int j = 0; j < S.size(); ++j ) {
        if ( S[j] == 'U' )
            ++X;
        if ( X > H ) {
            cout << "NO";
