	}
	int L, R, U, D;
	L = R = sy, U = D = sx;
	for (int i = 0; i < N; i++) {
		if (S[i] == 'L') {
			L--;
		}
		if (S[i] == 'R') {
			R++;
		}
		if (S[i] == 'U') {
			U--;
		}
		if (S[i] == 'D') {
			D++;
		}
		if (L == 0 || R == W + 1 || U == 0 || D == H + 1) {
			check = false;
			break;
		}
