			R--;
			if (R <= 0) R = 1;
		}
		if (T[i] == 'R') {
			L++;
			if (L > W) L = W;
		}
		if (T[i] == 'U') {
			D--;
			if (D <= 0) D = 1;
		}
		if (T[i] == 'D') {
			U++;
			if (U > H) U = H;
		}
	}
