    map<char, int> m{{'L', L}, {'R', R}, {'U', U}, {'D', D}};
    for (int i = 0; i < N; ++i) {
        S[i] = m[S[i]];
        T[i] = m[T[i]];
    }

    if (!check_dim(W, L, R, T, S, sc)
        || !check_dim(H, U, D, T, S, sr)) {
        cout << "NO\n";
        return 0;
    }    
    cout << "YES\n";

    return 0;
}

