bool check(int pos, int n, const string &s, const string &t, const string &lr)
{
	vector<int> l(s.size() + 1), r(s.size() + 1);

	for (int i = s.size(); i >= 0; i--)
	{
		l[i] = l[i + 1];
		r[i] = r[i + 1];

		if (t[i] == lr[0])
			r[i]--;
		if (t[i] == lr[1])
			l[i]--;
		if (s[i] == lr[0])
			l[i]++;
		if (s[i] == lr[1])
			r[i]++;
	}

	int lpos = pos, rpos = pos;

	for (int i = 0; i < (int) s.size(); i++)
	{
		lpos = max(lpos, l[i]);
		rpos = min(rpos, n - r[i] - 1);

		if (rpos < lpos)
			return false;

		if (lpos != rpos)
		{
			if (s[i] == lr[0])
				rpos--;
			if (s[i] == lr[1])
				lpos++;
		}

		if (t[i] == lr[0])
			lpos--;
		if (t[i] == lr[1])
			rpos++;

		lpos = max(lpos, l[i + 1]);
		rpos = min(rpos, n - r[i + 1] - 1);

		if (rpos < lpos)
			return false;
	}

	return true;
}


