int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  auto check = [&] (
      std::vector<std::pair<int, int>> steps,
      int w, int s
    )
    -> bool
    {
      int l = 1, r = w;
      std::reverse(steps.begin(), steps.end());
      for (auto p : steps) {
        int who, dir; std::tie(who, dir) = p;
        if (who == 0) {
          if (l == r) return false;
          if (dir == 1) r--;
          else          l++;
        }
        else {
          if      (dir ==  1 && 1 < l) l--;
          else if (dir == -1 && r < w) r++;
        }
      }
      return l <= s && s <= r;
    };
  size_t h, w, n, si, sj; std::string s, t;
  std::cin >> h >> w >> n >> si >> sj >> s >> t;
  std::vector<std::pair<int, int>> hor{}, ver{};
  for (size_t i = 0; i < n; i++) {
    switch(s.at(i)) {
      case 'L' : hor.emplace_back(0, -1); break;
      case 'R' : hor.emplace_back(0, +1); break;
      case 'D' : ver.emplace_back(0, -1); break;
      case 'U' : ver.emplace_back(0, +1); break;
    }
    switch(t.at(i)) {
      case 'L' : hor.emplace_back(1, -1); break;
      case 'R' : hor.emplace_back(1, +1); break;
      case 'D' : ver.emplace_back(1, -1); break;
      case 'U' : ver.emplace_back(1, +1); break;
    }
  }
  auto ret = check(hor, w, sj) && check(ver, h, si);
  std::cout << (ret ? "Yes" : "No") << std::endl;
  return 0;
}

