    int left = 1, right = W;
    int updown = 0;
    int leftright = 0;

    for(int i=N;i>0;i--){
        if(T[i] == 'D' && up > 1 && h.at(up-1) == 1){
            up--;
            h.at(up-1) = 0;
            updown--;
        }
        else if(T[i] == 'U' && down < H && h.at(down) == 1){
            down++;
            h.at(down-1) = 0;
            updown--;
        }
        if(S[i] == 'U' && up <= down && h.at(up-1) == 0){
            h.at(up-1) = 1;
            up++;
            updown++;
        }
        else if(S[i] == 'D' && down >= up && h.at(down-1)==0){
            h.at(down-1) = 1;
            down--;
            updown++;
        }

        if(updown == H){
            break;
        }
    }


    for(int i=N;i>0;i--){
        if(T[i] == 'R' && left > 1 && w.at(left-1) == 1){
            left--;
            w.at(left-1) = 0;
            leftright--;
        }
        else if(T[i] == 'L' && right < W && w.at(right) == 1){
            right++;
            w.at(right-1) = 0;
            leftright--;
        }
        if(S[i] == 'L' && left <= right && w.at(left-1) == 0){
            w.at(left-1) = 1;
            left++;
            leftright++;
        }
        else if(S[i] == 'R' && right >= left && w.at(right-1) == 0){
            w.at(right-1) = 1;
            right--;
            leftright++;
        }
        if(leftright == W){
            break;
        }
    }

    if(h.at(sr-1) == 0 && w.at(sc-1) == 0){
        cout << "YES" << endl;
