void solve(long long H, long long W, long long N, long long s_r, long long s_c, std::string S, std::string T)
{
    //右に落としたい
    ll now = s_c;

    for (int i = 0; i < N; i++)
    {
        if (S[i] == 'R')
            now++;
        if (now > W)
        {
            cout << NO << endl;
            return;
        }
        if (T[i] == 'L' && now != 1)
        {
            now--;
        }
    }

    //左に落としたい
    now = s_c;
    for (int i = 0; i < N; i++)
    {
        if (S[i] == 'L')
            now--;
        if (now <= 0)
        {
            cout << NO << endl;
            return;
        }
        if (T[i] == 'R' && now != W)
        {
            now++;
        }
    }
    //上に落としたい
    now = s_r;

    for (int i = 0; i < N; i++)
    {
        if (S[i] == 'U')
            now--;
        if (now <= 0)
        {
            cout << NO << endl;
            return;
        }
        if (T[i] == 'D' && now != H)
        {
            now++;
        }
    }

    //下に落としたい
    now = s_r;
    for (int i = 0; i < N; i++)
    {
        if (S[i] == 'D')
            now++;
        if (now > H)
        {
            cout << NO << endl;
            return;
        }
        if (T[i] == 'U' && now != 1)
        {
            now--;
        }
    }
    cout << YES << endl;
}

