int main() {
  int h, w, n;
  scanf("%d %d %d", &h, &w, &n);
  int init_y, init_x;
  scanf("%d %d", &init_y, &init_x), --init_y, --init_x;
  string s(n, ' '); // out
  string t(n, ' '); // in
  scanf(" %s", &s[0]);
  scanf(" %s", &t[0]);

  int y0 = 0, y1 = h - 1;
  int x0 = 0, x1 = w - 1;
  for (int i = n - 1; i >= 0; --i) {
    int s_dy, s_dx;
    int t_dy, t_dx;
    auto parse_letter = [](char c) -> pair<int, int> {
      if (c == 'L') return {0, -1};
      else if (c == 'R') return {0, +1};
      else if (c == 'U') return {-1, 0};
      else if (c == 'D') return {+1, 0};
      else {
        assert(false);
        return {INT_MIN, INT_MIN};
      }
    };
    tie(s_dy, s_dx) = parse_letter(s[i]);
    tie(t_dy, t_dx) = parse_letter(t[i]);

    auto update_range = [](int &x0, int &x1, int s_dx, int t_dx, int w) {
      if (x0 > x1) return;

      auto inside = [x0, x1, s_dx, t_dx, w](int x) {
        bool can_out = false;
        for (int use_s : {0, 1}) {
          bool can_in = false;
          for (int use_t : {0, 1}) {
            if (0 <= x + use_s * s_dx && x + use_s * s_dx < w &&
                x0 <= x + use_s * s_dx + use_t * t_dx &&
                x + use_s * s_dx + use_t * t_dx <= x1) {
              can_in = true;
            }
          }
          if (!can_in) {
            can_out = true;
          }
        }
        return !can_out;
      };

      int new_x0 = x0, new_x1 = x1;
      while (new_x0 - 1 >= 0 && inside(new_x0 - 1)) --new_x0;
      while (new_x1 + 1 < w && inside(new_x1 + 1)) ++new_x1;
      while (new_x0 <= new_x1 && !inside(new_x0)) ++new_x0;
      while (new_x1 >= new_x0 && !inside(new_x1)) --new_x1;
      x0 = new_x0;
      x1 = new_x1;
    };

    update_range(y0, y1, s_dy, t_dy, h);
    update_range(x0, x1, s_dx, t_dx, w);
  }

  if (y0 <= init_y && init_y <= y1 &&
      x0 <= init_x && init_x <= x1) {
    printf("YES\n");
  } else {
    printf("NO\n");
  }

  return 0;
}

