        // if (lb >= ub) return true;
        // cerr << i << "s" << lb << " " << ub << endl;
    }
    int ll = pos, rr = pos + 1;
    for (int i : range(N)) {
        chmin(rr, ub[i][0]);
        chmax(ll, lb[i][0]);
        if (ll >= rr) {
            cerr << i << endl;
            cerr << ll << " " << rr << endl;
            return true;
        }

        if (T[i] == u) rr++;
        if (T[i] == d) ll--;
        chmin(rr, ub[i][1]);
        chmax(ll, lb[i][1]);
        if (ll >= rr) {
            cerr << i << endl;
            cerr << ll << " " << rr << endl;
            return true;
        }
        // cerr << i << " " << ll << " " << rr << endl;
    }
    return false;
    // return !(lb <= pos || pos < ub);
}
