int second_win(
    const string& s, const string& t, const char left, const char right,
    int width, int start){
    int lb = 0; int ub = width;
    for(int i = s.size() - 1; i >= 0; --i){
        if(t.at(i) == left){
            ub = min(ub+1, width);
        }else if(t.at(i) == right){
            lb = max(lb-1, 0);
        }
        if(s.at(i) == left){
            lb++;
        }else if(s.at(i) == right){
            ub--;
        }
        if(lb >= ub){ return 0; }
    }
    return (lb <= start && start < ub);
}

