		}
		if (s[i] == 'D')
		{
			d = min(d+1, h);
		}
		if (t[i] == 'L')
		{
			lc++;
		}
		if (t[i] == 'R')
		{
			rc++;
		}
		if (t[i] == 'U')
		{
			uc++;
		}
		if (t[i] == 'D')
		{
			dc++;
		}
		if (l <= rc)
		{
			l++;
		}
		if (r <= lc)
		{
			r--;
		}
		if (u <= dc)
		{
			u++;
		}
		if (d <= uc)
		{
			d--;
		}
		win &= l <= r && u <= d;
	}
