using namespace std;
const int N = 200010;
int _w;

int n, m, q, sx, sy;
char s[N], t[N];

bool solve( int pos, int lim, char dec, char inc ) {
	int tot_inc = 0;
	for( int i = 1; i <= q; ++i )
		if( s[i] == inc )
			++tot_inc;
	int now = pos;
	for( int i = 1; i <= q; ++i ) {
		if( s[i] == dec ) --now;
		else if( s[i] == inc ) --tot_inc;
		if( now == 0 ) return false;
		if( t[i] == inc && now + tot_inc + 1 <= lim )
			++now;
	}

	int tot_dec = 0;
	for( int i = 1; i <= q; ++i )
		if( s[i] == dec )
			++tot_dec;
	now = pos;
	for( int i = 1; i <= q; ++i ) {
		if( s[i] == inc ) ++now;
		else if( s[i] == dec ) --tot_dec;
		if( now == lim+1 ) return false;
		if( t[i] == dec && now - tot_dec - 1 >= 1 )
			--now;
	}
	return true;
}

