using namespace std;

long n;
char str0[200005];
char str1[200005];

bool solve( long w, long s0, char l, char r )
{
    long lim[2]={0, w+1};
    long i;
    for(i=n-1; i>=0; i--) {
        if(i<n-1) {
            if(str1[i]==l) {
                lim[1]=MIN(lim[1]+1,w+1);
            }
            if(str1[i]==r) {
                lim[0]=MAX(lim[0]-1,0);
            }
        }

        if(str0[i]==r) {
            lim[1]--;
        }
        if(str0[i]==l) {
            lim[0]++;
        }
        //printf("[%ld]%ld,%ld\n", i, lim[0],lim[1]);

        if(lim[0]+1>=lim[1]) {
            return false;
        }
        if(i==0) {
            if(s0<=lim[0] || s0>=lim[1]) {
                return false;
            }
        }
    }

    return true;
}

