  ll cntu = 0LL;
  ll cntd = 0LL;
  for (ll i = 0; i < N; i++) {
    if (S[i] == 'L') cntl++;
    if (S[i] == 'R') cntr++;
    if (S[i] == 'U') cntu++;
    if (S[i] == 'D') cntd++;
  }

  ll lon = 0LL;
  ll ron = 0LL;
  ll uon = 0LL;
  ll don = 0LL;
  if (px - cntl <  0) lon = 1;
  if (px + cntr >= W) ron = 1;
  if (py - cntu <  0) uon = 1;
  if (py + cntd >= H) don = 1;

  if (lon == 1 && ron == 1) {
    if (std::abs(px - cntl) >= std::abs(px + cntr - W)) ron = 0LL;
    else lon = 0LL;
  }

  if (uon == 1 && don == 1) {
    if (std::abs(py - cntu) >= std::abs(py + cntd - H)) don = 0LL;
    else uon = 0LL;
  }

  //print('X', 'X', "y", py, "x", px, H, W);

