  for (ll i = 0; i < N; i++) {
    if ((S[i] == 'L' && T[i] == 'R') ||
	(S[i] == 'R' && T[i] == 'L') ||
	(S[i] == 'U' && T[i] == 'D') ||
	(S[i] == 'D' && T[i] == 'U')) {
      continue;
    }

    if (S[i] == 'L') {
      if (lon == 1LL) px--;
    }
    if (S[i] == 'R') {
      if (ron == 1LL) px++;
    }
    if (S[i] == 'U') {
      if (uon == 1LL) py--;
    }
    if (S[i] == 'D') {
      if (don == 1LL) py++;
    }

    if (T[i] == 'L' || T[i] == 'R') {
      if (W % 2 == 1 && px == W / 2) continue;
    }
    if (T[i] == 'U' || T[i] == 'D') {
      if (H % 2 == 1 && px == H / 2) continue;
    }

    if (T[i] == 'L') {
      if (px >= W / 2) px--;
    }
    if (T[i] == 'R') {
      if (px < W / 2) px++;
    }
    if (T[i] == 'U') {
      if (py >= H / 2) py--;
    }
    if (T[i] == 'D') {
      if (py < H / 2) py++;
    }
    //print(S[i], T[i], "y", py, "x", px, H, W);
    if (py >= 0 && px >= 0 && py < H && px < W) continue;
    judge = false;
    break;
  }

  if (judge) print("YES");
  else print("NO");

  return 0;
