			lef = max(lef, rng[i].first);
			rig = min(rig, rng[i].second);
		}
		if (s[i] == 'R') {
			rig++;
			lef = max(lef, rng[i].first);
			rig = min(rig, rng[i].second);
		}
		if (lef > rig)return false;
	}
	return true;
