}

const int N = 200005;

int h,w,n,x,y;
int a[N],b[N];
char s[N];

int F(char c) {
	if (c=='L') return 1;
	if (c=='R') return 2;
	if (c=='U') return 3;
	return 4;
}

void move(int opt) {
	if (opt==1) y-=1;
	else if (opt==2) y+=1;
	else if (opt==3) x-=1;
	else x+=1;
}

int change(int opt) {
	int bef,aft;
	if (opt<=2) bef=min(y-1,w-y);
	else bef=min(x-1,h-x);
	move(opt);
	if (opt<=2) aft=min(y-1,w-y);
	else aft=min(x-1,h-x);
	if (opt<=2) move(3-opt);
	else move(7-opt);
	return aft-bef;
}

int main() {

	h=read(),w=read(),n=read();
	x=read(),y=read();
	scanf("%s",s+1); rep(i,1,n) a[i]=F(s[i]);
	scanf("%s",s+1); rep(i,1,n) b[i]=F(s[i]);
	rep(i,1,n) {
		if (change(a[i])<0) move(a[i]);
		if (x<1||x>h||y<1||y>w) {puts("NO"); return 0;}
		if (change(b[i])>0) move(b[i]);
	}
	puts("YES");

	return 0;

}

