ll H, W, N, sr, sc;

bool check(ll ur, ll uc, ll lr, ll lc) {
    if(!(1 <= lr && ur <= H)) return false;
    if(!(1 <= lc && uc <= W)) return false;
    return true;
}

signed main() {
    cin >> H >> W >> N >> sr >> sc;
    string S, T;
    cin >> S >> T;
    char L = 'L', R = 'R', U = 'U', D = 'D';
    ll ur = sr, uc = sc, lr = sr, lc = sc;
    FOR(i, 0, N) {
        if(S[i] == L) {
            lc--;
        }
        if(S[i] == R) {
            uc++;
        }
        if(S[i] == U) {
            lr--;
        }
        if(S[i] == D) {
            ur++;
        }
        if(!check(ur, uc, lr, lc)) {
            cout << "NO" << endl;
            return 0;
        }
        if(T[i] == L) {
            uc--;
            uc = max(uc, 1);
        }
        if(T[i] == R) {
            lc++;
            lc = min(lc, W);
        }
        if(T[i] == U) {
            ur--;
            ur = max(ur, 1);
        }
        if(T[i] == D) {
            lr++;
            lr = min(lr, H);
        }
        if(!check(ur, uc, lr, lc)) {
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
}

