bool first(int i, int sr, int sc, int fL, int fR, int fU, int fD, int sL, int sR, int sU, int sD){
    if(sr<1||sr>h||sc<1||sc>w)return false;
    if(fR-sL>w-sc||fL-sR>sc-1||fU-sD>sr-1||fD-sU>h-sr)return false;

    if(S[i]=='L'){fL--;return second(i,sr,sc-1,fL,fR,fU,fD,sL,sR,sU,sD)&&second(i,sr,sc,fL,fR,fU,fD,sL,sR,sU,sD);}
    if(S[i]=='R'){fR--;return second(i,sr,sc+1,fL,fR,fU,fD,sL,sR,sU,sD)&&second(i,sr,sc,fL,fR,fU,fD,sL,sR,sU,sD);}
    if(S[i]=='U'){fU--;return second(i,sr-1,sc,fL,fR,fU,fD,sL,sR,sU,sD)&&second(i,sr,sc,fL,fR,fU,fD,sL,sR,sU,sD);}
                  fD--;return second(i,sr+1,sc,fL,fR,fU,fD,sL,sR,sU,sD)&&second(i,sr,sc,fL,fR,fU,fD,sL,sR,sU,sD);
}

bool second(int i, int sr, int sc, int fL, int fR, int fU, int fD, int sL, int sR, int sU, int sD){
    if(sr<1||sr>h||sc<1||sc>w)return false;//out
    if(i==n-1)return true;//end
    if(fL<=sc-1&&fR<=w-sc&&fU<=sr-1&&fD<=h-sr)return true;

    if(T[i]=='L'){sL--;return first(i+1,sr,sc-1,fL,fR,fU,fD,sL,sR,sU,sD)||first(i+1,sr,sc,fL,fR,fU,fD,sL,sR,sU,sD);}
    if(T[i]=='R'){sR--;return first(i+1,sr,sc+1,fL,fR,fU,fD,sL,sR,sU,sD)||first(i+1,sr,sc,fL,fR,fU,fD,sL,sR,sU,sD);}
    if(T[i]=='U'){sU--;return first(i+1,sr-1,sc,fL,fR,fU,fD,sL,sR,sU,sD)||first(i+1,sr,sc,fL,fR,fU,fD,sL,sR,sU,sD);}
                  sD--;return first(i+1,sr+1,sc,fL,fR,fU,fD,sL,sR,sU,sD)||first(i+1,sr,sc,fL,fR,fU,fD,sL,sR,sU,sD);
}

