const int N = 100005;
int h, w, n, gx, gy;
char A[N], B[N];

bool solve(int L, int x, char l, char r) {
    int a = 0, b = L + 1;
    for (int i = n - 1; i >= 0; i--) {
        int da = A[i] == l ? -1 : (A[i] == r ? 1 : 0);
        int db = B[i] == l ? -1 : (B[i] == r ? 1 : 0);
        // f[x] = g[x] and g[x+db] or g[x+da] and g[x+da+db]
        if (db == 0) {
            if (da == 1)
                b--;
            if (da == -1)
                a++;
        }
        else {
            if (da == 0) {
                //g[x] and g[x+1]
                if (db == 1)
                    b++;
                else
                    a--;
            }
            else {
                if (db == 1 && da == 1)
                    b--;
                else if (db == -1 && da == -1)
                    a++;
            }
        }
        // printf("%d : %d %d (%d, %d)\n", i, da, db, a, b);
        a = max(a, 0);
        b = min(b, L + 1);
    }
    return x <= a || x >= b;
}

