            else if(S[0] == 'R') R[0]++;
            else L[0]++;
            continue;
        }
        switch(S[i]){
            case 'R':
                R[i] = R[i-1]+1;
                L[i] = L[i-1];
                U[i] = U[i-1];
                D[i] = D[i-1];
                break;
            case 'L':
                R[i] = R[i-1];
                L[i] = L[i-1]+1;
                U[i] = U[i-1];
                D[i] = D[i-1];
                break;
            case 'U':
                R[i] = R[i-1];
                L[i] = L[i-1];
                U[i] = U[i-1]+1;
                D[i] = D[i-1];
                break;
            case 'D':
                R[i] = R[i-1];
                L[i] = L[i-1];
                U[i] = U[i-1];
                D[i] = D[i-1]+1;
                break;
            default:
                break;
        }
    }

    vector<pair<int, int>> tate(N+1);
    vector<pair<int, int>> yoko(N+1);
    tate[0] = make_pair(sx, sx);
    yoko[0] = make_pair(sy, sy);
