string S,T;
int N;

bool fall(char for_dir, char rev_dir, int s, int size){
  int index_for=1,index_rev=size;
  int i;REP(i,N){
    int I = N-i-1;
    if(T[I] == for_dir && index_rev != size) index_rev++;
    if(T[I] == rev_dir && index_for != 1 ) index_for--;
    if(S[I] == for_dir) index_for++;
    if(S[I] == rev_dir) index_rev--;
    if(index_for > index_rev) return true;
  }
  return index_for > s || s > index_rev;
}

