ll n, w, h, sr, sc, u1[200001], d1[200001], u2[200001], d2[200001];
char s[200001], t[200001];

bool check(char up, char down, ll u, ll d) { // u or d -> ok
  for (ll i = 0; i < n; i++) {
    u1[i+1] = u1[i], d1[i+1] = d1[i], u2[i+1] = u2[i], d2[i+1] = d2[i];
    if (s[i] == up) u1[i+1]++;
    if (s[i] == down) d1[i+1]++;
    if (t[i] == up) u2[i+1]++;
    if (t[i] == down) d2[i+1]++;
  }
  ll R1 = 0, R2 = 0;
  for (ll i = 1; i <= n; i++) {
    if (u1[i] - d2[i-1] + R1 >= u) return true;
    if (d2[i] - u1[i] - R1 >= d) R1++;
    if (d1[i] - u2[i-1] + R2 >= d) return true;
    if (u2[i] - d1[i - R2] >= u) R2++;
  }
  return false;
}

