bool calc(vector<P> &vec, int s, int n)
{
	bitset<200005> bs;
	bs[0] = bs[n+1] = true;

	//for(int j = 0; j <= n+1; j++) cout << bs[j]; cout << endl;

	int N = vec.size();
	for(int i = 0; i <= N-1; i++){
		if(vec[i].first == 1){
			if(vec[i].second == 1) bs |= (bs >> 1);
			if(vec[i].second == -1) bs |= (bs << 1);
		}
		else{
			if(vec[i].second == 1) bs &= (bs >> 1);
			if(vec[i].second == -1) bs &= (bs << 1);
		}
		bs[0] = bs[n+1] = true;
		//for(int j = 0; j <= n+1; j++) cout << bs[j]; cout << endl;
	}
	cout << endl;
	return bs[s];
}

