        if (T[idx] == plus)
        {
            lower_bound--;
        }
        if (T[idx] == minus)
        {
            upper_bound++;
        }
        upper_bound = min(upper_bound, maximum);
        lower_bound = max(lower_bound, minimum);

        if (S[idx] == plus)
        {
            upper_bound--;
        }
        if (S[idx] == minus)
        {
            lower_bound++;
        }
        upper_bound = min(upper_bound, maximum);
        lower_bound = max(lower_bound, minimum);

        idx--;
    }
    if (lower_bound > start || start > upper_bound)
    {
        return false;
    }
    if (lower_bound > upper_bound)
    {
        return false;
    }
    return true;
}

