bool Solve() {
    int H, W, N;
    cin >> H >> W >> N;

    using P = pair<int, int>; // 行，列
    P s;
    cin >> s.first >> s.second;

    string S, T;
    cin >> S >> T;

    // 右に出すことが可能化?
    P cur = s;
    for (int i = 0; i < N; ++i) {
        if (S[i] == 'R') ++cur.second;
        if (W < cur.second) return false;
        if (T[i] == 'L')
            cur.second = max(1, cur.second - 1);
    }

    // 左に出すことが可能化?
    cur = s;
    for (int i = 0; i < N; ++i) {
        if (S[i] == 'L') --cur.second;
        if (cur.second < 1) return false;
        if (T[i] == 'R')
            cur.second = min(W, cur.second + 1);
    }

    // 下に出すことが可能化?
    cur = s;
    for (int i = 0; i < N; ++i) {
        if (S[i] == 'D') ++cur.first;
        if (H < cur.first) return false;
        if (T[i] == 'U')
            cur.first = max(1, cur.first - 1);
    }


    // 上に出すことが可能化?
    cur = s;
    for (int i = 0; i < N; ++i) {
        if (S[i] == 'U') --cur.first;
        if (cur.first < 1) return false;
        if (T[i] == 'D')
            cur.first = min(H, cur.first + 1);
    }

    return true;
}

