    bool operator==(const F2 &r) const { return a == r.a && b == r.b && c == r.c && d == r.d; }
    bool operator!=(const F2 &r) const { return a != r.a || b != r.b || c != r.c || d != r.d; }
    ll operator[](ll i) {assert(i < 4);return i == 0 ? a : i == 1 ? b : i == 2 ? c : d;}
