bool solve(const vector<int> &dir, const vector<int> &which,
	   const int cur, const int len) 
{
  int left = 1, right = len;
  for(int i = dir.size()-1; i >= 0; i--) {

    if(which[i] == 0) { // T
      if(dir[i] == +1) left = max(left-1, 1);
      else if(dir[i] == -1) right = min(right+1, len);
    } else { // S
      if(dir[i] == +1) right --;
      else if(dir[i] == -1) left++;
    }

#ifdef DEBUG

    cout << i << " " << dir[i] << " " << which[i] << ";" << left << " " << right << ":" ;
    cout << endl;
#endif
#ifdef DEBUG
#endif
    if(left > right) return false;
  }
  if(left > cur) return false;
  if(right < cur) return false;
  return true;
}

