  int H, W, N; cin>>H>>W>>N;
  int sr, sc; cin>>sr>>sc;
  string S, T; cin>>S>>T;
  vector<int> dir,which;
  REP(i,N) {
    switch (S[i]) {
    case 'U': dir.push_back(-1); which.push_back(1); break;
    case 'D': dir.push_back(+1); which.push_back(1); break;
    }
    switch (T[i]) {
    case 'U': dir.push_back(-1); which.push_back(0); break;
    case 'D': dir.push_back(+1); which.push_back(0); break;
    }
  }
  bool ans1 = solve(dir, which, sr, H);
  dir.clear(); which.clear();
  REP(i,N) {
    switch (S[i]) {
    case 'L': dir.push_back(-1); which.push_back(1); break;
