bool can_out(int l, int s, string a, string b, char hc, char tc){
	int head = 0, tail = l - 1;
	const int n = a.size();

	rrep(i, n){
		if(head > tail) break;

		if(b[i] == hc){
			tail++;
			chmin(tail, l - 1);
		}

		if(b[i] == tc){
			head--;
			chmax(head, 0);
		}

		if(a[i] == hc){
			head++;
			chmax(head, 0);
		}

		if(a[i] == tc){
			tail--;
			chmin(tail, l - 1);
		}
	}

	if(head <= s and s <= tail) 
		return false;
	else
		return true;
}


