			int ma = le.query(2 * i + 2, 2 * n + 1);
			int cur = le.query(2 * i + 2, 2 * i + 3);
			ma -= cur;
			if (ma < y - 1 && y>1) {
				y--;
			}
		}
	}
	cout << "YES" << endl;
