using namespace std;

int n;
string s, t;

bool simulate(int start, int wide, char left, char right) {
    int l, r;
    l = r = start;
    int can_move_L, can_move_R; //後手の補正できる回数
    can_move_L = can_move_R = 0;

    for (int i = 0; i < n; ++i) {
        //先手
        if (s[i] == right) r++;
        else if (s[i] == left) l--;
        if (l < 1 || r > wide) { //区間がはみ出た場合
            if (l < 1 && r < wide && can_move_R > 0) { //右にずらす
                l++, r++;
                can_move_R--;
            } else if (r > wide && l > 1 && can_move_L > 0) { //左にずらす
                l--, r--;
                can_move_L--;
            } else {
                return false;
            }
        }

        //後手
        if (t[i] == right) {
            if (l < r) l++;
            else can_move_R++;
        } else if (t[i] == left) {
            if (l < r) r--;
            else can_move_L++;
        }
    }
    return true;
}

int main() {
    int h, w, sr, sc;
    cin >> h >> w >> n >> sr >> sc >> s >> t;
    if (simulate(sr, h, 'U', 'D') && simulate(sc, w, 'L', 'R')) cout << "YES" << endl;
    else cout << "NO" << endl;
    return 0;
}

