struct Vector{
	ll x,y;
	Vector(ll x=0,ll y=0):x(x),y(y){}
};
Vector operator+(Vector a,Vector b){
	return Vector(a.x+b.x,a.y+b.y);
}
void operator+=(Vector &a,Vector b){
	a=a+b;
}
bool isout(Vector v){
	return v.x<0||v.x>=W||v.y<0||v.y>=H;
}
ll yoi(ll dir,char c,Vector v){
	switch(dir){
		case 0:{
			if(c=='R'){
				return 1;
			}else if(c=='L' && v.x>0){
				return -1;
			}
			break;
		}
		case 1:{
			if(c=='D'){
				return 1;
			}else if(c=='U' && v.y>0){
				return -1;
			}
			break;
		}
		case 2:{
			if(c=='L'){
				return 1;
			}else if(c=='R' && v.x<W-1){
				return -1;
			}
			break;
		}
		case 3:{
			if(c=='U'){
				return 1;
			}else if(c=='D' && v.y<H-1){
				return -1;
			}
			break;
		}
	}
	return 0;
}
