				v+=mp[S[j]];
			}
			if(isout(v)){
				ans=true;
			}
			if(yoi(i,T[j],v)==-1){
				v+=mp[T[j]];
			}
		}
	}
	cout<<(ans?"NO":"YES")<<endl;
}

