        if (T[i] == 'U') down = min(down+1, H-1);
        if (T[i] == 'D') up = max(up-1, (ll)0);
        if (S[i] == 'L') left++;
        if (S[i] == 'R') right--;
        if (S[i] == 'U') up++;
        if (S[i] == 'D') down--;
        if (left > right || up > down) {
            cout << "NO\n";
            return 0;
        }
    }

    // cout << left << " " << right << " " << up << " " << down << endl;
    if (left <= sc && sc <= right && up <= sr && sr <= down) cout << "YES\n";
    else cout << "NO\n";
}

