 int py, int x1, int y1, int x2, int y2, int allow_on_border = 1) { if (allow_on_border) { if (px >= x1 && px <= x2 && py >= y1 && py <= y2) return 1; else return 0; } else { if (px > x1 && px < x2 && py > y1 && py < y2) return 1; else return 0; } }
