			wait();
			return 0;
		}
	}

	X = X_start;
	_for(num) {
		if (cbuf[0][i] == 'L' && X - L_debt[i] > 0) --X;
		if (R_left[1][i] - L_left[0][i] > W - X + 1) {
			cout << "NO" << endl;
			wait();
			return 0;
		}
	}

	Y = Y_start;
	_for(num) {
		if (cbuf[0][i] == 'D' && Y + D_debt[i] < H - 1) ++Y;
		if (U_left[1][i] - D_left[0][i] > H - Y + 1) {
