void solve()
{
	int n = II, m = II, len = II;
	int a = II, b = II;
	string s, t;
	cin >> s >> t;

	int x = a, y = b;
	// try left
	rep(i, len) {
		if (s[i] == 'L') {
			--y;
			if (y <= 0) {
				cout << "NO";
				return;
			}
		}
		if (t[i] == 'R') {
			if (y + 1 <= m) {
				++y;
			}
		}
	}

	x = a, y = b;
	// try right
	rep(i, len) {
		if (s[i] == 'R') {
			++y;
			if (y > m) {
				cout << "NO";
				return;
			}
		}
		if (t[i] == 'L') {
			if (y - 1 > 0) {
				--y;
			}
		}
	}

	x = a, y = b;
	// try up
	rep(i, len) {
		if (s[i] == 'U') {
			--x;
			if (x <= 0) {
				cout << "NO";
				return;
			}
		}
		if (t[i] == 'D') {
			if (x + 1 <= n) {
				++x;
			}
		}
	}

	x = a, y = b;
	// try down
	rep(i, len) {
		if (s[i] == 'D') {
			++x;
			if (x > n) {
				cout << "NO";
				return;
			}
		}
		if (t[i] == 'U') {
			if (x - 1 > 0) {
				--x;
			}
		}
	}

	cout << "YES";
}

