    if(t[i]=='U') dd=min(dd+1,h+1);
    if(t[i]=='D') du=max(du-1,0);
    if(s[i]=='L') ++dl;
    if(s[i]=='R') --dr;
    if(s[i]=='U') ++du;
    if(s[i]=='D') --dd;
    if(dr-dl < 2 || dd-du < 2) break;
  }
  bool flag = du < sr && sr < dd && dl < sc && sc < dr;
  cout << (flag?"YES":"NO") << endl;
}

