using namespace std;

int solve(vector<int> f, vector<int> s, int st, int len) {
    // cerr << "solve " << len << ' ' << st << endl;
    // for (auto t : f) {
    //     cerr << t << ' ';
    // }
    // cerr << endl;
    // for (auto t : s) {
    //     cerr << t << ' ';
    // }
    // cerr << endl;
    int n = (int)f.size();
    auto can_l = [&](int x) {
        int cp = x;
        for (int i = 0; i < n; i++) {
            if (f[i] == -1) {
                cp--;
                if (cp < 0) return true;
            }
            if (s[i] == 1) {
                cp++;
                cp = min(cp, len - 1);
            }
        }
        return false;
    };
    auto can_r = [&](int x) {
        int cp = x;
        for (int i = 0; i < n; i++) {
            if (f[i] == 1) {
                cp++;
                if (cp >= len) return true;
            }
            if (s[i] == -1) {
                cp--;
                cp = max(cp, 0);
            }
        }
        return false;
    };
    cerr << can_l(st) << ' ' << can_r(st) << endl;  
    return can_l(st) || can_r(st);
}

