int l1,l2,n,p1,p2;
string a,b;

bool licz(char sub, char add,int gd, int dl){
  int po = 0, ko = dl;
  for(int i = n - 1; i >= 0; i--){
    if(b[i] == add){
      po = max(po-1, 0ll);
    }else if(b[i] == sub){
      ko = min(ko + 1, dl);
    }

    if(a[i] == sub){
      po++;
    }else if(a[i] == add){
      ko--;
    }
    if(po >= ko)return 0;
  }
  gd--;
  return po <= gd && gd < ko;
}

