        if(!bt && (s[i] == pos || s[i] == neg))
        {
            if(s[i] == pos)
                pc++;
            else if(s[i] == neg)
                nc++;
        }
    }

    if(!bt)
    {
        lmx -= pc;
        lmn += nc;

        if(lmn > lmx)
            return false;
    }

    return lmn <= cr && cr <= lmx;
