    if(S[i]=='L') left_out_lim++;
    if(S[i]=='R') right_out_lim--; 
    if (left_out_lim>=right_out_lim) ans=false;
  }

  if (S[N-1]=='U') upper_out_lim++;
  if(S[N-1]=='D') lower_out_lim--;

  for (int i=N-2;i>=0;--i){
    if(T[i]=='D') upper_out_lim=max(upper_out_lim-1,0);
    if(T[i]=='U') lower_out_lim=min(lower_out_lim+1,H);

    if(S[i]=='U') upper_out_lim++;
    if(S[i]=='D') lower_out_lim--;
    if(upper_out_lim>=lower_out_lim) ans=false;
  }

  if(left_out_lim>=c|| right_out_lim<=c) ans=false;
  if(upper_out_lim>=r|| lower_out_lim<=r) ans=false;

  if(ans) cout << "YES" << endl;
  else cout << "NO" << endl;
  return 0;
}

