			CASE( 'U' ){
				b= std::min( b +1, H -1 );
			}
			CASE( 'D' ){
				t= std::max( t -1, 0 );
			}
			CASE( 'L' ){
				r= std::min( r +1, W -1 );
			}
			CASE( 'R' ){
				l= std::max( l -1, 0 );
			}
		}

		//	S
		switch( S[i] ){
			CASE( 'U' ){
				t++;
				if( t < b ) return false;
			}
			CASE( 'D' ){
				b--;
				if( t < b ) return false;
			}
			CASE( 'L' ){
				l++;
				if( r < l ) return false;
			}
			CASE( 'R' ){
				r--;
				if( r < l ) return false;
			}
		}
	}

	return l <= X && X <= r && t <= Y && Y <= b;
}
int main(){
	int W, H, N, X, Y;
	cin>> H>> W>> N>> Y>> X>> S>> T;

	cout<< ( check( W, H, N, X -1, Y -1 ) ? "YES" : "NO" )<< endl;

	return 0;
}

