		if (dt[i] == 1) L = max(L - 1, 1);
		if (dt[i] == -1) R = min(R + 1, n);

		if (ds[i] == 1) R--;
		if (ds[i] == -1) L++;

		if (L > R) return false;
	}

	return L <= x && x <= R;
}

