bool f(ll sx, ll w, char back, char next) {
  ll ngl = sx, ngr = sx;
  bool ok = true;
  for (int i = 0; i < n; i++) {
    if (s[i] == next) {
      ngr += 1;
    } else if (s[i] == back) {
      ngl -= 1;
    }
    if (ngr > w || ngl < 1) {
      ok = false;
    }
    if (t[i] == next) {
      ngl += 1;
    } else if (t[i] == back) {
      ngr -= 1;
    }
    ngr = max(ngr, 1LL);
    ngl = min(ngl, w);
    if (ngr > w || ngl < 1) {
      ok = false;
    }
  }
  return ok;
}

