int calc_row_min_dist(int x) {
    return min(x,h+1-x);
}

int calc_col_min_dist(int y) {
    return min(y, w+1-y);
}

bool is_in_box(int x, int y) {
    return (x >= 1 && x <= h && y >= 1 && y <= w);
}

map<char,pair<int,int>> moves;

void solve() {
    moves.insert({'L', {0,-1}});
