            int y = c + moves[move].second;
            int d=0,possible_d=0;

            if (move == 'L' || move == 'R') {
                d = calc_col_min_dist(c);
                possible_d = calc_col_min_dist(y);
                if (turn == 0) {
                    if (possible_d < d) {
                        c = y;
                    }
                } else {
                    if (possible_d > d) {
                        c = y;
                    }
                }
            } else {
                d = calc_row_min_dist(r);
                possible_d = calc_row_min_dist(x);
                if (turn == 0) {
                    if (possible_d < d) {
                        r = x;
                    }
                } else {
                    if (possible_d > d) {
                        r = x;
