bool dfs_S(int H, int W, int sr, int sc, string& S, string& T, int ith, bool pass);
bool dfs_T(int H, int W, int sr, int sc, string& S, string& T, int ith, bool pass);

bool dfs_S(int H, int W, int sr, int sc, string& S, string& T, int ith, bool pass){
    if(ith >= S.size()) return false;

    if(sr==0   && S[ith]=='U') return true;
    if(sr==H-1 && S[ith]=='D') return true;
    if(sc==0   && S[ith]=='L') return true;
    if(sc==W-1 && S[ith]=='R') return true;

    if(!dfs_T(H,W,sr,sc,S,T,ith,true)) return true;

    if     (S[ith]=='U') sr--;
    else if(S[ith]=='D') sr++;
    else if(S[ith]=='L') sc--;
    else if(S[ith]=='R') sc++;
    else abort();
    if(!dfs_T(H,W,sr,sc,S,T,ith,false)) return true;

    return false;
}

bool dfs_T(int H, int W, int sr, int sc, string& S, string& T, int ith, bool pass){
    if(ith >= S.size()) return true;

    if(!dfs_S(H,W,sr,sc,S,T,ith+1,true)) return true;

    if     (T[ith]=='U' && sr!=0)   sr--;
    else if(T[ith]=='D' && sr!=H-1) sr++;
    else if(T[ith]=='L' && sc!=0)   sc--;
    else if(T[ith]=='R' && sc!=W-1) sc++;
    else return false;
    if(!dfs_S(H,W,sr,sc,S,T,ith+1,false)) return true;

    return false;
}

