    scanf("%d%d", &gx, &gy);
    scanf("%s", &A);
    scanf("%s", &B);
    if (solve(h, gx, 'D', 'U') || solve(w, gy, 'L', 'R'))
        cout << "NO" << endl;
    else 
        cout << "YES" << endl;
    return 0;
}

