        } else if (s[i] == 'L') {
            ++l;
        } else if (s[i] == 'R' && t[i] == 'L') {
            if (r == m - 1) --r;
        } else if (s[i] == 'R' && t[i] == 'R') {
            --l;
            --r;
        } else if (s[i] == 'R') {
            --r;
        } else if (t[i] == 'L') {
            ++r;
        } else if (t[i] == 'R') {
            --l;
        }

        if (l > m - 1 || r < 0 || l > r)
            return true;

        l = max(0, l);
        r = min(m - 1, r);
    }

    return !(l <= y && y <= r);
}

bool lose_ud() {
    int l = 0, r = n - 1;

    for (int i = 0; i < q; ++i)
        s[i] = (s[i] == 'L' ? 'U' : (s[i] == 'R' ? 'D' : (s[i] == 'U' ? 'L' : 'R')));

    for (int i = q - 1; i >= 0; --i) {
        if (s[i] == 'L' && t[i] == 'L') {
            ++l;
            ++r;
        } else if (s[i] == 'L' && t[i] == 'R') {
            if (l == 0) ++l;
        } else if (s[i] == 'L') {
            ++l;
        } else if (s[i] == 'R' && t[i] == 'L') {
            if (r == m - 1) --r;
        } else if (s[i] == 'R' && t[i] == 'R') {
            --l;
            --r;
        } else if (s[i] == 'R') {
            --r;
        } else if (t[i] == 'L') {
            ++r;
        } else if (t[i] == 'R') {
            --l;
        }

        if (l > n - 1 || r < 0 || l > r)
            return true;

        l = max(0, l);
        r = min(n - 1, r);
    }

    return !(l <= x && x <= r);
}

