        }
        if (SrcntR[i-1]-TrcntL[i-1]>=restR-cntR[i] and t[i] == 'L')cntR[i]--;
    }
    for (int i = 1; i <= N; ++i) {
        cntD[i] = cntD[i - 1];

        if (s[i] == 'D')cntD[i]++;
        if(restD<=cntD[i]){
            puts("NO");
            return 0;
        }

        if (SrcntD[i-1]-TrcntU[i-1]>=restD-cntD[i] and t[i] == 'U')cntD[i]--;
