  for(ll i=0;i<N;i++){
    if(S[i]=='L') x--;
    if(x==0){
      flag = false;
    }
    if(T[i]=='R' && x<=W-1) x++;
  }

  ll y=sc;
  //上に落としたい
  for(ll i=0;i<N;i++){
    if(S[i]=='U') y++;
    if(y==H+1){
      flag = false;
    }
    if(T[i]=='D' && y>=2) y--;
  }
  //下に落としたい
  y=sc;
  for(ll i=0;i<N;i++){
    if(S[i]=='D') y--;
    if(y==0){
      flag = false;
    }
    if(T[i]=='U' && y<=H-1) y++;
  }

  cout << (flag?"YES":"NO") << endl;
}

