std::pair<std::vector<int>, std::vector<int>> prime_factor_decomp(int n) {
    std::vector<int> p, e;
    int m = n;
    for (int i = 2; i * i <= n; i++) {
        if (m % i != 0) continue;
        int c = 0;
        while (m % i == 0) c++, m /= i;
        p.push_back(i);
        e.push_back(c);
    }
    if (m > 1) {
        p.push_back(m);
        e.push_back(1);
    }
    return std::make_pair(p, e);
}

