bool isStableX()
{
    int lhs = 0, rhs = W - 1;

    rep (i, N)
    {
        const auto a = A[N - i - 1];
        const auto b = B[N - i - 1];

        if (b == 'L') { rhs = min(rhs + 1, W - 1); }
        if (b == 'R') { lhs = max(lhs - 1, 0); }

        if (a == 'L') { lhs += 1; }
        if (a == 'R') { rhs -= 1; }

        if (lhs > rhs) { return false; }
    }

    return lhs <= X && X <= rhs;
}

bool isStableY()
{
    int lhs = 0, rhs = H - 1;

    rep (i, N)
    {
        const auto a = A[N - i - 1];
        const auto b = B[N - i - 1];

