        if (b == 'D') { lhs = max(lhs - 1, 0); }

        if (a == 'U') { lhs += 1; }
        if (a == 'D') { rhs -= 1; }

        if (lhs > rhs) { return false; }
    }

    return lhs <= Y && Y <= rhs;
}

