using namespace std;

class BLRUDGame {
	class Solver {
		io::input_reader in;
		io::output_writer out;

	public:
		Solver(std::istream &in, std::ostream &out) : in(in), out(out) {}

		bool solve(int len, char left, char right, int loc, string &s, string &t) {
			fori(i, s.size()) {
				if (s[i] == right) loc++;
				if (loc >= len) return false;
				if (t[i] == left) loc--;
				loc = max(0, loc);
			}
			return true;
		}

		void solve() {
			int h, w, n;
			int s_r, s_c;
			string s, t;
			in.read(h, w, n, s_r, s_c, s, t);
			s_r--, s_c--;
			if (solve(w, 'L', 'R', s_r, s, t) &&
				solve(w, 'R', 'L', w - 1 - s_r, s, t) &&
				solve(h, 'D', 'U', s_c, s, t) &&
				solve(h, 'U', 'D', h - 1 - s_c, s, t)
					)
				out << "YES";
			else
				out << "NO";
		}
	};

public:
	void solve(std::istream &in, std::ostream &out) {
		Solver(in, out).solve();
	}
};

int main() {
	std::ios_base::sync_with_stdio(false), cin.tie(0);
	BLRUDGame solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

