const int N = 2e5+23;

int s[N], t[N];

void solve() {
  int h, w, n; scanf("%d%d%d", &h, &w, &n);
  int sr, sc; scanf("%d%d", &sr, &sc);
  int x[4] = {sc-1, w-sc, sr-1, h-sr};
  for (int i = 0; i < n; ++i) {
    scanf(" %c", s+i);
    if (s[i] == 'L') s[i] = 0;
    else if (s[i] == 'R') s[i] = 1;
    else if (s[i] == 'U') s[i] = 2;
    else s[i] = 3;
  }
  for (int i = 0; i < n; ++i) {
    scanf(" %c", t+i);
    if (t[i] == 'L') t[i] = 0;
    else if (t[i] == 'R') t[i] = 1;
    else if (t[i] == 'U') t[i] = 2;
    else t[i] = 3;
  }
  int z[4] = {};
  int y[4] = {};
  int pos = 0;
  queue<int> q;
  for (int i = 0; i < n; ++i) {
    ++z[s[i]];
    if (z[s[i]] <= x[s[i]]) continue;
    int other = s[i]+1;      
    if (s[i]%2) {
      other = s[i]-1;
    }
    q.push(other);
    bool found = false;
    for (; pos < i; ++pos) {
      if (q.front() == pos) {
	--y[s[q.front()]];
	q.pop();
      }
      if (t[pos] != other) continue;
      found = true;
      break;
    }
    if (y[t[pos]] == x[t[pos]]) {
      found = false;
    }
    if (!found) {
      puts("NO");
      return;
    }
    ++y[t[pos]];
    --z[s[i]];
  }
  puts("YES");
}

int main() {
  int t = 1; //scanf("%d", &t);
  while (t--) {
    solve();
  }
  return 0;
}

