#define FORR(i, a, b) for (int i = (int)(b) - 1; i >= (a); i--)

using namespace std;

string fliphw(string s) {
  for (int i = 0; i < s.size(); i++) {
    if (s[i] == 'L') {
      s[i] = 'U';
    } else if (s[i] == 'R') {
      s[i] = 'D';
    } else if (s[i] == 'U') {
      s[i] = 'L';
    } else {
      s[i] = 'R';
    }
  }
  return s;
}

bool solve() {
  int H, W, N;
  cin >> H >> W >> N;
  int sy, sx;
  cin >> sy >> sx;
  string S, T;
  cin >> S >> T;
  for (int ii = 0; ii < 2; ii++) {
    int dpl = 0;
    int dpr = W+1;
    REPR(i, N) {
      if (dpl + 1 >= dpr) { dpl++; break; }
      if (S[i] == 'L' && T[i] == 'L') {
        // (dp[j-1]&dp[j-2]) | (dp[j]&dp[j-1])
        dpl++;
        dpr++;
      } else if (S[i] == 'L' && T[i] == 'R') {
        // (dp[j-1]&dp[j]) | (dp[j]&dp[j+1])
        dpl = max(dpl, 1);
      } else if (S[i] == 'R' && T[i] == 'L') {
        // (dp[j+1]&dp[j]) | (dp[j-1]&dp[j])
        dpr = min(dpr, W);
      } else if (S[i] == 'R' && T[i] == 'R') {
        // (dp[j+2]&dp[j+1]) | (dp[j]&dp[j+1])
        dpl--;
        dpr--;
      } else if (S[i] == 'L') {
        // dp[j] | dp[j-1]
        dpl++;
      } else if (S[i] == 'R') {
        // dp[j] | dp[j+1]
        dpr--;
      } else if (T[i] == 'L') {
        // dp[j]&dp[j-1]
        dpr++;
      } else if (T[i] == 'R') {
        // dp[j]&dp[j+1]
        dpl--;
      }
      dpl = max(dpl, 0);
      dpr = min(dpr, W+1);
      if (dpl >= dpr) break;
    }
    if (sx <= dpl || sx >= dpr) return false;
    swap(H, W);
    swap(sy, sx);
    S = fliphw(S);
    T = fliphw(T);
  }
  return true;
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << (solve() ? "YES" : "NO") << '\n';
}

