void update(int& l, int& r, char c, char cl, char cr, int turn, int ma) {
	if (turn == 0) {
		if (c == cl)l++;
		if (c == cr)r--;
	}
	else {
		if (c == cl)r++;
		if (c == cr)l--;
	}
	l = min(max(l, 0), ma);
	r = min(max(r, 0), ma);
}

