int minmax(int i, int j, int step_i) {
    printf("minmax(%d,%d,%d)\n", i, j, step_i);
    if(step_i % 2 == 0) {
        int ii = i, jj = j;
        switch(takahashi[step_i/2]) {
            case 'U':
                ++ii;
                if(ii == h) return 1;
            case 'D':
                --ii;
                if(ii == -1) return 1;
            case 'L':
                ++jj;
                if(jj == w) return 1;
            case 'R':
                --jj;
                if(jj == -1) return 1;
            default:
                break;
        }
        if(step_i != 2*n-2) {
            if(minmax(ii, jj, step_i+1)) return 1;
            if(minmax(i, jj, step_i+1)) return 1;
        }
    }
    if(step_i % 2  == 1 && step_i != 2*n-2) {
        int ii = i, jj = j;
        bool out = false;
        switch(aoki[step_i/2]) {
            case 'U':
                ++ii;
                if(ii == h) out = true;
            case 'D':
                --ii;
                if(ii == -1) out = true;
            case 'L':
                ++jj;
                if(jj == w) out = true;
            case 'R':
                --jj;
                if(jj == -1) out = true;
            default:
                break;
        }
        if(!out) {
            if(!minmax(ii, jj, step_i+1)) return 0;
        }
        if(!minmax(i, jj, step_i+1)) return 0;
    }
    return 0;
}

int dirchar_to_idx(char dirchar) {
    if(dirchar == 'U') return 0;
    if(dirchar == 'D') return 1;
    if(dirchar == 'L') return 2;
    return 3;
}

int main() {
    cin >> h >> w >> n;
    int sr, sc;
    cin >> sr >> sc;
    --sr; --sc;
    cin >> takahashi;
    cin >> aoki;

    vector<vector<int>> counts_takahashi(n+1, vector<int>(4, 0)), counts_aoki(n+1, vector<int>(4, 0));
    for(int i=0;i<n;++i) {
        int t_idx = dirchar_to_idx(takahashi[i]);
        int a_idx  = dirchar_to_idx(aoki[i]);
        ++counts_takahashi[i+1][t_idx];
        ++counts_aoki[i+1][a_idx];
        for(int j=0;j<4;++j) {
            counts_takahashi[i+1][j] += counts_takahashi[i][j];
            counts_aoki[i+1][j] += counts_aoki[i][j];
        }
        counts_aoki[i+1][0] = min(sr + counts_takahashi[i+1][1], counts_aoki[i+1][0]);
        counts_aoki[i+1][1] = min(h-1 - (sr + counts_takahashi[i+1][0]), counts_aoki[i+1][1]);
        counts_aoki[i+1][2] = min(sc + counts_takahashi[i+1][3], counts_aoki[i+1][2]);
        counts_aoki[i+1][3] = min(w-1 - (sc + counts_takahashi[i+1][2]), counts_aoki[i+1][3]);
    }

    bool ans = true;
    for(int i=1;i<=n;++i) {
        if(sr - counts_takahashi[i][0] + counts_aoki[i-1][1] < 0) {
            ans = false;
            cerr << i << " U" << endl;
            break;
        }
        if(sr + counts_takahashi[i][1] - counts_aoki[i-1][0] >= h) {
            ans = false;
            cerr << i << " D" << endl;
            break;
        }
        if(sc - counts_takahashi[i][2] + counts_aoki[i-1][3] < 0) {
            ans = false;
            cerr << i << " L" << endl;
            break;
        }
        if(sc + counts_takahashi[i][3] - counts_aoki[i-1][2] >= w) {
            ans = false;
            break;
        }

    }

    cout << (ans?"YES\n":"NO\n");
}

