bool can_drop(int h, int w, int lx, int rx, int uy, int dy) {
    if (lx >= w || rx <= 1 || rx <= lx) return true;
    if (uy >= h || dy <= 1 || dy <= uy) return true;
    return false;
}

int main(int argc, char** argv) {
    int h, w, n;
    cin >> h >> w >> n;
    int sx, sy;
    cin >> sy >> sx;
    std::string c1, c2;
    cin >> c1 >> c2;

    int lx{1}, rx{w}, uy{1}, dy{h};

    for (auto it_1 = c1.rbegin(), it_2 = c2.rbegin();
         it_1 != c1.rend() && it_2 != c2.rend();
         ++it_1, ++it_2) {
        switch(*it_2) {
        case 'L':
            if (rx < w)
                ++rx;
            break;
        case 'R':
            if (lx > 1)
                --lx;
            break;
        case 'U':
            if (dy < h)
                ++dy;
            break;
        case 'D':
            if (uy > 1)
                --uy;
            break;
        }

        switch(*it_1) {
        case 'L':
            if (lx < w)
                ++lx;
            break;
        case 'R':
            if (rx < 1)
                --rx;
            break;
        case 'U':
            if (uy < h)
                ++uy;
            break;
        case 'D':
            if (dy > 1)
                --dy;
            break;
        }
        if (can_drop(h, w, lx, rx, uy, dy)) {
            cout << "YES" << endl;
            return 0;
        }
    }
    // << lx << " " << rx << " " << uy << " " << dy << endl;
    cout << (((sx <= lx || rx <= sx) && (sy <= uy || dy <= sy)) ? "YES": "NO") << endl;

    return 0;
}

