#include <bits/stdc++.h>
using namespace std;

const int U = 0;
const int L = 1;
const int D = 2;
const int R = 3;

int H, W, N ;
int sr, sc  ;
string _S, _T ;
vector<int> S, T;

bool isin(int r, int c){
  return 0 <= r && r < H && 0 <= c && c < W;
}

bool solve(){
  // Left
  {
    int r = sr, c = sc;
    for(int i = 0; i < N; i++){
      if(S[i] == L){
        c--;
      }
      if(isin(r, c) == false) return true;
      if(T[i] == R){
        int nr = r, nc = c + 1;
        if(isin(nr, nc)){
          r = nr;
          c = nc;
        }
      }
    }
  }

  // Right
  {
    int r = sr, c = sc;
    for(int i = 0; i < N; i++){
      if(S[i] == R){
        c++;
      }
      if(isin(r, c) == false) return true;
      if(T[i] == L){
        int nr = r, nc = c - 1;
        if(isin(nr, nc)){
          r = nr;
          c = nc;
        }
      }
    }
  }


  // Up
  {
    int r = sr, c = sc;
    for(int i = 0; i < N; i++){
      if(S[i] == U){
        r--;
      }
      if(isin(r, c) == false) return true;
      if(T[i] == D){
        int nr = r + 1, nc = c;
        if(isin(nr, nc)){
          r = nr;
          c = nc;
        }
      }
    }
  }

  // Down
  {
    int r = sr, c = sc;
    for(int i = 0; i < N; i++){
      if(S[i] == D){
        r++;
      }
      if(isin(r, c) == false) return true;
      if(T[i] == U){
        int nr = r - 1, nc = c;
        if(isin(nr, nc)){
          r = nr;
          c = nc;
        }
      }
    }
  }
  return false;
}

int main(void){
  cin >> H >> W >> N ; 
  cin >> sr >> sc    ; 
  cin >> _S >> _T      ; 
  sr--; sc--;
  S.resize(N); T.resize(N);

  for(int i = 0; i < N; i++){
    if( _S[i] == 'U') S[i] = U;
    else if(_S[i] == 'L') S[i] = L;
    else if(_S[i] == 'D') S[i] = D;
    else if(_S[i] == 'R') S[i] = R;

    if( _T[i] == 'U') T[i] = U;
    else if(_T[i] == 'L') T[i] = L;
    else if(_T[i] == 'D') T[i] = D;
    else if(_T[i] == 'R') T[i] = R;
  }


  if(solve() == true){
    cout << "NO" << endl;
    return 0;
  }

  cout << "YES" << endl;
  return 0;
}

