//上下左右は独立して考える
//必要十分条件を考える
//iターン目の先手が手を打った直後に[l,r]にロボットが存在するためには
//s[i]==Lなら[l+1,r]にロボットが存在する必要がある
//s[i]=Rなら[l,r-1]にロボットが存在している必要がある
//さらにiターン目の後手が手を打った直後に[l,r]にロボットが存在するようにするためには
//t[i]=Lなら[l,min(r+1,w-1)]にロボットが存在すること
//t[i]=Rなら[max(0,l-1),r]にロボットが存在すること
//とも言える
int main() {
	int H, W, N; cin >> H >> W >> N;
	int sr, sc; cin >> sr >> sc;
	sr -- ; sc--;
	string S, T; cin >> S >> T;
	int L = 0;
	int R = W - 1;
	int U = 0;
	int D = H - 1;
	for (int i = N-1; i >=0; --i) {
		if (T[i] == 'R') {
			L = max(0, L - 1);
		}
		else if (T[i] == 'L') {
			R = min(W - 1, R + 1);
		}
		else if (T[i] == 'D') {
			U = max(0, U - 1);
		}
		else {
			D = min(H - 1, D + 1);
		}

		if (S[i] == 'R') {
			R -= 1;
		}
		else if(S[i]=='L'){
			L += 1;
		}
		else if (S[i] == 'D') {
			D -= 1;
		}
		else {
			U += 1;
		}
		if (R < 0 || L >= W || U >= H || W < 0) {
			cout << "NO" << endl;
			return 0;
		}
	}
	if (L <= sc && sc <= R && U <= sr && sr <= D) {
		cout << "YES" << endl;
	}
	else {
		cout << "NO" << endl;
	}
	return 0;
}

