        }
        if (A.length() < 0 || B.length() < 0) res = 1;
        if (S1[i] == 'R') {
            B.right--;
        } else if (S1[i] == 'L') {
            B.left++;
        } else if (S1[i] == 'D') {
            A.right--;
        } else if (S1[i] == 'U') {
            A.left++;
        }
        if (A.length() < 0 || B.length() < 0) res = 1;
    }
    if (!(A >= Range(X, X))|| !(B >= Range(Y, Y))) res = 1;
