    if (D0 && U1) {
      D0 --;
      U1 --;
    }

    L1 = std::min(L1, sc - 1);
    R1 = std::min(R1, W - sc);
    U1 = std::min(U1, sr - 1);
    D1 = std::min(D1, H - sr);
  }

  std::cout << "YES" << std::endl;

  return 0;
}

