map<char, pii> mp = {
  {'U', {-1, 0}},
  {'D', {1, 0}},
  {'R', {0, 1}},
  {'L', {0, -1}},
};

bool check(int y, int x) {
  return y >= 1 and y <= H and x >= 1 and x <= W;
}

bool dfs(int idx, int y, int x) {
  if (check(y, x) == false) {
    return false;
  }

  // 最後まできたらコマは残ってる
  if (idx >= g.size()) {
    return true;
  }

  if (idx % 2 == 0) {
    // 一つでもfalseがあってほしい
    bool ret = true;
    int ny = y + mp[g[idx]].first;
    int nx = x + mp[g[idx]].second;
    ret &= dfs(idx + 1, ny, nx);

    return ret;
  } else {
    // 1つでもtrueがあってほしい
    bool ret = false;
    int ny = y + mp[g[idx]].first;
    int nx = x + mp[g[idx]].second;
    ret |= dfs(idx + 1, ny, nx);

    return ret;
  }
}

