  REP(i,N) {
    switch (S[i]) {
    case 'L': sw[i]=-1; break;
    case 'R': sw[i]=+1; break;
    case 'U': sh[i]=-1; break;
    case 'D': sh[i]=+1; break;
    }
    switch (T[i]) {
    case 'L': tw[i]=-1; break;
    case 'R': tw[i]=+1; break;
    case 'U': th[i]=-1; break;
    case 'D': th[i]=+1; break;
    }

  }
  bool ans1 = solve(N, sh, th, sr, H);
  bool ans2 = solve(N, sw, tw, sc, W);
