    int H, W, N, sr, sc;
    string S, T;
    cin >> H >> W >> N >> sr >> sc >> S >> T;

    auto func = [&](char mi, char ma, int pos, int siz) -> bool {
        int posmi = pos, posma = pos;
        for (int i = 0; i < N; ++i) {
            if (S[i] == ma)
                posma++;
            else if (S[i] == mi)
                posmi--;
            if (posma > siz)
                return true;
            if (posmi < 1)
                return true;
            if (T[i] == ma)
                posmi = min(posmi + 1, siz);
            else if (T[i] == mi)
                posma = max(posma - 1, 1);
            if (posma > siz)
                return true;
            if (posmi < 1)
                return true;
        }
        return false;
    };

    bool res = false;
    res |= func('U', 'D', sr, H);
    res |= func('L', 'R', sc, W);

    cout << (res ? "NO" : "YES") << endl;

    return 0;
}

