int solve(int sx, string &S, string &T, int W, int dir) {

    int p = sx;
    int N = S.size();

    // left
    p = sx;
    for (int i = 0; i < N; i++) {
        if (dir == 0) {
            if (S[i] == 'L') p--;
            if (p < 0) return 0;
            if (p + 1 < W && T[i] == 'R') p++;
        } else {
            if (S[i] == 'U') p--;
            if (p < 0) return 0;
            if (p + 1 < W && T[i] == 'D') p++;
        }
    }

    // right
    p = sx;
    for (int i = 0; i < N; i++) {
        if (dir == 0) {
            if (S[i] == 'R') p++;
            if (p >= W) return 0;
            if (p - 1 >= 0 && T[i] == 'L') p--;
        } else {
            if (S[i] == 'D') p++;
            if (p >= W) return 0;
            if (p - 1 >= 0 && T[i] == 'U') p--;
        }
    }

    return 1;
}

void solve() {
    int H, W, N;
    cin >> H >> W >> N;
    int sy, sx;
    cin >> sy >> sx;
    sy--, sx--;
    string S, T;
    cin >> S >> T;
    int r1 = solve(sx, S, T, W, 0);
    int r2 = solve(sy, S, T, H, 1);

    if (r1 && r2) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
}

