    cin.tie(0);
    ios::sync_with_stdio(false);
    ll h, w, n; cin >> h >> w >> n;
    ll sr, sc; cin >> sr >> sc;
    string s, t; cin >> s >> t;
    ll score = sr * sc * (w - sc + 1) * (h - sr + 1);
    ll pos = 0;
    pair<P, P> now = {{sr, sc}, {w - sc + 1, h - sr + 1}};
    bool isOut = false;
    while(pos < n)
    {
        pair<P, P> tmp = now;
        ll score = now.first.first * now.first.second * now.second.first * now.second.second;
        if(s[pos] == 'U')
        {
            tmp.first.first--;
            tmp.second.second++;
        }
        if(s[pos] == 'L')
        {
            tmp.first.second--;
            tmp.second.first++;
        }
        if(s[pos] == 'R')
        {
            tmp.first.second++;
            tmp.second.first--;
        }
        if(s[pos] == 'D')
        {
            tmp.first.first++;
            tmp.second.second--;
        }
        ll next_score = tmp.first.first * tmp.first.second * tmp.second.first * tmp.second.second;
        if(next_score < score)
        {
            now = tmp;
            score = next_score;
        }
        if(score == 0) isOut = true;
        //----------------------------------------------
        tmp = now;
        if(t[pos] == 'U')
        {
            tmp.first.first--;
            tmp.second.second++;
        }
        if(t[pos] == 'L')
        {
            tmp.first.second--;
            tmp.second.first++;
        }
        if(t[pos] == 'R')
        {
            tmp.first.second++;
            tmp.second.first--;
        }
        if(t[pos] == 'D')
        {
            tmp.first.first++;
            tmp.second.second--;
        }
        next_score = tmp.first.first * tmp.first.second * tmp.second.first * tmp.second.second;
        if(next_score > score)
        {
            now = tmp;
            score = next_score;
        }
        if(score == 0) isOut = true;
        pos++;
    }
    if(isOut) cout << "NO" << endl;
    else cout << "YES" << endl;
    return 0;
}

