            --r;
        } else if (s[i] == 'R') {
            --r;
        } else if (t[i] == 'L') {
            ++r;
        } else if (t[i] == 'R') {
            --l;
        }

        if (l > m - 1 || r < 0 || l > r)
            return true;

        l = max(0, l);
        r = min(m - 1, r);
    }

    return !(l <= x && x <= r);
}

void solve() {
    --x, --y;

    if (lose_lr() || lose_ud())
        cout << "NO\n";
    else
        cout << "YES\n";
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

