void sub(int k, int c) {
	if (c) {
		if (k == 0) --bi;
		if (k == 1) --bj;
		if (k == 2) ++ai;
		if (k == 3) ++aj;
	} else {
		if (k == 0) --ai;
		if (k == 1) --aj;
		if (k == 2) ++bi;
		if (k == 3) ++bj;
	}
	ai = max(0, ai);
	aj = max(0, aj);
	bi = min(H, bi);
	bj = min(W, bj);
}

