bool can_drop( ll w, ll sc, char L, char R, string s, string t ){
	int len = s.size();
	int pos = sc-1;
	int l = 0;
	int r = w;

	// posが[l,r) にあるなら駒が残る
	for ( int i = len-1; i >= 0; i-- ){
		// 後手 許容範囲を広げる
		if ( t[i] == R && 0 < l ) l--;
		if ( t[i] == L && r < w ) r++;

		// 先手 許容範囲を狭める
		if ( s[i] == R ) r--;
		if ( s[i] == L ) l++;

		if ( r <= l )
			return true;
	}
	if ( pos < l || r <= pos )
		return true;

	return false;
}



