bool solve(int H, int W, int N, int Sr, int Sc, string& S, string& T) {
    bool answer = true;

    // i回目(0..N-1)の行動終了時点でleft <= right の位置に駒があれば後手が勝てる
    int left = 1, right = W;

    RREP(i,0,N) {
        // 後手は範囲を広げようとする
        if (T[i] == 'R') {
            left = max(1, left-1);
        } else if (T[i] == 'L') {
            right = min(W, right+1);
        }

        // 先手は範囲を縮めようとする
        if (S[i] == 'L') {
            left++;
        } else if (S[i] == 'R') {
            right--;
        }

        if (left > right) return false;
    }
    if (left > Sc || right < Sc) return false;

    // i回目(0..N-1)でbottom <= top の位置に駒があれば後手が勝てる
    int bottom = 1, top = H;

    RREP(i,0,N) {
        // 後手は範囲を広げようとする
        if (T[i] == 'U') {
            bottom = max(1, bottom-1);
        } else if (T[i] == 'D') {
            top = min(H, top+1);
        }

        // 先手は範囲を縮めようとする
        if (S[i] == 'D') {
            bottom++;
        } else if (S[i] == 'U') {
            top--;
        }

        if (bottom > top) return false;
    }
    if (bottom > Sr || top < Sr) return false;

    return true;
}

signed main() {
    int H, W, N, Sr, Sc;
    cin >> H >> W >> N >> Sr >> Sc;
    string S, T;
    cin >> S >> T;

    cout << (solve(H, W, N, Sr, Sc, S, T) ? "YES" : "NO") << '\n';

    return 0;
}

