    vector<int> cd(n+1);
    cd.back() = 0;
    RREP(i,n){
        if(s[i]=='D'&&t[i]!='U'){
            cd[i]=cd[i+1]+1;
        }else if(s[i]!='D'&&t[i]=='U'){
            cd[i]=max(cd[i+1]-1,0);
        }else{
            cd[i]=cd[i+1];
        }
    }
    if(cd[0]>=h-sr+1){
        flag = false;
    }
    cnt = 0;
    int ub = sr;
    REP(i,n){
        if(s[i]=='U'){
            cnt++;
            if(ub<=cnt){
                flag = false;
            }
        }
        if(t[i]=='D'){
            cnt = max(cnt-1,-(h-sr-cd[i+1]));//min?
        }
    }
    if(flag){
        put("YES");
    }else{
        put("NO");
    }
    return 0;
}

