    vi atkR, atkC, defR, defC;
    tie(atkR, atkC) = split(N, S);
    tie(defR, defC) = split(N, T);

    bool ans = safe(N, atkR, defR, sr, H)
            && safe(N, atkC, defC, sc, W);

    cout << (ans ? "YES" : "NO") << endl;

    return 0;
}

