void solve(void)
{
  int H, W; cin >> H >> W;
  int N; cin >> N;
  int sr, sc; cin >> sr >> sc;
  string S, T; cin >> S >> T;

  ll minH = sr;
  ll maxH = sr;
  ll minW = sc;
  ll maxW = sc;
  for (int i = 0; i < N; ++i) {
    switch (S[i]) {
      case 'L': {
        --minW;
        break;
      }
      case 'R': {
        ++maxW;
        break;
      }
      case 'U': {
        --minH;
        break;
      }
      case 'D': {
        ++maxH;
        break;
      }
      default: {
        abort();
      }
    }
    if (minH <= 0 || minW <= 0) {
      cout << "NO" << CRLF;
      return;
    }
    if (maxH > H || maxW > W) {
      cout << "NO" << CRLF;
      return;
    }
    switch (T[i]) {
      case 'L': {
        if (maxW > 1) --maxW;
        break;
      }
      case 'R': {
        if (minW < W) ++minW;
        break;
      }
      case 'U': {
        if (maxH > 1) --maxH;
        break;
      }
      case 'D': {
        if (minH < H) ++minH;
        break;
      }
      default: {
        abort();
      }
    }
    if (minH <= 0 || minW <= 0) {
      cout << "NO" << CRLF;
      return;
    }
    if (maxH > H || maxW > W) {
      cout << "NO" << CRLF;
      return;
    }
  }
  cout << "YES" << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

