int find(int node){
    if(node == dsu[node]) return node;
    return dsu[node] = find(dsu[node]);
}

void combine(int a, int b){
    a = find(a); b = find(b);
    if(a == b) return;
    if(r[a] <= r[b]){
        dsu[a] = b; r[b] += r[a];
    } else if(r[b] < r[a]){
        dsu[b] = a; r[a] += r[b];
    }
}

