bool Process(char a,char b,int dis,int lim) {
    suf[N + 1] = 0;int sum = 0;
    for(int i = N ; i >= 1 ; --i) {
        suf[i] = suf[i + 1];
        if(s[i] == b) {
            suf[i] = min(suf[i],sum - 1);
            --sum;
        }
        if(t[i] == a) {
            if(sum < 0) ++sum;
        }
    }
    int pos = dis;
    for(int i = 1 ; i <= N ; ++i) {
        if(s[i] == a) ++pos;
        if(pos > lim) return false;
        if(t[i] == b) {
            if(pos - 1 + suf[i + 1] >= 1) --pos;
        }
    }
    return true;
}
