using namespace std;

int second_win(
    const string& s, const string& t, char left, char right,
    int width, int start){

    int lb = 0; int ub = width;
    for(int i = s.size() - 1; i >= 0; --i){
        if(s.at(i) == left){
            if(t.at(i) == right){
                lb = max(1, lb);
            }else{
                lb++;
            }
        }else if(s.at(i) == right){
            if(t.at(i) == left){
                ub = min(ub, width - 1);
            }else{
                ub--;
            }
        }else{
            if(t.at(i) == left){
                ub = min(ub + 1, width);
            }else if(t.at(i) == right){
                lb = max(0, lb - 1);
            }
        }
        if(lb >= ub){ return 0; }
    }
    return (lb <= start && start < ub);
}

