inline char nc() {
	return getchar();
	static char buf[100000], *l = buf, *r = buf;
	return l==r&&(r=(l=buf)+fread(buf,1,100000,stdin),l==r)?EOF:*l++;
}
template<class T> void read(T &x) {
	x = 0; int f = 1, ch = nc();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=nc();}
	while(ch>='0'&&ch<='9'){x=x*10-'0'+ch;ch=nc();}
	x *= f;
}
const int maxn = 200000 + 5;
int H, W, N;
int sx, sy;
char S[maxn], T[maxn];
int cnt[4], now[4];
inline int idx(char c) {
	if(c == 'L') return 0;
	if(c == 'R') return 1;
	if(c == 'U') return 2;
	return 3;
}
inline void update0(int c) {
	if(now[c]) ++cnt[c];
}
inline void update1(int c) {
	if(cnt[c]) --cnt[c];
	else ++now[c];
}
bool judge(char a, char b) {
	for(int i = 1; i <= N; ++i) {
		if(S[i] == a) return 1;
		if(T[i] == b) return 0;
	}
	return 0;	
}
bool solve() {
	if(sx == 1 && judge('U', 'D')) return 0;
	if(sy == 1 && judge('L', 'R')) return 0;
	if(sx == H && judge('D', 'U')) return 0;
	if(sy == W && judge('R', 'L')) return 0;
	for(int i = N; i >= 1; --i) {
		update0(idx(T[i]) ^ 1);
		update1(idx(S[i]));
	}
	if(now[0] + now[1] >= W) return 0;
	if(now[2] + now[3] >= H) return 0;
	if(sy + cnt[0] <= now[0]) return 0;
	if(sx + cnt[2] <= now[2]) return 0; 
	if(W - sy + 1 + cnt[1] <= now[1]) return 0;
	if(H - sx + 1 + cnt[3] <= now[3]) return 0; 
	return 1;
}
int main() {
	read(H), read(W), read(N);
	read(sx), read(sy);
	scanf("%s", S + 1); 
	scanf("%s", T + 1);
	puts(solve() ? "YES" : "NO");
	return 0;
}

