bool judge(int pos,int lim,int s,int a[],int b[]){
  reverse(a,a+s);
  reverse(b,b+s);
//printf("::pos=%d lim=%d s=%d\n",pos,lim,s);
//printf("a::");for(int i=0;i<s;i++)printf(" %d",a[i]);printf("\n");
//printf("b::");for(int i=0;i<s;i++)printf(" %d",b[i]);printf("\n");
  int ml=1,mr=lim;
  for(int i=0;i<s;i++){
    if(b[i]==1)ml--;
    else if(b[i]==-1)mr++;
    mr=min(mr,lim);
    ml=max(ml,1);
    if(a[i]==1)mr--;
    else if(a[i]==-1)ml++;
    //printf("i=%d ml=%d mr=%d\n",i,ml,mr);
    if(ml>mr)return true;
  }
  if(pos<ml||pos>mr)return true;
  return false;
}
