	int L = 1, R = m;
	for(int i = N - 1; i >= 0; i--){
		if(S[i] == 'L' || S[i] == 'R'){
			if(T[i] == 'U'){
				R = min(m, R + 1);
			}else if(T[i] == 'D'){
				L = max(1, L - 1);
			}
		}else if(S[i] == 'U'){
			if(T[i] == 'D'){
				L = max(2, L);
			}else if(T[i] == 'U'){
				R = min(m, R + 1);
				L = L + 1;
			}else{
				L = L + 1;
			}
		}else{
			if(T[i] == 'U'){
				R = min(m - 1, R);
			}else if(T[i] == 'D'){
				L = max(1, L - 1);
				R = R - 1;
			}else{
				R = R - 1;
			}
		}

		if(L > R)return false;
	}
	if(s < L || s > R)return false;
	return true;
}
