bool solve(char x, char y, int st){
    int wl = 0, wr = w+1;
    rep(i, n){
        if(T[i] == x) wr = min(w+1, wl+1);
        if(T[i] == y) wl = max(0, wl-1);
        //cout << wl << " " << wr << endl;

        if(S[i] == x) wl++;
        if(S[i] == y) wr--;
        //cout << wl << " " << wr << endl;
        if(wl == st || wr == st) return false;
    }
    return true;
}

