	map<char, int> mpc;
	mpc['L'] = 0;
	mpc['R'] = 1;
	mpc['U'] = 2;
	mpc['D'] = 3;
	vector<int> capa( 4 );
	capa[0] = sc - 1;
	capa[1] = W - sc;
	capa[2] = sr - 1;
	capa[3] = H - sr;
	vector<int> tcnt( 4 );
	vector<int> acnt( 4 );
	auto f = [&]( int idx ) -> int
	{
		if( idx == 0 ) {
			if( capa[0] < 1 + tcnt[0] - acnt[1] ) return 1;
			else if( capa[0] < 1 + tcnt[0] + acnt[0] - acnt[1] ) acnt[0] = capa[0] - 1 - tcnt[0] + acnt[1];
		}
		else if( idx == 1 ) {
			if( capa[1] < 1 + tcnt[1] - acnt[0] ) return 1;
			else if( capa[1] < 1 + tcnt[1] + acnt[1] - acnt[0] ) acnt[1] = capa[1] - 1 - tcnt[1] + acnt[0];
		}
		else if( idx == 2 ) {
			if( capa[2] < 1 + tcnt[2] - acnt[3] ) return 1;
			else if( capa[2] < 1 + tcnt[2] + acnt[2] - acnt[3] ) acnt[2] = capa[2] - 1 - tcnt[2] + acnt[3];
		}
		else if( idx == 3 ) {
			if( capa[3] < 1 + tcnt[3] - acnt[2] ) return 1;
			else if( capa[3] < 1 + tcnt[3] + acnt[3] - acnt[2] ) acnt[3] = capa[3] - 1 - tcnt[3] + acnt[2];
		}
		return 0;
	};
	string ans = "YES";
	for( int i = 0; i < N; i++ ) {
		int idx = mpc[ S[i] ];
		if( f( idx ) ) {
			ans = "NO";
			break;
		}
		tcnt[idx]++;
		idx = mpc[ T[i] ];
		if( f( idx ) ) {
			ans = "NO";
			break;
		}
		acnt[idx]++;
	}

	cout << ans << endl;
}

