char s1[N],s2[N];
bool judge(char opt)
{
    int x=sr,y=sc;
    for(int i=1;i<=n;i++)
    {
        if(s1[i]==opt)
        {
            if(opt=='U') x--;
            else if(opt=='D') x++;
            else if(opt=='L') y--;
            else y++;
        }
        if(x<1||x>h||y<1||y>w) return true;
        if(opt=='U')
        {
            if(s2[i]=='D'&&x+1<=h) x++;
        }
        else if(opt=='D')
        {
            if(s2[i]=='U'&&x-1>=1) x--;
        }
        else if(opt=='L')
        {
            if(s2[i]=='R'&&y+1<=w) y++;
        }
        else
        {
            if(s2[i]=='L'&&y-1>=1) y--;
        }
    }
    return false;
}
