int main() {
  int H, W, N; std::cin >> H >> W >> N;
  Point s; std::cin >> s.r >> s.c;
  std::string S, T; std::cin >> S >> T;

  int l = 0, r = 0, u = 0, d = 0;
  for (int i = 0; i < N; ++i) {
    // Takahashi action
    switch (S[i]) {
      case 'L':
        ++l; break;
      case 'R':
        ++r; break;
      case 'U':
        ++u; break;
      case 'D':
        ++d; break;
    }

#if DEBUG
    std::cout << "T:" << l << ", " << r << ", " << u << ", " << d << std::endl;
#endif

    if (s.r - u < 1 || s.r  + d > H || s.c - l < 1 || s.c + r > W) {
      std::cout << "NO" << std::endl;
      return 0;
    }

    // Aoki Action
    switch (T[i]) {
      case 'L':
        if (s.c + r > 1) --r; break;
      case 'R':
        if (s.c - l < W) --l; break;
      case 'U':
        if (s.r + d > 1) --d; break;
      case 'D':
        if (s.r - u < H) --u; break;
    }

#if DEBUG
    std::cout << "A:" << l << ", " << r << ", " << u << ", " << d << std::endl;
#endif
  }

  std::cout << "YES" << std::endl;
}

