vector<pii> ords;
int x;
int low, high;

bool solve(){
    int rl = low, rh = high;
    FORR(i,0,ords.size()){
        pii P = ords[i];
        if(P.first == 0){
            // takahashi
            if(P.second == +1){
                rh--;
            }else{
                rl++;
            }
            if(rl >= rh)return false;
        }else{
            // aoki
            if(P.second == +1){
                rl = max(low,rl-1);
            }else{
                rh = min(high,rh+1);
            }
        }
    }
    return rl<=x && x<rh;
}

