        if(T[i] == 'L'){
            W2 = min(W, W2 + 1);
        }else if(T[i] == 'R'){
            W1 = max(1, W1 - 1);
        }else if(T[i] == 'U'){
            H2 = min(H, H2 + 1);
        }else{
            H1 = max(1, H1 - 1);
        }
        if(S[i] == 'L'){
            W1 += 1;
        }else if(S[i] == 'R'){
            W2 -= 1;
        }else if(S[i] == 'U'){
            H1 += 1;
        }else{
            H2 -= 1;
        }
        if(H1 > H2 || W1 > W2){
            cout << "NO" << endl;
            return 0;
        }
    }
    if(H1 <= sy && sy <= H2 && W1 <= sx && sx <= W2){
        cout << "YES" << endl;
    }else{
        cout << "NO" << endl;
    }
    return 0;
}

