int solve(int size, int init, const string& s, const string& t)
{
    int left = 0;
    int right = size - 1;

    int n = s.size();
    for(int i=n-1; i>=0; --i){
        if(t[i] == 'L')
            right = min(right + 1, size - 1);
        else if(t[i] == 'R')
            left = max(left - 1, 0);

        if(s[i] == 'L')
            ++ left;
        else if(s[i] == 'R')
            -- right;
        if(left > right)
            return false;
    }

    return left <= init && init <= right;
}

