    sr--;
    sc--;

    int32_t leftBoundary = 0;
    int32_t rightBoundary = W - 1;
    int32_t upperBoundary = 0;
    int32_t bottomBoundary = H - 1;

    bool kickOutable = false;

    for (size_t cnt = 0; cnt < N; cnt++) {
        {
            if (T[N - cnt - 1] == 'L' && rightBoundary < W - 1) {
                rightBoundary++;
            }

            if (S[N - cnt - 1] == 'R') {
                rightBoundary--;
            }

            if (rightBoundary < (int32_t)sc) {
                kickOutable = true;

                break;
            }
        }
        {
            if (T[N - cnt - 1] == 'R' && 0 < leftBoundary) {
                leftBoundary--;
            }

            if (S[N - cnt - 1] == 'L') {
                leftBoundary++;
            }

            if ((int32_t)sc < leftBoundary) {
                kickOutable = true;

                break;
            }
        }
        {
            if (T[N - cnt - 1] == 'D' && 0 < upperBoundary) {
                upperBoundary--;
            }

            if (S[N - cnt - 1] == 'U') {
                upperBoundary++;
            }

            if ((int32_t)sr < upperBoundary) {
                kickOutable = true;

                break;
            }
        }
        {
            if (T[N - cnt - 1] == 'U' && bottomBoundary < H - 1) {
                bottomBoundary++;
            }

            if (S[N - cnt - 1] == 'D') {
                bottomBoundary--;
            }

            if (bottomBoundary < (int32_t)sr) {
                kickOutable = true;

                break;
            }
        }
    }

    puts(kickOutable ? "NO" : "YES");

    return 0;
}

