	case 'U':
		if (*y < H / 2 + 1)
			*y--;
		break;
	case 'D':
		if (*y > H / 2 + 1)
			*y++;
		break;
	}
}

void moveT(int *y, int *x, int H, int W, char dir) {
	switch (dir) {
	case 'L':
		if (*x > W / 2 + 1)
			*x--;
		break;
	case 'R':
		if (*x < W / 2 + 1)
			*x++;
		break;
	case 'U':
		if (*y > H / 2 + 1)
			*y--;
		break;
	case 'D':
		if (*y < H / 2 + 1)
			*y++;
		break;
	}
}

