ull parent[N_MAX], size[N_MAX];
void init (ull n) {
	for (sll i = 0; i < n; i++) {
		parent[i] = i;
		size[i] = 1;
	}
}
ull find (ull x) {
	if (parent[x] == x) return x;
	return parent[x] = find(parent[x]);
}
bool unite (ull a, ull b) {
	a = find(a);
	b = find(b);

	if (a == b) return false;

	if (size[a] < size[b]) {
		a ^= b;
		b ^= a;
		a ^= b;
	}
	size[a] += size[b];
	parent[b] = a;
	return true;
}

