int yaru(int target, int limit, char zyun, char gyaku) {
	int left = target;
	int i;
	for (i = 0; i < N; i++) {
		if (S[i] == zyun) left--;
		if (left <= 0) return 1;
		if (T[i] == gyaku && left < limit) left++;
	}
	return 0;
}

