	scanf("%s", T);

	//'L','R','U','D'
	int out[] = { 0,W + 1,0,H + 1 };
	int lim[] = { x,x,y,y };
	int move[] = { -1,1 };
	int i,dir;
	for (i = 0; i < N; i++) {
		dir = index(S[i]);
		lim[dir] += move[dir % 2];
		if (lim[dir] == out[dir]) {
			printf("NO\n");
			break;
		}
		dir = index(T[i]);
		dir = dir / 2 * 2 + (dir + 1) % 2;
		lim[dir] -= move[dir % 2];
	}
	if (i == N)
		printf("YES\n");
	return 0;
}

