            if (S[N - cnt - 1] == 'L') {
                leftBoundary++;
            }

            if ((int32_t)sc < leftBoundary) {
                kickOutable = true;

                break;
            }

            if (cnt < N - 1) {
                if (T[N - cnt - 2] == 'R' && 0 < leftBoundary) {
                    leftBoundary--;
                }
            }
