            if (S[N - cnt - 1] == 'U') {
                upperBoundary++;
            }

            if ((int32_t)sr < upperBoundary) {
                kickOutable = true;

                break;
            }

            if (cnt < N - 1) {
                if (T[N - cnt - 2] == 'D' && 0 < upperBoundary) {
                    upperBoundary--;
                }
            }
