int main(void){

	int H,W,N,sr,sc,result=1;

	scanf("%d",&H);
	scanf("%d",&W);
	scanf("%d",&N);
	scanf("%d",&sr);
	scanf("%d",&sc);

	char S[N],T[N];

	scanf("%s",&S);

	scanf("%s",&T);	

	for(int i=0;i<N;i++){
		//高橋
		if(S[i]=='L' && sc-1<=0){
			result=0;
			break;
		else if(S[i]=='L')
			sc--;
		}
		else if(S[i]=='R' && sc+1>W){
			result=0;
			break;
		else if(S[i]=='R')
			sc++;
		}
		else if(S[i]=='U' && sr-1<=0){
			result=0;
			break;
		else if(S[i]=='U')
			sr--;
		}
		else if(S[i]=='D' && sr+1>H){
			result=0;
			break;
		else if(S[i]=='D')
			sr++;
		}
		//青木
		if(T[i]=='L' && sc-1<=0){
			continue;
		else if(T[i]=='L')
			sc--;
		}
		else if(T[i]=='R' && sc+1>W){
			continue;
		else if(T[i]=='R')
			sc++;
		}
		else if(T[i]=='U' && sr-1<=0){
			continue;
		else if(T[i]=='U')
			sr--;
		}
		else if(T[i]=='D' && sr+1>H){
			continue;
		else if(T[i]=='D')
			sr++;
		}
	}

	if(result==0){
		printf("NO");
	}else{
		printf("YES");
	}

	return 0;
}

