int main(void){
  int H,W,N;
  scanf("%d%d%d",&H,&W,&N);

  int sr,sc;
  scanf("%d%d",&sr,&sc);

  char S[N],T[N];
  scanf("%s%s",S,T);

  int rsum1[N+1],rsum2[N+1];
  int lsum1[N+1],lsum2[N+1];
  int usum1[N+1],usum2[N+1];
  int dsum1[N+1],dsum2[N+1];

  rsum1[0] = 0; rsum2[0] = 0;
  lsum1[0] = 0; lsum2[0] = 0;
  usum1[0] = 0; usum2[0] = 0;
  dsum1[0] = 0; dsum2[0] = 0;

  for(int i = 0;i < N;i++){
    rsum1[i+1] = rsum1[i];
    lsum1[i+1] = lsum1[i];
    usum1[i+1] = usum1[i];
    dsum1[i+1] = dsum1[i];
    if(S[i] == 'R') rsum1[i+1]++;
    if(S[i] == 'L') lsum1[i+1]++;
    if(S[i] == 'U') usum1[i+1]++;
    if(S[i] == 'D') dsum1[i+1]++;

    if(rsum1[i+1]-lsum2[i] > W-sc){
      printf("NO\n");
      return 0;
    }else if(lsum2[i]-rsum1[i+1] >= sc){
      lsum2[i] = sc+rsum1[i+1]-1;
    }
    if(lsum1[i+1]-rsum2[i] >= sc){
      printf("NO\n");
      return 0;
    }else if(rsum2[i]-lsum1[i+1] > W-sc){
      rsum2[i] = W-sc+lsum1[i+1];
    }
    if(usum1[i+1]-dsum2[i] > H-sr){
      printf("NO\n");
      return 0;
    }else if(dsum2[i]-usum1[i+1] >= sr){
      dsum2[i] = sr+usum1[i+1]-1;
    }
    if(dsum1[i+1]-usum2[i] >= sr){
      printf("NO\n");
      return 0;
    }else if(usum2[i]-dsum1[i+1] > H-sr){
      usum2[i] = H-sr+dsum1[i+1];
    }

    rsum2[i+1] = rsum2[i];
    lsum2[i+1] = lsum2[i];
    usum2[i+1] = usum2[i];
    dsum2[i+1] = dsum2[i];
    if(T[i] == 'R' && rsum2[i]+1-lsum1[i+1] <= W-sc) rsum2[i+1]++;
    if(T[i] == 'L' && lsum2[i]+1-rsum1[i+1] < sc) lsum2[i+1]++;
    if(T[i] == 'U' && usum2[i]+1-dsum1[i+1] <= H-sr) usum2[i+1]++;
    if(T[i] == 'D' && dsum2[i]+1-usum1[i+1] < sr) dsum2[i+1]++;
  }

  printf("YES\n");

  return 0;
}

