fun PrintWriter.solve(sc: FastScanner) {
    val h = sc.nextInt()
    val w = sc.nextInt()
    val n = sc.nextInt()
    val r = sc.nextInt()
    val c = sc.nextInt()
    val s = sc.nextLine()
    val t = sc.nextLine()
    var left = 0
    var right = 0
    var up = 0
    var down = 0
    var ok = true
    for (i in 0 until n) {
        if (s[i] == 'L') left++
        if (s[i] == 'R') right++
        if (s[i] == 'U') up++
        if (s[i] == 'D') down++

        if (c - left <= 0) {
            ok = false
        }
        if (c + right > w) {
            ok = false
        }
        if (r - up <= 0) {
            ok = false
        }
        if (r + down > h) {
            ok = false
        }

        if (t[i] == 'L' && c + right - 1 > 0) right--
        if (t[i] == 'R' && c - left + 1 < w) left--
        if (t[i] == 'U' && r + down - 1 > 0) down--
        if (t[i] == 'D' && r - up + 1 < h) up--
    }
    println(if (ok) "YES" else "NO")
}

