fun solve() {
    val h = nextLong()
    val w = nextLong()
    val n = nextLong()
    val r = nextLong()
    val c = nextLong()
    val s = next()
    val t = next()
    val taka = longAry2(n + 1, 4)
    val aoki = longAry2(n + 1, 4)
    for (i in 0 until n) {
        taka[i + 1][0] = taka[i][0]
        taka[i + 1][1] = taka[i][1]
        taka[i + 1][2] = taka[i][2]
        taka[i + 1][3] = taka[i][3]
        when (s[i]) {
            'U' -> taka[i + 1][0] += 1L
            'D' -> taka[i + 1][1] += 1L
            'L' -> taka[i + 1][2] += 1L
            'R' -> taka[i + 1][3] += 1L
        }
    }
    var firstup = 0L
    var firstdown = 0L
    var firstleft = 0L
    var firstright = 0L
    var stockup = 0L
    var stockdown = 0L
    var stockleft = 0L
    var stockright = 0L
    var upflag = false
    var downflag = false
    var leftflag = false
    var rightflag = false
    for (i in 0 until n) {
        aoki[i + 1][0] = aoki[i][0]
        aoki[i + 1][1] = aoki[i][1]
        aoki[i + 1][2] = aoki[i][2]
        aoki[i + 1][3] = aoki[i][3]
        when (t[i]) {
            'U' -> aoki[i + 1][0] += 1L
            'D' -> aoki[i + 1][1] += 1L
            'L' -> aoki[i + 1][2] += 1L
            'R' -> aoki[i + 1][3] += 1L
        }
        when {
            s[i] == 'D' && !downflag -> {
                firstdown = i
                stockup = aoki[i][0]
                downflag = true
            }
            s[i] == 'U' && !upflag -> {
                firstup = i
                stockdown = aoki[i][1]
                upflag = true
            }
            s[i] == 'R' && !rightflag -> {
                firstright = i
                stockleft = aoki[i][2]
                rightflag = true
            }
            s[i] == 'L' && !leftflag -> {
                firstleft = i
                stockright = aoki[i][3]
                leftflag = true
            }
        }
    }

    val upgap = r
    val downgap = h - r + 1
    val leftgap = c
    val rightgap = w - c + 1
    stockup = min(stockup, upgap - 1)
    stockdown = min(stockdown, downgap - 1)
    stockleft = min(stockleft, leftgap - 1)
    stockright = min(stockright, rightgap - 1)
    for (i in 0 until n) {
        val takaup = taka[i + 1][0]
        val aokiup = stockup + max(0L, aoki[i][0] - aoki[firstdown][0])
        val takadown = taka[i + 1][1]
        val aokidown = stockdown + max(0L, aoki[i][1] - aoki[firstup][1])
        val takaleft = taka[i + 1][2]
        val aokileft = stockleft + max(0L, aoki[i][2] - aoki[firstright][2])
        val takaright = taka[i + 1][3]
        val aokiright = stockright + max(0L, aoki[i][3] - aoki[firstleft][3])
        val resup = takaup - aokidown >= upgap
        val resdown = takadown - aokiup >= downgap
        val resleft = takaleft - aokiright >= leftgap
        val resright = takaright - aokileft >= rightgap
        if(resup || resdown || resleft || resright) {
            println("NO")
            return
        }
    }

    println("YES")


}



