fun solve() {
    val h = nextLong()
    val w = nextLong()
    val n = nextLong()
    val r = nextLong()
    val c = nextLong()
    val s = next()
    val t = next()
    val taka = longAry2(n + 1, 4)
    val aoki = longAry2(n + 1, 4)
    for (i in 0 until n) {
        taka[i + 1][0] = taka[i][0]
        taka[i + 1][1] = taka[i][1]
        taka[i + 1][2] = taka[i][2]
        taka[i + 1][3] = taka[i][3]
        when (s[i]) {
            'U' -> taka[i + 1][0] += 1L
            'D' -> taka[i + 1][1] += 1L
            'L' -> taka[i + 1][2] += 1L
            'R' -> taka[i + 1][3] += 1L
        }
    }
    for (i in 0 until n) {
        aoki[i + 1][0] = aoki[i][0]
        aoki[i + 1][1] = aoki[i][1]
        aoki[i + 1][2] = aoki[i][2]
        aoki[i + 1][3] = aoki[i][3]
        when (s[i]) {
            'U' -> aoki[i + 1][0] += 1L
            'D' -> aoki[i + 1][1] += 1L
            'L' -> aoki[i + 1][2] += 1L
            'R' -> aoki[i + 1][3] += 1L
        }
    }

    val upgap = r
    val downgap = h - r + 1
    val leftgap = c
    val rightgap = w - c + 1
    for (i in 0 until n) {
        val takaup = taka[i + 1][0]
        val aokiup = min(aoki[i][0], downgap - 1)
        val takadown = taka[i + 1][1]
        val aokidown = min(aoki[i][1], upgap - 1)
        val takaleft = taka[i + 1][2]
        val aokileft = min(aoki[i][2], rightgap - 1)
        val takaright = taka[i + 1][3]
        val aokiright = min(aoki[i][3], leftgap - 1)
        val resup = takaup - aokiup >= upgap
        val resdown = takadown - aokidown >= downgap
        val resleft = takaleft - aokileft >= leftgap
        val resright = takaright - aokiright >= rightgap
        if(resup || resdown || resleft || resright) {
            println("NO")
            return
        }
    }

    println("YES")


}



