                case 'R': right--; break;
                case 'U': up++; break;
                case 'D': down--; break;
            }
            if (left > right || up > down) alive = false;
        }
        boolean ans = alive && Sr >= up && Sr <= down && Sc >= left && Sc <= right;
        System.out.println(ans ? "YES" :"NO");
    }
}

