                lft--;
            } else if(s.charAt(i) == 'R'){
                rgt++;
            }
            // --
            if(t.charAt(i) == 'L'){
                rgt--;
            } else if(t.charAt(i) == 'R'){
                lft++;
            }
            //---
            if(lft < 0 && (y + lft < 1)){
                return false;
            }
            if(rgt > 0 && (y + rgt > W)){
                return false;
            }
        }
        return true;
    }

    boolean okByUD(){
        int up = 0, down = 0;
        for(int i = 0; i < n; i++){
            if(s.charAt(i) == 'U'){
                up--;
            } else if(s.charAt(i) == 'D'){
                down++;
            }
            //---
            if(t.charAt(i) == 'U'){
                down--;
            } else if(t.charAt(i) == 'D'){
                up++;
            }
            //--
            if(up < 0 && (x + up < 1)){
                return false;
            }
            if(down > 0 && (x + down > H)){
                return false;
            }
        }
        return true;
    }

