		String[] S = s.split("");
		String t = sc.next();
		String[] T = t.split("");

		int scnt = 0;
		int tcnt = 0;

		int dstL = Sc;
		int dstR = h-Sc+1;
		int dstU = Sr;
		int dstD = w-Sr+1;

		for(int i=0;i<n;i++){
			switch(S[scnt]){
				case "L":
					if(dstL<dstR){
						dstL--;
						dstR++;
					}
					break;
				case "R":
