					}
					break;
				case "R":
					if(dstR>dstL){
						dstR--;
						dstL++;
					}
					break;
				case "U":
					if(dstU>dstD){
						dstU--;
						dstD++;
					}
					break;
				case "D":
					if(dstD>dstU){
						dstD--;
						dstU++;
					}
					break;
				default:break;
			}
		}

		// 出力
		System.out.println("NO");
	}
