        switch(s.charAt(n-1)){
            case 'L':
            max[n-1][0] = 1;
            cur[0] = 1;
            break;
            case 'R':
            max[n-1][1] = 1;
            cur[1] = 1;
            break;
            case 'U':
            max[n-1][2] = 1;
            cur[2] = 1;
            break;
            case 'D':
            max[n-1][3] = 1;
            cur[3] = 1;
            break;
        }
        for(int i=n-2; i>=0; i--){
            switch(t.charAt(i)){
                case 'L':
                cur[1] = Math.max(0, cur[1] - 1);
                break;
                case 'R':
                cur[0] = Math.max(0, cur[0] - 1);
                break;
