            for(int j=0; j<4; j++) max[i][j] = cur[j];
            switch(s.charAt(i)){
                case 'L':
                max[i][0]++;
                cur[0]++;
                break;
                case 'R':
                max[i][1]++;
                cur[1]++;
                break;
                case 'U':
                max[i][2]++;
                cur[2]++;
                break;
                case 'D':
                max[i][2]++;
                cur[2]++;
                break;
            }
        }

        int hmin = start[0];
        int hmax = start[0];
        int wmin = start[1];
        int wmax = start[1];
        for(int i=0; i<n; i++){
            hmin = Math.max(hmin, max[i][2]+1);
            hmax = Math.min(hmax, h - max[i][3]);
            wmin = Math.max(wmin, max[i][0]+1);
            wmax = Math.min(wmax, w - max[i][1]);
            if(hmin > hmax || wmin > wmax){
                System.out.println("NO");
                return;
            }
            // switch(s.charAt(i)){
            //     case 'L':
            //     wmin--;
            //     break;
            //     case 'R':
            //     wmax++;
            //     break;
            //     case 'U':
            //     hmin--;
            //     break;
            //     case 'D':
            //     hmax++;
            //     break;
            // }

            switch(s.charAt(i)){
                case 'L':
                wmax--;
                if(wmin > wmax) wmin = wmax;
                break;
                case 'R':
                wmin++;
                if(wmax < wmin) wmax = wmin;
                break;
                case 'U':
                hmax--;
                if(hmin > hmax) hmin = hmax;
                break;
                case 'D':
                hmin++;
                if(hmax < hmin) hmax = hmin;
                break;
            }

            switch(t.charAt(i)){
                case 'L':
                wmin--;
