import java.util.InputMismatchException;
import java.io.IOException;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        BLRUDGame solver = new BLRUDGame();
        solver.solve(1, in, out);
        out.close();
    }

    static class BLRUDGame {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int h = in.readInt();
            int w = in.readInt();
            int n = in.readInt();
            int sr = in.readInt();
            int sc = in.readInt();
            String s = in.readString();
            String t = in.readString();

            {
                int[] a = new int[n];
                int[] b = new int[n];
                for (int i = 0; i < n; i++) {
                    if (s.charAt(i) == 'L') {
                        a[i] = 1;
                    } else if (s.charAt(i) == 'R') {
                        a[i] = -1;
                    }
                    if (t.charAt(i) == 'L') {
                        b[i] = 1;
                    } else if (t.charAt(i) == 'R') {
                        b[i] = -1;
                    }
                }
                if (!f(w, sc, a, b)) {
                    out.printLine("NO");
                    return;
                }
            }
            {
                int[] a = new int[n];
                int[] b = new int[n];
                for (int i = 0; i < n; i++) {
                    if (s.charAt(i) == 'D') {
                        a[i] = 1;
                    } else if (s.charAt(i) == 'U') {
                        a[i] = -1;
                    }
                    if (t.charAt(i) == 'D') {
                        b[i] = 1;
                    } else if (t.charAt(i) == 'U') {
                        b[i] = -1;
                    }
                }
                if (!f(h, sr, a, b)) {
                    out.printLine("NO");
                    return;
                }
            }
            out.printLine("YES");
        }

        boolean f(int l, int s, int[] a, int[] b) {
            int n = a.length;
            int min = 1;
            int max = l;
            for (int i = 0; i < n; i++) {
                if (b[n - 1 - i] == 1) {
                    min = Math.min(min - 1, 1);
                } else if (b[n - 1 - i] == -1) {
                    max = Math.max(max + 1, l);
                }
                if (a[n - 1 - i] == 1) {
                    max--;
                } else if (a[n - 1 - i] == -1) {
                    min++;
                }
                if (min > max) return false;
            }
            return min <= s && s <= max;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int H = scanner.nextInt();
    int W = scanner.nextInt();
    int N = scanner.nextInt();
    int sr = scanner.nextInt();
    int sc = scanner.nextInt();
    char[] S = scanner.next().toCharArray();
    char[] T = scanner.next().toCharArray();
    if (possible(H, W, N, sr, sc, S, T)) {
      System.out.println("NO");
    } else {
      System.out.println("YES");
    }
  }

  private static boolean possible(int H, int W, int N, int sr, int sc, char[] S, char[] T) {
    int[] count = new int[4];
    for (int i = 0; i < N; i++) {
      switch (S[i]) {
        case 'U':
          count[0]++;
          break;
        case 'R':
          count[1]++;
          break;
        case 'D':
          count[2]++;
          break;
        case 'L':
          count[3]++;
          break;
      }
      if (sr - count[0] <= 0) return true;
      if (sr + count[2] > H) return true;
      if (sc - count[3] <= 0) return true;
      if (sc + count[1] > W) return true;
      switch (T[i]) {
        case 'U':
          if (sr + count[2] > 1) count[2]--;
          break;
        case 'R':
          if (sc - count[3] < W) count[3]--;
          break;
        case 'D':
          if (sr - count[0] < H) count[0]--;
          break;
        case 'L':
          if (sc + count[1] > 1) count[1]--;
          break;
      }
    }
    return false;
  }
}

import java.util.Scanner;

public class Main {
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int w = scanner.nextInt();
        int n = scanner.nextInt();
        int r = scanner.nextInt();
        int c = scanner.nextInt();
        String s = scanner.next();
        String t = scanner.next();

        boolean canGoOut = false;
        // go up
        canGoOut = willGoOut(s, t, r, h -r + 1, 'U', 'D');
        if (canGoOut) {
            System.out.println("NO");
            return;
        }

        // go down
        canGoOut = willGoOut(s, t, h - r + 1, r, 'D', 'U');
        if (canGoOut) {
            System.out.println("NO");
            return;
        }


        // go left
        canGoOut = willGoOut(s, t, c, w - c + 1, 'L', 'R');
        if (canGoOut) {
            System.out.println("NO");
            return;
        }


        // go right
        canGoOut = willGoOut(s, t, w - c + 1, c,'R', 'L');
        if (canGoOut) {
            System.out.println("NO");
            return;
        }
        System.out.println("YES");

    }

    public static boolean willGoOut(
            String s, String t, int needMoves, int cancelNeedMoves, char move, char cancelMove
    ) {
        int cancelMoveCount = 0;
        int moveCount = 0;
        int i;
        for (i = 0; i < s.length(); ++i) {
            if (s.charAt(i) == move) {
                break;
            }
            if (t.charAt(i) == cancelMove) {
                ++cancelMoveCount;
            }
        }
        if (cancelMoveCount >= cancelNeedMoves) {
            cancelMoveCount = cancelNeedMoves - 1;
        }
        moveCount -= cancelMoveCount;
        for (; i < s.length(); ++i) {
            if (s.charAt(i) == move) {
                ++moveCount;
                if (moveCount >= needMoves) {
                    return true;
                }
            }
            if (t.charAt(i) == cancelMove) {
                --moveCount;
            }
        }
        return false;
    }
}

