        public Task(FastIO io, Debug debug) {
            this.io = io;
            this.debug = debug;
        }

        @Override
        public void run() {
            solve();
        }


        Interval[] lrs;
        Interval[] uds;

        public void solve() {
            int n = io.readInt();
            int m = io.readInt();
            int t = io.readInt();
            int r = io.readInt();
            int c = io.readInt();
            char[] alice = new char[t];
            char[] bob = new char[t];
            io.readString(alice, 0);
            io.readString(bob, 0);

            lrs = new Interval[t];
            uds = new Interval[t];
            Interval lr = new Interval(m);
            Interval ud = new Interval(n);
            for (int i = t - 1; i >= 0; i--) {
                //bob
                if (bob[i] == 'L' || bob[i] == 'R') {
                    lr.bob(bob[i] == 'L');
                } else {
                    ud.bob(bob[i] == 'U');
                }
                //alice
                if (alice[i] == 'L' || alice[i] == 'R') {
                    lr.alice(alice[i] == 'L');
                } else {
                    ud.alice(alice[i] == 'U');
                }
                lrs[i] = new Interval(lr);
                uds[i] = new Interval(ud);
            }

            boolean bobWin = true;
            for (int i = 0; i < t; i++) {
                if (lrs[i].l >= c || lrs[i].r <= c
                        || uds[i].l >= r || uds[i].r <= r) {
                    bobWin = false;
                    break;
                }
                if (!(i + 1 < t && lrs[i].l >= c || lrs[i].r <= c
                        || uds[i].l >= r || uds[i].r <= r)) {
                    continue;
                }
                if (bob[i] == 'U') {
                    r--;
                } else if (bob[i] == 'D') {
                    r++;
                } else if (bob[i] == 'L') {
                    c--;
                } else if (bob[i] == 'R') {
                    c++;
                }
            }

            io.cache.append(bobWin ? "YES" : "NO");

        }
    }

    public static class Interval {
        int l;
        int r;
        int n;

        public Interval(Interval old) {
            l = old.l;
            r = old.r;
            n = old.n;
        }

        @Override
        public String toString() {
            return String.format("l=%d,r=%d", l, r);
        }

        public Interval(int n) {
            this.n = n;
            l = 0;
            r = n + 1;
        }

        public void alice(boolean left) {
            if (left) {
                l++;
            } else {
                r--;
            }
        }

        public void bob(boolean left) {
            if (left) {
                r = Math.min(n + 1, r + 1);
            } else {
                l = Math.max(0, l - 1);
            }
        }
    }

    public static class FastIO {
        public final StringBuilder cache = new StringBuilder();
        private final InputStream is;
        private final OutputStream os;
        private final Charset charset;
        private StringBuilder defaultStringBuf = new StringBuilder(1 << 8);
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastIO(InputStream is, OutputStream os, Charset charset) {
            this.is = is;
            this.os = os;
            this.charset = charset;
        }

        public FastIO(InputStream is, OutputStream os) {
            this(is, os, Charset.forName("ascii"));
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public long readLong() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            long val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public double readDouble() {
            boolean sign = true;
            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+';
                next = read();
            }

            long val = 0;
            while (next >= '0' && next <= '9') {
                val = val * 10 + next - '0';
                next = read();
            }
            if (next != '.') {
                return sign ? val : -val;
            }
            next = read();
            long radix = 1;
            long point = 0;
            while (next >= '0' && next <= '9') {
                point = point * 10 + next - '0';
                radix = radix * 10;
                next = read();
            }
            double result = val + (double) point / radix;
            return sign ? result : -result;
        }

        public String readString(StringBuilder builder) {
            skipBlank();

            while (next > 32) {
                builder.append((char) next);
                next = read();
            }

            return builder.toString();
        }

        public String readString() {
            defaultStringBuf.setLength(0);
            return readString(defaultStringBuf);
        }

        public int readLine(char[] data, int offset) {
            int originalOffset = offset;
            while (next != -1 && next != '\n') {
                data[offset++] = (char) next;
                next = read();
            }
            return offset - originalOffset;
        }

        public int readString(char[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (char) next;
                next = read();
            }

            return offset - originalOffset;
        }

        public int readString(byte[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (byte) next;
                next = read();
            }

            return offset - originalOffset;
        }

        public char readChar() {
            skipBlank();
            char c = (char) next;
            next = read();
            return c;
        }

        public void flush() {
            try {
                os.write(cache.toString().getBytes(charset));
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public boolean hasMore() {
            skipBlank();
            return next != -1;
        }
    }

