import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int h = scanner.nextInt();
		int w = scanner.nextInt();
		int n = scanner.nextInt();
		int sr = scanner.nextInt()-1;
		int sc = scanner.nextInt()-1;
		char[] S = scanner.next().toCharArray();
		char[] T = scanner.next().toCharArray();

		int r = 0;
		int l = 0;
		int u = 0;
		int d = 0;
		for (int i=0; i<n; i++){
			switch (S[i]){
				case 'R':
					r++;
					if (r>(w-1)-sc) no();
					break;
				case 'L':
					l++;
					if (l>sc) no();
					break;
				case 'U':
					u++;
					if (u>sr) no();
					break;
				case 'D':
					d++;
					if (d>(h-1)-sr) no();
					break;
			}
			switch (T[i]){
				case 'L':
					if (r>-sc)r--;
					break;
				case 'R':
					if (l>sc-(w-1)) l--;
					break;
				case 'D':
					if (u>sr-(h-1)) u--;
					break;
				case 'U':
					if (d>-sr) d--;
					break;
			}
		}
		System.out.println("YES");
	}

	static void no() {
		System.out.println("NO");
		System.exit(0);
	}
}

import java.util.Scanner;
import java.util.stream.Stream;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // マス取得
        int[] nums = Stream.of(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        int h = nums[0];
        int w = nums[1];
        int n = nums[2];

        // スタート位置取得
        int[] poss = Stream.of(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        int posH = poss[0];
        int posW = poss[1];

        // 方向取得
        String[] dirs = new String[2];
        for (int i = 0; i < 2; i++) {
            dirs[i] = sc.nextLine();
        }

        if (isOut(n, w, w - posW, dirs[0], dirs[1], "L", "R")) {
            System.out.println("NO");
            return;
        }

        if (isOut(n, w, posW, dirs[0], dirs[1], "R", "L")) {
            System.out.println("NO");
            return;
        }

        if (isOut(n, h, h - posH, dirs[0], dirs[1], "U", "D")) {
            System.out.println("NO");
            return;
        }

        if (isOut(n, h, posH, dirs[0], dirs[1], "D", "U")) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
    }

    private static boolean isOut(int n, int maxHW, int startPos, String tDir, String aDir, String t, String a) {
        String[] tDirs = tDir.split("");
        String[] aDirs = aDir.split("");
        for (int i = 0; i < n; i++) {
            // 高橋くんのターン
            if (tDirs[i].equals(t)) {
                if (++startPos >= maxHW) {
                    return true;
                }
            }

            // 青木くんのターン
            if (aDirs[i].equals(a)) {
                if (startPos - 1 > 0) {
                    startPos--;
                }
            }
        }
        return false;
    }

    private static int getCount(String str, char target){
        int count = 0;

        for(char x: str.toCharArray()){
            if(x == target){
                count++;
            }
        }

        return count;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int H = scan.nextInt();
        int W = scan.nextInt();
        int N = scan.nextInt();
        int sr = scan.nextInt()-1;
        int sc = scan.nextInt()-1;
        String S = scan.next();
        String T = scan.next();

        int left = 0;
        int right = W-1;
    if (S.charAt(N-1) == 'L') ++left;
    if (S.charAt(N-1) == 'R') --right;
        for (int i=N-2;i>=0;i--) {
            if (T.charAt(i)=='L') {
                if (right<W-1) right++;
            } else if (T.charAt(i)=='R') {
                if (left>0) left--;
            }

            if (S.charAt(i)=='L') {
                left++;
            } else if (S.charAt(i)=='R') {
                right--;
            }

            if (right<left) {
                System.out.println("NO");
                return;
            }
        }

        int down = 0;
        int up = H-1;
    if (S.charAt(N-1) == 'D') ++down;
    if (S.charAt(N-1) == 'U') --up;
        for (int i=N-2;i>=0;i--) {
            if (T.charAt(i)=='D') {
                if (up<H-1) up++;
            } else if (T.charAt(i)=='U') {
                if (down>0) down--;
            }

            if (S.charAt(i)=='D') {
                down++;
            } else if (S.charAt(i)=='U') {
                up--;
            }

            if (up<down) {
                System.out.println("NO");
                return;
            }
        }

        if (left<=sc && sc<=right && down<=sr && sr<=up) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

