    /**
     * https://atcoder.jp/contests/abc064/tasks/abc064_d
     * D - Insertion
     */
    private void solveD() {
        int n = nextInt();
        String s = next();
        int open = 0;
        int close = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                open++;
            } else {
                if (open == 0)
                    close++;
                else
                    open--;
            }
        }

        /*
        左に(を、右に)を足せば()の組を作るのは可能
        そして、辞書順最小も達成できる
         */
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < close; i++)
            sb.append('(');
        sb.append(s);
        for (int i = 0; i < open; i++)
            sb.append(')');
        out.println(sb.toString());
    }

    private void solveE() {
        int h = nextInt();
        int w = nextInt();
        int n = nextInt();
        int sr = nextInt();
        int sc = nextInt();
        String s = next();
        String t = next();
        int u = sr;
        int d = sr;
        int r = sc;
        int l = sc;
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            switch (cs) {
                case 'U':
                    u--;
                    if (u < 1) {
                        out.println("NO");
                        return;
                    }
                    break;
                case 'D':
                    d++;
                    if (d > h) {
                        out.println("NO");
                        return;
                    }
                    break;
                case 'L':
                    l--;
                    if (l < 1) {
                        out.println("NO");
                        return;
                    }
                    break;
                case 'R':
                    r++;
                    if (r > w) {
                        out.println("NO");
                        return;
                    }
                    break;
            }
            char ct = t.charAt(i);
            switch (ct) {
                case 'U':
                    d--;
                    if (d < 1)
                        d = 1;
                    break;
                case 'D':
                    u++;
                    if (d > h)
                        d = h;
                    break;
                case 'L':
                    r--;
                    if (r < 1)
                        r = 1;
                    break;
                case 'R':
                    l++;
                    if (l > w)
                        l = w;
