	private void solve() {
		Scanner sc = new Scanner(System.in);
		int H = sc.nextInt();
		int W = sc.nextInt();
		int N = sc.nextInt();
		int s_r = sc.nextInt();
		int s_c = sc.nextInt();
		String S = sc.next();
		String T = sc.next();

		int Umin = s_r;
		int Umax = s_r;
		int Dmin = s_r;
		int Dmax = s_r;
		int Lmin = s_c;
		int Lmax = s_c;
		int Rmin = s_c;
		int Rmax = s_c;
		for (int i = 0; i < N; i++) {
			if (S.charAt(i) == 'L') {
				Lmin--;
				Lmax--;
			}
			if (S.charAt(i) == 'R') {
				Rmin++;
				Rmax++;
			}
			if (S.charAt(i) == 'U') {
				Umin--;
				Umax--;
			}
			if (S.charAt(i) == 'D') {
				Dmin++;
				Dmax++;
			}

			if (Lmax - Rmax + W < 1 || Umax - Dmax + H < 1 || Rmin - Lmin + 1 > W || Dmin - Umin + 1 > H) {
				System.out.println("NO");
				return;
			}

			if (T.charAt(i) == 'L') {
				Lmin--;
				Rmin--;
			}
			if (T.charAt(i) == 'R') {
