import java.io.DataInputStream;
import java.io.FileInputStream;
import java.io.IOException;

public class Main {

    int H, W, n;
    int x, y;
    String s, t;

    boolean okByLR(){
        int lft = 0, rgt = 0;
        for(int i = 0; i < n; i++){
            if(s.charAt(i) == 'L'){
                rgt--;
            } else {
                lft++;
            }
            // --
            if(t.charAt(i) == 'L'){
                lft--;
            } else {
                rgt++;
            }
            //---
            if(lft < 0 && (y + lft < 1)){
                return false;
            }
            if(rgt > 0 && (y + rgt > W)){
                return false;
            }
        }
        return true;
    }

    boolean okByUD(){
        int up = 0, down = 0;
        for(int i = 0; i < n; i++){
            if(s.charAt(i) == 'U'){
                down--;
            } else {
                up++;
            }
            //---
            if(t.charAt(i) == 'U'){
                up--;
            } else {
                down++;
            }
            //--
            if(up < 0 && (x - up < 1)){
                return false;
            }
            if(down > 0 && (x + down > H)){
                return false;
            }
        }
        return true;
    }

    void run() throws IOException {
        Reader in = new Reader();
        H = in.nextInt();
        W = in.nextInt();
        n = in.nextInt();
        x = in.nextInt();
        y = in.nextInt();
        s = in.readLine();
        t = in.readLine();

        if(okByUD() == false || okByLR() == false){
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    static class Reader {
        final private int bufferSize = 1 << 16;
        final private DataInputStream din;
        final private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader(){
            din = new DataInputStream(System.in);
            buffer = new byte[bufferSize];
            bufferPointer = bytesRead = 0;
        }

        public Reader(String fileName) throws IOException {
            din = new DataInputStream(new FileInputStream(fileName));
            buffer = new byte[bufferSize];
            bufferPointer = bytesRead = 0;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, bufferSize);
            if(bytesRead == -1){
                buffer[0] = -1;
            }
        }

        private byte read() throws IOException {
            if(bufferPointer == bytesRead){
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }

        private void close() throws IOException {
            if(din == null){
                return ;
            }
            din.close();
        }

        public String readLine() throws IOException {
            byte[] buf = new byte[200005];
            int cnt = 0, c;
            while((c = read()) != -1){
                if(c == '\n'){
                    break;
                }
                buf[cnt++] = (byte)c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException { 
            int ret = 0; 
            byte c = read(); 
            while (c <= ' ') c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read();
            do{ 
                ret = ret * 10 + c - '0'; 
            } while ((c = read()) >= '0' && c <= '9'); 
            if (neg) 
                return -ret; 
            return ret; 
        }

        public long nextLong() throws IOException { 
            long ret = 0; 
            byte c = read(); 
            while (c <= ' ') c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do { 
                ret = ret * 10 + c - '0'; 
            } while ((c = read()) >= '0' && c <= '9'); 
            if (neg) 
                return -ret; 
            return ret; 
        }

        public double nextDouble() throws IOException { 
            double ret = 0, div = 1; 
            byte c = read(); 
            while (c <= ' ') c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 
            if (c == '.'){
                while ((c = read()) >= '0' && c <= '9'){ 
                    ret += (c - '0') / (div *= 10); 
                } 
            }
            if (neg) 
                return -ret; 
            return ret; 
        } 
    }
}

import java.util.Scanner;
import java.util.stream.Stream;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // マス取得
        int[] nums = Stream.of(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        int h = nums[0];
        int w = nums[1];
        int n = nums[2];

        // スタート位置取得
        int[] poss = Stream.of(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        int posH = poss[0];
        int posW = poss[1];

        // 方向取得
        String[] dirs = new String[2];
        for (int i = 0; i < 2; i++) {
            dirs[i] = sc.nextLine();
        }

        if (isOut(n, w, w - posW, dirs[0], dirs[1], "L", "R")) {
            System.out.println("NO");
            return;
        }

        if (isOut(n, w, posW, dirs[0], dirs[1], "R", "L")) {
            System.out.println("NO");
            return;
        }

        if (isOut(n, h, h - posH, dirs[0], dirs[1], "U", "D")) {
            System.out.println("NO");
            return;
        }

        if (isOut(n, h, posH, dirs[0], dirs[1], "D", "U")) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
    }

    private static boolean isOut(int n, int maxHW, int startPos, String tDir, String aDir, String t, String a) {
        String[] tDirs = tDir.split("");
        String[] aDirs = aDir.split("");
        for (int i = 0; i < n; i++) {
            // 高橋くんのターン
            if (tDirs[i].equals(t)) {
                if (++startPos > maxHW) {
                    return true;
                }
            }

            // 青木くんのターン
            if (aDirs[i].equals(a)) {
                if (startPos - 1 > 0) {
                    startPos--;
                }
            }
        }
        return false;
    }

    private static int getCount(String str, char target){
        int count = 0;

        for(char x: str.toCharArray()){
            if(x == target){
                count++;
            }
        }

        return count;
    }
}

