    private void solveD() {
        int n = nextInt();
        String s = next();
        int open = 0;
        int close = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                open++;
            } else {
                if (open == 0)
                    close++;
                else
                    open--;
            }
        }

        /*
        左に(を、右に)を足せば()の組を作るのは可能
        そして、辞書順最小も達成できる
         */
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < close; i++)
            sb.append('(');
        sb.append(s);
        for (int i = 0; i < open; i++)
            sb.append(')');
        out.println(sb.toString());
    }

    /**
     * https://atcoder.jp/contests/agc033/tasks/agc033_b
     * B - LRUD Game
     * <p>
     * https://betrue12.hateblo.jp/entry/2019/05/14/222544
     */
    private void solveE() {
        int h = nextInt();
        int w = nextInt();
        int n = nextInt();
        int sr = nextInt() - 1;
        int sc = nextInt() - 1;
        String s = next();
        String t = next();
        int[] S = new int[200000];
        int[] T = new int[200000];
        for (int i = 0; i < n; i++) {
            switch (s.charAt(i)) {
                case 'U':
                    S[i] = 0;
                    break;
                case 'D':
                    S[i] = 1;
                    break;
                case 'L':
                    S[i] = 2;
                    break;
                case 'R':
                    S[i] = 3;
                    break;
            }
            switch (t.charAt(i)) {
                case 'U':
                    T[i] = 0;
                    break;
                case 'D':
                    T[i] = 1;
                    break;
                case 'L':
                    T[i] = 2;
                    break;
                case 'R':
                    T[i] = 3;
                    break;
            }
        }

        for (int time = 0; time < 2; time++) {
            int add = 2 * time + 1;
            int sub = 2 * time;
            int start = (time == 0 ? sr : sc);
            int hw = (time == 0 ? h : w);
            long mx = hw - 1;
            long mn = 0;
            for (int i = n - 1; i >= 0; i--) {
                if (T[i] == sub) {
                    mx = min(hw - 1, mx + 1);
                } else if (T[i] == add) {
                    mn = max(0, mn - 1);
                }
                if (S[i] == add) {
                    mx--;
                } else if (S[i] == sub) {
                    mn++;
                }
                if (mn > mx) {
                    out.println("NO");
                    return;
                }
            }
            if (!(mn <= start && start <= mx)) {
                out.println("NO");
                return;
            }
        }
        out.println("YES");
    }

