public class Main {
	static final long MOD=1000000007;//998244353;
	static long ans;
	public static void main(String[] args) {
		PrintWriter out = new PrintWriter(System.out);
		InputReader sc=new InputReader(System.in);
		int H=sc.nextInt();
		int W=sc.nextInt();
		int N=sc.nextInt();
		int R=sc.nextInt()-1;
		int C=sc.nextInt()-1;
		char[] S=sc.next().toCharArray();
		char[] T=sc.next().toCharArray();
		if (f(H, S, T, 'U', 'D', R)&&f(W, S, T, 'R', 'L', C)) {
			System.out.println("YES");
		}else {
			System.out.println("NO");
		}
 	}
	static boolean f(int HorW,char[] S,char[] T,char p, char m,int Fist) {
		int right=HorW-1;
		int left=0;
		for (int i = 0; i < S.length; i++) {
			if (T[S.length-1-i]==p) {
				left=Math.max(left-1, 0);
			}else if (T[S.length-1-i]==m) {
				right=Math.min(HorW-1, right+1);
			}
			if (S[T.length-1-i]==p) {
				right--;
			}else if (S[T.length-1-i]==m) {
				left++;
			}
			if (right<left) {
				return false;
			}
		}
		if (Fist>=left&&Fist<=right) {
			return true;
		}else {
			return false;
		}
	}
	static class InputReader { 
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;
		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
