public class Main {

	InputStream is;
	PrintWriter out;
	String INPUT = "";

	private static final long M = 1000000007;

	void solve() {
		int h = ni();
		int w = ni();

		int n = ni();

		int[] dp = new int[4];
		dp[0] = dp[1] = ni() - 1;
		dp[2] = dp[3] = ni() - 1;

		String s1 = ns();
		String s2 = ns();

		for (int i = 0; i < n; i++) {
			switch (s1.charAt(i)) {
			case 'L':
				dp[2]--;
				break;
			case 'R':
				dp[3]++;
				break;
			case 'U':
				dp[0]--;
				break;
			case 'D':
				dp[1]++;
				break;
			}
			if (dp[0] < 0 || dp[1] >= n || dp[2] < 0 || dp[3] >= w) {
				out.println("No");
				return;
			}
			switch (s2.charAt(i)) {
			case 'L':
				dp[3]--;
				break;
			case 'R':
				dp[2]++;
				break;
			case 'U':
				dp[1]--;
				break;
			case 'D':
				dp[0]++;
				break;
			}
			dp[1] = Math.max(dp[1], 0);
			dp[0] = Math.min(dp[0], h - 1);
			dp[3] = Math.max(dp[3], 0);
			dp[2] = Math.min(dp[2], w - 1);
