                case 'L':
                    T[i] = 2;
                    break;
                case 'R':
                    T[i] = 3;
                    break;
            }
        }

        for (int time = 0; time < 2; time++) {
            int add = 2 * time + 1;
            int sub = 2 * time;
            int start = (time == 0 ? sr : sc);
            int hw = (time == 0 ? h : w);
            long mx = hw - 1;
            long mn = 0;
            for (int i = n - 1; i >= 0; i--) {
                if (T[i] == sub) {
                    mx = min(hw - 1, mx + 1);
                } else if (T[i] == add) {
                    mn = max(0, mn - 1);
