		for (int i = 0; i < n; i++) {
			if (s.charAt(i) == 'L') {
				tsuml[i + 1] = tsuml[i] + 1;
			} else if (s.charAt(i) == 'R') {
				tsumr[i + 1] = tsumr[i] + 1;
			} else if (s.charAt(i) == 'U') {
				tsumu[i + 1] = tsumu[i] + 1;
			} else {
				tsumd[i + 1] = tsumd[i] + 1;
			}
		}
		int[] asuml = new int[n + 1];
		int[] asumr = new int[n + 1];
		int[] asumu = new int[n + 1];
		int[] asumd = new int[n + 1];
		for (int i = 0; i < n; i++) {
			if (t.charAt(i) == 'L') {
				asuml[i + 1] = asuml[i] + 1;
			} else if (t.charAt(i) == 'R') {
				asumr[i + 1] = asumr[i] + 1;
			} else if (t.charAt(i) == 'U') {
				asumu[i + 1] = asumu[i] + 1;
			} else {
				asumd[i + 1] = asumd[i] + 1;
			}
