    int H, W, n;
    int x, y;
    String s, t;

    boolean okByLR(){
        int lft = y, rgt = y;
        for(int i = 0; i < n; i++){
            if(s.charAt(i) == 'L'){
                lft--;
            } else if(s.charAt(i) == 'R'){
                rgt++;
            }
            //---
            if(lft < 1 || rgt > W){
                return false;
            }
            //---
            if(t.charAt(i) == 'L'){
                if(rgt > 1){
                    rgt--;
                }
            } else if(t.charAt(i) == 'R'){
                if(lft < W){
                    lft++;
                }
            }
        }
        return true;
    }

    boolean okByUD(){
        int up = x, down = x;
        for(int i = 0; i < n; i++){
            if(s.charAt(i) == 'U'){
                up--;
            } else if(s.charAt(i) == 'D'){
                down++;
            }
            //---
            if(up < 1 || down > H){
                return false;
            }
            //---
            if(t.charAt(i) == 'U'){
                if(down > 1){
                    down--;
                }
            } else if(t.charAt(i) == 'D'){
                if(up < H){
                    up++;
                }
            }
        }
        return true;
    }

    void run() throws IOException {
        Reader in = new Reader();
        H = in.nextInt();
        W = in.nextInt();
        n = in.nextInt();
        x = in.nextInt();
        y = in.nextInt();
        s = in.readLine();
        t = in.readLine();

        if(okByUD() == false || okByLR() == false){
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    static class Reader {
        final private int bufferSize = 1 << 16;
        final private DataInputStream din;
        final private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader(){
            din = new DataInputStream(System.in);
            buffer = new byte[bufferSize];
            bufferPointer = bytesRead = 0;
        }

        public Reader(String fileName) throws IOException {
            din = new DataInputStream(new FileInputStream(fileName));
            buffer = new byte[bufferSize];
            bufferPointer = bytesRead = 0;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, bufferSize);
            if(bytesRead == -1){
                buffer[0] = -1;
            }
        }

        private byte read() throws IOException {
            if(bufferPointer == bytesRead){
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }

        private void close() throws IOException {
            if(din == null){
                return ;
            }
            din.close();
        }

        public String readLine() throws IOException {
            byte[] buf = new byte[64];
            int cnt = 0, c;
            while((c = read()) != -1){
                if(c == '\n'){
                    break;
                }
                buf[cnt++] = (byte)c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException { 
            int ret = 0; 
            byte c = read(); 
            while (c <= ' ') c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read();
            do{ 
                ret = ret * 10 + c - '0'; 
            } while ((c = read()) >= '0' && c <= '9'); 
            if (neg) 
                return -ret; 
            return ret; 
        }

        public long nextLong() throws IOException { 
            long ret = 0; 
            byte c = read(); 
            while (c <= ' ') c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do { 
                ret = ret * 10 + c - '0'; 
            } while ((c = read()) >= '0' && c <= '9'); 
            if (neg) 
                return -ret; 
            return ret; 
        }

        public double nextDouble() throws IOException { 
            double ret = 0, div = 1; 
            byte c = read(); 
            while (c <= ' ') c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 
            if (c == '.'){
                while ((c = read()) >= '0' && c <= '9'){ 
                    ret += (c - '0') / (div *= 10); 
                } 
            }
            if (neg) 
                return -ret; 
            return ret; 
        } 
    }
}

import java.util.*;
import java.lang.*;

public class Main {
	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int h = scanner.nextInt();
		int w = scanner.nextInt();
		int n = scanner.nextInt();
		int sr = scanner.nextInt();
		int sc = scanner.nextInt();
		String s = scanner.next();
		String t = scanner.next();
		boolean end = false;
		//左から
		int hidari = sc;
		if (s.charAt(0) == 'L') {
			hidari--;
		}
		for (int i = 0; i < n - 1; i++) {
			if (hidari == 0) {
				end = true;
				break;
			} else {
				if (t.charAt(i) == 'R') {
					hidari = Math.min(hidari + 1, w);
				}
				if (s.charAt(i + 1) == 'L') {
					hidari--;
				}
			}
		}
		if (hidari == 0) {
			end = true;
		}
		//右から
		int migi = sc;
		if (s.charAt(0) == 'R') {
			migi++;
		}
		for (int i = 0; i < n - 1; i++) {
			if (migi == w + 1) {
				end = true;
				break;
			} else {
				if (t.charAt(i) == 'L') {
					migi = Math.max(1, migi - 1);
				}
				if (s.charAt(i + 1) == 'R') {
					migi++;
				}
			}
		}
		if (migi == w + 1) {
			end = true;
		}
		//上
		int ue = sr;
		if (s.charAt(0) == 'U') {
			ue--;
		}
		for (int i = 0; i < n - 1; i++) {
			if (ue == 0) {
				end = true;
				break;
			} else {
				if (t.charAt(i) == 'D') {
					ue = Math.max(ue + 1, h);
				}
				if (s.charAt(i + 1) == 'U') {
					ue--;
				}
			}
		}
		if (ue == 0) {
			end = true;
		}
		//下から
		int sita = sr;
		if (s.charAt(0) == 'D') {
			sita++;
		}
		for (int i = 0; i < n - 1; i++) {
			if (sita == h + 1) {
				end = true;
				break;
			} else {
				if (t.charAt(i) == 'U') {
					sita = Math.max(1, sita - 1);
				}
				if (s.charAt(i + 1) == 'D') {
					sita++;
				}
			}
		}
		if (sita == h + 1) {
			end = true;
		}
		if (!end) {
			System.out.println("YES");
		} else {
			System.out.println("NO");
		}
	}
}

