/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        BLRUDGame solver = new BLRUDGame();
        solver.solve(1, in, out);
        out.close();
    }

    static class BLRUDGame {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            out.setBoolLabel(LightWriter.BoolLabel.YES_NO_ALL_UP);
            int h = in.ints(), w = in.ints(), n = in.ints();
            int sr = in.ints() - 1, sc = in.ints() - 1;
            String s = in.string(), t = in.string();

            {
                int c = sc;
                for (int i = 0; i < n; i++) {
                    if (s.charAt(i) == 'L') c--;
                    if (c == -1) {
                        out.noln();
                        return;
                    }
                    if (t.charAt(i) == 'R' && c + 1 < w) c++;
                }

                c = sc;
                for (int i = 0; i < n; i++) {
                    if (s.charAt(i) == 'R') c++;
                    if (c == w) {
                        out.noln();
                        return;
                    }
                    if (t.charAt(i) == 'L' && c > 0) c--;
                }
            }

            {
                int r = sr;
                for (int i = 0; i < n; i++) {
                    if (s.charAt(i) == 'U') r--;
                    if (r == -1) {
                        out.noln();
                        return;
                    }
                    if (t.charAt(i) == 'D' && r + 1 < h) r++;
                }

                r = sr;
                for (int i = 0; i < n; i++) {
                    if (s.charAt(i) == 'D') r++;
                    if (r == h) {
                        out.noln();
                        return;
                    }
                    if (t.charAt(i) == 'U' && r > 0) r--;
                }
            }

            out.yesln();
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;
        private LightWriter.BoolLabel boolLabel = LightWriter.BoolLabel.YES_NO_FIRST_UP;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new BufferedWriter(new OutputStreamWriter(out, Charset.defaultCharset())));
        }

        public void setBoolLabel(LightWriter.BoolLabel label) {
            this.boolLabel = Objects.requireNonNull(label);
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!breaked) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(boolean b) {
            return ans(boolLabel.transfer(b));
        }

        public LightWriter yesln() {
            return ans(true).ln();
        }

        public LightWriter noln() {
            return ans(false).ln();
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

        public enum BoolLabel {
            YES_NO_FIRST_UP("Yes", "No"),
            YES_NO_ALL_UP("YES", "NO"),
            YES_NO_ALL_DOWN("yes", "no"),
            POSSIBLE_IMPOSSIBLE_FIRST_UP("Possible", "Impossible"),
            POSSIBLE_IMPOSSIBLE_ALL_UP("POSSIBLE", "IMPOSSIBLE"),
            POSSIBLE_IMPOSSIBLE_ALL_DOWN("possible", "impossible"),
            FIRST_SECOND_FIRST_UP("First", "Second"),
            ;
            private final String positive;
            private final String negative;

            BoolLabel(String positive, String negative) {
                this.positive = positive;
                this.negative = negative;
            }

            private String transfer(boolean f) {
                return f ? positive : negative;
            }

        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();
        int N = sc.nextInt();
        int Sr = sc.nextInt();
        int Sc = sc.nextInt();
        String S = sc.next();
        String T = sc.next();


        //Row
        int left=0;
        int right=W -1;

        for (int i = N-1; i >=0; i--) {
            char s = S.charAt(i);
            char t = T.charAt(i);
            if(t=='R') left = Math.max(left-1,0);
            if(t=='L') right = Math.min(right+1,W-1);
            if(s=='L') left++;
            if(s=='R') right--;

            if(left>right){
                System.out.println("NO");
                return;
            }
        }

        int top=0;
        int bottom=H -1;
        for (int i = N-1; i >= 0 ; i--) {
            char s = S.charAt(i);
            char t = T.charAt(i);
            if(t=='D') top = Math.max(top-1,0);
            if(t=='U') bottom = Math.min(bottom+1,H-1);
            if(s=='U') top++;
            if(s=='D') bottom--;

            if(top>bottom){
                System.out.println("NO");
                return;
            }

        }

        if( left<=Sc-1 && Sc-1 <= right && top<= Sr-1 && Sr-1 <= bottom){
            System.out.println("YES");
        }else{
            System.out.println("NO");
        }
    }
}

