                        break;
                    case 'U':
                        switch (T[i])
                        {
                            case 'L':
                                if (upper < 0)
                                    upper = 0;
                                else
                                    upper++;
                                if (right > 0)
                                    right++;
                                break;
                            case 'R':
                                if (upper < 0)
                                    upper = 0;
