                                    upper++;
                                break;
                            case 'D':
                                if (upper < 0)
                                    upper = 0;
                                break;
                            default:
                                break;
                        }
                        break;
                    case 'D':
                        switch (T[i])
                        {
                            case 'L':
                                if (lower >= H)
                                    lower = H - 1;
                                else
                                    lower--;
                                if (right > 0)
                                    right++;
                                break;
