        }

        static bool ToR()
        {
            var now = SW;
            for (int i = 0; i < N; i++)
            {
                if (S[i] == 'R') now++;
                if (W < now) return true;
                if (T[i] == 'L' && now > 1) now--;
            }
            return false;
        }

        static bool ToD()
        {
            var now = SH;
            for (int i = 0; i < N; i++)
            {
                if (S[i] == 'D') now++;
                if (W < now) return true;
                if (T[i] == 'U' && now > 1) now--;
            }
            return false;
        }

        static bool ToL()
        {
            var now = SW;
            for (int i = 0; i < N; i++)
            {
                if (S[i] == 'L') now--;
                if (0 >= now) return true;
                if (T[i] == 'R' && now < W) now++;
            }
            return false;
        }

        static bool ToU()
        {
