                else if (tkDflag && ao == 'U') { if (tkD_ < h) ++tkD_; }
                else if (tkUflag && ao == 'D') { if (tkU_ > 1) --tkU_; }

                char tk = s[i];

                if (tk == 'R') { tkRflag = true; --tkR_; if (tkR_ < tkL_) flag = false; }
                else if (tk == 'L') { tkLflag = true; ++tkL_; if (tkL_ > tkR_) flag = false; }
                else if (tk == 'U') { tkUflag = true; ++tkU_; if (tkU_ > tkD_) flag = false; }
                else if (tk == 'D') { tkDflag = true; --tkD_; if (tkD_ < tkU_) flag = false; }
            }

            if (flag)
            {
                flag = (tkL_ <= x && x <= tkR_ && tkU_ <= x && x <= tkD_);
            }

            Console.WriteLine("{0}", flag ? "YES" : "NO");
        }
    }
}

