class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var H = sc.ReadInt();
        var W = sc.ReadInt();
        var N = sc.ReadInt();
        var Sh = sc.ReadInt();
        var Sw = sc.ReadInt();
        var S = sc.ReadStr();
        var T = sc.ReadStr();

        // この矩形の範囲内であれば後手の勝ち
        var u = 1;
        var b = H;
        var l = 1;
        var r = W;
        for (int i = N - 1; i >= 0; i--)
        {
            switch (T[i])
            {
                case 'U':
                    b = Math.Min(H, b + 1);
                    break;
                case 'D':
                    u = Math.Max(1, u - 1);
                    break;
                case 'L':
                    r = Math.Min(W, r + 1);
                    break;
                case 'R':
                    l = Math.Max(1, l - 1);
                    break;
            }
            switch (S[i])
            {
                case 'U':
                    u++;
                    break;
                case 'D':
                    b--;
                    break;
                case 'L':
                    l++;
                    break;
                case 'R':
                    r--;
                    break;
            }
            if (r == 0 || l == W + 1 || b == 0 || u == H + 1)
            {
                Console.WriteLine("NO");
                return;
            }
        }
        if ((u <= Sh && Sh <= b) && (l <= Sw && Sw <= r))
        {
            Console.WriteLine("YES");
        }
        else
        {
            Console.WriteLine("NO");
        }
    }
    static Scanner sc = new Scanner();
}
