class Battle
{
    int first;
    int length;
    public List<Status> statuses = new List<Status>();
    public Battle(int first, int length)
    {
        this.first = first;
        this.length = length;
    }

    public bool Result()
    {
        var safeleft = 0;
        var saferight = length - 1;
        for (int i = statuses.Count - 1; i >= 0; i--)
        {
            var st = statuses[i];
            if (st.takahashi)
            {
                if (st.plus)
                {
                    saferight--;
                }
                else
                {
                    safeleft++;
                }
            }
            else
            {
                if (st.plus)
                {
                    safeleft = Math.Max(safeleft - 1, 0);
                }
                else
                {
                    saferight = Math.Min(saferight + 1, length - 1);
                }
            }
            if (saferight < 0 || length <= safeleft)
                return true;
        }
        return first < safeleft || saferight < first;
    }

}
