        var W = sc.ReadInt();
        var N = sc.ReadInt();
        var sh = sc.ReadInt();
        var sw = sc.ReadInt();
        var S = sc.ReadStr();
        var T = sc.ReadStr();
        var sumL1 = 0;
        var sumR1 = 0;
        var sumL2 = 0;
        var sumR2 = 0;
        var winLR = false;
        for (int i = 0; i < N; i++)
        {
            if (S[i] == 'L') sumL1++;
            if (S[i] == 'R') sumR1++;
            var dr = sumR1 - sumL2;
            if (sw + dr > W) winLR = true;
            var dl = sumL1 - sumR2;
            if (sw - dl <= 0) winLR = true;
            if (T[i] == 'L' && (sw + sumR1 > sumL2 + 1)) sumL2++;
            if (T[i] == 'R' && (W + 1 - sw + sumL1 > sumR2)) sumR2++;
        }
        var sumD1 = 0;
        var sumU1 = 0;
        var sumD2 = 0;
        var sumU2 = 0;
        var winUD = false;
        for (int i = 0; i < N; i++)
        {
            if (S[i] == 'D') sumD1++;
            if (S[i] == 'U') sumU1++;
            var du = sumU1 - sumD2;
            if (sh + du > H) winUD = true;
            var dd = sumD1 - sumU2;
            if (sh - dd <= 0) winUD = true;
            if (T[i] == 'D' && (sh + sumD1 > sumD2 + 1)) sumD2++;
            if (T[i] == 'U' && (H + 1 - sh + sumD1 > sumU2)) sumU2++;
        }
        if (winLR || winUD)
        {
            Console.WriteLine("NO");
        }
        else
        {
            Console.WriteLine("YES");
        }
    }
