    public class Program
    {
        public static string WriteBoard(bool[,,] board, int i, int H, int W)
        {
            var sb = new System.Text.StringBuilder();
            for (int h = 0; h < H; h++)
            {
                for (int w = 0; w < W; w++)
                    sb.Append(board[i, h, w] ? 'Y' : 'N');
                sb.AppendLine();
            }
            return sb.ToString();
        }
        public object Calc()
        {
            var line = consoleReader.SplitInt32();
            var H = line[0];
            var W = line[1];
            var N = line[2];

            line = consoleReader.SplitInt32();
            var sr = line[0];
            var sc = line[1];

            var S = consoleReader.String();
            var T = consoleReader.String();

            int right = W;
            int left = -1;
            int lower = H;
            int upper = -1;

            switch (S[N - 1])
            {
                case 'L':
                    left = 0;
                    break;
                case 'R':
                    right = W;
                    break;
                case 'U':
                    upper = 0;
                    break;
                case 'D':
                    lower = H - 1;
                    break;
                default:
                    break;
            }
            for (int i = N - 2; i >= 0; i--)
            {
                switch (S[i])
                {
                    case 'L':
                        switch (T[i])
                        {
                            case 'L':
                                if (left < 0)
                                    left = 0;
                                else
                                    left++;
                                break;
                            case 'R':
                                break;
                            case 'U':
                                if (left < 0)
                                    left = 0;
                                else
                                    left++;

                                lower++;
                                break;
                            case 'D':
                                if (left < 0)
                                    left = 0;
                                else
                                    left++;

                                upper--;
                                break;
                            default:
                                break;
                        }
                        break;
                    case 'R':
                        switch (T[i])
                        {
                            case 'L':
                                break;
                            case 'R':
                                if (right >= W)
                                    right = W - 1;
                                else
                                    right--;
                                break;
                            case 'U':
                                if (right >= W)
                                    right = W - 1;
                                else
                                    right--;

                                lower++;
                                break;
                            case 'D':
                                if (right >= W)
                                    right = W - 1;
                                else
                                    right--;

                                upper--;
                                break;
                            default:
                                break;
                        }
                        break;
                    case 'U':
                        if (upper < 0)
                            upper = 0;
                        switch (T[i])
                        {
                            case 'L':
                                if (upper < 0)
                                    upper = 0;
                                else
                                    upper++;

                                right++;
                                break;
                            case 'R':
                                if (upper < 0)
                                    upper = 0;
                                else
                                    upper++;

                                left--;
                                break;
                            case 'U':
                                if (upper < 0)
                                    upper = 0;
                                else
                                    upper++;
                                break;
                            case 'D':
                                break;
                            default:
                                break;
                        }
                        break;
                    case 'D':
                        if (lower >= W)
                            lower = H - 1;
                        switch (T[i])
                        {
                            case 'L':
                                if (lower >= H)
                                    lower = H - 1;
                                else
                                    lower--;

                                right++;
                                break;
                            case 'R':
                                if (lower >= H)
                                    lower = H - 1;
                                else
                                    lower--;

                                left--;
                                break;
                            case 'U':
                                break;
                            case 'D':
                                if (lower >= H)
                                    lower = H - 1;
                                else
                                    lower--;
                                break;
                            default:
                                break;
                        }
                        break;
                    default:
                        break;
                }
            }
            return sr - 1 <= upper || lower <= sr - 1 || sc - 1 <= left || right <= sc - 1 ? "NO" : "YES";
        }

        const int mod = 1000000007;
        private readonly ConsoleReader consoleReader;
        public Program() : this(new ConsoleReader()) { }
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program().Calc());
    }

