	int CharToX(char c) => c == 'L' ? -1 : c == 'R' ? 1 : 0;
	int CharToY(char c) => c == 'U' ? -1 : c == 'D' ? 1 : 0;
	int[] StringToX(string S) => S.Select(CharToX).ToArray();
	int[] StringToY(string S) => S.Select(CharToY).ToArray();
