	}
	bool Safe(int x, int X, int N, int[] S, int[] T)
	{
		int l = 0, r = X;
		for (var n = N - 1; n >= 0; n--)
		{
			// T[n]
			if (T[n] > 0) l = Max(l - 1, 0);
			else if (T[n] < 0) r = Min(r + 1, X);
			// S[n]
			if (S[n] > 0) { if (r - l == 1) return false; r--; }
			else if (S[n] < 0) { if (r - l == 1) return false; l++; }
		}
		return l <= x && x < r;
	}
}

