    {
        public static string WriteBoard(bool[,,] board, int i, int H, int W)
        {
            var sb = new System.Text.StringBuilder();
            for (int h = 0; h < H; h++)
            {
                for (int w = 0; w < W; w++)
                    sb.Append(board[i, h, w] ? 'Y' : 'N');
                sb.AppendLine();
            }
            return sb.ToString();
        }
        public object Calc()
        {
            var line = consoleReader.SplitInt32();
            var H = line[0];
            var W = line[1];
            var N = line[2];

            line = consoleReader.SplitInt32();
            var sr = line[0];
            var sc = line[1];

            var S = consoleReader.String();
            var T = consoleReader.String();

            int right = W;
            int left = -1;
            int lower = H;
            int upper = -1;

            for (int i = N - 1; i >= 0; i--)
            {
                switch (S[i])
                {
                    case 'L':
                        switch (T[i])
                        {
                            case 'L':
                                if (left < 0)
                                    left = 0;
                                else
                                    left++;
                                break;
                            case 'R':
                                if (left < 0)
                                    left = 0;
                                break;
                            case 'U':
                                if (left < 0)
                                    left = 0;
                                else
                                    left++;
                                if (lower > 0)
                                    lower++;
                                break;
                            case 'D':
                                if (left < 0)
                                    left = 0;
                                else
                                    left++;
                                if (upper < W - 1)
                                    upper--;
                                break;
                            default:
                                break;
                        }
                        break;
                    case 'R':
                        switch (T[i])
                        {
                            case 'L':
                                if (right >= W)
                                    right = W - 1;
                                break;
                            case 'R':
                                if (right >= W)
                                    right = W - 1;
                                else
                                    right--;
                                break;
                            case 'U':
                                if (right >= W)
                                    right = W - 1;
                                else
                                    right--;
                                if (lower > 0)
                                    lower++;
                                break;
                            case 'D':
                                if (right >= W)
                                    right = W - 1;
                                else
                                    right--;
                                if (upper < W - 1)
                                    upper--;
                                break;
                            default:
                                break;
                        }
                        break;
                    case 'U':
                        switch (T[i])
                        {
                            case 'L':
                                if (upper < 0)
                                    upper = 0;
                                else
                                    upper++;
                                if (right > 0)
                                    right++;
                                break;
                            case 'R':
                                if (upper < 0)
                                    upper = 0;
                                else
                                    upper++;
                                if (left < W - 1)
                                    left--;
                                break;
                            case 'U':
                                if (upper < 0)
                                    upper = 0;
                                else
                                    upper++;
                                break;
                            case 'D':
                                if (upper < 0)
                                    upper = 0;
                                break;
                            default:
                                break;
                        }
                        break;
                    case 'D':
                        switch (T[i])
                        {
                            case 'L':
                                if (lower >= H)
                                    lower = H - 1;
                                else
                                    lower--;
                                if (right > 0)
                                    right++;
                                break;
                            case 'R':
                                if (lower >= H)
                                    lower = H - 1;
                                else
                                    lower--;
                                if (left < W - 1)
                                    left--;
                                break;
                            case 'U':
                                if (lower >= H)
                                    lower = H - 1;
                                break;
                            case 'D':
                                if (lower >= H)
                                    lower = H - 1;
                                else
                                    lower--;
                                break;
                            default:
                                break;
                        }
                        break;
                    default:
                        break;
                }
                if (lower == 0 || upper == H - 1 || left == W - 1 || right == 0) return "NO";
            }
            return sr - 1 <= upper || lower <= sr - 1 || sc - 1 <= left || right <= sc - 1 ? "NO" : "YES";
        }

