using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Diagnostics;

static class CodeJam
{
    static bool Solve(int H, int W, int N, int r, int c, string S, string T)
    {
        int U = 0, D = H - 1, L = 0, R = W - 1;
        for (int i = N - 1; i >= 0; --i)
        {
            switch (T[i])
            {
            case 'L': R = Math.Min(R + 1, W - 1); break;
            case 'R': L = Math.Max(L - 1, 0); break;
            case 'U': D = Math.Min(D + 1, H - 1); break;
            case 'D': U = Math.Max(U - 1, 0); break;
            }
            switch (S[i])
            {
            case 'L': L = Math.Min(L + 1, W); break;
            case 'R': R = Math.Max(R - 1, -1); break;
            case 'U': U = Math.Min(U + 1, H); break;
            case 'D': D = Math.Max(D - 1, -1); break;
            }
            if (L == W || R == -1 || U == H || D == -1) { return false; }
        }
        return U <= r && r <= D && L <= c && c <= R;
    }

    static void Main(string[] args)
    {
        int[] V1 = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int[] V2 = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        var S = Console.ReadLine();
        var T = Console.ReadLine();
        Console.WriteLine(Solve(V1[0], V1[1], V1[2], V2[0] - 1, V2[1] - 1, S, T) ? "YES" : "NO");
    }
}

