    public void AtCoder()
    {
        string[] s;
        s = Console.ReadLine().Split(' ');

        int h, w, n;
        h = int.Parse(s[0]);
        w = int.Parse(s[1]);
        n = int.Parse(s[2]);

        s = Console.ReadLine().Split(' ');
        int x, y;
        y = int.Parse(s[0]);
        x = int.Parse(s[1]);

        string a = Console.ReadLine();
        string b = Console.ReadLine();

        char[] d1 = new char[n+1];
        char[] d2 = new char[n+1];
        for(int i=0; i<n; i++)
        {
            d1[i + 1] = a[i];
            d2[i + 1] = b[i];
        }

        int[] dpl = new int[n+1];
        int[] dpr = new int[n+1];
        int[] dpu = new int[n+1];
        int[] dpd = new int[n+1];

        dpl[0] = x; dpr[0] = x;
        dpu[0] = y; dpd[0] = y;

        bool f = true;
        for(int i=1; i<=n; i++)
        {
            dpl[i] = dpl[i - 1];
            dpr[i] = dpr[i - 1];
            if (d1[i] == 'L') dpl[i]--;
            if (dpl[i] < 1) f = false;
            if (d1[i] == 'R') dpr[i]++;
            if (dpr[i] > w) f = false;
            if (d2[i] == 'L' && dpr[i] > 1) dpr[i]--;
            if (d2[i] == 'R' && dpl[i] < w) dpl[i]++;
        }
        for (int i = 1; i <= n; i++)
        {
            dpu[i] = dpu[i - 1];
            dpd[i] = dpd[i - 1];
            if (d1[i] == 'U') dpu[i]--;
            if (dpu[i] < 1) f = false;
            if (d1[i] == 'D') dpd[i]++;
            if (dpd[i] > h) f = false;
            if (d2[i] == 'U' && dpd[i] > 1) dpd[i]--;
            if (d2[i] == 'D' && dpu[i] < h) dpu[i]++;
        }

        if (f) Console.WriteLine("YES");
        else Console.WriteLine("NO");
    }
