	public class Solver : SolverBase
	{
		public void Run() {
			var ary = ReadIntArray();
			var H = ary[0];
			var W = ary[1];
			var N = ary[2];
			ary = ReadIntArray();
			var Sr = ary[0];
			var Sc = ary[1];
			var S = ReadLine();
			var T = ReadLine();

			// 左右生存限界 ※grid内を 1 ~ W とする
			int limR = W;
			int limL = 1;
			int limU = 1;
			int limD = H;
			for (int i = N - 1; i >= 0; i--) {
				// T側
				var c = T[i];
				if (c == 'R') limL = Math.Max(limL - 1, 1);
				else if (c == 'L') limR = Math.Min(limR + 1, W);
				else if (c == 'U') limD = Math.Min(limD + 1, H);
				else if (c == 'D') limU = Math.Max(limU - 1, 1);

				// S側
				c = S[i];
				if (c == 'R') limR--;
				else if (c == 'L') limL++;
				else if (c == 'U') limU++;
				else if (c == 'D') limD--;

				// 生存限界が左右/上下逆転（＝どこにいても落とされる）していたらアウト
				if (limR < limL || limD < limU) {
					WriteLine("NO");
					return;
				}
			}
			// 開始地点が生存範囲に入っている？
			var ret = (limL <= Sc && Sc <= limR && limU <= Sr && Sr <= limD);
			WriteLine(ret ? "YES" : "NO");
		}
