static class P
{
    static int n;
    static string s;
    static string t;
    static void Main()
    {
        var hwn = Console.ReadLine().Split().Select(int.Parse).ToArray();
        n = hwn[2];
        var rc = Console.ReadLine().Split().Select(int.Parse).ToArray();
        //どっちにも耐えられる状況
        //チェックメイトになる部分
        s = Console.ReadLine();
        t = Console.ReadLine();
        Console.WriteLine(Solve(hwn[0], rc[0] - 1, 'U', 'D') && Solve(hwn[1], rc[1] - 1, 'L', 'R') ? "YES" : "NO");
    }
    static bool Solve(int width, int point, char l, char r)
    {
        //0←L, R→n
        int deadR = -1;
        int deadL = width;
        for (int i = n - 1; i >= 0; i--)
        {
            //逆から見ているので、青木くんの巻き返し
            if (t[i] == r) deadL = Min(width, deadL + 1);
            if (t[i] == l) deadR = Max(-1, deadR - 1);
            if (s[i] == r) deadR = deadR + 1;
            if (s[i] == l) deadL = deadL - 1;
            if (deadR + 1 >= deadL) return false;
        }
        if (deadR < point && point < deadL) return true;
        else return false;
    }
}

