            var S = consoleReader.String();
            var T = consoleReader.String();

            int right = W;
            int left = -1;
            int lower = H;
            int upper = -1;

            for (int i = N - 1; i >= 0; i--)
            {
                switch (S[i])
                {
                    case 'L':
