                        {
                            case 'L':
                                if (left < 0)
                                    left = 0;
                                else
                                    left++;
                                break;
                            case 'R':
                                if (left < 0)
                                    left = 0;
                                break;
                            case 'U':
                                if (left < 0)
                                    left = 0;
                                else
