                                    left = 0;
                                else
                                    left++;
                                if (upper < W - 1)
                                    upper--;
                                break;
                            default:
                                break;
                        }
                        break;
                    case 'R':
                        switch (T[i])
                        {
                            case 'L':
                                if (right >= W)
