                    if (x > w)
                    {
                        flag = false;
                        break;
                    }
                }

                if (tk == 'L' && x <= xThreshold)
                {
                    --x;
                    if (x == 0)
                    {
                        flag = false;
                        break;
                    }
                }

                if (tk == 'U' && y <= yThreshold)
                {
                    --y;
                    if (y == 0)
                    {
                        flag = false;
                        break;
                    }
                }

                if (tk == 'D' && y >= yThreshold)
                {
                    ++y;
                    if (y > h)
                    {
                        flag = false;
                        break;
                    }
                }

                char ao = t[i];
                if (ao == 'R' && x < xThreshold)
                {
                    ++x;
                }
                if (ao == 'L' && x > xThreshold)
                {
                    --x;
                }
                if (ao == 'U' && y > yThreshold)
                {
                    --y;
                }
                if (ao == 'D' && y < yThreshold)
                {
                    ++y;
                }

            }

            Console.WriteLine("{0}", flag ? "YES" : "NO");
        }
    }
}

