class Program
{
    static void Main(string[] args)
    {
        var sc = new Scanner();
        int h = sc.NextInt();
        int w = sc.NextInt();
        int n = sc.NextInt();
        int r = sc.NextInt() - 1;
        int c = sc.NextInt() - 1;
        string s = sc.NextString();
        string t = sc.NextString();

        var d = new Dictionary<char, int>() { { 'L', 0 }, { 'R', 0 }, { 'U', 0 }, { 'D', 0 } };
        var e = new Dictionary<char, int>() { { 'L', 0 }, { 'R', 0 }, { 'U', 0 }, { 'D', 0 } };

        var rev = new Dictionary<char, char>() { { 'L', 'R' }, { 'R', 'L' }, { 'U', 'D' }, { 'D', 'U' } };
        for (int i = 0; i < n; i++)
        {
            d[s[i]]++;
            if (d['U'] > r || d['L'] > c || d['D'] >= (h - r) || d['R'] >= (w - c))
            {
                if (e[rev[s[i]]] > 0)
                {
                    d[s[i]]--;
                    e[rev[s[i]]]--;
                }
                else
                {
                    Console.WriteLine("NO");
                    return;
                }
            }
            if (d[rev[t[i]]] > 0)
            {
                d[rev[t[i]]]--;
            }
            else
            {
                d[t[i]]++;
                if (d['U'] > r || d['L'] > c || d['D'] >= (h - r) || d['R'] >= (w - c))
                {
                    d[t[i]]--;
                    continue;
                }
                e[t[i]]++;
            }
        }
        Console.WriteLine("YES");
    }

    static long Gcd(long a, long b)
    {
        if (a < b) return Gcd(b, a);
        if (b == 0) return a;
        return Gcd(b, a % b);
    }
}

