namespace AGC033_B
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] strs = Console.ReadLine().Split(' ');
            int h = int.Parse(strs[0]);
            int w = int.Parse(strs[1]);
            int n = int.Parse(strs[2]);

            string[] strs_ = Console.ReadLine().Split(' ');
            int y = int.Parse(strs_[0]);
            int x = int.Parse(strs_[1]);

            string s = Console.ReadLine();
            string t = Console.ReadLine();


            /*--w; --h;*/ /*--x; --y;*/


            //int xThreshold = (w+1) / 2;
            //int yThreshold = (h+1) / 2;
            float xThreshold = (w + 1) / 2.0f;
            float yThreshold = (h + 1) / 2.0f;

            bool flag = true;

            for (int i = 0; i < n; ++i)
            {
                char tk = s[i];
                //if (tk == 'R' && x >= xThreshold)
                if (tk == 'R' && x > xThreshold - 0.1f)
                {
                    ++x;
                    if (x > w)
                    {
                        flag = false;
                        break;
                    }
                }

                //if (tk == 'L' && x <= xThreshold)
                if (tk == 'L' && x < xThreshold + 0.1f)
                {
                    --x;
                    if (x == 0)
                    {
                        flag = false;
                        break;
                    }
                }

                //if (tk == 'U' && y <= yThreshold)
                if (tk == 'U' && y < yThreshold + 0.1f)
                    {
                    --y;
                    if (y == 0)
                    {
                        flag = false;
                        break;
                    }
                }

                //if (tk == 'D' && y >= yThreshold)
                if (tk == 'D' && y > yThreshold - 0.1f)
                    {
                    ++y;
                    if (y > h)
                    {
                        flag = false;
                        break;
                    }
                }

                char ao = t[i];
                if (ao == 'R' && x < xThreshold)
                {
                    ++x;
                }
                if (ao == 'L' && x > xThreshold)
                {
                    --x;
                }
                if (ao == 'U' && y > yThreshold)
                {
                    --y;
                }
                if (ao == 'D' && y < yThreshold)
                {
                    ++y;
                }

            }

            Console.WriteLine("{0}", flag ? "YES" : "NO");
        }
    }
