    {
        foreach (var item in source)
            yield return item;
        yield return element;
    }
    public static IEnumerable<TSource> Prepend<TSource>(this IEnumerable<TSource> source, TSource element)
    {
        yield return element;
        foreach (var item in source)
            yield return item;
    }
