public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Calc());

    #endregion
    public object Calc()
    {
        var H = cr.Int;
        var W = cr.Int;
        var N = cr.Int;

        var tate = new Battle(cr.Int0, H);
        var yoko = new Battle(cr.Int0, W);

        var takahashi = cr.Ascii;
        var aoki = cr.Ascii;
        for (int i = 0; i < N; i++)
        {
            switch (takahashi[i])
            {
                case 'U':
                    tate.statuses.Add(new Status { takahashi = true, plus = false });
                    break;
                case 'D':
                    tate.statuses.Add(new Status { takahashi = true, plus = true });
                    break;
                case 'L':
                    yoko.statuses.Add(new Status { takahashi = true, plus = false });
                    break;
                case 'R':
                    yoko.statuses.Add(new Status { takahashi = true, plus = true });
                    break;
            }
            switch (aoki[i])
            {
                case 'U':
                    tate.statuses.Add(new Status { plus = false });
                    break;
                case 'D':
                    tate.statuses.Add(new Status { plus = true });
                    break;
                case 'L':
                    yoko.statuses.Add(new Status { plus = false });
                    break;
                case 'R':
                    yoko.statuses.Add(new Status { plus = true });
                    break;
            }
        }

        return tate.Result() || yoko.Result() ? "NO" : "YES";
    }
}
class Battle
{
    int first;
    int length;
    public List<Status> statuses = new List<Status>();
    public Battle(int first, int length)
    {
        this.first = first;
        this.length = length;
    }

    public bool Result()
    {
        var safeleft = 0;
        var saferight = length - 1;
        for (int i = statuses.Count - 1; i >= 0; i--)
        {
            var st = statuses[i];
            if (st.takahashi)
            {
                if (st.plus)
                {
                    saferight--;
                }
                else
                {
                    safeleft++;
                }
            }
            else
            {
                if (st.plus)
                {
                    safeleft = Math.Max(safeleft - 1, 0);
                }
                else
                {
                    saferight = Math.Min(saferight + 1, length - 1);
                }
            }
            if (first < safeleft || saferight < first)
                return true;
        }
        return first < safeleft || saferight < first;
    }

}
