namespace AGC033_B
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] strs = Console.ReadLine().Split(' ');
            int h = int.Parse(strs[0]);
            int w = int.Parse(strs[1]);
            int n = int.Parse(strs[2]);

            string[] strs_ = Console.ReadLine().Split(' ');
            int y = int.Parse(strs_[0]);
            int x = int.Parse(strs_[1]);

            string s = Console.ReadLine();
            string t = Console.ReadLine();

            int tkR_ = w, tkL_ = 1, tkU_ = 1, tkD_ = h;

            bool tkRflag = false;
            bool tkLflag = false;
            bool tkUflag = false;
            bool tkDflag = false;

            bool flag = true;

            for (int i = n - 1; i >= 0; --i)
            {
                char ao = t[i];

                if (tkLflag && ao == 'R') { if (tkL_ > 1) --tkL_; }
                else if (tkRflag && ao == 'L') { if (tkR_ < w) ++tkR_; }
                else if (tkDflag && ao == 'U') { if (tkD_ < h) ++tkD_; }
                else if (tkUflag && ao == 'D') { if (tkU_ > 1) --tkU_; }

                char tk = s[i];

                if (tk == 'R') { tkRflag = true; --tkR_; if (tkR_ < 1) flag = false; }
                else if (tk == 'L') { tkLflag = true; ++tkL_; if (tkL_ > w) flag = false; }
                else if (tk == 'U') { tkUflag = true; ++tkU_; if (tkU_ > h) flag = false; }
                else if (tk == 'D') { tkDflag = true; --tkD_; if (tkD_ < 1) flag = false; }
            }

            if (flag)
            {
                flag = (tkL_ <= x && x <= tkR_ && tkU_ <= x && x <= tkD_);
            }

            Console.WriteLine("{0}", flag ? "YES" : "NO");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Diagnostics;

public class Program
{
    //public static readonly int Mod = 1000000007;

    public static void Main(string[] args)
    {
        // 2 ~ 2 * 10^5
        int YS = Scanner.Int;
        int XS = Scanner.Int;
        int N = Scanner.Int;

        int y = Scanner.Int;
        int x = Scanner.Int;

        int[] dir = new int['Z'];
        dir['U'] = 0;
        dir['R'] = 1;
        dir['D'] = 2;
        dir['L'] = 3;

        int[] rev = new int[4];
        rev[0] = 2;
        rev[2] = 0;
        rev[1] = 3;
        rev[3] = 1;

        int[] need = new int[4];
        need[0] = y;
        need[1] = XS - x + 1;
        need[2] = YS - y + 1;
        need[3] = x;

        bool[] horizon = new bool[4];
        horizon[0] = true;
        horizon[2] = true;

        int[] S = Scanner.String.Select(i => dir[i]).ToArray();
        int[] T = Scanner.String.Select(i => dir[i]).ToArray();

        bool success = false;
        int[][] SZ = new int[4][];
        int[][] TZ = new int[4][];
        foreach (int i in Enumerable.Range(0, 4))
        {
            SZ[i] = new int[N];
            TZ[i] = new int[N];
        }

        int[] countS = new int[4];
        int[] countT = new int[4];
        foreach (int i in Enumerable.Range(0, N))
        {
            foreach (int j in Enumerable.Range(0, 4))
            {
                if (S[i] == j) countS[j]++;
                if (T[i] == j) countT[j]++;

                SZ[j][i] = countS[j];
                TZ[j][i] = countT[j];
            }

            foreach (int j in Enumerable.Range(0, 4))
            {
                int d = countS[j] - ((i == 0) ? 0 : TZ[rev[j]][i - 1]);
                if(d >= need[j])
                {
                    success = true;
                }
                else if(countS[j] >= (horizon[j] ? YS : XS) - 1)
                {
                    /*
                    int limit = countS[j] - (horizon[j] ? YS : XS);
                    int index = SZ[j].LeftBinarySearchIndex(v => v > limit);
                    index = Math.Max(0, Math.Min(index, N - 1));


                    int tCount = TZ[rev[j]][index] - ((i == 0) ? 0 : TZ[rev[j]][i - 1]);

                    if (countS[j] - tCount >= (horizon[j] ? YS : XS))
                    {
                        success = true;
                    }
                    */

                    int index = Math.Max(0, TZ[rev[j]].LeftBinarySearchIndex(v => v >= countT[rev[j]]));
                    index = Math.Min(index, N - 1);
                    int sCount = countS[j] - SZ[j][index];
                    if(sCount >= (horizon[j] ? YS : XS))
                    {
                        success = true;
                    }
                }
            }
        }

        Console.WriteLine(success ? "NO" : "YES");
        Console.ReadLine();
    }

    private static IEnumerable<Tuple<int, int>> NextPoint(Tuple<int, int> point)
    {
        yield return new Tuple<int, int>(point.Item1 - 1, point.Item2);
        yield return new Tuple<int, int>(point.Item1 + 1, point.Item2);
        yield return new Tuple<int, int>(point.Item1, point.Item2 - 1);
        yield return new Tuple<int, int>(point.Item1, point.Item2 + 1);
    }
}

