using System.Collections;

class Program
{
    static void Main()
    {
        int[] hwn = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
        int H = hwn[0];
        int W = hwn[1];
        int N = hwn[2];

        int[] rc = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
        int sr = rc[0];
        int sc = rc[1];

        string S = Console.ReadLine();
        string T = Console.ReadLine();

        bool isRemain = true;

        //横方向判定
        {
            int rangeSt = 1;
            int rangeEd = W;

            for (int i = S.Length - 1; i >= 0; i--)
            {
                char chT = T[i];
                char chS = S[i];

                //後手の補正
                if (chT == 'R')
                {
                    //この後手を指す直前に居ても大丈夫な範囲が左側に1増える
                    rangeSt = Math.Max(rangeSt - 1, 1);                    
                }
                else if (chT == 'L')
                {
                    //この後手を指す直前に居ても大丈夫な範囲が右側に1増える
                    rangeEd = Math.Min(rangeEd + 1, W);
                }

                //先手の補正
                if (chS == 'R')
                {
                    //この先手を指す直前に居ても大丈夫な範囲が右側から1縮む
                    rangeEd--;
                }
                else if (chS == 'L')
                {
                    //この先手を指す直前にいても大丈夫な範囲が左側から1縮む
                    rangeSt++;
                }

                //先手が始まる前にいても良い範囲がない時点で後手の負けは確定
                if (rangeEd == rangeSt)
                {
                    isRemain = false;
                }
            }

            //更に初期座標が居ても良い範囲に含まれていない場合、後手の負けが確定
            if (rangeSt > sc || sc > rangeEd)
            {
                isRemain = false;
            }
        }

        //縦方向判定
        {
            int rangeSt = 1;
            int rangeEd = H;

            for (int i = S.Length - 1; i >= 0; i--)
            {
                char chT = T[i];
                char chS = S[i];

                //後手の補正
                if (chT == 'D')
                {
                    //この後手を指す直前に居ても大丈夫な範囲が上側に1増える
                    rangeSt = Math.Max(rangeSt - 1, 1);
                }
                else if (chT == 'U')
                {
                    //この後手を指す直前に居ても大丈夫な範囲が下側に1増える
                    rangeEd = Math.Min(rangeEd + 1, H);
                }

                //先手の補正
                if (chS == 'D')
                {
                    //この先手を指す直前に居ても大丈夫な範囲が下側から1縮む
                    rangeEd--;
                }
                else if (chS == 'U')
                {
                    //この先手を指す直前にいても大丈夫な範囲が上側から1縮む
                    rangeSt++;
                }

                //先手が始まる前にいても良い範囲がない時点で後手の負けは確定
                if (rangeEd == rangeSt)
                {
                    isRemain = false;
                }
            }

            //更に初期座標が居ても良い範囲に含まれていない場合、後手の負けが確定
            if (rangeSt > sr || sr > rangeEd)
            {
                isRemain = false;
            }
        }

        Console.WriteLine(isRemain ? "YES" : "NO");
    }
}



static class MathUtil
{
    public static IEnumerable<IEnumerable<int>> GetPermutation(int n)
    {
        if (n == 0)
        {
            yield return Single(0);
            yield break;
        }

        for (int i = 0; i <= n; i++)
        {
            foreach (var x in GetPermutation(n - 1))
            {
                yield return Single(i).Concat(x.Select(itm => itm < i ? itm : itm + 1));
            }
        }
    }

    private static IEnumerable<int> Single(int x)
    {
        yield return x;
    }

    public static IEnumerable<int> EnumeratePrimeNumbers()
    {
        List<int> primes = new List<int>() { 2 };
        yield return 2;

        for (int i = 3; i < int.MaxValue; i++)
        {
            bool isPrime = true;
            int Sqrt = (int)Math.Sqrt(i) + 1;

            foreach (var prime in primes)
            {
                if (prime > Sqrt)
                {
                    break;
                }
                if (i % prime == 0)
                {
                    isPrime = false;
                    break;
                }
            }

            if (isPrime)
            {
                primes.Add(i);
                yield return i;
            }
        }
    }
}


public enum PriorityKind
{
    BiggerIsPrior,
    SmallerIsPrior,
}

public abstract class PriorityQueue<T> : IEnumerable<T>
{
    public static PriorityQueue<T> Create<U>(Func<T, U> prioritySelector, PriorityKind kind)
    {
        return new PriorityQueueInner<T, U>(prioritySelector, kind);
    }

    public abstract IEnumerator<T> GetEnumerator();

    public abstract void Enqueue(T item);

    public abstract T Dequeue();

    IEnumerator IEnumerable.GetEnumerator()
    {
        return this.GetEnumerator();
    }

    /// <summary>
    /// 優先度順に取り出されるキュー
    /// </summary>
    /// <typeparam name="T"></typeparam>
    private class PriorityQueueInner<T, U> : PriorityQueue<T>
    {
        private Comparison<T> comparison;

        private List<T> heap = new List<T>();

        /// <summary>
        /// 優先度を決定するComparisonを指定して初期化
        /// 比較結果が大きいものほど先に出てくる。
        /// </summary>
        /// <param name="comparison"></param>
        public PriorityQueueInner(Func<T, U> prioritySelector, PriorityKind kind)
        {
            var comparer = Comparer<U>.Default;

            int biggerPriorComparison(T x, T y)
            {
                return comparer.Compare(prioritySelector(y), prioritySelector(x));
            }

            int smallerPriorComparison(T x, T y)
            {
                return comparer.Compare(prioritySelector(x), prioritySelector(y));
            }

            if (kind == PriorityKind.BiggerIsPrior)
            {
                this.comparison = biggerPriorComparison;
            }
            else
            {
                this.comparison = smallerPriorComparison;
            }
        }

        public override void Enqueue(T item)
        {
            heap.Add(item);

            int i = heap.Count - 1;
            while (i > 0)
            {
                //親のノードの番号
                int p = (i - 1) / 2;

                //もう逆転していないなら抜ける
                if (comparison(item, heap[p]) >= 0) break;

                //親のノードの数字を下ろして、自分は上に
                heap[i] = heap[p];
                i = p;
            }

            heap[i] = item;
        }

        public override T Dequeue()
        {
            int nextSize = heap.Count - 1;

            T ret = heap[0];

            //根に持ってくる値
            T x = heap[nextSize];

            //根から下ろしていく
            int i = 0;
            while (i * 2 + 1 < nextSize)
            {
                //子同士を比較
                int a = i * 2 + 1;
                int b = i * 2 + 2;
                if (b < nextSize && comparison(heap[a], heap[b]) > 0) a = b;

                //もう逆転していないなら終わり
                if (comparison(heap[a], x) >= 0) break;

                //子の数字を持ち上げる
                heap[i] = heap[a];
                i = a;
            }

            heap[i] = x;
            heap.RemoveAt(nextSize);
            return ret;
        }

        public override IEnumerator<T> GetEnumerator()
        {
            return heap.GetEnumerator();
        }

        public int Count => heap.Count;
    }
}

