class Solver
{
    public void Solve(Scanner sc)
    {
        int H, W, N;
        sc.Make(out H, out W, out N);
        int str, stc;
        sc.Make(out str, out stc);str--;stc--;
        var S = Create(2, () => sc.Str);
        var lr = new List<Pi>();
        var ud = new List<Pi>();
        for (int i = 0; i < N; i++)
        {
            for (int k = 0; k < 2; k++)
            {
                switch (S[k][i])
                {
                    case 'L':
                        lr.Add(new Pi(0, k));
                        break;
                    case 'R':
                        lr.Add(new Pi(1, k));
                        break;
                    case 'U':
                        ud.Add(new Pi(0, k));
                        break;
                    case 'D':
                        ud.Add(new Pi(1, k));
                        break;

                }                
            }
        }
        lr.Reverse();ud.Reverse();
        int l = 0, r = W - 1;
        foreach(var p in lr)
        {
            if (p.v2 == 0)
            {
                if (p.v1 == 0) l++;
                else r--;
            }else
            {
                if (p.v1 == 1) l = Max(0, l - 1);
                else r = Min(W - 1, r + 1);
            }
            if (r < l) Fail("NO");
        }
        if (stc < l || r < stc) Fail("NO");
        int u = 0, d = H - 1;
        foreach (var p in ud)
        {
            if (p.v2 == 0)
            {
                if (p.v1 == 0) u++;
                else d--;
            }
            else
            {
                if (p.v1 == 1) u = Max(0, u - 1);
                else d = Min(W - 1, d + 1);
            }
            if (d < u) Fail("NO");
        }
        if (str < u || d < str) Fail("NO");
        Console.WriteLine("YES");
    }
}

