        sr = int.Parse(line[0]) - 1;
        sc = int.Parse(line[1]) - 1;

        mass[sr, sc] = 1;

        S = Console.ReadLine();
        T = Console.ReadLine();

        while(count < N)
        {
            switch (S[count])
            {
                case 'L':
                    moveLeft(mass, ref sr, ref sc);
                    break;
                case 'R':
                    moveRight(mass, ref sr, ref sc);
                    break;
                case 'U':
                    moveUp(mass, ref sr, ref sc);
                    break;
                case 'D':
                    moveDown(mass, ref sr, ref sc);
                    break;
            }
            switch (T[count])
            {
                case 'L':
                    if (moveLeft(mass, ref sr, ref sc))
                    {
                        Console.WriteLine("NO");
                        count = N;
                    }
                    break;
                case 'R':
                    if (moveRight(mass, ref sr, ref sc))
                    {
                        Console.WriteLine("NO");
                        count = N;
                    }
                    break;
                case 'U':
                    if (moveUp(mass, ref sr, ref sc))
                    {
                        Console.WriteLine("NO");
                        count = N;
                    }
                    break;
                case 'D':
                    if (moveDown(mass, ref sr, ref sc))
                    {
                        Console.WriteLine("NO");
                        count = N;
                    }
                    break;
            }

            if (count == N - 1)
                Console.WriteLine("YES");

            count++;
        }
    }

    public static bool moveLeft(int[,] mass,ref int indexX,ref int indexY)
    {

        if (indexY - 1 >= 0)
        {
            mass[indexX, indexY] = 0;
            mass[indexX, indexY - 1] = 1;
            indexY--;
            return false;
        }
        else
        {
            return true;
        }
    }

    public static bool moveRight(int[,] mass, ref int indexX, ref int indexY)
    {

        if (indexY + 1 < mass.GetLength(1))
        {
            mass[indexX, indexY] = 0;
            mass[indexX, indexY + 1] = 1;
            indexY++;
            return false;
        }
        else
        {
            return true;
        }
    }

    public static bool moveUp(int[,] mass, ref int indexX, ref int indexY)
    {

        if (indexX - 1 >= 0)
        {
            mass[indexX, indexY] = 0;
            mass[indexX - 1, indexY] = 1;
            indexX--;
            return false;
        }
        else
        {
            return true;
        }
    }

    public static bool moveDown(int[,] mass, ref int indexX, ref int indexY)
    {

        if (indexX + 1 < mass.GetLength(0))
        {
            mass[indexX, indexY] = 0;
            mass[indexX + 1, indexY] = 1;
            indexX++;
            return false;
        }
        else
        {
            return true;
        }
    }
}

