using System.Linq;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static void Main(string[] args)
    {
        var sc = new Scanner();
        int h = sc.NextInt();
        int w = sc.NextInt();
        int n = sc.NextInt();
        int r = sc.NextInt() - 1;
        int c = sc.NextInt() - 1;
        string s = sc.NextString();
        string t = sc.NextString();

        var d = new Dictionary<char, int>() { { 'L', 0 }, { 'R', 0 }, { 'U', 0 }, { 'D', 0 } };
        var rev = new Dictionary<char, char>() { { 'L', 'R' }, { 'R', 'L' }, { 'U', 'D' }, { 'D', 'U' } };
        d[s[0]]++;
        for (int i = 0; i < n; i++)
        {
            if (d['U'] > r || d['L'] > c || d['D'] >= (h - r) || d['R'] >= (w - c))
            {
                Console.WriteLine("NO");
                return;
            }
            if (d[rev[t[i]]] > 0)
            {
                d[rev[t[i]]]--;
                if (i < n - 1) d[s[i + 1]]++;
                continue;
            }
            if (i < n - 1 && t[i] == rev[s[i + 1]]) d[rev[t[i]]]--;
            if (i < n - 1) d[s[i + 1]]++;
        }
        Console.WriteLine("YES");
    }

    static long Gcd(long a, long b)
    {
        if (a < b) return Gcd(b, a);
        if (b == 0) return a;
        return Gcd(b, a % b);
    }
}

class Scanner
{
    int index = -1;
    string[] buf;

    public Scanner()
    {
    }

    public int NextInt()
    {
        CheckNext();
        return int.Parse(buf[index++]);
    }

    public long NextLong()
    {
        CheckNext();
        return long.Parse(buf[index++]);
    }

    public double NextDouble()
    {
        CheckNext();
        return double.Parse(buf[index++]);
    }

    public string NextString()
    {
        CheckNext();
        return buf[index++];
    }

    private void CheckNext()
    {
        if (index >= 0 && index < buf.Length) return;

        buf = Console.ReadLine().Split(' ');
        index = 0;
    }
}

