            var h = line1[0];
            var w = line1[1];
            var n = line1[2];

            var line2 = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            var s_r = line2[0];
            var s_c = line2[1];

            var top = s_r - 1;
            var bottom = s_r;  // exclusive
            var left = s_c - 1;
            var right = s_c;

            var L = 0;
            var R = 0;
            var U = 0;
            var D = 0;

            var S = Console.ReadLine();
            var T = Console.ReadLine();

            for (int i = 0; i < n; i++)
            {
                // takahashi move
                switch (S[i])
                {
                    case 'L': left -= 1; break;
                    case 'R': right += 1; break;
                    case 'U': top -= 1; break;
                    case 'D': bottom += 1; break;
                }

                // boundary check
                if (top - bottom > h || right - left > w)
                {
                    Console.WriteLine("NO");
                    return;
                }

                if ((left < 0 && R <= 0) ||
                    (top < 0 && D <= 0) ||
                    (right > w && L <= 0) ||
                    (bottom > h && U <= 0))
                {
                    Console.WriteLine("NO");
                    return;
                }

                if (left < 0) { R--; left++; /*right++;*/ }
                if (top < 0) { D--; top++; /*bottom++;*/ }
                if (right > w) { L--; /*left--;*/ right--; }
                if (bottom > h) { U--; /*top--;*/ bottom--; }

                // aoki move
                switch (T[i])
                {
                    case 'L': if (L < left) { L++; } break;
                    case 'R': if (R < w - right) { R++; } break;
                    case 'U': if (U < top) { U++; } break;
                    case 'D': if (D < h - bottom) { D++; } break;
                }
            }

            Console.WriteLine("YES");
        }
    }
}

