using Pi = Pair<int, int>;

class Solver
{
    public void Solve(Scanner sc)
    {
        int H, W, N;
        sc.Make(out H, out W, out N);
        int str, stc;
        sc.Make(out str, out stc);str--;stc--;
        var S = Create(2, () => sc.Str);
        var lr = new List<Pi>();
        var ud = new List<Pi>();
        for (int i = 0; i < N; i++)
        {
            for (int k = 0; k < 2; k++)
            {
                switch (S[k][i])
                {
                    case 'L':
                        lr.Add(new Pi(0, k));
                        break;
                    case 'R':
                        lr.Add(new Pi(1, k));
                        break;
                    case 'U':
                        ud.Add(new Pi(0, k));
                        break;
                    case 'D':
                        ud.Add(new Pi(1, k));
                        break;

                }                
            }
        }
        int l = stc, r = stc;
        int idx = 0;
        for(int i = 0; i < lr.Count;)
        {
            int L = 0, R = 0;
            while (idx < lr.Count && lr[idx].v2 == lr[i].v2)
            {
                L += 1-lr[idx].v1;
                R += lr[idx].v1;
                idx++;
            }
            if (lr[i].v2 == 1)
            {
                l = Max(0, l - L);
                r = Min(W - 1, r + R);
            }
            else
            {
                chmax(ref l, L);
                chmin(ref r, W-R-1);
            }
            if (r < l) Fail("NO");
            i = idx;
        }
        int u = str, d = str;
        idx = 0;
        for (int i = 0; i < ud.Count;)
        {
            int U = 0, D = 0;
            while (idx < ud.Count && ud[idx].v2 == ud[i].v2)
            {
                U += 1 - ud[idx].v1;
                D += ud[idx].v1;
                idx++;
            }
            if (ud[i].v2 == 1)
            {
                u = Max(0, u - U);
                d = Min(H - 1, d + D);
            }
            else
            {
                chmax(ref u, U);
                chmin(ref d, H - D - 1);
            }
            if (d < u) Fail("NO");
            i = idx;
        }
        Console.WriteLine("YES");
    }
}

