using System;
class AGC_033_B
{
    static void Main(string[] args)
    {
        string[] input = Console.ReadLine().Split(' ');
        int H = int.Parse(input[0]);
        int W = int.Parse(input[1]);
        int N = int.Parse(input[2]);

        string[] input2 = Console.ReadLine().Split(' ');
        int sr = int.Parse(input2[0]);
        int sc = int.Parse(input2[1]);

        string S = Console.ReadLine();
        string T = Console.ReadLine();

        int TL = 0;
        int TR = 0;
        int TU = 0;
        int TD = 0;

        int AL = 0;
        int AR = 0;
        int AU = 0;
        int AD = 0;

        Action[] Takahashi = new Action[N];
        Action[] Aoki = new Action[N];

        for (int i = 0; i < N; i++)
        {
            if (S[i] == 'L') TL++;
            else if (S[i] == 'R') TR++;
            else if (S[i] == 'U') TU++;
            else if (S[i] == 'D') TD++;

            if (T[i] == 'L' && sc + TR - AL > 1) AL++;
            else if (T[i] == 'R' && sc - TL + AR < W) AR++;
            else if (T[i] == 'U' && sr + TD - AU > 1) AU++;
            else if (T[i] == 'D' && sr - TU + AD < H) AD++;

            Takahashi[i] = new Action(TL, TR, TU, TD);
            Aoki[i] = new Action(AL, AR, AU, AD);
        }

        bool result = false;
        for (int i = 0; i < N; i++)
        {
            Action TakahashiAction = Takahashi[i];
            Action AokiAction = i==0 ?  new Action(0,0,0,0) :Aoki[i-1];


            if (sc - TakahashiAction.L + AokiAction.R <= 0)
            {
                result = true;
                break;
            }

            if (sc + TakahashiAction.R - AokiAction.L > W)
            {
                result = true;
                break;
            }

            if (sr - TakahashiAction.U + AokiAction.D <= 0)
            {
                result = true;
                break;
            }

            if (sr + TakahashiAction.D - AokiAction.U > H)
            {
                result = true;
                break;
            }

        }

        if (result)
        {
            Console.WriteLine("NO");
        }
        else
        {
            Console.WriteLine("YES");
        }
    }
}

