    {
        static void Main(string[] args)
        {
            var HWN = Console.ReadLine().Split().Select(int.Parse).ToList();
            var Src = Console.ReadLine().Split().Select(int.Parse).ToList();
            var S = Console.ReadLine();
            var T = Console.ReadLine();
            var dst = new int[] {
                                Src[1] - 1,         //L
                                HWN[1] - Src[1],    //R
                                Src[0] - 1,         //U
                                HWN[0] - Src[0]     //D
                            };
