        var dstr = HWN[1] - Src[1];
        var dstu = Src[0] - 1;
        var dstd = HWN[0] - Src[0];*/

            var numSD = new int[4];//L,R.U,D
            var drct = new char[] { 'L', 'R', 'U', 'D' };
            var drctR = new char[] { 'D', 'U', 'R', 'L' };
            for (int d = 0; d < 4; ++d)//L,R,U,D
            {
                int ps = 0;
                for (int i = 0; i < HWN[2]; ++i)//N
                {                                       
                    if (drct[d] == S[i]) { ++numSD[d]; }
