import "fmt"

type point struct {
	x int
	y int
}

func main() {

	var h, w, n int
	fmt.Scan(&h, &w, &n)

	var sr, sc int
	fmt.Scan(&sr, &sc)
	var init point = point{x: sr - 1, y: sc - 1}

	var s, t string
	fmt.Scan(&s)
	fmt.Scan(&t)

	if isWin(n, w, h, s, t, init) {
		fmt.Println("NO")
	} else {
		fmt.Println("YES")
	}
}

func isWin(n int, w, h int, s, t string, init point) bool {
	var current point = init

	// 右上に向かう
	for i := 0; i < n; i++ {
		if s[i] == 'R' {
			current.x += 1
		}
		if s[i] == 'U' {
			current.y += 1
		}

		if current.x > w-1 || current.y > h-1 {
			return true
		}

		if t[i] == 'L' && current.x > 0 {
			current.x -= 1
		}
		if t[i] == 'D' && current.y > 0 {
			current.y -= 1
		}
	}

	// 左下に向かう
	for i := 0; i < n; i++ {
		if t[i] == 'L' {
			current.x -= 1
		}
		if t[i] == 'D' {
			current.y -= 1
		}

		if current.x < 0 || current.y < 0 {
			return true
		}

		if t[i] == 'R' && current.x < w-1 {
			current.x += 1
		}
		if t[i] == 'U' && current.y < h-1 {
			current.y += 1
		}
	}

	return false
}

