	// 上に逃げる戦略
	x = sr
	for i := 0; i < n; i++ {
		if s[i] == 'U' {
			x--
			if !(1 <= x && x <= h) {
				stdout.Println("NO")
				return
			}
		}
		if t[i] == 'D' && 1 <= sc+1 && sc+1 <= h {
			x++
		}
	}

	// 下に逃げる戦略
	x = sr
	for i := 0; i < n; i++ {
		if s[i] == 'D' {
			x++
			if !(1 <= x && x <= h) {
				stdout.Println("NO")
				return
			}
		}
