		// out(sc, W+1-sc, sr, H+1-sr)
		if LR >= sc || RL >= W+1-sc || UD >= sr || DU >= H+1-sr {
			out("NO")
			return
		}
		switch T[i] {
		case 'L':
			cT[0]++
			if sc+cS[1]-cT[0] <= 0 {
				cT[0]--
			}
		case 'R':
			cT[1]++
			if sc+cS[0]-cT[1] >= W {
				cT[1]--
			}
		case 'U':
			cT[2]++
			if sr+cS[3]-cT[2] <= 0 {
				cT[2]--
			}
		case 'D':
			cT[3]++
			if sc+cS[2]-cT[3] >= H {
				cT[3]--
			}
		}
	}
	out("YES")
}

