	pline, err := strconv.Atoi(pos[0])
	if err != nil {
		panic(err)
	}

	prow, err := strconv.Atoi(pos[1])
	if err != nil {
		panic(err)
	}
	p := NewPorn(pline-1, prow-1)

	s.Scan()
	tCmds := s.Text()
	thand := NewHand(p, strings.Split(tCmds, "")...)

	s.Scan()
	aCmds := s.Text()
	ahand := NewHand(p, strings.Split(aCmds, "")...)

	result := "YES"

	for i := 0; i < cmdNum; i++ {
		thand.Run()
		if line, row := p.Location(); line < 0 || line >= b.line || row < 0 || row >= b.row {
			result = "NO"
			break
		}

		ahand.Run()
		if line, row := p.Location(); line < 0 || line >= b.line || row < 0 || row >= b.row {
			result = "NO"
			break
		}
	}

	fmt.Println(result)
}

type Board struct {
	line int
	row  int
}

func NewBoard(line, row int) *Board {
	return &Board{line, row}
}

type Porn struct {
	line      int
	row       int
	isRemoved bool
}

func NewPorn(line, row int) *Porn {
	return &Porn{line, row, false}
}

func (p *Porn) Location() (line int, row int) {
	return p.line, p.row
}

func (p *Porn) Up() {
	p.line--
}

func (p *Porn) Down() {
	p.line++
}

func (p *Porn) Right() {
	p.row++
}

func (p *Porn) Left() {
	p.row--
}

type Hand struct {
	cmds     []string
	cmdIndex int
	porn     *Porn
}

func NewHand(porn *Porn, cmds ...string) *Hand {
	return &Hand{porn: porn, cmds: cmds}
}

func (h *Hand) Run() {
	switch h.cmds[h.cmdIndex] {
	case "U":
		h.porn.Up()
	case "D":
		h.porn.Down()
	case "R":
		h.porn.Right()
	case "L":
		h.porn.Left()
	}

	h.cmdIndex++
}

