var H, W, N int

func main() {
	H, W, N = ReadInt(), ReadInt(), ReadInt()
	Sr, Sc := ReadInt(), ReadInt()
	S := Read()
	T := Read()

	if recur(Sr-1, Sc-1, 1, S, T) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

func recur(r, c int, turn int, s, t string) bool {
	if r < 0 || r >= H || c < 0 || c >= W {
		return false
	}

	if s == "" && t == "" {
		return true
	}

	var step byte
	if turn%2 == 1 {
		// Takahashi
		step = s[0]
		s = s[1:]
	} else {
		// Aoki
		step = t[0]
		t = t[1:]
	}

	// 動かさない場合
	r1 := recur(r, c, turn+1, s, t)

	// 動かす場合
	switch step {
	case 'L':
		c--
	case 'R':
		c++
	case 'U':
		r--
	case 'D':
		r++
	}
	r2 := recur(r, c, turn+1, s, t)

	if r1 == r2 {
		return r1
	}

	if turn%2 == 0 {
		// Takahashi
		if r1 == true || r2 == true {
			return true
		}
		return false
	}

	// Aoki
	if r1 == false || r2 == false {
		return false
	}
	return true
}

