bool solve(int n, int h, int x, string S, string T, char down, char up) {
    int btm = 0, top = h;

    foreach_reverse (i ; 0 .. n) {
        if (S[i] == down) {
            if (i == 0 || T[i - 1] != up) {
                top--;
            }
        }
        if (S[i] == up) {
            if (i == 0 || T[i - 1] != down) {
                btm++;
            }
        }

        debug {
            writefln("btm: %d, top: %d", btm, top);
        }
    }

    return btm <= x && x < top;
}























int[][] readGraph(int n, int m, bool isUndirected = true, bool is1indexed = true) {
    auto adj = new int[][](n, 0);

    foreach (i; 0 .. m) {
        int u, v;
        scan(u, v);
        if (is1indexed) {
            u--, v--;
        }
        adj[u] ~= v;
        if (isUndirected) {
            adj[v] ~= u;
        }
    }

    return adj;
}

alias Edge = Tuple!(int, "to", int, "cost");

Edge[][] readWeightedGraph(int n, int m, bool isUndirected = true, bool is1indexed = true) {
    auto adj = new Edge[][](n, 0);

    foreach (i; 0 .. m) {
        int u, v, c;
        scan(u, v, c);
        if (is1indexed) {
            u--, v--;
        }
        adj[u] ~= Edge(v, c);
        if (isUndirected) {
            adj[v] ~= Edge(u, c);
        }
    }

    return adj;
}

