    h, w, n = read().parseInt
    sy, sx = read().parseInt
    s = read()
    t = read()

  var lose = false
  var
    right = newSeq[int](n + 1)
    left = newSeq[int](n + 1)
  right[n] = w
  left[n] = 1
  for i in countdown(n - 1, 0):
    if s[i] == 'R' and t[i] != 'L':
      right[i] = right[i + 1] - 1
    elif s[i] != 'R' and t[i] == 'L':
      right[i] = min(w, right[i + 1] + 1)
    else:
      right[i] = right[i + 1]
    if s[i] == 'L' and t[i] != 'R':
      left[i] = left[i + 1] + 1
    elif s[i] != 'L' and t[i] == 'R':
      left[i] = max(1, left[i + 1] - 1)
    else:
      left[i] = left[i + 1]
    if left[i] > right[i] or
      (s[i] == 'R' and right[i] == w) or
      (s[i] == 'L' and left[i] == 1):
      lose = true

  var
    bottom = newSeq[int](n + 1)
    top = newSeq[int](n + 1)
  bottom[n] = h
  top[n] = 1
  for i in countdown(n - 1, 0):
    if s[i] == 'D' and t[i] != 'U':
      bottom[i] = bottom[i + 1] - 1
    elif s[i] != 'D' and t[i] == 'U':
      bottom[i] = min(h, bottom[i + 1] + 1)
    else:
      bottom[i] = bottom[i + 1]
    if s[i] == 'U' and t[i] != 'D':
      top[i] = top[i + 1] + 1
    elif s[i] != 'U' and t[i] == 'D':
      top[i] = max(1, top[i + 1] - 1)
    else:
      top[i] = top[i + 1]
    if top[i] > bottom[i] or
      (s[i] == 'D' and bottom[i] == h) or
      (s[i] == 'U' and top[i] == 1):
      lose = true

  if not lose and left[0] <= sx and sx <= right[0] and top[0] <= sy and sy <= bottom[0]:
    echo "YES"
  else:
    echo "NO"
