def search(i, y, x):
    if y == -1 or y == H or x == -1 or x == W:
        return False
    if i == 2*N:
        return True

    if i%2 == 0:
        M = S
    else:
        M = T

    if M[i//2] == 'L':
        move = search(i + 1, y, x - 1)
    elif M[i//2] == 'R':
        move = search(i + 1, y, x + 1)
    elif M[i//2] == 'U':
        move = search(i + 1, y - 1, x)
    else:
        move = search(i + 1, y + 1, x)
    stop = search(i + 1, y, x)

    if i%2 == 0:
        return move and stop
    else:
        return move or stop

