def sousa(x, s):
    if s == 'L':
        return [x[0], x[1]-1]
    elif s == 'R':
        return [x[0], x[1]+1]
    elif s == 'U':
        return [x[0]-1, x[1]]
    elif s == 'D':
        return [x[0]+1, x[1]]
    return x

def sousa_inv(x, s):
    if s == 'R':
        return [x[0], x[1]-1]
    elif s == 'L':
        return [x[0], x[1]+1]
    elif s == 'D':
        return [x[0]-1, x[1]]
    elif s == 'U':
        return [x[0]+1, x[1]]
    return x


