def main():
  height, width, _ = map(int, input().split())
  r, c = map(int, input().split())
  s_coms = input()[::-1]
  t_coms = input()[::-1]
  left = 0
  right = 0
  up = 0
  down = 0

  for s, t in zip(s_coms, t_coms):
    if t == 'L':
      right = max(right - 1, 0)
    elif t == 'R':
      left = max(left - 1, 0)
    elif t == 'U':
      down = max(down - 1, 0)
    elif t == 'D':
      up = max(up - 1, 0)

    if s == 'L':
      left = left + 1
    elif s == 'R':
      right = right + 1
    elif s == 'U':
      up = up + 1
    elif s == 'D':
      down = down + 1

    if left >= width or right >= width or up >= height or down >= height:
      print('NO', flush=True)
      return

  if up < r <= height - down and left < c <= width - right:
    print('YES')
  else:
    print('NO')


if __name__ == '__main__':
  main()

def RL(a):
    if a=='R':
        return 1
    elif a=='L':
        return -1
    else:
        return 0

def UD(a):
    if a=='D':
        return 1
    elif a=='U':
        return -1
    else:
        return 0

def printLim(minus_lim, plus_lim, MAX):
    if minus_lim <0:
        print('X|', end='')
    else:
        print('|'+'X'*(minus_lim+1), end='')

    print('O'*(plus_lim - minus_lim -1), end='')
    if plus_lim ==MAX:
        print('|X')
    else:
        print('X'*(MAX-plus_lim) + '|')

def isFall(s_data,t_data,MAX,target):
    a = -1
    b = MAX
    for i in range(N-1, -1,-1):
        save = t_data[i]
        if save == 1:
            a-=1
        elif save == -1:
            b+=1

        # limit check
        if a < -1:
            a=-1
        if b>MAX:
            b=MAX
        if a==b:
            break
#         printLim(a,b,MAX)

        kill = s_data[i]
#         print(kill, save)
        # A lim
        if kill == -1:
            a +=1
        # B lim
        elif kill == 1:
            b -=1

        # limit check
        if a < -1:
            a=-1
        if b>MAX:
            b=MAX
        if a==b:
            break


#         printLim(a,b,MAX)
#     print(a,b)

    if a < target < b:
        return False
    else:
        return True




