def Takahashi(now_w,now_h,next_w,next_h,center_w,center_h):
    if EuclidDis(now_w,now_h,center_w,center_h) < EuclidDis(next_w,next_h,center_w,center_h):
        return (next_w,next_h)
    else:
        return (now_w,now_h)
def Aoki(now_w,now_h,next_w,next_h,center_w,center_h):
    if EuclidDis(now_w,now_h,center_w,center_h) > EuclidDis(next_w,next_h,center_w,center_h):
        return (next_w,next_h)
    else:
        return (now_w,now_h)

def EuclidDis(x0,y0,x1,y1):
    return ((x0-x1)**2 + (y0-y1)**2)

def isRemain(sr,sc,op):
    center_h = H / 2
    center_w = W / 2
    now_h = sr
    now_w = sc
    for i in range(len(op)):
        if op[i] == 'L':
            next_w = now_w - 1
            next_h = now_h
        elif op[i] == 'R':
            next_w = now_w + 1
            next_h = now_h
        elif op[i] == 'U':
            next_w = now_w
            next_h = now_h + 1
        elif op[i] == 'D':
            next_w = now_w
            next_h = now_h - 1
        if i % 2 == 0:#Sのop
            now_w,now_h = Takahashi(now_w,now_h,next_w,next_h,center_w,center_h)
            #print('Takahashi nw={} nh={}'.format(now_w,now_h))
        else:#Tのop
            now_w,now_h = Aoki(now_w,now_h,next_w,next_h,center_w,center_h)
            #print('Aoki nw={} nh={}'.format(now_w,now_h))
        if  0 > now_w or now_w >= W or 0 > now_h or now_h >= H:
            return False
    return True

