def aok_turn(com: str, tolow: str, toup: str, lower: int, upper: int, amin: int, amax: int):
    if com == tolow:
        upper = min(upper + 1, amax)
    elif com == toup:
        lower = max(lower - 1, amin)

    return lower, upper


def tak_turn(com: str, tolow: str, toup: str, lower: int, upper: int, amin: int, amax: int):
    if com == tolow:
        lower += 1
    elif com == toup:
        upper -= 1

    return lower, upper


def on_board(lower: int, upper: int):
    return True if lower < upper else False


def judge(tak: str, aok: str, start: int, tolow: str, toup: str, lower: int, upper: int, amin: int, amax: int):
    for aoki, taki in zip(aok, tak):
        lower, upper = aok_turn(aoki, tolow, toup, lower, upper, amin, amax)
        lower, upper = tak_turn(taki, tolow, toup, lower, upper, amin, amax)

        if lower >= upper:
            return False

    if lower <= start < upper:
        return True
    else:
        return False


