def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(H, W, N, s, S, T):
    s_ = s
    left = 0
    right = W-1
    bottom = 0
    top = H-1
    for s, t in reversed(list(zip(S, T))):
        if t == 'R':
            left = max(0, left-1)
        elif t == 'L':
            right = min(W-1, right+1)
        elif t == 'U':
            bottom = max(0, bottom-1)
        elif t == 'D':
            top = min(H-1, top+1)

        if s == 'L':
            left += 1
        elif s == 'R':
            right -= 1
        elif s == 'D':
            bottom += 1
        elif s == 'U':
            top -= 1

        if left > right:
            return 'NO'
        elif bottom > top:
            return 'NO'

    s = s_
    if not (left <= s[1]-1 <= right):
        return 'NO'
    elif not (bottom <= s[0]-1 <= top):
        return 'NO'
    return 'YES'


