    # 2 3 4
    # 2 2
    # ULRR
    # LUUU
    # はNo(Yesと出る)
    H, W, N = (int(i) for i in input().split())
    sr, sc = (int(i) for i in input().split())
    S = input()
    T = input()
    from collections import Counter
    S_C = Counter(S)
    if sc <= S_C['L']:
        move = 0
        for s, t in zip(S, T):
            if s == "L":
                move += 1
            if sc <= move:
                return print("NO")
            if t == "R":
                move -= 1
                if -move == W - sc + 1:
                    move += 1
    if W - sc + 1 <= S_C['R']:
        move = 0
        for s, t in zip(S, T):
            if s == "R":
                move += 1
            if W - sc + 1 <= move:
                return print("NO")
            if t == "L":
                move -= 1
                if -move == sc:
                    move += 1
    if sr <= S_C['U']:
        move = 0
        for s, t in zip(S, T):
            if s == "U":
                move += 1
            if sr <= move:
                return print("NO")
            if t == "D":
                move -= 1
                if -move == H - sr + 1:
                    move += 1
    if H - sr + 1 <= S_C['D']:
        move = 0
        for s, t in zip(S, T):
            if s == "D":
                move += 1
            if H - sr + 1 <= move:
                return print("NO")
            if t == "U":
                move -= 1
                if -move == sr:
                    move += 1
    print("YES")


