    return 0 <= r < H and 0 <= c < W


def rec(cur_r, cur_c, cur_step_index, bl_cur_player_takahashi):
    if bl_cur_player_takahashi:
        nr, nc = next_move_pos(cur_r, cur_c, cur_step_index, True)
        if not is_in_range(nr, nc):
            return True
        if rec(nr, nc, cur_step_index, not bl_cur_player_takahashi):
            return True
        if rec(cur_r, cur_c, cur_step_index, not bl_cur_player_takahashi):
            return True
    else:
        if cur_step_index == N - 1:
            return False
        for nr, nc in (cur_r, cur_c), next_move_pos(cur_r, cur_c, cur_step_index, False):
            if not is_in_range(nr, nc): continue
            nnr, nnc = next_move_pos(nr, nc, cur_step_index + 1, True)
            if not is_in_range(nnr, nnc): continue
            if not rec(nr, nc, cur_step_index + 1, not bl_cur_player_takahashi):
                return False
            if not rec(cur_r, cur_c, cur_step_index + 1, not bl_cur_player_takahashi):
