class Takahashi:
  def __init__(self, S, H, W):
    self.s = S
    self.up = S.count('R')
    self.down = S.count('D')
    self.right = S.count('R')
    self.left = S.count('L')

    self.H = H
    self.W = W

  def __call__(self, i, s, aoki):
    if self.s[i] == 'U':
      self.up -= 1
      if ((self.up - aoki.down - s[0]) - 1) > ((s[0] + self.down - aoki.up) - H):
        return (s[0] - 1, s[1])

    elif self.s[i] == 'D':
      self.down -= 1
      if ((self.up - aoki.down - s[0]) - 1) < ((s[0] + self.down - aoki.up) - H):
        return (s[0] - 1, s[1])

    elif self.s[i] == 'R':
      self.right -= 1
      if ((self.left - aoki.right - s[1]) - 1) < ((s[1] + self.right - aoki.left) - W):
        return (s[0], s[1] + 1)

    elif self.s[i] == 'L':
      self.left -= 1
      if ((self.left - aoki.right - s[1]) - 1) > ((s[1] + self.right - aoki.left) - W):
        return (s[0], s[1] - 1)

    return s

class Aoki:
  def __init__(self, T, H, W):
    self.t = T
    self.up = T.count('R')
    self.down = T.count('D')
    self.right = T.count('R')
    self.left = T.count('L')

    self.H = H
