        return (s[0] - 1, s[1])

    elif self.t[i] == 'D':
      self.down -= 1
      if ((takahashi.up - self.down - s[0]) - 1) > ((s[0] + takahashi.down - self.up) - H):
        return (s[0] - 1, s[1])

    elif self.t[i] == 'R':
