        t: Chars,
    }

    let mut left = 1i64;
    let mut right = w;
    if s[n-1] == 'L' {
        left += 1;
    } else if s[n-1] == 'R' {
        right -= 1;
    }

    for i in (0..n-1).rev() {
        if t[i] == 'L' {
            right = min(w, right+1);
        } else if t[i] == 'R' {
            left = max(1, left - 1);
        }
        if s[i] == 'L' {
            left += 1;
        } else if s[i] == 'R' {
            right -= 1;
        }
        if left > right {
            println!("NO");
            return;
        }
    }
    if sc < left || right < sc {
        println!("NO");
        return;
    }

    let mut up = 1i64;
    let mut down = h;
    if s[n-1] == 'U' {
        up += 1;
    } else if s[n-1] == 'D' {
        down -= 1;
    }

    for i in (0..n-1).rev() {
        if t[i] == 'U' {
            down = min(w, down+1);
