fn can_win(s: &[char], t: &[char], start: usize, length: usize, left: char, right: char) -> bool {
    let mut idx = start;
    for i in 0..s.len() {
        if s[i] == left {
            idx -= 1;
        }
        if idx == 0 {
            return true;
        }
        if t[i] == right && idx + 1 <= length {
            idx += 1;
        }
    }
    false
}

fn solve(h: usize, w: usize, y: usize, x: usize, s: &[char], t: &[char]) -> bool {
    if can_win(s, t, y, h, 'U', 'D') {
        eprintln!("1");
        return false;
    }
    if can_win(s, t, h - (y - 1), h, 'D', 'U') {
        eprintln!("2");
        return false;
    }
    if can_win(s, t, x, w, 'L', 'R') {
        eprintln!("3");
        return false;
    }
    if can_win(s, t, w - (x - 1), w, 'R', 'L') {
        eprintln!("4");
        return false;
    }
    true
}

fn run() {
    input! {
        h: usize,
        w: usize,
        _n: usize,
        y: usize,
        x: usize,
        s: chars,
        t: chars,
    }
    if solve(h, w, y, x, &s, &t) {
        println!("YES");
    } else {
        println!("NO");
    }
}

