use std::cmp::{max, min};

fn convert(s: &Vec<char>) -> Vec<usize> {
    let mut a = vec![];
    for &c in s {
        let k = match c {
            'L' => 0,
            'R' => 1,
            'U' => 2,
            'D' => 3,
            _ => unreachable!(),
        };
        a.push(k);
    }
    a
}

fn run() {
    input! {
        h: i32,
        w: i32,
        n: usize,
        p: (i32, i32),
        s: chars,
        t: chars,
    }
    let s = convert(&s);
    let t = convert(&t);
    let mut x = [1, h];
    let mut y = [1, w];
    let d = [(0, -1), (0, 1), (-1, 0), (1, 0)];
    for i in (0..n).rev() {
        let v = d[t[i]];
        x[0] = max(1, min(x[0] + v.0, x[0]));
        x[1] = min(h, max(x[1] + v.0, x[1]));
        y[0] = max(1, min(y[0], y[0] + v.1));
        y[1] = min(w, max(y[1], y[1] + v.1));
        let v = d[s[i]];
        x[0] = max(x[0] + v.0, x[0]);
        x[1] = min(x[1] + v.0, x[1]);
        y[0] = max(y[0], y[0] + v.1);
        y[1] = min(y[1], y[1] + v.1);
        if x[0] > x[1] || y[0] > y[1] {
            println!("NO");
            return;
        }
    }
    if x[0] <= p.0 && p.0 <= x[1] && y[0] <= p.1 && p.1 <= y[1] {
        println!("YES");
    } else {
        println!("NO");
    }
}

