fn main() {
    let line: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let h = line[0];
    let w = line[1];
    let n = line[2];
    let line: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let y = line[0];
    let x = line[1];
    let s: Vec<char> = read_line().trim().chars().collect();
    let t: Vec<char> = read_line().trim().chars().collect();

    let mut lx = 1;
    let mut rx = w;
    let mut ly = 1;
    let mut ry = h;
    let mut ans = true;
    for i in (0..n).rev() {
        match t[i] {
            'L' => { rx = cmp::min(w, rx+1); },
            'R' => { lx = cmp::max(1, lx-1); },
            'U' => { ry = cmp::min(h, ry+1); },
            'D' => { ly = cmp::max(1, ly-1); },
            _ => {},
        }
        match s[i] {
            'L' => { lx += 1; },
            'R' => { rx -= 1; },
            'U' => { ly += 1; },
            'D' => { ry -= 1; },
            _ => {},
        }
        if lx > rx || ly > ry {
            ans = false;
            break;
        }
    }

    if ans && lx <= x && x <= rx && ly <= y && y <= ry {
        println!("YES");
    } else {
        println!("NO");
    }
}

