type XRange = (i32, i32);

fn process(size: Vec<usize>, start: (usize, usize), s: Vec<char>, t: Vec<char>) -> bool {

    let result = backtrack(size[2], size[1], &s, &t, 'L', 'R', start.1);
    if !result {
        return result;
    }
    let result = backtrack(size[2], size[0], &s, &t, 'U', 'D', start.0);
    return result;
}

fn backtrack(n:usize, size:usize, s: &Vec<char>, t: &Vec<char>, b:char, f:char, start:usize) -> bool {
    let size_i = size as i32;
    let mut r : XRange = (0, size_i-1);
    for i in (0..n).rev() {
        if t[i] == b {
            if r.1 < size_i - 1 {
                r.1 += 1;
            }
        } else if t[i] == f {
            if r.0 > 0 {
                r.0 -= 1;
            }
        }

        if s[i] == b {
            r.0 += 1;
        } else if s[i] == f {
            r.1 -= 1;
        }

        if r.0 > r.1 {
            return false;
        }
    }
    let start_i = start as i32;
    if start_i < r.0 || r.1 < start_i {
        return false;
    }
    return true;
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

