fn read_as_vec<T>() -> Vec<T>
where T: FromStr, <T as FromStr>::Err : Debug{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().split_whitespace().map(|c| T::from_str(c).unwrap()).collect()

}

fn read_as_string() -> String{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().to_string()
}

fn solve(takahashi: &Vec<char>, aoki: &Vec<char>, command: (char, char), limit: i32) -> (i32, i32){
    let mut safety: (i32, i32) = (0, limit-1);
    //println!("safety = {:?}", safety);
    for i in (0..aoki.len()).rev(){
        //aoki phase
        if aoki[i] == command.0{
            safety.1 = cmp::min(safety.1+1, limit-1);   
        }else if aoki[i] == command.1{
            safety.0 = cmp::max(safety.0-1, 0);
        }

        //takahashi phase
        if takahashi[i] == command.0{
            if safety.0 == limit-1{
                return (0, -1);
            }else{
                safety.0 = cmp::min(safety.0+1,limit-1);
            }
        }else if takahashi[i] == command.1{
            if safety.1 == 0{
                return (0, -1);
            }else{
                safety.1 = cmp::max(safety.1-1, 0);
            }
        }
    }
    safety
}

