fn main() {
    let size: Vec<usize> = read_vec::<usize>();
    let start: Vec<usize> = read_vec::<usize>();
    let start: (usize, usize) = (start[0] - 1, start[1] - 1);
    let s = read::<String>().chars().collect::<Vec<char>>();
    let t = read::<String>().chars().collect::<Vec<char>>();

    let result = process(size, start, s, t);
    if result {
        println!("YES");
    } else {
        println!("NO");
    }
}

fn process(size: Vec<usize>, start: (usize, usize), s: Vec<char>, t: Vec<char>) -> bool {
    let inc = |x: usize| -> usize { x + 1 };
    let dec = |x: usize| -> usize { x - 1 };
    let result = check(
        start.1,
        &s,
        &t,
        'L',
        dec,
        0,
        'R',
        inc,
        size[1] - 1,
    );
    if !result {
        return result;
    }
    let result = check(
        start.1,
        &s,
        &t,
        'R',
        inc,
        size[1] - 1,
        'L',
        dec,
        0,
    );
    if !result {
        return result;
    }
    // U
    let result = check(
        start.0,
        &s,
        &t,
        'U',
        dec,
        0,
        'D',
        inc,
        size[0] - 1,
    );
    if !result {
        return result;
    }
    // D
    let result = check(
        start.0,
        &s,
        &t,
        'D',
        inc,
        size[0] - 1,
        'U',
        inc,
        0,
    );

    return result;
}

fn check(
    start: usize,
    s: &Vec<char>,
    t: &Vec<char>,
    f: char,
    ff: fn(usize) -> usize,
    f_limit: usize,
    b: char,
    bb: fn(usize) -> usize,
    b_limit: usize,
) -> bool {
    let mut x = start;
    for i in 0..s.len() {
        if s[i] == f {
            if x == f_limit {
                return false;
            }
            x = ff(x);
        }
        if t[i] == b {
            if x == b_limit {
                continue;
            }
            x = bb(x);
        }
    }
    return true;
}

