fn convert(s: &Vec<char>) -> Vec<usize> {
    let mut a = vec![];
    for &c in s {
        let k = match c {
            'L' => 0,
            'R' => 1,
            'U' => 2,
            'D' => 3,
            _ => unreachable!(),
        };
        a.push(k);
    }
    a
}

