    N: usize,
    Sr: usize,
    Sc: usize,
    S: Vec<char>,
    T: Vec<char>,
}

impl LRUDGame {
    pub fn new(param: (usize, usize, usize, usize, usize, Vec<char>, Vec<char>)) -> LRUDGame {
        LRUDGame {
            H: param.0,
            W: param.1,
            N: param.2,
            Sr: param.3,
            Sc: param.4,
            S: param.5,
            T: param.6,
        }
    }

    fn solve(&mut self) -> usize {
        let mut lbound = 1;
        let mut rbound = self.W as i32;
        let mut ubound = 1;
        let mut dbound = self.H as i32;
        for i in (0..self.N).rev() {
            // println!("({}, {}), ({}, {})", ubound, dbound, lbound, rbound);
            if self.S[i] == 'd' {
                ubound = ubound + 1;
                if self.T[i] == 'u' {
                    ubound = max!(ubound - 1, 1);
                }
            } else if self.S[i] == 'u' {
                dbound = dbound - 1;
                if self.T[i] == 'd' {
                    dbound = min!(dbound + 1, self.H as i32);
                }
            } else if self.S[i] == 'l' {
                lbound = lbound + 1;
                if self.T[i] == 'r' {
                    lbound = max!(lbound - 1, 1);
                }
            } else {
                rbound = rbound - 1;
                if self.T[i] == 'l' {
                    rbound = min!(rbound + 1, self.H as i32);
                }
            }
        }

        // println!("({}, {}), ({}, {})", ubound, dbound, lbound, rbound);

        if ubound <= self.Sr && self.Sr <= dbound as usize && lbound <= self.Sc && self.Sc <= rbound as usize {
            0
        } else {
            1
        }
    }
}
