fn solve() {
    let (h,w,n) = get!(isize, isize, usize);
    let (sr, sc) = get!(isize, isize);
    let s = get!(String).chars().collect::<Vec<_>>();
    let t = get!(String).chars().collect::<Vec<_>>();

    let mut right = w;
    let mut left = 1;
    let mut up = 1;
    let mut down = h;

    for i in (0..n).rev() {
        match t[i] {
            'L' => if right < w {
                right += 1;
            },
            'R' => if left > 1 {
                left -= 1;
            },
            'U' => if down < h {
                down += 1;
            },
            'D' => if up > 1 {
                up -= 1;
            },
            _ => (),
        }
        match s[i] {
            'L' => left += 1,
            'R' => right -= 1,
            'U' => up += 1,
            'D' => down -= 1,
            _ => (),
        }
        if right < left || up > down {
            println!("NO");
            return;
        }
    }

    if right >= sc && left <= sc && down >= sr && up <= sr {
        println!("YES");
    } else {
        println!("NO");
    }
}

