fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (h, w, _n) = i.read3::<usize, usize, usize>();
    let (y, x) = i.read2::<usize, usize>();
    let s: Vec<_> = i.read_line_bytes_vec();
    let t: Vec<_> = i.read_line_bytes_vec();

    let ans = if solve(y - 1, x - 1, h, w, &s, &t) {
        "YES"
    } else {
        "NO"
    };
    writeln!(o, "{}", ans).unwrap();
}
fn solve(y: usize, x: usize, h: usize, w: usize, s: &[u8], t: &[u8]) -> bool {
    let mut rx0 = 0;
    let mut rx1 = 0;
    let mut ry0 = 0;
    let mut ry1 = 0;
    for (&s, &t) in s.iter().zip(t).rev() {
        if rx0 + rx1 == w {
            return false;
        }
        if ry0 + ry1 == h {
            return false;
        }
        match t {
            b'L' => {
                if rx1 > 0 {
                    rx1 -= 1;
                }
            }
            b'R' => {
                if rx0 > 0 {
                    rx0 -= 1;
                }
            }
            b'U' => {
                if ry1 > 0 {
                    ry1 -= 1;
                }
            }
            b'D' => {
                if ry0 > 0 {
                    ry0 -= 1;
                }
            }
            _ => unreachable!(),
        }
        match s {
            b'L' => rx0 += 1,
            b'R' => rx1 += 1,
            b'U' => ry0 += 1,
            b'D' => ry1 += 1,
            _ => unreachable!(),
        }
    }
    !(rx0 >= x + 1 || ry0 >= y + 1 || rx1 >= w - x || ry1 >= h - y)
}

