            self.s.clear();
            self.b.clear();
            self.r.read_line(&mut self.s).unwrap();
            self.s.trim()
        }

        #[allow(dead_code)]
        pub fn read_line_bytes(&mut self) -> &[u8] {
            self.s.clear();
            self.b.clear();
            self.r.read_until(b'\n', &mut self.b).unwrap();
            if self.b.last() == Some(&b'\n') {
                self.b.pop();
            }
            &self.b
        }
        pub fn read_line_bytes_vec(&mut self) -> Vec<u8> {
            let mut b = Vec::new();
            self.r.read_until(b'\n', &mut b).unwrap();
            if b.last() == Some(&b'\n') {
                b.pop();
            }
            b
        }

