fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let h: usize = sc.read();
    let w: usize = sc.read();
    let n: usize = sc.read();
    let r: usize = sc.read();
    let c: usize = sc.read();
    let s = sc.chars();
    let t = sc.chars();

    let mut lrud = (1, w, 1, h);
    for i in (0..n).rev() {
        match t[i] {
            'L' => {
                if lrud.1 < w {
                    lrud.1 += 1
                }
            }
            'R' => {
                if lrud.0 > 1 {
                    lrud.0 -= 1
                }
            }
            'U' => {
                if lrud.3 < h {
                    lrud.3 += 1
                }
            }
            'D' => {
                if lrud.2 > 1 {
                    lrud.2 -= 1
                }
            }
            _ => unreachable!(),
        }
        match s[i] {
            'L' => lrud.0 += 1,
            'R' => lrud.1 -= 1,
            'U' => lrud.2 += 1,
            'D' => lrud.3 -= 1,
            _ => unreachable!(),
        }
        if lrud.0 > lrud.1 || lrud.2 > lrud.3 {
            return "NO\n".to_string();
        }
    }
    if lrud.0 <= c && c <= lrud.1 && lrud.2 <= r && r <= lrud.3 {
        "YES\n"
    } else {
        "NO\n"
    }
    .to_string()
}

