use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        h: usize,
        w: usize,
        n: usize,
        sy: usize1,
        sx: usize1,
        s: chars,
        t: chars,
    }
    let cs = ['L', 'R', 'U', 'D'];
    let ds = [-1, 1, -1, 1];
    let bs = [w, w, h, h];
    for i in 0..4 {
        let my_c = cs[i];
        let op_c = cs[i ^ 1];
        let mut p = if i < 2 { sx } else { sy } as i64;
        for k in 0..n {
            if s[k] == my_c {
                p += ds[i];
            }
            if p < 0 || bs[i] as i64 <= p {
                writeln!(buf, "NO");
                return buf;
            }
            if t[k] == op_c {
                p -= ds[i];
                p = max(0, p);
                p = min(bs[i] as i64 - 1, p);
            }
            // eprintln!("  k={},p={}", k,p);
        }
        // eprintln!("i={},p={}", i, p);
    }
    //panic!();
    writeln!(buf, "YES");
    buf
}

