fn main() {
    let (H, W, N) = read!(usize, usize, usize);
    let (Y, X) = read!(usize, usize);
    let S = rl().chars().collect::<Vec<_>>();
    let T = rl().chars().collect::<Vec<_>>();

    let mut ok = true;

    for &negative in &['L', 'R', 'U', 'D'] {
        let (start, end, positive) = match negative {
            'L' => (X, W, 'R'),
            'R' => (W - X + 1, W, 'L'),
            'U' => (Y, H, 'D'),
            'D' => (H - Y + 1, H, 'U'),
            _ => unreachable!(),
        };

        let mut x = start;
        for i in 0..N {
            if S[i] == negative {
                x -= 1;
            }
            if x == 0 {
                // debug!((start, end, positive, negative, i));
                ok = false;
                break;
            }
            if T[i] == positive && x + 1 <= end {
                x += 1;
            }
        }
    }

    println!("{}", if ok { "YES" } else { "NO" })
}

