use std::io;
use std::io::prelude::*;
use std::str::FromStr;

fn check(size: i32, maxv: i32, vec_t: &Vec<i32>, vec_a: &Vec<i32>, vl: i32) -> bool {
    let mut vec_rt = vec_t.clone();
    vec_rt.reverse();
    let mut vec_ra = vec_a.clone();
    vec_ra.reverse();
    let mut iter_t = vec_rt.iter();
    let mut iter_a = vec_ra.iter();
    let mut curmin = 0;
    let mut curmax = maxv;
    for i in 0..size {
        let action = iter_a.next().unwrap();
        if *action == -1 {
            curmax = std::cmp::min(maxv, curmax + 1);
        } else if *action == 1 {
            curmin = std::cmp::max(0, curmin - 1);
        }
        let action = iter_t.next().unwrap();
        if *action == -1 {
            curmin += 1;
        } else if *action == 1 {
            curmax -= 1;
        }
        if curmin > curmax {
            return true;
        }
    }
    if curmin <= vl && vl <= curmax {
        return false;
    }
    true
}

