fn solve() {
    let stdin = std::io::stdin();
    let mut scn = Scanner {
        stdin: stdin.lock(),
    };
    let h: i64 = scn.read();
    let w: i64 = scn.read();
    let n: usize = scn.read();
    let (sy, sx): (i64, i64) = (scn.read(), scn.read());
    let s = scn.chars();
    let t = scn.chars();

    //L
    let l = {
        let mut ok = false;
        let (mut py, mut px) = (sy, sx);
        for (s, t) in s.iter().zip(t.iter()) {
            if *s == 'L' {
                px -= 1;
            }
            if px <= 0 {
                ok = true;
            }
            if *t == 'R' {
                if px + 1 <= w {
                    px += 1;
                }
            }
        }
        ok
    };
    //R
    let r = {
        let mut ok = false;
        let (mut py, mut px) = (sy, sx);
        for (s, t) in s.iter().zip(t.iter()) {
            if *s == 'R' {
                px += 1;
            }
            if px > w {
                ok = true;
            }
            if *t == 'L' {
                if px - 1 >= 1 {
                    px -= 1;
                }
            }
        }
        ok
    };
    //U
    let u = {
        let mut ok = false;
        let (mut py, mut px) = (sy, sx);
        for (s, t) in s.iter().zip(t.iter()) {
            //eprintln!("{} {} {}", s, t, py);
            if *s == 'U' {
                py -= 1;
            }
            if py <= 0 {
                ok = true;
            }
            if *t == 'D' {
                if py + 1 <= h {
                    py += 1;
                }
            }
        }
        ok
    };
    //U
    let d = {
        let mut ok = false;
        let (mut py, mut px) = (sy, sx);
        for (s, t) in s.iter().zip(t.iter()) {
            if *s == 'D' {
                py += 1;
            }
            if py > h {
                ok = true;
            }
            if *t == 'U' {
                if py - 1 >= 1 {
                    py -= 1;
                }
            }
        }
        ok
    };

    let result = if l || r || u || d { "NO" } else { "YES" };
    println!("{}", result);
}

