use std::cmp::{max, min};

fn run() {
    input! {
        h: i32,
        w: i32,
        n: usize,
        x: i32,
        y: i32,
        s: chars,
        t: chars,
    }
    let mut r = [1, h];
    let mut c = [1, w];
    let dir = [(0, 1), (0, -1), (1, 0), (-1, 0)];//RLDU
    for i in (0..n).rev() {
        if r[0] > r[1] || c[0] > c[1] {
            println!("NO");
            return;
        }
        let k = match t[i] {
            'R' => 0,
            'L' => 1,
            'D' => 2,
            'U' => 3,
            _ => unreachable!(),
        };
        r[0] = max(1, min(r[0], r[0] + dir[k].0));
        r[1] = min(h, max(r[1], r[1] + dir[k].0));
        c[0] = max(1, min(c[0], c[0] + dir[k].1));
        c[1] = min(w, max(c[1], c[1] + dir[k].1));
        let k = match s[i] {
            'R' => 0,
            'L' => 1,
            'D' => 2,
            'U' => 3,
            _ => unreachable!(),
        };
        r[0] = max(r[0], r[0] + dir[k].0);
        r[1] = min(r[1], r[1] + dir[k].0);
        c[0] = max(c[0], c[0] + dir[k].1);
        c[1] = min(c[1], c[1] + dir[k].1);
    }
    if r[0] <= x && x <= r[1] && c[0] <= y && y <= c[1] {
        println!("YES");
    } else {
        println!("NO");
    }
}

