fn solve<R: BufRead, W: Write>(reader: R, mut writer: W) {
  let mut _scanner = spella::io::Scanner::new(reader);

  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.next::<$T>().unwrap().unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($($T:ty),+; $n:expr $(; $m:expr)*) => {{
      (0..$n).map(|_| scan!($($T),+ $(; $m)*)).collect::<Vec<_>>()
    }};
  }

  #[allow(unused_macros)]
  macro_rules! scan_iter {
    ($($T:ty),+; $n:expr) => {
      (0..$n).map(|_| scan!($($T),+))
    };
  }

  #[allow(unused_macros)]
  macro_rules! print {
    ($fmt:expr) => {
      write!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      write!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! println {
    ($fmt:expr) => {
      writeln!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprint {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dbg {
    ($($x:expr),+) => {{
      eprintln!(concat!("[{}:{}] ", $(stringify!($x), " = {:?}; "),+), file!(), line!(), $($x),+);
    }};
  }

  let (h, w, n) = scan!(isize, isize, usize);
  let (s_y, s_x) = scan!(isize, isize);
  let remover_s = scan!(ByteString);
  let keeper_s = scan!(ByteString);

  // X
  {
    let is_in = |crt_x: isize| 1 <= crt_x && crt_x <= w;

    // remover -> R, keeper -> L
    {
      let mut crt_x = s_x;

      for i in 0..n {
        match remover_s[i].into_byte() {
          b'R' => crt_x += 1,
          _ => {}
        }
        if !is_in(crt_x) {
          println!("NO");
          return;
        }
        match keeper_s[i].into_byte() {
          b'L' if is_in(crt_x - 1) => crt_x -= 1,
          _ => {}
        }
      }
    }
    // remover -> L, keeper -> R
    {
      let mut crt_x = s_x;

      for i in 0..n {
        match remover_s[i].into_byte() {
          b'L' => crt_x -= 1,
          _ => {}
        }
        if !is_in(crt_x) {
          println!("NO");
          return;
        }
        match keeper_s[i].into_byte() {
          b'R' if is_in(crt_x + 1) => crt_x += 1,
          _ => {}
        }
      }
    }
  }

  // Y
  {
    let is_in = |crt_y: isize| 1 <= crt_y && crt_y <= h;

    // remover -> D, keeper -> U
    {
      let mut crt_y = s_y;

      for i in 0..n {
        match remover_s[i].into_byte() {
          b'D' => crt_y += 1,
          _ => {}
        }
        if !is_in(crt_y) {
          println!("NO");
          return;
        }
        match keeper_s[i].into_byte() {
          b'U' if is_in(crt_y - 1) => crt_y -= 1,
          _ => {}
        }
      }
    }
    // remover -> U, keeper -> D
    {
      let mut crt_y = s_y;

      for i in 0..n {
        match remover_s[i].into_byte() {
          b'U' => crt_y -= 1,
          _ => {}
        }
        if !is_in(crt_y) {
          println!("NO");
          return;
        }
        match keeper_s[i].into_byte() {
          b'D' if is_in(crt_y + 1) => crt_y += 1,
          _ => {}
        }
      }
    }
  }

  println!("YES");
}

use std::io::*;
use std::str::FromStr;
use utils::*;

pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (h, w, _n) = i.read3::<usize, usize, usize>();
    let (y, x) = i.read2::<usize, usize>();
    let s: Vec<_> = i.read_line().as_bytes().iter().cloned().collect();
    let t: Vec<_> = i.read_line().as_bytes().iter().cloned().collect();

    let ans = if solve(y, x, h, w, &s, &t) {
        "YES"
    } else {
        "NO"
    };
    writeln!(o, "{}", ans).unwrap();
}
fn solve(y: usize, x: usize, h: usize, w: usize, s: &[u8], t: &[u8]) -> bool {
    let mut rx0 = 0;
    let mut rx1 = 0;
    let mut ry0 = 0;
    let mut ry1 = 0;
    for (&s, &t) in s.iter().zip(t).rev() {
        if rx0 + rx1 == w {
            return false;
        }
        if ry0 + ry1 == h {
            return false;
        }
        match t {
            b'L' => {
                if rx1 > 0 {
                    rx1 -= 1;
                }
            }
            b'R' => {
                if rx0 > 0 {
                    rx0 -= 1;
                }
            }
            b'U' => {
                if ry1 > 0 {
                    ry1 -= 1;
                }
            }
            b'D' => {
                if ry0 > 0 {
                    ry0 -= 1;
                }
            }
            _ => unreachable!(),
        }
        match s {
            b'L' => rx0 += 1,
            b'R' => rx1 += 1,
            b'U' => ry0 += 1,
            b'D' => ry1 += 1,
            _ => unreachable!(),
        }
    }
    rx0 >= x + 1 || ry0 >= y + 1 || rx1 >= w - x || ry1 >= h - y
}

mod utils {
