#[allow(unused_imports)]
use std::cmp::{min, max};

#[allow(unused_imports)]
use std::io::Write;

fn main() {
    input!{
      h: isize,
      w: isize,
      n: usize,
      sr: isize1,
      sc: isize1,
      ss: chars,
      ts: chars,
    }

    let mut left = 0;
    let mut right = w-1;
    let mut top = 0;
    let mut buttom = h-1;

    for i in (0..n).rev() {
        let s = ss[i];
        let t = ts[i];

        if i != n-1 {
            match t {
                'U' => buttom = min(buttom+1, h-1),
                'D' => top = max(top-1, 0),
                'R' => left = max(left-1, 0),
                'L' => right = min(right+1, w-1),
                _ => unreachable!()
            }
        }

        match s {
            'U' => top = top+1,
            'D' => buttom = buttom-1,
            'R' => right = right-1,
            'L' => left = left+1,
            _ => unreachable!()
        }

        if top >= h || buttom < 0 || left >= w || right < 0 {
            return println!("{}", "NO");
        }
        if top > buttom || left > right {
            return println!("{}", "NO");
        }
    }

    if sr >= top && sr <= buttom && sc >= left && sc <= right {
        println!("{}", "YES")
    } else {
        println!("{}", "NO")
    }
}

