type I = usize;

fn can_block(dir: usize, h: isize, w: isize, mut x: isize, mut y: isize, ss: &Vec<char>, ts: &Vec<char>) -> bool {
    // debug!(dir, h, w, x, y);
    let n = ss.len();
    for i in 0..n {
        match dir {
            0 => {
                if ss[i] == 'U' { x -=1; }
                if ss[i] == 'R' { y +=1; }
            },
            1 => {
                if ss[i] == 'D' { x +=1; }
                if ss[i] == 'R' { y +=1; }
            },
            2 => {
                if ss[i] == 'D' { x +=1; }
                if ss[i] == 'L' { y -=1; }
            },
            3 => {
                if ss[i] == 'U' { x -=1; }
                if ss[i] == 'L' { y -=1; }
            },
            _ => unreachable!()
        };
        if !(x>=0 && x<h && y>=0 && y < w) {
            return false
        }

        match dir {
            0 => {
                if ts[i] == 'D' { x = min(x+1, h-1); }
                if ts[i] == 'L' { y = max(y-1, 0); }
            },
            1 => {
                if ts[i] == 'U' { x = max(x-1, 0); }
                if ts[i] == 'L' { y = max(y-1, 0); }
            },
            2 => {
                if ts[i] == 'U' { x = max(x-1, 0); }
                if ts[i] == 'R' { y = min(y+1, w-1); }
            },
            3 => {
                if ts[i] == 'D' { x = min(x+1, h-1); }
                if ts[i] == 'R' { y = min(y+1, w-1); }
            },
            _ => unreachable!()
        };

        if !(x>=0 && x<h && y>=0 && y < w) {
            return false
        }
    }
    true
}

fn main() {
    input!{
      h: usize,
      w: usize,
      n: usize,
      sr: isize,
      sc: isize,
