fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let h: i64 = sc.read();
    let w: i64 = sc.read();
    let n: usize = sc.read();

    let r: i64 = sc.read();
    let c: i64 = sc.read();

    let s = sc.chars();
    let t = sc.chars();

    let calc_max_left = |l: char, r: char| {
        let mut max_left = vec![0; n];
        let mut left: i64 = 0;
        for i in (0..n).rev() {
            if s[i] == l {
                left += 1;
            }
            max_left[i] = left;
            if i > 0 && t[i - 1] == r {
                left -= 1;
            }
        }
        max_left
    };

    let a = |l: char, r: char, c: i64, w: i64| {
        let max_left = calc_max_left(l, r);
        let max_right = calc_max_left(r, l);

        let mut left = c;
        let mut right = c;
        for i in 0..n {
            if left - max_left[i] <= 0 {
                return false;
            }
            if right + max_right[i] > w {
                return false;
            }

            if s[i] == r {
                right += 1;
            }
            if s[i] == l {
                left -= 1;
            }

            if i + 1 < n {
                if t[i] == r && left + 1 + max_right[i + 1] <= w {
                    left += 1;
                }
                if t[i] == l && right - 1 - max_left[i + 1] > 0 {
                    right -= 1;
                }
            }
        }
        true
    };

    println!(
        "{}",
        if a('L', 'R', c, w) && a('D', 'U', r, h) {
            "YES"
        } else {
            "NO"
        }
    );
}

