fn solve() {
    let stdin = std::io::stdin();
    let mut scn = Scanner {
        stdin: stdin.lock(),
    };
    let h: i64 = scn.read();
    let w: i64 = scn.read();
    let n: usize = scn.read();
    let (sy, sx): (i64, i64) = (scn.read(), scn.read());
    let s = scn.chars();
    let t = scn.chars();

    //L
    let l = {
        let mut ok = false;
        let (mut py, mut px) = (sy, sx);
        for (s, t) in s.iter().zip(t.iter()) {
            if *s == 'L' {
                px -= 1;
            }
            if px <= 0 {
                ok = true;
            }
            if *t == 'R' {
                if px + 1 <= w {
                    px += 1;
                }
            }
        }
        ok
    };
    //R
    let r = {
        let mut ok = false;
        let (mut py, mut px) = (sy, sx);
        for (s, t) in s.iter().zip(t.iter()) {
            if *s == 'R' {
                px += 1;
            }
            if px > w {
                ok = true;
            }
            if *t == 'L' {
                if px - 1 >= 1 {
                    px -= 1;
                }
            }
        }
        ok
    };
    //U
    let u = {
        let mut ok = false;
        let (mut py, mut px) = (sy, sx);
        for (s, t) in s.iter().zip(t.iter()) {
            if *s == 'U' {
                py += 1;
            }
            if py > h {
                ok = true;
            }
            if *t == 'D' {
                if py - 1 >= 1 {
                    py -= 1;
                }
            }
        }
        ok
    };
    //U
    let d = {
        let mut ok = false;
        let (mut py, mut px) = (sy, sx);
        for (s, t) in s.iter().zip(t.iter()) {
            if *s == 'D' {
                py -= 1;
            }
            if py <= 0 {
                ok = true;
            }
            if *t == 'U' {
                if py + 1 <= h {
                    py += 1;
                }
            }
        }
        ok
    };

    let result = if l || r || u || d { "NO" } else { "YES" };
    println!("{}", result);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}
pub mod utils {
    const DYX: [(isize, isize); 8] = [
        (0, 1),   //right
        (1, 0),   //down
        (0, -1),  //left
        (-1, 0),  //top
        (1, 1),   //down right
        (-1, 1),  //top right
        (1, -1),  //down left
        (-1, -1), //top left
    ];

    pub fn try_adj(y: usize, x: usize, dir: usize, h: usize, w: usize) -> Option<(usize, usize)> {
        let ny = y as isize + DYX[dir].0;
        let nx = x as isize + DYX[dir].1;
        if ny >= 0 && nx >= 0 {
            let ny = ny as usize;
            let nx = nx as usize;
            if ny < h && nx < w {
                Some((ny, nx))
            } else {
                None
            }
        } else {
            None
        }
    }
}

