pub struct LRUDGame {
    H: usize,
    W: usize,
    N: usize,
    Sr: usize,
    Sc: usize,
    S: Vec<char>,
    T: Vec<char>,
}

impl LRUDGame {
    pub fn new(param: (usize, usize, usize, usize, usize, Vec<char>, Vec<char>)) -> LRUDGame {
        LRUDGame {
            H: param.0,
            W: param.1,
            N: param.2,
            Sr: param.3,
            Sc: param.4,
            S: param.5,
            T: param.6,
        }
    }

    fn solve(&mut self) -> usize {
        let mut lbound = 1;
        let mut rbound = self.W as i32;
        let mut ubound = 1;
        let mut dbound = self.H as i32;
        for i in (0..self.N).rev() {
            if self.S[i] == 'd' {
                ubound = ubound + 1;
                if self.T[i] == 'u' {
                    ubound = max!(ubound - 1, 1);
                }
            } else if self.S[i] == 'u' {
                dbound = dbound - 1;
                if self.T[i] == 'd' {
                    dbound = min!(dbound + 1, self.H as i32);
                }
            } else if self.S[i] == 'l' {
                lbound = lbound + 1;
                if self.T[i] == 'r' {
                    lbound = max!(lbound - 1, 1);
                }
            } else {
                rbound = rbound - 1;
                if self.T[i] == 'l' {
                    rbound = min!(rbound + 1, self.H as i32);
                }
            }
            // println!("({}, {}), ({}, {})", ubound, dbound, lbound, rbound);
        }

        if ubound <= self.Sr && self.Sr as i32 <= dbound && lbound <= self.Sc && self.Sc as i32 <= rbound {
            0
        } else {
            1
        }
    }
}
fn main() {
    input! {
        H: usize,
        W: usize,
        N: usize,
        Sr: usize,
        Sc: usize,
        S: String,
        T: String,
    };

    let S:Vec<char> = S.chars().collect();
    let T:Vec<char> = T.chars().collect();
    let mut lrudgame = LRUDGame::new((H, W, N, Sr, Sc, S, T));
    println!("{}", if lrudgame.solve() == 0 { "NO" } else { "YES" });
}

